const items: CultureArticle[] = [{"id":"afr-001","version":2,"slug":"nigerian-pidgin-is-the-one-language-almost-every-nigerian-shares","contentType":"feature","category":"languages","title":{"ar":"البيجين النيجيري: لغة تجمع نيجيريا","de":"Nigerianisches Pidgin: Die Sprache, die Nigeria verbindet","en":"Nigerian Pidgin: The One Language Almost Every Nigerian Shares"},"deck":{"ar":"كيف أصبحت لغة التواصل المشتركة في الأسواق والراديو وكرة القدم؟","de":"Wie eine Kreolsprache in Märkten, Radio und Fußballkommentaren funktioniert.","en":"How a creole born of trade became the country's widest shared second language."},"teaser":{"ar":"منذ القرن السابع عشر، نشأت لغة البيجين النيجيري من لقاء التجار البريطانيين والمجتمعات الساحلية، لتصبح اليوم اللغة الأوسع انتشارًا في نيجيريا.","de":"Seit dem 17. Jahrhundert entstand Naijá aus dem Kontakt zwischen britischen Händlern und Küstengemeinden – heute ist es die geografisch am weitesten verbreitete Sprachform Nigerias.","en":"Since the 17th century, Naijá has grown from coastal trade contact into Nigeria's most geographically widespread speech form, used in markets, radio and football commentary."},"readingMinutes":1,"sections":{"ar":[{"heading":"نشأة اللغة وانتشارها","paragraphs":["بدأت لغة البيجين النيجيري، التي يسميها العلماء نايجا، في القرنين السابع عشر والثامن عشر من الاتصال بين التجار البريطانيين والمجتمعات الأفريقية الساحلية. واليوم هي صيغة الكلام الأوسع تغطية جغرافية في نيجيريا.","لأنها لا تنتمي إلى أي مجموعة عرقية واحدة، فإنها تعمل كرمز محايد في الأسواق وعلى الراديو وفي التعليق على كرة القدم وبين الغرباء من مناطق مختلفة."]},{"heading":"لغة كاملة وليست إنجليزية رديئة","paragraphs":["للبيجين ضمائرها الخاصة وجزيئاتها الزمنية وتعبيراتها الاصطلاحية. ويعتبرها اللغويون لغة كريولية قائمة على الإنجليزية وليست إنجليزية رديئة.","تتغير المفردات والنغمة بين بيجين لاغوس وبورت هاركورت وكانو، مستمدة من اليوروبا والإيبو والهوسا على التوالي. ويختلف الاستخدام أيضًا حسب المنطقة والجيل، إذ يميل الشباب في المدن الكبرى إلى مزج أكبر مع الإنجليزية."]},{"heading":"حضور متزايد في الإعلام والحياة اليومية","paragraphs":["منذ العقد الثاني من القرن الحادي والعشرين، ظهرت البيجين في الإعلانات والأدب وبعض البث الإذاعي والتلفزيوني، رغم أن الوثائق الرسمية تظل بالإنجليزية الفصحى.","مثال حي: يلتقي غريبان من ولايتين مختلفتين في محطة حافلات في لاغوس؛ لا يتحول أي منهما إلى لغة الآخر الأم، بل ينزلقان إلى البيجين، ويسير الحوار دون أن يضطر أحد إلى ادعاء هوية.","سوء فهم شائع: يعتقد بعض الناس أن البيجين إنجليزية سيئة أو لغة غير منظمة. لكنها في الواقع لغة كاملة بقواعدها الخاصة، رغم أن شكلها المكتوب لا يزال غير مستقر."]}],"de":[{"heading":"Entstehung und Verbreitung","paragraphs":["Naijá, wie Wissenschaftler das Nigerianische Pidgin nennen, entstand im 17. und 18. Jahrhundert aus dem Kontakt zwischen britischen Händlern und afrikanischen Küstengemeinden. Heute ist es die Sprachform mit der größten geografischen Abdeckung in Nigeria.","Da es keiner einzelnen ethnischen Gruppe gehört, dient es als neutraler Code in Märkten, im Radio, bei Fußballkommentaren und zwischen Fremden aus verschiedenen Regionen."]},{"heading":"Eine vollwertige Sprache, kein schlechtes Englisch","paragraphs":["Naijá hat eigene Pronomen, Tempuspartikeln und Idiome. Linguisten betrachten es als englisch-basierte Kreolsprache und nicht als schlecht gesprochenes Englisch.","Wortschatz und Intonation variieren zwischen Lagos-, Port Harcourt- und Kano-Pidgin, die sich jeweils aus Yoruba, Igbo und Hausa speisen. Auch der Gebrauch unterscheidet sich regional und generationell: Jüngere in Großstädten mischen häufiger Englisch bei."]},{"heading":"Zunehmende Präsenz in Medien und Alltag","paragraphs":["Seit den 2010er Jahren erscheint Naijá in Werbung, Literatur und einigen Rundfunksendungen, während offizielle Dokumente weiterhin in Standardenglisch verfasst werden.","Ein Beispiel: Zwei Fremde aus verschiedenen Bundesstaaten treffen sich an einer Bushaltestelle in Lagos; keiner wechselt in die Erstsprache des anderen, beide gleiten ins Pidgin, und das Gespräch verläuft, ohne dass jemand eine Identität beanspruchen muss.","Ein häufiges Missverständnis: Viele halten Pidgin für schlechtes Englisch oder eine regellose Sprache. Tatsächlich ist es eine vollwertige Kreolsprache mit eigener Grammatik, auch wenn die Schriftform noch uneinheitlich ist."]}],"en":[{"heading":"Origins and Spread","paragraphs":["Naijá, as scholars call Nigerian Pidgin, began in the 17th and 18th centuries from contact between British traders and coastal African communities. It is now the speech form with the widest geographical coverage in Nigeria.","Because it belongs to no single ethnic group, it works as a neutral code in markets, on radio, in football commentary and between strangers from different regions."]},{"heading":"A Full Language, Not Bad English","paragraphs":["It has its own pronouns, tense particles and idioms, and linguists treat it as an English-based creole rather than as badly spoken English.","Vocabulary and intonation shift between Lagos, Port Harcourt and Kano Pidgin, drawing on Yoruba, Igbo and Hausa respectively. Usage also varies by region and generation, with younger speakers in big cities mixing in more English."]},{"heading":"Growing Presence in Media and Daily Life","paragraphs":["Since the 2010s it has appeared in advertising, literature and some broadcasting, though official documents stay in Standard English.","Consider two strangers from different states meeting at a Lagos bus stop; neither switches to the other's first language, both slide into Pidgin, and the conversation proceeds without anyone having to claim an identity.","A common misunderstanding is that Pidgin is lazy or ruleless English. In fact it is a full creole with its own grammar, even if written Pidgin remains unsettled and many Nigerians switch to Standard English in formal settings."]}]},"context":{"countries":["NG"],"region":"West Africa — Nigeria","community":"Nigerian Pidgin speakers","continent":"africa","languages":["en","yo","ig","ha"],"period":"contemporary"},"tags":["languages","West Africa — Nigeria"],"sources":[{"organization":"Wikipedia","title":{"ar":"Nigerian Pidgin","de":"Nigerian Pidgin","en":"Nigerian Pidgin"},"url":"https://en.wikipedia.org/wiki/Nigerian_Pidgin","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Languages of Nigeria","de":"Languages of Nigeria","en":"Languages of Nigeria"},"url":"https://en.wikipedia.org/wiki/Languages_of_Nigeria","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"غريبان من ولايتين مختلفتين يلتقيان في محطة حافلات في لاغوس؛ لا يتحول أي منهما إلى لغة الآخر الأم، بل ينزلقان إلى البيجين، ويسير الحوار دون أن يضطر أحد إلى ادعاء هوية.","de":"Zwei Fremde aus verschiedenen Bundesstaaten treffen sich an einer Bushaltestelle in Lagos; keiner wechselt in die Erstsprache des anderen, beide gleiten ins Pidgin, und das Gespräch verläuft, ohne dass jemand eine Identität beanspruchen muss.","en":"Two strangers from different states meet at a Lagos bus stop; neither switches to the other's first language, both slide into Pidgin, and the conversation proceeds without anyone having to claim an identity."},"misunderstanding":{"ar":"الاعتقاد بأن البيجين إنجليزية رديئة أو لغة بلا قواعد. في الواقع، هي لغة كريولية كاملة بضمائرها وجزيئاتها الزمنية وتعبيراتها الاصطلاحية.","de":"Die Annahme, Pidgin sei schlechtes Englisch oder eine regellose Sprache. Tatsächlich ist es eine vollwertige Kreolsprache mit eigenen Pronomen, Tempuspartikeln und Idiomen.","en":"The belief that Pidgin is bad or ruleless English. In fact, it is a full creole with its own pronouns, tense particles and idioms, though written Pidgin is still unsettled."},"comparison":{"ar":"على عكس اللغات العرقية الثلاث الكبرى (اليوروبا والإيبو والهوسا)، لا ترتبط البيجين بمجموعة عرقية واحدة، مما يجعلها محايدة في التواصل بين المجموعات.","de":"Anders als die drei großen ethnischen Sprachen Yoruba, Igbo und Hausa ist Naijá an keine einzelne Gruppe gebunden und daher ein neutraler Code zwischen ihnen.","en":"Unlike Nigeria's three major ethnic languages—Yoruba, Igbo and Hausa—Naijá is tied to no single group, making it a neutral code for inter-group communication."},"expression":{"original":"How you dey?","language":"Naijá (Nigerian Pidgin)","gloss":{"ar":"كيف حالك؟ — التحية اليومية في أوسع لغة ثانية مشتركة في نيجيريا","de":"Wie geht es dir? — die alltägliche Begrüßung in Nigerias am weitesten verbreiteter Zweitsprache","en":"How are you? — the everyday greeting in Nigeria's widest shared second language"},"usage":{"ar":"تستخدم كتحية غير رسمية بين الغرباء والأصدقاء في الحياة اليومية.","de":"Wird als informelle Begrüßung unter Fremden und Freunden im Alltag verwendet.","en":"Used as an informal greeting among strangers and friends in daily life."},"transliteration":"How you dey?"}},{"id":"afr-002","version":2,"slug":"hausa-the-sahel-s-market-language-written-in-arabic-letters","contentType":"feature","category":"languages","title":{"ar":"الهوسا: لغة أسواق الساحل","de":"Hausa: die Marktsprache des Sahel","en":"Hausa: the Sahel's market language"},"deck":{"ar":"من القوافل التجارية إلى البث الإذاعي، ظلت الهوسا جسر التواصل في غرب أفريقيا، مكتوبة بحروف عربية في موازاة اللاتينية.","de":"Von Karawanen bis zu Radiowellen: Hausa verbindet über 90 Millionen Menschen und lebt in zwei Schriften nebeneinander.","en":"From caravan routes to radio waves, Hausa connects over 90 million people and lives in two scripts side by side."},"teaser":{"ar":"أكثر من 90 مليون ناطق، لغة تجارة وبحث عن هوية بين الأبجديتين العربية واللاتينية.","de":"Eine Lingua franca, die den Handel prägt und in arabischen wie lateinischen Buchstaben geschrieben wird.","en":"A lingua franca shaped by trade and written in both Arabic and Latin letters, with regional and generational variation."},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة تجارة عابرة للحدود","paragraphs":["قبل أن ترسم الحدود الاستعمارية خرائطها، كانت قوافل التجارة تجعل الهوسا لغة عملية في أسواق الساحل. اليوم، يتحدث بها أكثر من 90 مليون شخص، وتعمل كلغة تواصل مشتركة في شمال نيجيريا وجنوب النيجر وشمال الكاميرون وغانا وبنين وتشاد وأجزاء من السودان. في كانو وزيندر، لا تزال الهوسا اللغة الافتراضية للمساومة والبيع.","يختلف إيقاع الكلام بين مدينة وأخرى؛ فلهجة كانو هي الأكثر انتشارًا بفضل الإذاعة، بينما تحتفظ لهجات سوكوتو وزاريا بخصوصيتها. كما تتفاوت معرفة الكتابة بين الأجيال، إذ يقرأ الشباب المتعلم لاتينيًا، بينما يحتفظ كبار السن بمعرفة الأجادي.","في سوق كانو، قد يكتب تاجر إيصالًا بالأجادي لعميل يقرأ الحروف العربية أكثر من اللاتينية، ثم يكرر السعر بالهوسا المنطوقة. هذا التداخل بين الكتابتين يعكس حياة يومية لا تعرف حدودًا صارمة بين اللغات."]},{"heading":"الأجادي: كتابة عربية بصوت أفريقي","paragraphs":["الأجادي هو تكييف للحرف العربي لكتابة الهوسا وغيرها من لغات غرب أفريقيا، وله تاريخ طويل في الشعر والطب والمراسلات. لم يكن مجرد أداة دينية، بل كان وسيلة تواصل يومية في المناطق التي انتشر فيها الإسلام.","مع التعليم الاستعماري، تراجعت مكانة الأجادي لصالح الحرف اللاتيني (بوكو)، لكنه نجا في التعليم القرآني والتمائم والشعر النسائي. هذا المزيج يجعل الهوسا حالة نادرة تجتمع فيها كتابتان في حياة شعب واحد."]},{"heading":"إذاعة توحّد اللهجات","paragraphs":["ساهمت الدراما الإذاعية الهوسية وبث هيئة الإذاعة البريطانية ودويتشه فيله في توحيد لهجة كانو، حتى أصبحت مفهومة خارج المدينة. هذا التأثير الإعلامي لم يلغِ التنوع، لكنه خلق معيارًا مشتركًا للتواصل.","رغم انتشار الهوسا، لا تزال معرفة الأجادي بعيدة عن الشيوع. فالهوسا ليست لهجة واحدة، والقراءة والكتابة بالأجادي ليستا مهارة عامة بين جميع الناطقين بها."]}],"de":[{"heading":"Eine Sprache des Handels","paragraphs":["Lange bevor Kolonialgrenzen gezogen wurden, machten Karawanen Hausa zur praktischen Sprache der Sahel-Märkte. Heute sprechen über 90 Millionen Menschen Hausa; es dient als Lingua franca in Nordnigeria, im Süden Nigers, in Nordkamerun, Ghana, Benin, Tschad und Teilen des Sudan. In Kano und Zinder bleibt es die Standardsprache des Feilschens.","Die Aussprache variiert regional: Der Kano-Dialekt ist durch Radio am weitesten verbreitet, während Sokoto und Zaria eigene Färbungen bewahren. Auch die Schreibkompetenz unterscheidet sich generationell – viele Jüngere lesen lateinische Schrift, Ältere oft Ajami.","Auf dem Markt von Kano schreibt ein Händler manchmal eine Quittung in Ajami für einen Kunden, der arabische Schrift besser liest als lateinische, und wiederholt dann den Preis auf gesprochenem Hausa. Dieser Alltag zeigt, wie Schriften und Sprachen ineinandergreifen."]},{"heading":"Ajami: arabische Schrift, afrikanischer Klang","paragraphs":["Ajami ist die Anpassung der arabischen Schrift an Hausa und andere westafrikanische Sprachen. Sie hat eine lange Geschichte in Poesie, Medizin und Korrespondenz und war nie nur religiös, sondern auch alltäglich.","Mit der Kolonialschule wurde die lateinische Boko-Schrift gefördert, Ajami zog sich aus dem formellen Gebrauch zurück. Es überlebte in Koranschulen, Talismanen und Frauendichtung – ein seltenes Nebeneinander zweier Schriftsysteme im Alltag."]},{"heading":"Radio vereinheitlicht Dialekte","paragraphs":["Hausa-Hörspiele sowie Sendungen der BBC und der Deutschen Welle halfen, eine Kano-Varietät zu standardisieren, die weit über die Stadt hinaus verstanden wird. Das schuf einen gemeinsamen Bezug, ohne die regionalen Unterschiede auszulöschen.","Dennoch ist Ajami-Kenntnis nicht allgemein verbreitet. Hausa ist keine einheitliche Sprache, und die Fähigkeit, Ajami zu lesen, ist unter Sprechern keineswegs selbstverständlich."]}],"en":[{"heading":"A language of trade","paragraphs":["Long before colonial borders were drawn, caravan trade made Hausa the practical language of Sahelian markets. Today more than 90 million people speak it, and it serves as a lingua franca across northern Nigeria, southern Niger, northern Cameroon, Ghana, Benin, Chad and parts of Sudan. In Kano and Zinder, it remains the default language of bargaining.","Speech varies by region: the Kano variety is the most widely broadcast, while Sokoto and Zaria keep their own flavours. Literacy also differs by generation—many younger people read Latin script, while older speakers often know Ajami.","In a Kano market, a trader may write a receipt in Ajami for a customer who reads Arabic script more comfortably than Latin letters, then repeat the price in spoken Hausa. This everyday mixing shows how scripts and languages overlap."]},{"heading":"Ajami: Arabic letters, African voice","paragraphs":["Ajami is the adaptation of the Arabic script to write Hausa and other West African languages. It has a long history in poetry, medicine and correspondence, and was never only religious—it was part of daily communication.","Colonial schooling promoted the Latin-based boko script, and Ajami retreated from formal use. It survived in Qur'anic education, talismans and women's poetry—a rare case of two writing systems coexisting in one community."]},{"heading":"Radio standardises dialects","paragraphs":["Hausa radio drama and broadcasts by the BBC and Deutsche Welle helped standardise a Kano-based variety understood far beyond the city. This created a shared reference without erasing regional differences.","Yet Ajami literacy is far from universal. Hausa is not one variety—Kano, Sokoto and Zaria speech differ—and the ability to read Ajami is not a given among all speakers."]}]},"context":{"countries":["NG","NE"],"region":"Sahel — northern Nigeria and southern Niger","community":"Hausa","continent":"africa","languages":["ha","en","fr"],"period":"contemporary"},"tags":["languages","Sahel — northern Nigeria and southern Niger"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hausa language","de":"Hausa language","en":"Hausa language"},"url":"https://en.wikipedia.org/wiki/Hausa_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Ajami script","de":"Ajami script","en":"Ajami script"},"url":"https://en.wikipedia.org/wiki/Ajami_script","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تاجر في كانو يكتب إيصالًا بالأجادي لعميل يقرأ الحروف العربية أكثر من اللاتينية، ثم يكرر السعر بالهوسا المنطوقة.","de":"Ein Händler in Kano schreibt eine Quittung in Ajami für einen Kunden, der arabische Schrift besser liest als lateinische, und wiederholt den Preis auf gesprochenem Hausa.","en":"A trader in Kano writes a receipt in Ajami for a customer who reads Arabic script more comfortably than Latin letters, then repeats the price in spoken Hausa."},"misunderstanding":{"ar":"الاعتقاد بأن جميع متحدثي الهوسا يقرؤون الأجادي، أو أن الهوسا لغة واحدة بلهجة واحدة.","de":"Die Annahme, alle Hausa-Sprecher könnten Ajami lesen oder Hausa sei eine einzige, einheitliche Varietät.","en":"Assuming all Hausa speakers can read Ajami or that Hausa is a single, uniform variety."},"comparison":{"ar":"تشبه الهوسا في دورها اللغوي السواحيلية في شرق أفريقيا، لكنها تختلف بوجود كتابة عربية موازية.","de":"Hausa ähnelt in seiner Rolle als Lingua franca dem Swahili in Ostafrika, unterscheidet sich aber durch die parallele arabische Schrift.","en":"Hausa plays a lingua franca role in West Africa similar to Swahili in East Africa, but differs in its parallel use of Arabic script."},"expression":{"original":"Ina kwana?","language":"Harshen Hausa","gloss":{"ar":"صباح الخير — حرفيًا 'كيف نمت؟'، التحية الصباحية المعتادة","de":"Guten Morgen – wörtlich 'Wie hast du geschlafen?', die übliche Morgenbegrüßung","en":"Good morning — literally 'how did you sleep?', the standard morning greeting"},"usage":{"ar":"تقال في الصباح عند اللقاء، ويرد عليها بـ 'لاهيا لاهيا' (بخير).","de":"Wird morgens zur Begrüßung gesagt; die Antwort lautet 'Lahiya lahiya' (gut).","en":"Said in the morning when meeting someone; the reply is 'Lahiya lahiya' (well)."},"transliteration":"Ina kwana?"}},{"id":"afr-003","version":2,"slug":"sheng-nairobi-s-youth-language-that-keeps-outgrowing-itself","contentType":"feature","category":"languages","title":{"ar":"شينغ: لغة شباب نيروبي التي تتجاوز نفسها","de":"Sheng: Nairobis Jugendsprache, die sich selbst überholt","en":"Sheng: Nairobi's youth language that keeps outgrowing itself"},"deck":{"ar":"لغة عمرانية سريعة التغير تجمع بين السواحلية والإنجليزية وتتجاوز الحدود","de":"Eine schnelllebige Stadtsprache aus Swahili und Englisch, die Grenzen überschreitet","en":"A fast-changing urban cant mixing Swahili and English, crossing borders"},"teaser":{"ar":"شينغ ليست لغة قبيلة بل لغة مدينة: تبدأ في الشارع، تنتقل إلى الأغاني والرسائل، وتتغير قبل أن يتعلمها الكبار.","de":"Sheng ist keine Stammessprache, sondern eine Stadtsprache: Sie entsteht auf der Straße, wandert in Lieder und Nachrichten und ändert sich, bevor Erwachsene sie lernen.","en":"Sheng is not a tribal language but a city language: it starts on the street, moves into songs and texts, and changes before adults catch up."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الشارع إلى الأغنية","paragraphs":["بدأت شينغ بين شباب نيروبي الحضريين كلغة مختلطة تجمع قواعد السواحلية مع كلمات إنجليزية واستعارات من الكيكويو واللو واللوهيا ولغات كينية أخرى. نشأت في محيط الحافلات الصغيرة (ماتاتو) والموسيقى وساحات المدارس، حيث يلتقي الشباب من خلفيات لغوية مختلفة.","ترتبط شينغ بثقافة الماتاتو والأغاني، ومفرداتها تتغير بسرعة كبيرة حتى أن المتحدثين الأكبر سناً غالباً ما لا يستطيعون متابعة العامية الحالية. هذا التبدل السريع جزء من هويتها: كل جيل يضيف طبقة جديدة."]},{"heading":"هوية عمرانية لا قبلية","paragraphs":["لأن شينغ غير مرتبطة بمجموعة عرقية واحدة، فهي تسمح للشباب بالتعبير عن هوية عمرانية بدلاً من الأصل العرقي. عندما يلتقي طالبان من لغتين مختلفتين في محطة ماتاتو، يجدان نفسيهما في شينغ خلال جملة واحدة.","انتشرت شينغ خارج نيروبي إلى مدن كينية أخرى وإلى تنزانيا وأوغندا، وتظهر الآن في الحملات السياسية والإذاعة والإعلانات. هذا الانتشار أثار نقاشاً بين المعلمين والممتحنين حول مكانها في المدارس، فهي نادراً ما تُكتب في السياقات الرسمية لكنها تزدهر في الرسائل النصية ووسائل التواصل الاجتماعي وكلمات الأغاني.","يختلف استخدام شينغ حسب المنطقة والجيل: فبعض الشباب في المدن الثانوية يستخدمون مفردات محلية مختلفة، بينما يقتصر استخدام الكبار لها على عبارات قليلة."]},{"heading":"لغة تتغير باستمرار","paragraphs":["شينغ ليست تنوعاً واحداً مستقراً؛ مفرداتها محلية وقصيرة العمر، وكثير من الكينيين يستخدمونها فقط في سياقات غير رسمية ومحددة بالعمر. هذا يعني أن ما يبدو «شينغ» اليوم قد يبدو قديماً بعد سنوات قليلة.","في النهاية، تظل شينغ مثالاً حياً على كيف يبتكر الشباب لغتهم الخاصة للتعبير عن الانتماء والتمييز في المدينة."]}],"de":[{"heading":"Von der Straße zum Lied","paragraphs":["Sheng entstand unter Nairobis Stadtjugend als eine Mischsprache, die Swahili-Grammatik mit englischen Wörtern und Entlehnungen aus Kikuyu, Luo, Luhya und anderen kenianischen Sprachen verbindet. Sie ist mit der Matatu-Kultur, der Musik und Schulhöfen verbunden, wo Jugendliche aus verschiedenen Sprachhintergründen zusammenkommen.","Sheng ist an die Matatu-Kultur und Musik gebunden, und sein Wortschatz wechselt so schnell, dass ältere Sprecher oft nicht mehr folgen können. Dieser schnelle Wandel ist Teil seiner Identität: Jede Generation fügt eine neue Schicht hinzu."]},{"heading":"Urbane Identität statt ethnischer Herkunft","paragraphs":["Weil Sheng nicht an eine einzige ethnische Gruppe gebunden ist, können junge Leute damit eine urbane Identität statt ihrer ethnischen Herkunft signalisieren. Wenn zwei Schüler mit unterschiedlichen Muttersprachen an einer Matatu-Haltestelle in Nairobi aufeinandertreffen, wechseln sie innerhalb eines Satzes in Sheng.","Sheng hat sich über Nairobi hinaus in andere kenianische Städte sowie nach Tansania und Uganda verbreitet und erscheint nun in politischen Kampagnen, im Radio und in der Werbung. Diese Verbreitung hat unter Lehrern und Prüfern eine Debatte über Sheng in Schulen ausgelöst; es wird selten in offiziellen Kontexten geschrieben, gedeiht aber in Textnachrichten, sozialen Medien und Songtexten.","Die Verwendung von Sheng variiert je nach Region und Generation: Jugendliche in kleineren Städten verwenden manchmal andere lokale Wörter, während Ältere oft nur wenige Ausdrücke kennen."]},{"heading":"Eine Sprache im ständigen Wandel","paragraphs":["Sheng ist keine einzelne stabile Varietät; sein Wortschatz ist lokal und kurzlebig, und viele Kenianer verwenden es nur in informellen, altersspezifischen Situationen. Was heute als Sheng gilt, kann in wenigen Jahren veraltet wirken.","Letztlich bleibt Sheng ein lebendiges Beispiel dafür, wie Jugendliche ihre eigene Sprache erfinden, um Zugehörigkeit und Abgrenzung in der Stadt auszudrücken."]}],"en":[{"heading":"From street to song","paragraphs":["Sheng began among Nairobi's urban youth as a cant mixing Swahili grammar with English words and borrowings from Kikuyu, Luo, Luhya and other Kenyan languages. It is tied to matatu culture, music and school playgrounds, where young people from different language backgrounds meet.","Sheng is tied to matatu culture and music, and its vocabulary turns over fast enough that older speakers often cannot follow current slang. This rapid turnover is part of its identity: each generation adds a new layer."]},{"heading":"Urban identity, not ethnic origin","paragraphs":["Because it is not tied to one ethnic group, Sheng lets young people signal urban identity rather than ethnic origin. When two students from different home languages meet at a Nairobi matatu stage, they settle into Sheng within a sentence.","Sheng has spread beyond Nairobi to other Kenyan towns and into Tanzania and Uganda, and it now appears in political campaigns, radio and advertising. This spread has sparked debate among teachers and examiners about Sheng in schools; it is rarely written in official contexts but thrives in text messages, social media and song lyrics.","The use of Sheng varies by region and generation: youth in smaller towns sometimes use different local vocabulary, while older people may know only a few phrases."]},{"heading":"A language always in motion","paragraphs":["Sheng is not a single stable variety; its vocabulary is local and short-lived, and many Kenyans use it only in informal, age-specific settings. What counts as Sheng today may sound dated in a few years.","Ultimately, Sheng remains a living example of how young people invent their own language to express belonging and distinction in the city."]}]},"context":{"countries":["KE"],"region":"Nairobi and urban Kenya","community":"Urban youth","continent":"africa","languages":["sw","en"],"period":"contemporary"},"tags":["languages","Nairobi and urban Kenya"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sheng slang","de":"Sheng slang","en":"Sheng slang"},"url":"https://en.wikipedia.org/wiki/Sheng_slang","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Languages of Kenya","de":"Languages of Kenya","en":"Languages of Kenya"},"url":"https://en.wikipedia.org/wiki/Languages_of_Kenya","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالبان من لغتين مختلفتين يلتقيان في محطة ماتاتو في نيروبي، ينتقلان إلى شينغ خلال جملة واحدة، ثم يعودان إلى الإنجليزية عندما تبدأ المحاضرة.","de":"Zwei Schüler mit unterschiedlichen Muttersprachen treffen sich an einer Matatu-Haltestelle in Nairobi, wechseln innerhalb eines Satzes in Sheng und schalten zurück ins Englische, als die Vorlesung beginnt.","en":"Two students from different home languages meet at a Nairobi matatu stage, settle into Sheng within a sentence, then switch back to English when the lecture starts."},"misunderstanding":{"ar":"شينغ ليست لغة واحدة ثابتة؛ مفرداتها محلية وقصيرة العمر، وكثير من الكينيين يستخدمونها فقط في سياقات غير رسمية ومحددة بالعمر.","de":"Sheng ist keine einzelne stabile Varietät; sein Wortschatz ist lokal und kurzlebig, und viele Kenianer verwenden es nur in informellen, altersspezifischen Situationen.","en":"Sheng is not a single stable variety; its vocabulary is local and short-lived, and many Kenyans use it only in informal, age-specific settings."},"comparison":{"ar":"بينما ترتبط اللغات القبلية بالأصل، تمنح شينغ الشباب وسيلة للتعبير عن هوية عمرانية مشتركة تتجاوز الانتماء العرقي.","de":"Während Stammessprachen an Herkunft gebunden sind, bietet Sheng Jugendlichen eine Möglichkeit, eine gemeinsame urbane Identität auszudrücken, die ethnische Grenzen überschreitet.","en":"While ethnic languages are tied to ancestry, Sheng gives young people a way to express a shared urban identity that crosses ethnic lines."},"expression":{"original":"Niaje?","language":"Sheng","gloss":{"ar":"كيف الحال؟ — تحية تشير إلى أنك جزء من نفس السجل الحضري","de":"Wie läuft's? — ein Gruß, der zeigt, dass man zum selben urbanen Register gehört","en":"How's it going? — a greeting that signals you are part of the same urban register"},"usage":{"ar":"تستخدم بين الشباب في نيروبي كتحية غير رسمية تعبر عن الانتماء إلى جيل المدينة.","de":"Wird unter Jugendlichen in Nairobi als informeller Gruß verwendet, der die Zugehörigkeit zur Stadtgeneration signalisiert.","en":"Used among young people in Nairobi as an informal greeting that signals belonging to the city generation."},"transliteration":"Niaje?"}},{"id":"afr-004","version":2,"slug":"n-ko-a-script-invented-in-1949-to-write-manding-without-french","contentType":"feature","category":"languages","title":{"ar":"نكو: كتابة ابتكرها سولومانا كانتيه لغةً للاستقلال","de":"N'Ko: Eine Schrift, die 1949 für das Manding erfunden wurde","en":"N'Ko: A Script Invented in 1949 for Manding"},"deck":{"ar":"حين اخترع سولومانا كانتيه خط نكو عام 1949، لم يكن يبحث عن حروف فقط، بل عن وسيلة ليعبّر الناس عن أنفسهم بلغتهم الأم بعيداً عن الفرنسية.","de":"Solomana Kanté schuf 1949 in Kankan eine eigene Schrift für die Manding-Sprachen – als Werkzeug der Alphabetisierung und der kulturellen Unabhängigkeit.","en":"Solomana Kanté created N'Ko in 1949 to give Manding speakers a writing system of their own—one that became a tool of معرفة القراءة والكتابة and cultural independence."},"teaser":{"ar":"ما الذي يجعل خطاً ابتُكر قبل سبعين عاماً رمزاً للهوية والمقاومة الثقافية؟ قصة نكو من كانكان إلى هواتف اليوم.","de":"Warum schreibt man in Teilen Westafrikas von rechts nach links in einer Schrift, die es erst seit 1949 gibt? Die Geschichte des N'Ko.","en":"Why do some West Africans write from right to left in a script less than a century old? The story of N'Ko, from a Guinean city to social media."},"readingMinutes":1,"sections":{"ar":[{"heading":"ولادة خط في كانكان","paragraphs":["في عام 1949، وفي مدينة كانكان بغينيا، ابتكر سولومانا كانتيه خطاً جديداً أسماه «نكو»، وهو تعبير يعني «أنا أقول» في لغات الماندنغ. لم يكن كانتيه يريد مجرد تدوين الأصوات، بل أراد أن يمنح المتحدثين بلغات الماندنغ وسيلة كتابة خاصة بهم، تُستخدم عبر غينيا ومالي وساحل العاج والدول المجاورة.","يُكتب نكو من اليمين إلى اليسار، على غرار العربية، لكن أشكال حروفه أصلية تماماً وليست مستعارة. هذا الاتجاه في الكتابة يعكس تأثير العربية في المنطقة، لكنه في الوقت نفسه يؤكد استقلالية الخط كهوية بصرية ولغوية مستقلة."]},{"heading":"أداة تعليم ومقاومة ثقافية","paragraphs":["ارتبط نكو منذ البداية بفكرة أن معرفة القراءة والكتابة باللغة الأم شكل من أشكال الاستقلال عن الفرنسية. فقد انتشرت دروس تعليم نكو في المجتمعات الناطقة بالماندنغ منذ الخمسينيات، وكانت تُقدَّم في مدارس خاصة ومدارس قرآنية، مما جعله أداة لنشر المعرفة الدينية والطبية.","اليوم، لا يقتصر استخدام نكو على التعليم، بل أصبح وسيلة تعبير يومية: تُطبع به صحف، وتُنشر نصوص دينية وإرشادات صحية، بل أصبح له خطوط رقمية خاصة به. ففي باماكو، يبيع أحد الكتبة كراسة لتعليم حروف نكو إلى جانب كتيب طبي مترجم إلى نكو، ويقرأ الزبون كليهما دون اللجوء إلى الفرنسية."]},{"heading":"بين المدارس الرسمية والهواتف","paragraphs":["مع إضافة دعم الحواسيب والهواتف المحمولة في العقد الأول من القرن الحادي والعشرين، أصبح نكو قابلاً للاستخدام في وسائل التواصل الاجتماعي والنشر الرقمي، مما وسّع دائرته بين الأجيال الشابة. لكن نكو ليس الخط الوحيد لكتابة الماندنغ؛ فلا تزال الكتابة القائمة على الحروف اللاتينية هي المعيار في المدارس الحكومية، كما أن إجادة نكو تتفاوت بين المناطق.","هذا التفاوت لا يقلل من أهمية نكو، بل يذكّرنا بأن معرفة القراءة والكتابة في أي مجتمع ليست حالة واحدة، بل نسيج من الممارسات والخيارات التي تتشكل حسب السياق المحلي والجيل."]}],"de":[{"heading":"Die Geburtsstunde in Kankan","paragraphs":["Im Jahr 1949 entwickelte Solomana Kanté in der guineischen Stadt Kankan die Schrift N'Ko für die Manding-Sprachen, die in Guinea, Mali, der Elfenbeinküste und den Nachbarländern gesprochen werden. Der Name bedeutet „ich sage“ auf Manding. Die Schrift wird von rechts nach links geschrieben, was teilweise an das Arabische erinnert, doch die Buchstabenformen sind eigenständig.","Kanté ging es nicht nur um die Fixierung von Lauten. Er wollte den Sprecherinnen und Sprechern der Manding-Sprachen ein eigenes Schriftsystem geben, das ihre Sprache und Identität sichtbar macht."]},{"heading":"Bildung als Akt der Unabhängigkeit","paragraphs":["Die N'Ko-Bewegung verstand Alphabetisierung in der eigenen Sprache als eine Form der Unabhängigkeit von der französischen Kolonialsprache. Seit den 1950er Jahren verbreiteten sich N'Ko-Kurse in den Manding-Gemeinschaften, oft in privaten Schulen und Koranschulen. Dort diente die Schrift nicht nur dem Lesen und Schreiben, sondern auch der Vermittlung religiöser und medizinischer Texte.","Bis heute ist N'Ko ein lebendiges Kommunikationsmittel: Es gibt Zeitungen, religiöse Schriften und Gesundheitsratgeber in N'Ko, und seit den 2000er Jahren auch digitale Schriftarten. Ein Buchhändler in Bamako verkauft zum Beispiel eine N'Ko-Fibel neben einer medizinischen Broschüre in N'Ko – und die Kundin liest beides, ohne ins Französische wechseln zu müssen."]},{"heading":"Zwischen Staatsschule und Smartphone","paragraphs":["Mit der Unterstützung durch Computer und Mobiltelefone ab den 2000er Jahren wurde N'Ko auch in sozialen Medien und im digitalen Publizieren nutzbar, was seine Reichweite unter jüngeren Generationen vergrößerte. Allerdings ist N'Ko nicht die einzige Schrift für Manding: In den staatlichen Schulen bleibt die lateinische Orthographie der Standard, und die N'Ko-Alphabetisierung ist regional unterschiedlich stark verbreitet.","Diese Ungleichzeitigkeit zeigt, dass Alphabetisierung keine einheitliche Errungenschaft ist, sondern ein Geflecht von Praktiken, das von lokalen Gegebenheiten und Generationen abhängt."]}],"en":[{"heading":"A Script Born in Kankan","paragraphs":["In 1949, in the Guinean city of Kankan, Solomana Kanté devised a new writing system for the Manding languages, spoken across Guinea, Mali, Côte d'Ivoire and neighbouring countries. He called it N'Ko, meaning 'I say' in Manding. The script runs from right to left, partly echoing Arabic, though its letter shapes are original.","Kanté's aim went beyond recording sounds. He wanted Manding speakers to have a script that was entirely their own, one that could carry their language and identity without relying on French."]},{"heading":"Literacy as an Act of Independence","paragraphs":["From the outset, the N'Ko movement treated معرفة القراءة والكتابة in one's own language as a form of independence from French. N'Ko classes spread through Manding-speaking communities from the 1950s, often held in private schools and Qur'anic schools. There, the script served not only for reading and writing but also for transmitting religious and medical texts.","Today N'Ko is a living medium: it has its own newspapers, religious publications and health pamphlets, as well as digital fonts. In Bamako, for instance, a bookseller sells a N'Ko alphabet primer next to a N'Ko translation of a medical pamphlet, and a customer reads both without switching to French."]},{"heading":"Between State Schools and Smartphones","paragraphs":["Computer and phone support added in the 2000s made N'Ko usable on social media and in publishing, widening its reach among younger generations. Yet N'Ko is not the only script for Manding: Latin-based orthographies remain standard in state schools, and N'Ko معرفة القراءة والكتابة is uneven across the region.","This unevenness is not a weakness but a reminder that معرفة القراءة والكتابة in any society is a patchwork of practices, shaped by local context and generation rather than a single uniform standard."]}]},"context":{"countries":["GN","ML"],"region":"Manding-speaking West Africa","community":"Manding","continent":"africa","languages":["bm","fr"],"period":"contemporary"},"tags":["languages","Manding-speaking West Africa","Solomana Kanté","The name"],"sources":[{"organization":"Wikipedia","title":{"ar":"N'Ko script","de":"N'Ko script","en":"N'Ko script"},"url":"https://en.wikipedia.org/wiki/N%27Ko_script","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Manding languages","de":"Manding languages","en":"Manding languages"},"url":"https://en.wikipedia.org/wiki/Manding_languages","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في باماكو، يبيع أحد الكتبة كراسة لتعليم حروف نكو إلى جانب كتيب طبي مترجم إلى نكو، ويقرأ الزبون كليهما دون اللجوء إلى الفرنسية.","de":"Ein Buchhändler in Bamako verkauft eine N'Ko-Fibel neben einer medizinischen Broschüre in N'Ko, und eine Kundin liest beides, ohne ins Französische zu wechseln.","en":"A bookseller in Bamako sells a N'Ko alphabet primer next to a N'Ko translation of a medical pamphlet, and a customer reads both without switching to French."},"misunderstanding":{"ar":"يعتقد البعض أن نكو مجرد نسخة من الأبجدية العربية أو أنه اختراع حديث بلا جذور، لكنه في الواقع خط أصلي الشكل، استُلهم اتجاه الكتابة من العربية فقط، وقد تطوّر عبر عقود من الاستخدام اليومي.","de":"Manche halten N'Ko für eine bloße Kopie der arabischen Schrift oder für eine moderne Erfindung ohne Wurzeln. Tatsächlich sind die Buchstabenformen eigenständig; nur die Schreibrichtung erinnert an das Arabische.","en":"Some assume N'Ko is merely a copy of the Arabic script or a recent invention without roots. In fact, its letter shapes are original; only the right-to-left direction echoes Arabic."},"comparison":{"ar":"في حين أن كثيراً من لغات غرب أفريقيا تستخدم الأبجدية اللاتينية أو العربية المعدلة، اختار نكو أن يكون خطاً أصلياً بالكامل، مما يجعله حالة نادرة في عالم الكتابات.","de":"Während viele westafrikanische Sprachen lateinische oder arabische Alphabete nutzen, ist N'Ko eine vollständig eigenständige Schrift – ein seltener Fall in der Geschichte der Schriftsysteme.","en":"While many West African languages use Latin or modified Arabic alphabets, N'Ko is a fully original script—a rare case in the history of writing systems."},"expression":{"original":"ߒߞߏ","language":"N'Ko / Manding","gloss":{"ar":"نكو — تعني حرفياً «أنا أقول» في لغات الماندنغ، وهو اسم الخط نفسه","de":"N'Ko – wörtlich „ich sage“ in den Manding-Sprachen und zugleich der Name der Schrift","en":"N'Ko — literally 'I say' in the Manding languages, and the name of the script itself"},"usage":{"ar":"تُستخدم الكلمة للإشارة إلى الخط وإلى حركة تعليم اللغة الأم، ويقول المتحدث بها «أنا أقرأ نكو» للدلالة على إجادة القراءة والكتابة بهذا الخط.","de":"Das Wort bezeichnet sowohl die Schrift als auch die Bewegung für Alphabetisierung in der Muttersprache. Wer sie beherrscht, sagt oft „Ich lese N'Ko“ und meint damit die Fähigkeit, in dieser Schrift zu lesen und zu schreiben.","en":"The word refers both to the script and to the movement for معرفة القراءة والكتابة in the mother tongue. A speaker might say 'I read N'Ko' to indicate the ability to read and write in this script."},"transliteration":"N'Ko"}},{"id":"afr-005","version":2,"slug":"tsotsitaal-and-camtho-the-township-registers-that-hide-and-reveal","contentType":"note","category":"languages","title":{"ar":"لغة الشوارع التي تخفي وتكشف","de":"Die Straßensprache, die verbirgt und zeigt","en":"The street register that hides and reveals"},"deck":{"ar":"سجلات لغوية في بلدات جنوب أفريقيا يبدّل بها الشباب هوياتهم في منتصف الجملة.","de":"Sprachregister in südafrikanischen Townships, in denen junge Leute mitten im Satz die Identität wechseln.","en":"Linguistic registers in South African townships where young people switch identity mid-sentence."},"teaser":{"ar":"كيف تصنع كلمة واحدة مكانة صاحبها في بلدة سويتو؟ رحلة في لغة تسوتسيتال وكامتو بين الأحياء والمسرح والأغنية.","de":"Wie ein einziges Wort über den Status entscheidet: Tsotsitaal und Camtho zwischen Hinterhof, Bühne und Popsong.","en":"How one word can place a speaker in a Soweto street: Tsotsitaal and Camtho between back yard, stage and pop song."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الخليط تولد لغة","paragraphs":["نشأت تسوتسيتال في بلدات جوهانسبرغ من امتزاج الأفريكانية والزولو والسوتو والتسوانا والإنجليزية، والاسم نفسه يجمع كلمة «تسوتسي» أي السفّاح بالأفريكانية «taal» أي اللغة. وهي ليست لغة أمّ لأحد، بل سجل لغوي ينتقل إليه المتكلم ليرمز إلى الأناقة أو القوة أو التضامن ثم يعود إلى لغته الأصلية.","أما كامتو فهي السجل الأحدث في البلدات ذاتها، وأكثر اعتمادًا على الزولو والسوتو، وتتغير بسرعة متعمّدة كي يبقى الغرباء خارج الدائرة. وتحمل هذه السجلات مفردات خاصة بالمال والشرطة والسجن والمكانة الاجتماعية، وقد غذّت الموسيقى والسينما والإعلان في جنوب أفريقيا."]},{"heading":"من يتكلمها ومتى","paragraphs":["لأن هذه السجلات تختزن هوية محلية، فإنها تُؤدّى بوعي: يستخدمها الشبان، ويشكو منها الآباء، ويدرسها الباحثون بوصفها تغيّرًا لغويًا حضريًا. وفي محطة سيارات الأجرة في سويتو يحيّي شابان بعضهما بالكامتو، ثم ينتقلان إلى الزولو ليشركا امرأة مسنّة، ثم يعودان إلى الكامتو بعد أن تغادر.","لكن الحدود ليست ثابتة: تختلف المفردات من بلدة إلى أخرى ومن جيل إلى جيل، ويتداخل الاسمان في الاستعمال اليومي، فلا يصحّ التعامل معهما كشيفرة واحدة موحّدة."]}],"de":[{"heading":"Aus dem Gemisch entsteht eine Sprache","paragraphs":["Tsotsitaal entstand in den Townships Johannesburgs aus einem Gemisch von Afrikaans, Zulu, Sotho, Tswana und Englisch; das Wort verbindet „tsotsi“ (Ganove) mit dem afrikaansen „taal“ (Sprache). Es ist keine Muttersprache, sondern ein Register: Sprecher wechseln hinein, um Stil, Härte oder Zusammenhalt zu zeigen, und kehren danach in ihre Herkunftssprache zurück.","Camtho (iscamtho) ist das neuere, stärker auf Zulu und Sotho gegründete Register derselben Townships, und es verändert sich bewusst schnell, damit Außenstehende ratlos bleiben. Beide Register haben eigenes Vokabular für Geld, Polizei, Gefängnis und Status und haben Musik, Film und Werbung in Südafrika geprägt."]},{"heading":"Wer spricht sie, und wann","paragraphs":["Weil sie lokale Identität transportieren, werden sie bewusst aufgeführt: junge Männer nutzen sie, Eltern beklagen sie, und Forschende untersuchen sie als städtischen Sprachwandel. An einem Taxistand in Soweto begrüßen sich zwei junge Männer auf Camtho, wechseln ins Zulu, um eine ältere Frau einzubeziehen, und kehren zum Camtho zurück, sobald sie gegangen ist.","Doch die Grenzen sind fließend: Das Vokabular unterscheidet sich je nach Township und Generation, und im Alltag überschneiden sich beide Namen, sodass man sie nicht als einen festen Code behandeln sollte."]}],"en":[{"heading":"A language born from a mixture","paragraphs":["Tsotsitaal grew in Johannesburg's townships from mixed Afrikaans, Zulu, Sotho, Tswana and English; the word joins 'tsotsi' (thug) with Afrikaans 'taal' (language). It is a register rather than a mother tongue: speakers switch into it to mark style, toughness or solidarity, then return to their home language.","Camtho (iscamtho) is the newer, more Zulu- and Sotho-based register of the same townships, and it changes quickly to keep outsiders guessing. Both registers carry vocabulary for money, police, prison and status, and they have fed South African music, film and advertising."]},{"heading":"Who speaks them, and when","paragraphs":["Because they encode local identity, they are performed self-consciously: young men use them, parents complain about them, and researchers study them as urban language change. In a Soweto taxi rank two young men greet in Camtho, switch to Zulu to include an older woman, then return to Camtho once she has gone.","But the boundaries are not fixed: vocabularies differ by township and generation, and the two names overlap in everyday use, so they should not be treated as one uniform code."]}]},"context":{"countries":["ZA"],"region":"Gauteng townships, South Africa","community":"Township youth","continent":"africa","languages":["zu","st","af","en"],"period":"contemporary"},"tags":["languages","Gauteng townships, South Africa","Tsotsitaal grew","It is"],"sources":[{"organization":"Wikipedia","title":{"ar":"Tsotsitaal and Camtho","de":"Tsotsitaal and Camtho","en":"Tsotsitaal and Camtho"},"url":"https://en.wikipedia.org/wiki/Tsotsitaal_and_Camtho","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Fanagalo","de":"Fanagalo","en":"Fanagalo"},"url":"https://en.wikipedia.org/wiki/Fanagalo","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في محطة سيارات الأجرة في سويتو يحيّي شابان بعضهما بالكامتو، ثم ينتقلان إلى الزولو ليشركا امرأة مسنّة، ثم يعودان إلى الكامتو بعد أن تغادر.","de":"An einem Taxistand in Soweto begrüßen sich zwei junge Männer auf Camtho, wechseln ins Zulu, um eine ältere Frau einzubeziehen, und kehren zum Camtho zurück, sobald sie gegangen ist.","en":"In a Soweto taxi rank two young men greet in Camtho, switch to Zulu to include an older woman, then return to Camtho once she has gone."},"misunderstanding":{"ar":"يظنّ كثيرون أنها لغة سرية للخارجين عن القانون، لكنها في الواقع سجل أسلوبي يستخدمه طلاب وعاملون وفنانون في حياتهم اليومية.","de":"Viele halten sie für eine Geheimsprache von Kriminellen; tatsächlich ist es ein stilistisches Register, das Studierende, Arbeiter und Musiker täglich verwenden.","en":"Many assume it is a secret code of criminals, but it is really a stylistic register used daily by students, workers and musicians."},"comparison":{"ar":"كما تنتقل جماعات مدينية في أماكن أخرى بين لهجة محلية ولغة معيارية حسب من يخاطبونه، يبدّل متكلمو البلدات السجل نفسه في الجملة الواحدة.","de":"So wie Stadtbewohner anderswo je nach Gegenüber zwischen Dialekt und Standardsprache wechseln, wechseln Township-Sprecher das Register mitten im Satz.","en":"Just as city dwellers elsewhere move between local dialect and standard language depending on who is listening, township speakers switch register mid-sentence."},"expression":{"original":"tsotsi","language":"Tsotsitaal (from Sesotho)","gloss":{"ar":"سفّاح أو خارج عن القانون — الكلمة التي منحت تسوتسيتال اسمها","de":"Ganove oder Krimineller — das Wort, das Tsotsitaal seinen Namen gab","en":"thug or gangster — the word that gave Tsotsitaal its name"},"usage":{"ar":"تُستعمل في الكلام اليومي لوصف شخص عنيف أو خطير، ومنها اشتُقّ اسم السجل اللغوي نفسه.","de":"Im Alltag bezeichnet es eine gewalttätige oder gefährliche Person; davon leitet sich der Name des Registers selbst ab.","en":"In everyday speech it describes a violent or dangerous person, and from it the name of the register itself derives."},"transliteration":"tsotsi"}},{"id":"afr-006","version":2,"slug":"lingala-the-river-language-that-became-two-capitals-lingua-franca","contentType":"feature","category":"languages","title":{"ar":"لينغالا: لغة النهر التي تجمع عاصمتين","de":"Lingala: die Flusssprache zweier Hauptstädte","en":"Lingala, the river language of two capitals"},"deck":{"ar":"من لغة تجارة على ضفاف الكونغو إلى صوت الموسيقى الشعبية في كينشاسا وبرازافيل.","de":"Wie aus einer Handelssprache am Kongo die Alltagssprache von Kinshasa und Brazzaville und der Sound der kongolesischen Popmusik wurde.","en":"How a trading tongue on the Congo became the everyday speech of Kinshasa and Brazzaville and the sound of Congolese pop."},"teaser":{"ar":"كيف صارت لغة تجارية على ضفاف النهر لساناً يومياً لعشرات الملايين في عاصمتين تفصل بينهما حدود وسياسة؟","de":"Eine Sprache, die am Fluss entstand, heute von rund vierzig Millionen Menschen verstanden wird und in zwei Hauptstädten über eine Staatsgrenze hinweg verbindet.","en":"A language born on the river now carries daily life across a state border, shapes hit songs, and shifts with every generation of city slang."},"readingMinutes":1,"sections":{"ar":[{"heading":"من ممر تجاري إلى لسان يومي","paragraphs":["نشأت اللينغالا في أواخر القرن التاسع عشر كلغة تعامل على طول نهر الكونغو، حيث كان التجار بحاجة إلى وسيلة تفاهم تتجاوز لغاتهم المحلية. ثم تبنّاها الجيش الاستعماري والإدارة، فانتشرت خارج دائرتها الأصلية الأولى. واليوم يتحدثها نحو عشرين مليون نسمة كلغة أم، ومثلهم كلغة ثانية، وهي لغة أساسية في شمال غرب الكونغو الديمقراطية والنصف الشمالي من جمهورية الكونغو، بما في ذلك كينشاسا وبرازافيل.","تكتب اللينغالا بحروف لاتينية وفق إملاء معياري، لكن الاستعمال اليومي يظل شفهياً في المقام الأول: في الأسواق والإذاعات وفي الأغاني. وهي اللغة الرئيسية للموسيقى الشعبية الكونغولية، ومنها انتقلت إلى مسامع المستمعين في أنحاء القارة."]},{"heading":"لغة الشارع التي تتغير مع كل جيل","paragraphs":["لينغالا الشوارع في كينشاسا تمزج الفرنسية بالعامية المحلية، فتتغير مع كل جيل. لذلك تبدو لغة أغاني الرومبا في الستينيات مختلفة عن لغة أغنية من العشرينيات والألفين.","في السوق، قد يفتتح بائع كلامه باللينغالا، ثم يذكر الأسعار بأرقام فرنسية، ويتحول إلى السواحيلية لزبون قادم من شرق البلاد. هذا التنقل السلس بين اللغات هو ما يجعل اللينغالا عملية في الحياة اليومية أكثر من كونها لغة رسمية صارمة."]},{"heading":"لغة مشتركة لا لغة الجميع","paragraphs":["ليست اللينغالا لغة كل الكونغوليين: فالسواحيلية والتشيلوبا والكيكونغو تهيمن على مناطق أخرى، ولكل من اللغات الوطنية الأربع مكانة مختلفة في الحياة العامة والتعليم. كما أن مستوى الفرنسية يتفاوت بين المدن والأرياف وبين الأجيال.","ومع ذلك، تبقى اللينغالا اللغة التي تعبر الحدود بين كينشاسا وبرازافيل، إذ يفهمها السكان على الضفتين ويستخدمونها في التجارة والترفيه. هذه الوظيفة العابرة للحدود تفسر لماذا تطورت اللغة في المدينتين معاً رغم اختلاف الإدارتين."]}],"de":[{"heading":"Vom Handelsweg zur Alltagssprache","paragraphs":["Lingala entstand im späten 19. Jahrhundert als Handelssprache entlang des Kongo, wo Händler eine gemeinsame Verständigungsbasis brauchten. Später griffen Kolonialarmee und Verwaltung darauf zurück und trugen sie weit über ihre ursprüngliche Gemeinschaft hinaus. Heute hat Lingala rund zwanzig Millionen Muttersprachler und ebenso viele Zweitsprachler; sie ist im Nordwesten der Demokratischen Republik Kongo und in der nördlichen Hälfte der Republik Kongo zu Hause, also auch in Kinshasa und Brazzaville.","Geschrieben wird Lingala in lateinischer Schrift mit einer standardisierten Orthografie, doch der Alltag ist vor allem mündlich: auf Märkten, im Radio und im Gesang. Als Hauptsprache der kongolesischen Popmusik hat sie ein Publikum weit über die Region hinaus erreicht."]},{"heading":"Straßensprache im Wandel","paragraphs":["Das Lingala der Straße in Kinshasa mischt Französisch mit Slang und verändert sich mit jeder Generation. Deshalb klingt die Sprache der Rumba aus den 1960er Jahren anders als die eines Songs aus den 2020er Jahren.","Auf dem Markt eröffnet eine Händlerin das Gespräch auf Lingala, nennt die Preise mit französischen Zahlwörtern und wechselt für einen Kunden aus dem Osten des Landes ins Swahili. Dieses gleitende Wechseln zwischen Sprachen macht Lingala im Alltag praktischer als jede strenge Standardnorm."]},{"heading":"Gemeinsame Sprache, nicht Sprache aller","paragraphs":["Lingala ist nicht die Sprache aller Kongolesen: Swahili, Tshiluba und Kikongo prägen andere Regionen, und die vier Nationalsprachen haben unterschiedliches Ansehen in Schule und Öffentlichkeit. Auch das Niveau des Französischen unterscheidet sich zwischen Stadt und Land und zwischen den Generationen.","Trotzdem bleibt Lingala die Sprache, die Kinshasa und Brazzaville verbindet: Auf beiden Ufern wird sie verstanden und in Handel und Unterhaltung genutzt. Diese grenzüberschreitende Funktion erklärt, warum sich die Sprache in beiden Städten trotz getrennter Verwaltungen gemeinsam weiterentwickelt hat."]}],"en":[{"heading":"From trade route to everyday speech","paragraphs":["Lingala grew in the late nineteenth century as a trade language along the Congo River, where traders needed a shared way to understand each other. The colonial army and administration later adopted it, pushing it far beyond its original speakers. Today it has roughly twenty million native speakers and another twenty million second-language speakers, and it is at home in north-western DR Congo and the northern half of the Republic of the Congo, including Kinshasa and Brazzaville.","It is written in the Latin alphabet with a standard orthography, but daily use is mostly spoken, sung and broadcast. As the main language of Congolese popular music, it has carried its sound well beyond the region."]},{"heading":"A street language that reinvents itself","paragraphs":["Kinshasa street Lingala mixes French and slang and changes with each generation, so the language of 1960s rumba sounds different from that of a 2020s song.","At a market, a trader opens in Lingala, gives prices in French numbers, and switches to Swahili for a customer from the east of the country. That easy sliding between languages is what makes Lingala practical in daily life rather than a rigid standard."]},{"heading":"Shared language, not everyone's language","paragraphs":["Lingala is not the language of all Congolese: Swahili, Tshiluba and Kikongo dominate other regions, and the four national languages carry different status in schools and public life. Levels of French, too, differ between city and countryside and between generations.","Still, Lingala remains the language that links Kinshasa and Brazzaville, understood on both banks and used in trade and entertainment. That cross-border role explains why the language developed in tandem in the two cities despite separate administrations."]}]},"context":{"countries":["CD","CG"],"region":"Congo Basin — Kinshasa and Brazzaville","community":"Lingala speakers","continent":"africa","languages":["ln","fr"],"period":"contemporary"},"tags":["languages","Congo Basin — Kinshasa and Brazzaville","Lingala is","It grew"],"sources":[{"organization":"Wikipedia","title":{"ar":"Lingala","de":"Lingala","en":"Lingala"},"url":"https://en.wikipedia.org/wiki/Lingala","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Kinshasa","de":"Kinshasa","en":"Kinshasa"},"url":"https://en.wikipedia.org/wiki/Kinshasa","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في سوق كينشاسا، يفتتح تاجر الحديث باللينغالا، ويذكر الأسعار بأرقام فرنسية، ثم ينتقل إلى السواحيلية لزبون قادم من شرق البلاد.","de":"Auf einem Markt in Kinshasa begrüßt eine Händlerin den Kunden auf Lingala, nennt die Preise mit französischen Zahlwörtern und wechselt für einen Kunden aus dem Osten ins Swahili.","en":"At a Kinshasa market, a trader opens in Lingala, gives prices in French numbers, then switches to Swahili for a customer from the east of the country."},"misunderstanding":{"ar":"كثيراً ما يُفترض أن اللينغالا لغة وطنية موحدة لكل الكونغوليين، لكنها في الواقع واحدة من أربع لغات وطنية ذات مكانات متفاوتة، والسواحيلية هي الأوسع في الشرق.","de":"Häufig wird angenommen, Lingala sei die gemeinsame Nationalsprache aller Kongolesen. Tatsächlich ist sie eine von vier Nationalsprachen mit unterschiedlichem Status, und im Osten dominiert Swahili.","en":"It is often assumed that Lingala is the shared national language of all Congolese. In fact it is one of four national languages with differing status, and Swahili dominates in the east."},"comparison":{"ar":"كما تخدم السواحيلية شرق أفريقيا كلغة تواصل عابرة للجماعات، تؤدي اللينغالا وظيفة مماثلة في حوض الكونغو، لكنها ترتبط تحديداً بالنهر والموسيقى الشعبية.","de":"Ähnlich wie Swahili in Ostafrika dient Lingala als Verkehrssprache zwischen verschiedenen Gruppen, ist aber stärker an den Fluss und die Popmusik gebunden.","en":"Much like Swahili in East Africa, Lingala works as a lingua franca between different communities, though it is more closely tied to the river and to popular music."},"expression":{"original":"Mbote","language":"Lingála","gloss":{"ar":"تحية تعني «مرحباً»، وهي التحية اليومية في كينشاسا وبرازافيل","de":"Hallo – der alltägliche Gruß in Kinshasa und Brazzaville","en":"Hello — the everyday greeting in Kinshasa and Brazzaville"},"usage":{"ar":"تُقال عند اللقاء وفي افتتاح الحديث مع الغرباء والأصدقاء على حد سواء، وغالباً يتبعها سؤال عن الحال. وفي الإذاعة والأغاني تفتتح بها العروض، ما يجعلها من أكثر الكلمات تردداً في الحياة العامة.","de":"Mbote sagt man beim Treffen und zu Beginn eines Gesprächs, unter Fremden wie unter Freunden, oft gefolgt von einer Frage nach dem Befinden. In Radio und Musik eröffnet der Gruß Sendungen und Lieder, weshalb er zu den meistgehörten Wörtern des öffentlichen Lebens zählt.","en":"Mbote is said on meeting and to open a conversation, with strangers and friends alike, often followed by a question about how things are. On radio and in songs it opens broadcasts and tracks, which makes it one of the most frequently heard words in public life."},"transliteration":"Mbote"}},{"id":"afr-007","version":2,"slug":"swahili-the-coast-s-language-that-became-east-africa-s-common-tongue","contentType":"feature","category":"languages","title":{"ar":"كيف صارت لغة الساحل جسراً لشرق أفريقيا","de":"Wie eine Küstensprache Ostafrika verband","en":"How a Coastal Tongue Became East Africa's Bridge"},"deck":{"ar":"نشأت السواحيلية في تجارة المحيط الهندي، وصارت اليوم لغة المدارس والبرلمانات والحافلات في شرق أفريقيا.","de":"Swahili entstand im Handel des Indischen Ozeans und trägt heute Schulen, Parlamente und alltägliche Busfahrten in Ostafrika.","en":"Swahili grew out of Indian Ocean trade and now carries schools, parliaments and everyday bus rides across East Africa."},"teaser":{"ar":"وُلدت على الساحل وصقلتها التجارة، ثم انتقلت إلى الأسواق والفصول والبرلمانات؛ غالباً كلغة ثانية، ونادراً كلغة أم للجميع.","de":"An der Küste geboren und vom Handel geprägt, bewegt sich Swahili heute zwischen Märkten, Klassenzimmern und Parlamenten — oft als Zweitsprache, selten als Muttersprache aller.","en":"Born on the coast and shaped by trade, Swahili now moves between markets, classrooms and parliaments — often as a second language, rarely as everyone's mother tongue."},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة بانتو صقلها البحر","paragraphs":["السواحيلية لغة بانتو نشأت على ساحل شرق أفريقيا. واقتراضها الواسع من العربية يعكس قروناً من تجارة المحيط الهندي وانتشار الإسلام على الساحل نفسه. لم تصل اللغة كمعيار واحد مصدَّر، بل تشكّلت في المرافئ والمستوطنات حيث عاشت جماعات ناطقة بالبانتو وتجار وعلماء في تواصل مستمر.","وهي اليوم لغة رسمية أو وطنية في تنزانيا وكينيا وأوغندا، وتُستخدم في جمهورية الكونغو الديمقراطية ورواندا وبوروندي وموزمبيق وجزر القمر. وتقدَّر أعداد متحدثيها بما بين أربعين ومئتي مليون نسمة. ومعظمهم يستخدمونها لغة ثانية لا لغة أم، ولهذا يمكن لتحية مثل «Habari yako?» — أي «ما أخبارك؟» حرفياً — أن تفتح حديثاً من دون افتراض لغة بيت مشتركة."]},{"heading":"توحيد لسان مشترك","paragraphs":["تم تقعيد السواحيلية المعيارية في ثلاثينيات القرن العشرين حول لهجة زنجبار كيونغوجا. منح ذلك الاختيار المدارس والبرلمانات ومجموعة شرق أفريقيا مرجعاً مشتركاً، لكنه لم يسوِّ اللغة. فمتحدثو الساحل والداخل والكونغو قد يبدون مختلفين بوضوح، والمعيار يُتعلَّم ولا يُورَث تلقائياً."]},{"heading":"من يتحدثها، وأين؟","paragraphs":["جعلت حقبة الأوجاما والتعليم الابتدائي الشامل في تنزانيا السواحيلية مهيمنة على الحياة العامة بدرجة غير معتادة. وفي كينيا، على النقيض، ظل الإنجليزية مهماً في كثير من الأعمال الرسمية، فلا تعطي البلدان السواحيلية الوزن اليومي نفسه. فسائق حافلة في دار السلام ينادي المحطات بالسواحيلية، ويعيد الأجرة بالإنجليزية لزائر، ثم يعود إلى المزاح مع الركاب المعتادين بالسواحيلية.","لكن الوضع الرسمي لا يعني أن الجميع يتحدثون السواحيلية في البيت. فللريف في تنزانيا وكينيا لغات أولى كثيرة، والسواحيلية الكونغولية تختلف اختلافاً حاداً عن معيار الساحل. تعمل اللغة أداة عامة مشتركة في إقليم تظل فيه الحياة الخاصة متعددة اللغات."]}],"de":[{"heading":"Eine Bantusprache, vom Meer geprägt","paragraphs":["Swahili ist eine Bantusprache, die an der ostafrikanischen Küste entstand. Die starken arabischen Entlehnungen spiegeln Jahrhunderte des Handels im Indischen Ozean und die Ausbreitung des Islam entlang derselben Küste. Die Sprache kam nicht als einheitlicher Exportstandard an; sie bildete sich in Häfen und Siedlungen, in denen bantusprachige Gemeinschaften, Händler und Gelehrte dauerhaft miteinander zu tun hatten.","Heute ist Swahili in Tansania, Kenia und Uganda Amts- oder Nationalsprache und wird in der DR Kongo, in Ruanda, Burundi, Mosambik und auf den Komoren verwendet. Schätzungen zu den Sprecherzahlen reichen von etwa 40 Millionen bis 200 Millionen. Die meisten Menschen sprechen es als Zweitsprache, nicht als Muttersprache. Darum kann die Begrüßung Habari yako? — wörtlich „deine Nachrichten?“ — ein Gespräch eröffnen, ohne eine gemeinsame Haussprache vorauszusetzen."]},{"heading":"Ein gemeinsamer Standard","paragraphs":["Standardswahili wurde in den 1930er-Jahren rund um den Dialekt Kiunguja aus Sansibar kodifiziert. Diese Wahl gab Schulen, Parlamenten und der Ostafrikanischen Gemeinschaft einen gemeinsamen Bezugspunkt, ebnete die Sprache aber nicht ein. Küstenbewohner, Menschen aus dem Landesinneren und Sprecher in der DR Kongo können deutlich verschieden klingen; der Standard wird gelernt, nicht einfach geerbt."]},{"heading":"Wer es spricht — und wo","paragraphs":["Tansanias Ujamaa-Ära und die allgemeine Grundschulbildung machten Swahili im öffentlichen Leben ungewöhnlich dominant. In Kenia blieb Englisch dagegen für vieles im offiziellen Geschäftsverkehr wichtig, sodass beide Länder dem Swahili nicht dasselbe Alltagsgewicht geben. Ein Busschaffner in Daressalam ruft die Haltestellen auf Swahili aus, wiederholt den Fahrpreis für einen Besucher auf Englisch und scherzt dann wieder mit den Stammgästen auf Swahili.","Der offizielle Status heißt dennoch nicht, dass alle zu Hause Swahili sprechen. Im ländlichen Tansania und Kenia gibt es viele Erstsprachen, und das Swahili im Kongo unterscheidet sich stark vom Küstenstandard. Die Sprache funktioniert als gemeinsames öffentliches Werkzeug in einer Region, in der das Privatleben mehrsprachig bleibt."]}],"en":[{"heading":"A Bantu Language Shaped by the Sea","paragraphs":["Swahili is a Bantu language that grew along the East African coast. Its heavy Arabic borrowing reflects centuries of Indian Ocean trade and the spread of Islam along the same shoreline. The language did not arrive as a single exported standard; it took shape in ports and settlements where Bantu-speaking communities, traders and scholars lived in sustained contact.","Today it is an official or national language in Tanzania, Kenya and Uganda, and it is used in DR Congo, Rwanda, Burundi, Mozambique and the Comoros. Estimates of its speakers range from about 40 million to 200 million. Most of those people use Swahili as a second language rather than a mother tongue, which explains why the greeting Habari yako? — literally 'your news?' — can open a conversation without assuming a shared home language."]},{"heading":"Standardising a Shared Tongue","paragraphs":["Standard Swahili was codified in the 1930s around the Zanzibar dialect Kiunguja. That choice gave schools, parliaments and the East African Community a common reference point, but it did not flatten the language. Coastal speakers, inland speakers and Congolese speakers can sound markedly different, and the standard is learned rather than simply inherited."]},{"heading":"Who Speaks It, and Where","paragraphs":["Tanzania's ujamaa era and universal primary education made Swahili unusually dominant in public life. In Kenya, by contrast, English has remained important for much official business, so the two countries do not give Swahili the same everyday weight. A bus conductor in Dar es Salaam can call the stops in Swahili, repeat the fare in English for a visitor, then joke with the regulars in Swahili again.","Official status still does not mean everyone speaks Swahili at home. Rural Tanzania and Kenya have many first languages, and Congolese Swahili differs sharply from the coastal standard. The language works as a shared public tool across a region where private life remains multilingual."]}]},"context":{"countries":["TZ","KE","UG"],"region":"East African coast and interior","community":"Swahili speakers","continent":"africa","languages":["sw","en"],"period":"contemporary"},"tags":["languages","East African coast and interior","Swahili is","It is"],"sources":[{"organization":"Wikipedia","title":{"ar":"Swahili","de":"Swahili","en":"Swahili"},"url":"https://en.wikipedia.org/wiki/Swahili","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Swahili culture","de":"Swahili culture","en":"Swahili culture"},"url":"https://en.wikipedia.org/wiki/Swahili_culture","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"سائق حافلة في دار السلام ينادي المحطات بالسواحيلية، ويعيد الأجرة بالإنجليزية لزائر، ثم يمزح مع الركاب المعتادين بالسواحيلية مرة أخرى.","de":"Ein Busschaffner in Daressalam ruft die Haltestellen auf Swahili aus, wiederholt den Fahrpreis für einen Besucher auf Englisch und scherzt dann wieder mit den Stammgästen auf Swahili.","en":"A bus conductor in Dar es Salaam calls the stops in Swahili, repeats the fare in English for a visitor, then jokes with the regulars in Swahili again."},"misunderstanding":{"ar":"أن السواحيلية عربية في جوهرها، أو أن كل سكان شرق أفريقيا يتحدثونها لغة أم. هي لغة بانتو ذات اقتراض عربي واسع، ومعظم متحدثيها يتعلمونها لغة ثانية.","de":"Dass Swahili im Kern Arabisch mit Bantu-Wörtern sei oder dass alle in Ostafrika es als Muttersprache sprechen. Es ist eine Bantusprache mit umfangreichen arabischen Entlehnungen, und die meisten Sprecher lernen es als Zweitsprache.","en":"That Swahili is essentially Arabic with Bantu words, or that everyone in East Africa speaks it as a mother tongue. It is a Bantu language with substantial Arabic borrowing, and most speakers learn it as a second language."},"comparison":{"ar":"تسير الحياة العامة في تنزانيا غالباً بالسواحيلية، بينما تحتفظ كينيا بالإنجليزية في كثير من الأعمال الرسمية.","de":"In Tansania läuft das öffentliche Leben weitgehend auf Swahili, während Kenia für vieles im offiziellen Geschäftsverkehr beim Englischen bleibt.","en":"Tanzania's public life runs largely in Swahili, while Kenya often keeps English for official business."},"expression":{"original":"Habari yako?","language":"Kiswahili","gloss":{"ar":"كيف حالك؟ — حرفياً «ما أخبارك؟»","de":"Wie geht es dir? — wörtlich „deine Nachrichten?“","en":"How are you? — literally 'your news?'"},"usage":{"ar":"تحية معيارية تُقال للغرباء والجيران والزملاء، وتدعو إلى رد موجز عن الأخبار من دون أن تفرض تفاصيل شخصية.","de":"Eine Standardbegrüßung unter Fremden, Nachbarn und Kolleginnen; sie lädt zu einer kurzen Antwort über die eigenen Neuigkeiten ein, ohne persönliche Details zu verlangen.","en":"A standard greeting used with strangers, neighbours and colleagues; it invites a brief reply about one's news rather than demanding personal detail."},"transliteration":"Habari yako?"}},{"id":"afr-008","version":2,"slug":"krio-the-sierra-leonean-creole-that-unites-a-multilingual-state","contentType":"feature","category":"languages","title":{"ar":"الكريو، اللغة التي توحّد سيراليون","de":"Die Kreolsprache, die Sierra Leone zusammenhält","en":"The Creole That Holds Sierra Leone Together"},"deck":{"ar":"لغة الكريو تتيح لبلدٍ تتعدّد فيه اللغات الأم أن يتحدّث مع نفسه: في الأسواق والإذاعات والكنائس.","de":"Krio ermöglicht einem Land mit vielen Muttersprachen das Gespräch — auf dem Markt, im Radio und in der Kirche.","en":"Krio lets a country of many mother tongues talk to itself — in markets, on the radio and in church."},"teaser":{"ar":"قلّة فقط تنشأ على الكريو كلغة أم، لكنّ معظم أهل سيراليون يستخدمونها يوميًا. كيف تصبح لغةٌ واحدة مفتاحًا للحياة اليومية في بلدٍ متعدّد اللغات؟","de":"Nur eine Minderheit wächst mit Krio als Erstsprache auf, doch fast alle in Sierra Leone nutzen es täglich. Eine Sprache, die den Alltag erst möglich macht.","en":"Only a small minority grow up speaking Krio, yet almost everyone in Sierra Leone uses it. A look at the language that makes daily business possible."},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة وُلدت في مدينة ميناء","paragraphs":["الكريو لغة كريولية أساسها الإنجليزية نشأت بين المحرَّرين من العبودية وذريتهم في فريتاون منذ أواخر القرن الثامن عشر. تستمدّ مفرداتها من الإنجليزية واليوروبا والبرتغالية وكلماتٍ من أصل فرنسي، لكنها ليست إنجليزيةً مشوّهة: لها قواعدها وأدواتها وأمثالها التي يستخدمها الناس في الجدال والمزاح وتسوية الخلافات، وكثيرًا ما تُستدعى هذه الأمثال لتلخيص موقفٍ ما أو لإغلاق نقاش.","اليوم يتحدّث الكريو نحو 96 في المئة من سكان سيراليون، وأكثرهم يتعلّمونها لغةً ثانية. وهي الجسر العملي بين التيمنه والمندي والليمبا وسواها من المجموعات: اللغة التي يلجأ إليها الناس حين يتاجرون أو يسافرون أو يحتاجون إلى أن يُفهموا خارج جماعتهم."]},{"heading":"صوت السوق والمذياع","paragraphs":["في فريتاون الكريو هي لغة الحياة اليومية ووسائل الإعلام الأساسية، ولها رصيد من الأدب المكتوب والمسرح وترجمات الكتاب المقدّس. وهي تعيش إلى جانب الهوية العِرقية الكريولية لدى كريول فريتاون، وهو تمييز جدير بالانتباه، إذ إنّ معظم متحدّثيها ليسوا من الكريول عِرقًا.","تُظهر السوق كيف تعمل هذه اللغة: مزارع من المندي وتاجر من التيمنه يتّفقان على السعر بالكريو، ثم يعود كلٌّ منهما إلى لغته مع أقاربه المنتظرين قريبًا. وغالبًا ما يفتتح الناس الحديث بـ«Kushɛ»، التحيّة اليومية في فريتاون، قبل أن يُطرح أيّ أمر عملي."]},{"heading":"لماذا تحمل لغةٌ واحدة كلّ هذا؟","paragraphs":["تبقى الكريو حيّة لأنها لا تخصّ جماعةً وحدها وتنفع الجميع. فمن ينشأ في العاصمة يسمعها في البيت والشارع، ومن ينشأ في الأقاليم يلتقطها عبر التعامل والسماع أكثر مما يلتقطها من الكتب، وهذا الاختلاف نفسه يحدّد طريقة التحدّث ومدى الكتابة بها. وهي ليست مطابقة للإنجليزية الفصحى، فالمدارس وشؤون الحكم تعتمد حتى اليوم اعتمادًا كبيرًا على الإنجليزية."]}],"de":[{"heading":"Entstanden in einer Hafenstadt","paragraphs":["Krio ist eine auf dem Englischen basierende Kreolsprache, die sich ab dem späten 18. Jahrhundert unter befreiten Sklaven und ihren Nachkommen in Freetown entwickelte. Ihr Wortschatz speist sich aus dem Englischen, dem Yoruba, dem Portugiesischen und aus französischstämmigen Wörtern — doch sie ist kein gebrochenes Englisch: Sie hat eine eigene Grammatik, eigene Partikeln und eigene Sprichwörter, mit denen gestritten, geneckt und ein Streit beigelegt wird.","Heute sprechen rund 96 Prozent der Bevölkerung Sierra Leones Krio, die meisten als Zweitsprache. Es ist die praktische Brücke zwischen Temne, Mende, Limba und anderen Gruppen — der Code, zu dem Menschen wechseln, wenn sie handeln, reisen oder außerhalb der eigenen Gemeinschaft verstanden werden wollen."]},{"heading":"Die Stimme von Markt und Radio","paragraphs":["In Freetown ist Krio die Hauptsprache des Alltags und der Medien; es gibt eine eigene Literatur, Theaterstücke und Bibelübersetzungen. Zugleich besteht es neben der Krio-Ethnizität der Freetown-Creoles — ein Unterschied, der wichtig bleibt, denn die meisten Sprecher sind ethnisch nicht Krio.","Wie das funktioniert, zeigt ein Markt: Ein Mende-Bauer und ein Temne-Händler einigen sich auf Krio über den Preis und wechseln gleich wieder in ihre eigenen Sprachen, sobald sie mit den wartenden Verwandten sprechen. Begegnungen beginnen meist mit Kushɛ, dem alltäglichen Gruß in Freetown, bevor es um irgendetwas Geschäftliches geht."]},{"heading":"Warum eine Sprache so viel trägt","paragraphs":["Krio überlebt, weil es niemandem allein gehört und allen nützt. Ob ein Kind in der Hauptstadt damit aufwächst oder es später in einer Provinzstadt aufschnappt, prägt, wie es spricht und wie oft die Sprache überhaupt verschriftlicht wird. Mit Standardenglisch ist sie nicht gleichzusetzen, denn Schulen und Verwaltung stützen sich weiterhin stark auf das Englische."]}],"en":[{"heading":"A Language Born in a Port City","paragraphs":["Krio is an English-based creole that developed among freed slaves and their descendants in Freetown from the late 18th century. Its vocabulary draws on English, Yoruba, Portuguese and French-derived words, but it is not broken English: it has its own grammar, its own particles and its own proverbs, which speakers use to argue, tease and settle disputes.","Today around 96 percent of Sierra Leone's population speaks Krio, most of them as a second language. It is the practical link between Temne, Mende, Limba and other groups — the code people switch to when they trade, travel or simply need to be understood outside their own community."]},{"heading":"The Voice of the Market and the Radio","paragraphs":["In Freetown Krio is the main language of daily life and of mass media, and it carries a body of written literature, drama and Bible translation. It also coexists with the Krio ethnic identity of Freetown Creoles — a distinction worth keeping in mind, since most people who speak the language are not ethnically Krio.","You can hear how it works in a market: a Mende farmer and a Temne trader settle a price in Krio, then turn back to their own languages with the relatives waiting nearby. Conversations usually open with Kushɛ, the everyday greeting in Freetown, before any business is mentioned."]},{"heading":"Why One Language Carries So Much","paragraphs":["Krio survives because it belongs to nobody in particular and is useful to everybody. Whether a child grows up hearing it at home in the capital or picks it up later in a provincial town shapes how it is spoken and how often it is written down — and it is not the same as Standard English, since schools and government business still rely heavily on English."]}]},"context":{"countries":["SL"],"region":"Freetown and nationwide Sierra Leone","community":"Krio speakers","continent":"africa","languages":["en"],"period":"contemporary"},"tags":["languages","Freetown and nationwide Sierra Leone","Krio is","About 96"],"sources":[{"organization":"Wikipedia","title":{"ar":"Krio language","de":"Krio language","en":"Krio language"},"url":"https://en.wikipedia.org/wiki/Krio_language","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Sierra Leone Creole people","de":"Sierra Leone Creole people","en":"Sierra Leone Creole people"},"url":"https://en.wikipedia.org/wiki/Sierra_Leone_Creole_people","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مزارع من المندي وتاجر من التيمنه يتّفقان على السعر بالكريو في سوق فريتاون، ثم يعود كلٌّ منهما إلى لغته مع أقاربه.","de":"Auf einem Markt in Freetown einigen sich ein Mende-Bauer und ein Temne-Händler auf Krio über den Preis und sprechen mit den wartenden Verwandten gleich wieder ihre eigene Sprache.","en":"A Mende farmer and a Temne trader settle a price in Krio at a Freetown market, then return to their own languages with relatives."},"misunderstanding":{"ar":"يُظنّ أنّ الكريو إنجليزية مبتسرة أو مبسّطة؛ لها في الحقيقة نحوها وأدواتها وأمثالها، والإنجليزية الفصحى تظلّ لغة التعليم الرسمي وأعمال الحكومة.","de":"Krio sei bloß vereinfachtes oder kaputtes Englisch. Tatsächlich hat es eine eigene Grammatik, eigene Partikeln und Sprichwörter; für Bildung und Verwaltung bleibt Standardenglisch maßgeblich.","en":"That Krio is simply broken or simplified English. It has its own grammar, particles and proverbs, while Standard English remains the language of formal education and government."},"comparison":{"ar":"بخلاف الإنجليزية الفصحى التي تُتعلَّم في المدرسة وتُستخدم في الأوراق الرسمية، يتعلّم الناس الكريو في البيت والشارع والسوق.","de":"Anders als Standardenglisch, das in der Schule gelehrt wird und Ämter und Unterricht prägt, wird Krio vor allem zu Hause, auf der Straße und auf dem Markt erworben.","en":"Unlike Standard English, which is taught in classrooms and used in government paperwork, Krio is picked up at home, in the street and in the market."},"expression":{"original":"Kushɛ","language":"Krio","gloss":{"ar":"تحيّة — التحيّة اليومية في فريتاون","de":"Hallo — der alltägliche Gruß in Freetown","en":"Hello — the everyday greeting in Freetown"},"usage":{"ar":"تُفتتح بها معظم اللقاءات في فريتاون، بين الجيران كما بين الغرباء الذين يتعاملون تجاريًا؛ فالتحية تسبق الحديث عن السعر.","de":"Eröffnet in Freetown fast jedes Gespräch, unter Nachbarn wie zwischen Fremden, die ins Geschäft kommen — der Gruß steht vor dem Preis.","en":"Opens almost any encounter in Freetown, between neighbours or strangers doing business; the greeting comes before the price is named."},"transliteration":"Kushɛ"}},{"id":"afr-009","version":2,"slug":"sango-a-river-creole-that-became-a-national-language","contentType":"feature","category":"languages","title":{"ar":"السانغو: لغة تجارية أصبحت لغة وطنية","de":"Sango: Von der Handelssprache zur Nationalsprache","en":"Sango: A River Creole That Became a National Language"},"deck":{"ar":"كيف تحوّلت لغة السوق على ضفاف نهر أوبانغي إلى لغة مشتركة تجمع ملايين الأشخاص في جمهورية أفريقيا الوسطى.","de":"Wie eine Kreolsprache vom Ufer des Ubangi-Flusses zur gemeinsamen Sprache von Millionen in der Zentralafrikanischen Republik wurde.","en":"How a trade language from the banks of the Ubangi River became the shared tongue of millions in the Central African Republic."},"teaser":{"ar":"لغة وُلدت من التجارة على النهر، ثم أصبحت لغة الإدارة والإذاعة والمدارس. تعرّف على السانغو، اللغة التي تتجاوز الانتماءات العرقية.","de":"Eine Sprache, die aus dem Handel am Fluss entstand und heute in Schulen, Radio und Verwaltung präsent ist. Entdecken Sie Sango, die neutrale Sprache eines vielsprachigen Landes.","en":"Born from river trade, Sango now fills schools, radio and public life. Discover the neutral language that bridges a multilingual nation."},"readingMinutes":1,"sections":{"ar":[{"heading":"من ضفاف النهر إلى المؤسسات","paragraphs":["نشأت لغة السانغو في الأصل كلغة تجارية على طول نهر أوبانغي، حيث كان التجار يتواصلون بها عبر جماعات لغوية متعددة. وبعد استقلال جمهورية أفريقيا الوسطى، جرى توحيدها وتطويرها لتصبح لغة رسمية تُدرَّس في المدارس وتُستخدم في الإذاعة. واليوم يتحدث بها معظم سكان البلاد البالغ عددهم نحو 5.5 مليون نسمة، كما يمتد متحدثوها إلى جنوب تشاد وأجزاء من جمهورية الكونغو الديمقراطية.","تستمد السانغو قوتها من كونها لا تنتمي إلى أي مجموعة عرقية بعينها. فهي لغة محايدة في الحياة العامة، تتيح للناس من خلفيات لغوية مختلفة أن يتفاهموا دون أن يفرض أحدهم لغته على الآخر. هذا الحياد هو ما جعلها lingua franca الأساسية في بلد يزخر بلغات محلية كثيرة."]},{"heading":"لغة الإذاعة والحياة اليومية","paragraphs":["في بانغي، يقرأ مذيع الأخبار بالفرنسية ثم يشرحها بالسانغو، ويستقبل اتصالات المستمعين بأي من اللغتين. هذا المشهد يلخص الواقع اليومي: الفرنسية لغة الإدارة الرسمية، والسانغو لغة الشارع والراديو والتفاعل المباشر. وقد أسهمت الموسيقى، وخاصة أعمال الرائد أنطوان دوكو، في ترسيخ مكانة السانغو في الثقافة الشعبية.","لكن الوضع الرسمي للسانغو لم يزحف الفرنسية عن مواقع الإدارة، كما أن المعيار المكتوب للسانغو لا يُلتزم به بدقة في الاستخدام اليومي. وتختلف درجة إتقان الكتابة بين الأجيال والمناطق، إذ يميل سكان المدن إلى مزج السانغو بالفرنسية في حديثهم اليومي."]},{"heading":"لغة تعبر الحدود","paragraphs":["إلى جانب وظيفتها الوطنية، تعمل السانغو كجسر تواصل عبر الحدود، حيث يتحدثها سكان جنوب تشاد وأجزاء من الكونغو الديمقراطية. وهذا الانتشار الإقليمي يعكس تاريخ الهجرة والتجارة على طول النهر، ويجعل من السانغو مثالاً على لغة تجارية تحولت إلى أداة هوية وطنية.","ومع ذلك، يبقى استخدام السانغو في الكتابة الأدبية محدوداً مقارنة بانتشارها الشفهي، رغم وجود أدب مكتوب. وهذا التباين بين قوة اللغة الشفهية وضعف معيارها المكتوب يطرح تحديات أمام تعميم تعليمها."]}],"de":[{"heading":"Vom Flussufer in die Institutionen","paragraphs":["Sango entstand ursprünglich als Handelssprache entlang des Ubangi-Flusses, wo Händler über verschiedene Sprachgruppen hinweg kommunizierten. Nach der Unabhängigkeit der Zentralafrikanischen Republik wurde es standardisiert und gefördert, um als offizielle Sprache in Schulen und im Radio zu dienen. Heute sprechen es fast alle der rund 5,5 Millionen Einwohner, und auch in der südlichen Tschad und Teilen der Demokratischen Republik Kongo gibt es Sprecher.","Die Stärke von Sango liegt darin, dass es keiner einzelnen ethnischen Gruppe gehört. Als neutrale Sprache des öffentlichen Lebens ermöglicht es Menschen mit unterschiedlichen sprachlichen Hintergründen, miteinander zu kommunizieren, ohne dass eine Gruppe ihre Sprache aufzwingt. Diese Neutralität machte es zur wichtigsten Lingua franca des Landes."]},{"heading":"Sprache des Radios und des Alltags","paragraphs":["In Bangui liest ein Radiomoderator die Nachrichten auf Französisch vor, erklärt sie dann auf Sango und nimmt Anrufe von Hörern in beiden Sprachen entgegen. Diese Szene fasst den Alltag zusammen: Französisch ist die Sprache der Verwaltung, Sango die Sprache der Straße, des Radios und der direkten Interaktion. Auch die Musik, insbesondere die Pionierarbeit des Musikers Antoine Doko, hat zur Verankerung von Sango in der Populärkultur beigetragen.","Doch der offizielle Status hat Französisch nicht aus der Verwaltung verdrängt, und die schriftliche Norm des Sango wird im Alltag nur locker befolgt. Die Schreibkompetenz variiert zwischen Generationen und Regionen; Stadtbewohner neigen dazu, Sango im Alltag mit Französisch zu mischen."]},{"heading":"Eine Sprache über Grenzen hinweg","paragraphs":["Neben ihrer nationalen Funktion dient Sango als Brücke über Grenzen hinweg, da es auch in der südlichen Tschad und Teilen der Demokratischen Republik Kongo gesprochen wird. Diese regionale Verbreitung spiegelt die Geschichte von Migration und Handel entlang des Flusses wider und macht Sango zu einem Beispiel für eine Handelssprache, die zu einem nationalen Identifikationsmittel wurde.","Allerdings bleibt die Verwendung von Sango in der Literatur begrenzt, obwohl es eine schriftliche Literatur gibt. Diese Diskrepanz zwischen der Stärke der gesprochenen Sprache und der schwachen schriftlichen Norm stellt Herausforderungen für die allgemeine Bildung dar."]}],"en":[{"heading":"From Riverbanks to Institutions","paragraphs":["Sango began as a trade language along the Ubangi River, where merchants needed to communicate across different language groups. After the Central African Republic gained independence, it was standardised and promoted as an official language for schools and radio. Today, almost all of the country's roughly 5.5 million people speak it, and speakers also extend into southern Chad and parts of the Democratic Republic of Congo.","Sango's strength lies in belonging to no single ethnic group. As a neutral language of public life, it allows people from diverse linguistic backgrounds to communicate without any one group imposing its tongue. This neutrality has made it the country's main lingua franca."]},{"heading":"Language of Radio and Daily Life","paragraphs":["In Bangui, a radio presenter reads the news in French, explains it in Sango, and takes calls from listeners in either language. This scene captures daily reality: French remains the language of administration, while Sango dominates the street, the airwaves and direct interaction. Music, especially the pioneering work of Antoine Doko, has also helped cement Sango in popular culture.","Yet Sango's official status has not displaced French in administration, and its written standard is only loosely observed in everyday use. Literacy in Sango varies between generations and regions, with urban speakers often mixing it with French in casual conversation."]},{"heading":"A Language That Crosses Borders","paragraphs":["Beyond its national role, Sango serves as a bridge across borders, spoken in southern Chad and parts of the DRC. This regional spread reflects a history of migration and trade along the river, making Sango an example of a trade language that became a tool of national identity.","However, written literature in Sango remains limited compared to its spoken reach. This gap between the vitality of the spoken language and the weakness of its written standard poses challenges for universal education."]}]},"context":{"countries":["CF"],"region":"Central African Republic and the Ubangi basin","community":"Sango speakers","continent":"africa","languages":["fr"],"period":"contemporary"},"tags":["languages","Central African Republic and the Ubangi basin","Sango is","It is"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sango language","de":"Sango language","en":"Sango language"},"url":"https://en.wikipedia.org/wiki/Sango_language","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Central African Republic","de":"Central African Republic","en":"Central African Republic"},"url":"https://en.wikipedia.org/wiki/Central_African_Republic","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في بانغي، يقرأ مذيع الأخبار بالفرنسية ثم يشرحها بالسانغو، ويستقبل اتصالات المستمعين بأي من اللغتين.","de":"In Bangui liest ein Radiomoderator die Nachrichten auf Französisch vor, erklärt sie dann auf Sango und nimmt Anrufe von Hörern in beiden Sprachen entgegen.","en":"In Bangui, a radio presenter reads the news in French, explains it in Sango, and takes calls from listeners in either language."},"misunderstanding":{"ar":"يعتقد البعض أن السانغو مجرد لهجة محلية، لكنها لغة رسمية كاملة ذات معيار مكتوب وأدب، وإن كان استخدامها المكتوب أقل شيوعاً من الشفهي.","de":"Manche halten Sango für einen bloßen lokalen Dialekt, doch es ist eine vollwertige offizielle Sprache mit schriftlicher Norm und Literatur, auch wenn die Schriftform weniger verbreitet ist als die mündliche.","en":"Some assume Sango is just a local dialect, but it is a full official language with a written standard and literature, even if writing is less common than speech."},"comparison":{"ar":"على عكس اللغات الوطنية التي ترتبط بمجموعة عرقية واحدة، تستمد السانغو شرعيتها من كونها محايدة، تماماً كما الحال مع السواحلية في شرق أفريقيا.","de":"Anders als Nationalsprachen, die an eine einzelne ethnische Gruppe gebunden sind, bezieht Sango seine Legitimität aus seiner Neutralität – ähnlich wie Swahili in Ostafrika.","en":"Unlike national languages tied to a single ethnic group, Sango draws its legitimacy from neutrality, much as Swahili does in East Africa."},"expression":{"original":"Balao","language":"Sängö","gloss":{"ar":"مرحباً — تحية تفتح المحادثات في جميع أنحاء جمهورية أفريقيا الوسطى","de":"Hallo – ein Gruß, der Gespräche in der gesamten Zentralafrikanischen Republik eröffnet","en":"Hello — a greeting that opens conversations across the Central African Republic"},"usage":{"ar":"تُستخدم في اللقاءات اليومية بين الغرباء والأصدقاء، وغالباً ما تسبق أي حديث في الإذاعة أو السوق.","de":"Wird bei alltäglichen Begegnungen zwischen Fremden und Freunden verwendet und steht oft am Anfang eines Gesprächs im Radio oder auf dem Markt.","en":"Used in everyday encounters between strangers and friends, often opening a conversation on the radio or in the market."},"transliteration":"Balao"}},{"id":"afr-010","version":2,"slug":"yoruba-greetings-that-name-the-hour-the-age-and-the-standing","contentType":"feature","category":"communication","title":{"ar":"تحيات اليوروبا: الساعة والعمر والوقفة","de":"Yoruba-Grüße: Stunde, Alter und Haltung","en":"Yoruba greetings that name the hour, the age and the standing"},"deck":{"ar":"في أرض اليوروبا، التحية ليست مجاملة عابرة بل تحدد الوقت وتكشف عن الاحترام.","de":"In Yorubaland ist ein Gruß keine Floskel – er nennt die Tageszeit und zeigt Respekt.","en":"In Yorubaland, a greeting is not small talk – it states the time of day and signals respect."},"teaser":{"ar":"تحيات اليوروبا تسمي الساعة والعمر والوقفة، فتحية واحدة تخبرك متى تلتقي وبمن تتحدث.","de":"Yoruba-Grüße benennen die Stunde, das Alter und die Haltung. Ein Gruß verrät, wann man sich trifft und wen man anspricht.","en":"Yoruba greetings name the hour, the age and the standing. One greeting tells you when you meet and whom you address."},"readingMinutes":1,"sections":{"ar":[{"heading":"تحية تسمي الساعة","paragraphs":["في لغة اليوروبا، التحية ليست كلمة واحدة تُقال في أي وقت. هناك تحية خاصة للصباح (Ẹ kú àárọ̀)، وأخرى للظهيرة (Ẹ kú ọ̀sán)، وثالثة للمساء (Ẹ kú ìrọ̀lẹ́). بمجرد أن تسمع التحية، تعرف متى يحدث اللقاء.","هذا يعني أن التحية تحمل معلومة عن الزمن، وليست مجرد افتتاحية. في الصباح الباكر، ستسمع Ẹ kú àárọ̀، وفي فترة بعد الظهر تسمع Ẹ kú ọ̀sán، وعند الغروب تسمع Ẹ kú ìrọ̀lẹ́."]},{"heading":"البادئة Ẹ والاحترام","paragraphs":["البادئة Ẹ هي صيغة تشريفية تُستخدم مع كبار السن والغرباء. حذفها قد يعني إما حميمية أو إشارة إلى خطأ في الاحترام. لذلك، فإن اختيار الصيغة يعكس العلاقة بين المتحدثين.","في كثير من العائلات اليوروبية، ينحني الرجال الأصغر سنًا (dọ̀bálẹ̀) وتركع النساء الأصغر سنًا (kúnlẹ̀) عند تحية كبار السن. لكن الممارسة تختلف في المدن والشتات، حيث تخفف هذه الطقوس أحيانًا."]},{"heading":"التحية كالتزام","paragraphs":["التحية في ثقافة اليوروبا ليست حديثًا جانبيًا، بل هي واجب. الدخول في صلب الموضوع دون تحية قد يُفسر على أنه وقاحة، خاصة مع كبار السن. لهذا السبب، يبدأ الناس دائمًا بالتحية قبل أي طلب أو نقاش.","لغة اليوروبا نغمية: نفس المقطع بنبرة مختلفة يمكن أن يكون كلمة مختلفة. لذلك يجب نطق التحيات بنغماتها الصحيحة حتى تُفهم. هذا يجعل التحية تمرينًا صوتيًا بقدر ما هي اجتماعية.","الممارسة ليست موحدة: العديد من عائلات لاغوس والشتات تخلت عن الركوع والانحناء، والأسر المسيحية والمسلمة تستخدم صيغ تحية مختلفة. كما أن الأجيال الشابة في المدن الكبرى قد تتبنى أشكالًا مختلطة."]}],"de":[{"heading":"Ein Gruß, der die Stunde nennt","paragraphs":["In der Yoruba-Sprache gibt es nicht nur ein Wort für „Hallo“. Morgen (Ẹ kú àárọ̀), Nachmittag (Ẹ kú ọ̀sán) und Abend (Ẹ kú ìrọ̀lẹ́) haben eigene Grußformeln. Schon der Gruß sagt, wann die Begegnung stattfindet.","Das bedeutet: Der Gruß transportiert eine Zeitangabe. Wer morgens Ẹ kú àárọ̀ hört, weiß, dass es früh am Tag ist; Ẹ kú ọ̀sán gehört in den Nachmittag, Ẹ kú ìrọ̀lẹ́ in den Abend."]},{"heading":"Die Vorsilbe Ẹ und der Respekt","paragraphs":["Die Vorsilbe Ẹ ist eine Ehrenform, die gegenüber Älteren und Fremden verwendet wird. Lässt man sie weg, kann das Vertrautheit ausdrücken – oder einen Mangel an Respekt signalisieren. Die Wahl der Form spiegelt also die Beziehung der Sprecher wider.","In vielen Yoruba-Familien verneigen sich jüngere Männer (dọ̀bálẹ̀) und jüngere Frauen knien (kúnlẹ̀) beim Gruß an Ältere. In Städten und in der Diaspora wird dies jedoch unterschiedlich gehandhabt."]},{"heading":"Grüßen als Pflicht","paragraphs":["Grüßen ist in der Yoruba-Kultur keine Small Talk-Einlage, sondern eine Pflicht. Wer ohne Gruß zur Sache kommt, gilt schnell als unhöflich, besonders gegenüber älteren Menschen. Deshalb beginnt man stets mit einem Gruß, bevor man ein Anliegen vorträgt.","Yoruba ist eine Tonsprache: Dieselbe Silbe kann je nach Tonhöhe ein anderes Wort sein. Grüße müssen also mit den richtigen Tönen gesprochen werden, um verstanden zu werden. Das macht das Grüßen zu einer stimmlichen wie sozialen Übung.","Die Praxis ist nicht einheitlich: Viele Familien in Lagos und in der Diaspora haben Knien und Verneigen aufgegeben, und christliche wie muslimische Haushalte verwenden unterschiedliche Grußformeln. Auch junge Stadtbewohner mischen Formen."]}],"en":[{"heading":"A greeting that names the hour","paragraphs":["In Yoruba, there is no single word for hello. Morning (Ẹ kú àárọ̀), afternoon (Ẹ kú ọ̀sán) and evening (Ẹ kú ìrọ̀lẹ́) each have their own greeting. A greeting immediately states when the meeting happens.","This means the greeting carries information about time, not just an opening. Early in the day you hear Ẹ kú àárọ̀; in the afternoon, Ẹ kú ọ̀sán; at dusk, Ẹ kú ìrọ̀lẹ́."]},{"heading":"The prefix Ẹ and respect","paragraphs":["The prefix Ẹ is an honorific form used for elders and strangers. Dropping it can claim intimacy or signal a lapse in respect. The choice of form therefore reflects the relationship between speakers.","In many Yoruba families, younger men prostrate (dọ̀bálẹ̀) and younger women kneel (kúnlẹ̀) when greeting elders. But practice varies in urban and diaspora settings, where these gestures are sometimes relaxed."]},{"heading":"Greeting as an obligation","paragraphs":["Greeting is an obligation rather than small talk. Going straight to business without it can read as rudeness, especially with older people. That is why people always begin with a greeting before making a request or starting a discussion.","Yoruba is tonal: the same syllable at a different pitch can be a different word. Greetings must be voiced with the right tones to be understood. This makes greeting a vocal exercise as much as a social one.","Practice is not uniform: many Lagos and diaspora families have dropped kneeling and prostration, and Christian and Muslim households use different greeting formulas. Younger generations in big cities may also mix forms."]}]},"context":{"countries":["NG"],"region":"Yorubaland, south-west Nigeria","community":"Yoruba","continent":"africa","languages":["yo","en"],"period":"contemporary"},"tags":["communication","Yorubaland, south-west Nigeria"],"sources":[{"organization":"Wikipedia","title":{"ar":"Yoruba language","de":"Yoruba language","en":"Yoruba language"},"url":"https://en.wikipedia.org/wiki/Yoruba_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Yoruba people","de":"Yoruba people","en":"Yoruba people"},"url":"https://en.wikipedia.org/wiki/Yoruba_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"شاب يدخل مجمعًا عائليًا في إبادان، ويسلم على كل كبير بالدور وينحني قليلًا قبل أن يشرح سبب مجيئه.","de":"Ein junger Mann betritt einen Familienwohnhof in Ibadan, grüßt jeden Älteren der Reihe nach und verneigt sich kurz, bevor er sein Anliegen erklärt.","en":"A young man enters a family compound in Ibadan, greets each elder in turn and prostrates briefly before explaining why he has come."},"misunderstanding":{"ar":"قد يعتقد الزائر أن حذف البادئة Ẹ علامة على التواضع، لكنه في الواقع قد يُفهم على أنه قلة احترام.","de":"Ein Besucher könnte denken, das Weglassen von Ẹ sei ein Zeichen von Bescheidenheit – doch es kann als Respektlosigkeit aufgefasst werden.","en":"A visitor might think dropping the prefix Ẹ shows humility, but it can actually be read as a lack of respect."},"comparison":{"ar":"في الثقافات الغربية، التحية العامة مثل «مرحبًا» تُستخدم في أي وقت، بينما في اليوروبا تحدد التحية الوقت بدقة.","de":"In westlichen Kulturen wird ein allgemeines „Hallo“ zu jeder Tageszeit verwendet; im Yoruba benennt der Gruß die Tageszeit genau.","en":"In Western cultures, a general “hello” works at any time of day; in Yoruba, the greeting names the time precisely."},"expression":{"original":"Ẹ kú àárọ̀","language":"Yorùbá","gloss":{"ar":"صباح الخير — البادئة Ẹ تشير إلى الاحترام للشخص المُحيا","de":"Guten Morgen – die Ehrenform Ẹ zeigt Respekt vor der gegrüßten Person","en":"Good morning — the honorific Ẹ marks respect for the person greeted"},"usage":{"ar":"تُقال في الصباح، خاصة عند تحية كبار السن أو الغرباء.","de":"Wird am Morgen verwendet, besonders gegenüber Älteren oder Fremden.","en":"Said in the morning, especially when greeting elders or strangers."},"transliteration":"E ku aaro"}},{"id":"afr-011","version":2,"slug":"when-the-drum-is-the-sentence-speech-surrogacy-in-west-africa","contentType":"feature","category":"communication","title":{"ar":"حين يصبح الطبل جملة: التمثيل الصوتي للكلام في غرب أفريقيا","de":"Wenn die Trommel zum Satz wird: Sprachsurrogat in Westafrika","en":"When the Drum Is the Sentence: Speech Surrogacy in West Africa"},"deck":{"ar":"في مجتمعات اليوروبا والإيوي، لا يقتصر الطبل على الإيقاع، بل ينطق بالتحيات والمدائح والأمثال.","de":"Bei den Yoruba und Ewe übernimmt die Trommel nicht nur den Rhythmus, sondern spricht Grüße, Lobpreisungen und Sprichwörter.","en":"Among Yoruba and Ewe communities, the drum does more than keep rhythm—it speaks greetings, praises, and proverbs."},"teaser":{"ar":"كيف يمكن لطبل صغير أن يحمل رسالة مفهومة دون أن ينطق بها أحد؟ رحلة في عالم الطبول الناطقة.","de":"Wie kann eine kleine Trommel eine verständliche Botschaft übermitteln, ohne dass jemand spricht? Eine Reise in die Welt der sprechenden Trommeln.","en":"How can a small drum carry a message that listeners understand without a word being spoken? A journey into the world of talking drums."},"readingMinutes":1,"sections":{"ar":[{"heading":"طبل يتكلم بلغة الناس","paragraphs":["في مناطق اليوروبا والإيوي بغرب أفريقيا، يُمسك طبل الساعة الرملية تحت الإبط ويُضغط عليه لتغيير حدته الصوتية، فيحاكي نغمات اللغات النغمية مثل اليوروبا والإيوي. هذا الطبل، المعروف باسم الدُّنْدُن، ليس آلة إيقاع فحسب، بل وسيلة للتعبير اللفظي.","يعتمد عازفو الدندن على عبارات محددة وأسماء المدح (أوريكي) لقول التحيات والأمثال وأنساب العائلات في المناسبات. ولا يصلح الطبل لكل رسالة، فهو يعمل بشكل أفضل حيث يحمل النغم المعنى، لذا ينقل الكلام الصيغي بدقة أكبر من الجمل الاعتباطية."]},{"heading":"من إعلان الأخبار إلى الأعراس","paragraphs":["في القرن العشرين، كانت الطبول تعلن الأخبار وتستدعي الناس. أما اليوم، فتظهر غالباً في الأعراس وحفلات تسمية المولود والمهرجانات إلى جانب الموسيقى المكبرة. وقد أعادت الحياة الكنسية والمسجدية تشكيل الممارسة: بعض المجتمعات المسيحية حظرت الطبول، بينما تبنتها أخرى، وتغذت أشكال المدح في الترانيم والإنجيل.","في حفل زفاف بلاغوس، يمدح عازف الدندن عائلة العروس بالاسم، ويستجيب المدعوون لعبارات يعرفونها دون أن يُخبروا بما قيل. هذا التباين في الفهم يعكس طبيعة التمثيل الصوتي الجزئي والاصطلاحي؛ فليس كل عبارة طبول يفهمها كل مستمع، وتختلف تقاليد الإيوي واليوروبا اختلافاً كبيراً."]},{"heading":"لماذا يبقى الطبل حياً؟","paragraphs":["يستمر الطبل الناطق لأن المجتمعات تجد فيه وسيلة للتعبير عن الهوية والانتماء. ففي الأعراس والمناسبات، لا يقتصر دوره على الترفيه، بل يعيد تأكيد الروابط العائلية والاجتماعية من خلال المدح والتحية. كما أن قدرته على نقل الرسائل في سياقات محددة تجعله أداة تواصل فعّالة رغم التغيرات.","تختلف الممارسة بين الأجيال والمناطق؛ فبعض الشباب يدمجون الدندن مع الأنماط الموسيقية المعاصرة، بينما يتمسك آخرون بالأشكال التقليدية. هذا التنوع يعكس حيوية التقليد وقدرته على التكيف."]}],"de":[{"heading":"Eine Trommel spricht die Sprache der Menschen","paragraphs":["In den Yoruba- und Ewe-Gebieten Westafrikas wird die sanduhrförmige Trommel unter dem Arm gehalten und gedrückt, um die Tonhöhe zu verändern. So ahmt sie die Töne tonaler Sprachen wie Yoruba und Ewe nach. Diese Trommel, bekannt als Dùndún, ist nicht nur ein Rhythmusinstrument, sondern ein Mittel des sprachlichen Ausdrucks.","Die Dùndún-Spieler verwenden feste Phrasen und Lobnamen (Oríkì), um bei Feiern Grüße, Sprichwörter und Genealogien „zu sagen“. Die Trommel eignet sich nicht für jede Botschaft: Sie funktioniert am besten, wo der Ton Bedeutung trägt, und übermittelt formelhafte Sprache daher viel zuverlässiger als beliebige Sätze."]},{"heading":"Von der Nachrichtenübermittlung zur Hochzeit","paragraphs":["Im 20. Jahrhundert kündigten Trommeln Nachrichten an und riefen Menschen zusammen. Heute treten sie meist bei Hochzeiten, Namensfeiern und Festivals auf, oft zusammen mit verstärkter Musik. Das kirchliche und moscheeische Leben hat die Praxis umgeformt: Einige christliche Gemeinschaften verboten das Trommeln, andere übernahmen es, und Oríkì-artige Lobformen flossen in Hymnen und Gospel ein.","Bei einer Hochzeit in Lagos lobt der Dùndún-Spieler die Familie der Braut namentlich, und die Gäste reagieren auf Phrasen, die sie erkennen, ohne dass ihnen gesagt wurde, was gesagt wurde. Dieses unterschiedliche Verständnis spiegelt die partielle und konventionelle Natur des Sprachsurrogats wider; nicht jede Trommelphrase wird von jedem Hörer verstanden, und die Ewe- und Yoruba-Traditionen unterscheiden sich erheblich."]},{"heading":"Warum die Trommel lebendig bleibt","paragraphs":["Die sprechende Trommel bleibt erhalten, weil Gemeinschaften in ihr ein Mittel sehen, Identität und Zugehörigkeit auszudrücken. Bei Hochzeiten und Feiern dient sie nicht nur der Unterhaltung, sondern bekräftigt durch Lob und Gruß familiäre und soziale Bindungen. Ihre Fähigkeit, in bestimmten Kontexten Botschaften zu übermitteln, macht sie trotz Veränderungen zu einem wirksamen Kommunikationsmittel.","Die Praxis variiert zwischen Generationen und Regionen; einige junge Menschen integrieren das Dùndún in zeitgenössische Musikstile, während andere an traditionellen Formen festhalten. Diese Vielfalt zeigt die Lebendigkeit der Tradition und ihre Anpassungsfähigkeit."]}],"en":[{"heading":"A Drum That Speaks the People's Language","paragraphs":["In the Yoruba and Ewe areas of West Africa, the hourglass-shaped drum is held under the arm and squeezed to change pitch, imitating the tones of tonal languages like Yoruba and Ewe. Known as the dùndún, this drum is not just a rhythm instrument but a means of verbal expression.","Dùndún players use set phrases and oríkì (praise names) to 'say' greetings, proverbs, and genealogies at ceremonies. The drum is not a code for every message: it works best where tone carries meaning, so it conveys formulaic speech far more reliably than arbitrary sentences."]},{"heading":"From Announcing News to Wedding Celebrations","paragraphs":["In the 20th century, drums announced news and summoned people. Today, they mostly appear at weddings, naming ceremonies, and festivals alongside amplified music. Church and mosque life reshaped the practice: some Christian communities banned drumming, others adopted it, and oríkì-style praise fed into hymn and gospel forms.","At a Lagos wedding, the dùndún player praises the bride's family by name, and guests respond to phrases they recognise without being told what was said. This variation in understanding reflects the partial and conventional nature of speech surrogacy; not every drum phrase is understood by every listener, and Ewe and Yoruba drum traditions differ substantially."]},{"heading":"Why the Drum Endures","paragraphs":["The talking drum persists because communities find in it a way to express identity and belonging. At weddings and ceremonies, it is not merely entertainment but a reaffirmation of family and social ties through praise and greeting. Its ability to convey messages in specific contexts makes it an effective communication tool despite changes.","The practice varies across generations and regions; some young people integrate the dùndún with contemporary musical styles, while others hold to traditional forms. This diversity reflects the vitality of the tradition and its adaptability."]}]},"context":{"countries":["NG","GH","TG"],"region":"West Africa — Yoruba and Ewe areas","community":"Yoruba and Ewe drummers","continent":"africa","languages":["yo","ee","en"],"period":"contemporary"},"tags":["communication","West Africa — Yoruba and Ewe areas","The hourglass-shaped","Yoruba dùndún"],"sources":[{"organization":"Wikipedia","title":{"ar":"Talking drum","de":"Talking drum","en":"Talking drum"},"url":"https://en.wikipedia.org/wiki/Talking_drum","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Ewe music","de":"Ewe music","en":"Ewe music"},"url":"https://en.wikipedia.org/wiki/Ewe_music","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في حفل زفاف بلاغوس، يمدح عازف الدندن عائلة العروس بالاسم، ويستجيب المدعوون لعبارات يعرفونها دون أن يُخبروا بما قيل.","de":"Bei einer Hochzeit in Lagos lobt der Dùndún-Spieler die Familie der Braut namentlich, und die Gäste reagieren auf Phrasen, die sie erkennen, ohne dass ihnen gesagt wurde, was gesagt wurde.","en":"At a Lagos wedding, the dùndún player praises the bride's family by name, and guests respond to phrases they recognise without being told what was said."},"misunderstanding":{"ar":"ليس كل ما يعزفه الطبل مفهوماً لكل المستمعين؛ فالتمثيل الصوتي جزئي واصطلاحي، ويختلف بين المجتمعات.","de":"Nicht jede Trommelphrase wird von allen Hörern verstanden; Sprachsurrogat ist partiell und konventionell und variiert zwischen Gemeinschaften.","en":"Not every drum phrase is understood by every listener; speech surrogacy is partial and conventional, and it varies between communities."},"comparison":{"ar":"على عكس الإشارات الصوتية العالمية كصفارة الإنذار، يعتمد الطبل الناطق على معرفة لغوية وثقافية مشتركة.","de":"Anders als universelle Schallsignale wie eine Alarmhupe beruht die sprechende Trommel auf gemeinsamem sprachlichem und kulturellem Wissen.","en":"Unlike universal sound signals such as an alarm siren, the talking drum relies on shared linguistic and cultural knowledge."},"expression":{"original":"Dùndún","language":"Yorùbá","gloss":{"ar":"طبل الساعة الرملية الناطق، تُضغط أوتاره لتقليد نغمات الكلام","de":"die sanduhrförmige „sprechende“ Trommel, deren Spannschnüre gedrückt werden, um Sprachtöne nachzuahmen","en":"the hourglass 'talking' drum, whose tension cords are squeezed to imitate speech tones"},"usage":{"ar":"يُستخدم في المناسبات الاجتماعية لنقل التحيات والمدائح، ويُعرف به عازفو اليوروبا.","de":"Wird bei gesellschaftlichen Anlässen zur Übermittlung von Grüßen und Lobpreisungen verwendet und ist bei Yoruba-Trommlern bekannt.","en":"Used at social occasions to convey greetings and praises, and known among Yoruba drummers."},"transliteration":"Dundun"}},{"id":"afr-012","version":2,"slug":"the-shebeen-drinking-licences-and-sociability-after-apartheid","contentType":"feature","category":"everyday-life","title":{"ar":"شيبين: الشرب والتراخيص والحياة الاجتماعية بعد الفصل العنصري","de":"Shebeens: Trinken, Lizenzen und Geselligkeit nach der Apartheid","en":"The shebeen: drinking, licences and sociability after apartheid"},"deck":{"ar":"حانات غير مرخصة تحولت إلى مؤسسات اجتماعية في بلدات جنوب أفريقيا وناميبيا، حيث تلتقي الجيرة والأخبار والموسيقى.","de":"Unlizenzierte Bars wurden zu sozialen Institutionen in den Townships Südafrikas und Namibias, wo Nachbarschaft, Nachrichten und Musik zusammenkommen.","en":"Unlicensed bars became social institutions in South African and Namibian townships, where neighbours, news and music meet."},"teaser":{"ar":"كيف تحولت الحانات غير المرخصة إلى مؤسسات اجتماعية في البلدات؟ قصة الشيبين من الفصل العنصري إلى اليوم.","de":"Wie wurden unlizenzierte Bars zu sozialen Institutionen in den Townships? Die Geschichte der Shebeens von der Apartheid bis heute.","en":"How did unlicensed bars become social institutions in the townships? The story of shebeens from apartheid to today."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الحظر إلى الاجتماع","paragraphs":["كانت الشيبين حانات غير مرخصة تبيع الكحول في بلدات جنوب أفريقيا عندما كانت قوانين الفصل العنصري تمنع السود من شراء الكحول وشربه في الأماكن المرخصة. فكان الناس يلجأون إلى غرف خلفية في المنازل، حيث تُخزَّن زجاجات البيرة في الثلاجة، ويُشغَّل الراديو، ويستقبل المضيف الذي يعرف الجميع جيرانه.","غالبًا ما كانت النساء يديرن هذه الأماكن، فتصبح الغرفة الخلفية مساحة اقتصادية واجتماعية في آن واحد. لم تكن مجرد مكان للشرب، بل نقطة لقاء تُتبادل فيها الأخبار وتُحلّ فيها الخلافات."]},{"heading":"بعد 1994: التراخيص والاستمرارية","paragraphs":["بعد عام 1994 حصلت многие من الشيبين على تراخيص، بينما بقيت أخرى غير رسمية. وانتقلت الكلمة إلى ناميبيا وزيمبابوي وزامبيا وملاوي، حيث تتخذ أشكالًا محلية.","تختلف الشيبين من مدينة إلى أخرى: ففي كيب تاون وديربان وويندهوك تتباين من حيث القانونية والزبائن والموسيقى. كما تختلف بين الأجيال: فالشباب قد يفضلون الحانات العصرية، بينما يظل كبار السن أوفياء للشيبين التقليدي."]},{"heading":"المخاطر والنقاش المحلي","paragraphs":["يسجل الباحثون أيضًا المخاطر: أضرار الكحول والشرطة والمنافسة مع تجارة المشروبات الرسمية هي نقاشات محلية متكررة. فالشيبين ليست مجرد مكان للترفيه، بل تعكس توترات الاقتصاد غير الرسمي.","اليوم، توجد الشيبين إلى جانب الحانات ومحلات بيع الزجاجات في اقتصاد البلدات. تبقى أماكن للمحادثة والموسيقى والأخبار المحلية، لكنها تحمل أيضًا وصمة عند البعض."]}],"de":[{"heading":"Vom Verbot zur Geselligkeit","paragraphs":["Shebeens waren unlizenzierte Bars, die Alkohol in südafrikanischen Townships verkauften, als Apartheidgesetze Schwarzen den Kauf und Konsum in lizenzierten Lokalen verboten. Die Menschen wichen auf Hinterzimmer in Wohnhäusern aus, wo Bierflaschen im Kühlschrank standen, das Radio lief und ein Gastgeber empfing, der alle kannte.","Oft wurden diese Orte von Frauen geführt, sodass das Hinterzimmer zu einem wirtschaftlichen und sozialen Raum zugleich wurde. Es war nicht nur ein Ort zum Trinken, sondern ein Treffpunkt für Nachrichten und Konfliktlösung."]},{"heading":"Nach 1994: Lizenzen und Kontinuität","paragraphs":["Nach 1994 erhielten viele Shebeens eine Lizenz, während andere informell blieben. Das Wort wanderte nach Namibia, Simbabwe, Sambia und Malawi, wo es lokale Formen annahm.","Shebeens unterscheiden sich von Stadt zu Stadt: In Kapstadt, Durban und Windhoek variieren Legalität, Publikum und Musik. Auch zwischen den Generationen gibt es Unterschiede: Jüngere bevorzugen manchmal moderne Tavernen, während Ältere dem traditionellen Shebeen treu bleiben."]},{"heading":"Risiken und lokale Debatten","paragraphs":["Forscher verzeichnen auch Risiken: Alkoholschäden, Polizeiarbeit und Konkurrenz mit dem formellen Spirituosenhandel sind wiederkehrende lokale Debatten. Shebeens sind nicht nur Orte der Unterhaltung, sondern spiegeln die Spannungen der Informalwirtschaft wider.","Heute stehen Shebeens neben Tavernen und Flaschenläden in der Township-Ökonomie. Sie bleiben Orte für Gespräche, Musik und lokale Nachrichten, tragen aber für manche auch ein Stigma."]}],"en":[{"heading":"From prohibition to sociability","paragraphs":["Shebeens were unlicensed bars that sold alcohol in South African townships when apartheid law restricted Black people from buying and drinking in licensed venues. People turned to back rooms in homes, where beer bottles sat in the fridge, the radio played, and a host who knew everyone welcomed neighbours.","These places were often run by women, making the back room an economic and social space at once. It was not just a place to drink but a meeting point for news and resolving disputes."]},{"heading":"After 1994: licences and continuity","paragraphs":["After 1994 many shebeens obtained licences while others stayed informal. The word travelled to Namibia, Zimbabwe, Zambia and Malawi, taking on local forms.","Shebeens differ from city to city: in Cape Town, Durban and Windhoek, legality, clientele and music vary. They also vary between generations: younger people may prefer modern taverns, while older residents remain loyal to the traditional shebeen."]},{"heading":"Risks and local debates","paragraphs":["Researchers also record the risks: alcohol harm, policing and competition with the formal liquor trade are recurring local debates. Shebeens are not just places of entertainment but reflect tensions in the informal economy.","Today, shebeens sit alongside taverns and bottle stores in the township economy. They remain places for conversation, music and local news, but for some they also carry a stigma."]}]},"context":{"countries":["ZA","NA"],"region":"South African and Namibian townships","continent":"africa","languages":["zu","af","en"],"period":"contemporary"},"tags":["everyday-life","South African and Namibian townships"],"sources":[{"organization":"Wikipedia","title":{"ar":"Shebeen","de":"Shebeen","en":"Shebeen"},"url":"https://en.wikipedia.org/wiki/Shebeen","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Township (South Africa)","de":"Township (South Africa)","en":"Township (South Africa)"},"url":"https://en.wikipedia.org/wiki/Township_(South_Africa)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مساء يوم جمعة في بلدة بولاية فري ستيت، يجتمع الجيران في مرآب محوّل، يتشاركون صندوق بيرة ويتحدثون عن الجنازات والوظائف وكرة القدم.","de":"An einem Freitagabend in einem Township im Freistaat versammeln sich Nachbarn in einer umgebauten Garage, teilen eine Kiste Bier und tauschen Neuigkeiten über Beerdigungen, Jobs und Fußball aus.","en":"On a Friday evening in a Free State township, neighbours gather in a converted garage, share a crate of beer and catch up on funerals, jobs and football."},"misunderstanding":{"ar":"الاعتقاد بأن الشيبين مجرد حانات غير قانونية؛ فهي مؤسسات اجتماعية لها قواعدها الخاصة، وقد تكون مرخصة أو غير مرخصة.","de":"Die Annahme, Shebeens seien nur illegale Bars; sie sind soziale Institutionen mit eigenen Regeln und können lizenziert oder informell sein.","en":"The assumption that shebeens are merely illegal bars; they are social institutions with their own rules and may be licensed or informal."},"comparison":{"ar":"مثل المقهى الشعبي في بعض المجتمعات، تجمع الشيبين بين البيع والتواصل، لكنها تحمل تاريخًا من التمييز والعزلة.","de":"Ähnlich dem Volkscafé in manchen Gesellschaften verbinden Shebeens Verkauf und Gespräch, tragen aber eine Geschichte der Diskriminierung und Ausgrenzung.","en":"Like the neighbourhood café in some societies, shebeens combine commerce and conversation, but they carry a history of discrimination and exclusion."}},{"id":"afr-014","version":2,"slug":"the-kanga-a-cloth-that-speaks-in-proverbs","contentType":"detail","category":"everyday-life","title":{"ar":"الكانغا: قماش يتحدث بالأمثال","de":"Kanga: Ein Stoff, der in Sprichwörtern spricht","en":"The Kanga: A Cloth That Speaks in Proverbs"},"deck":{"ar":"لفافة قطنية مطبوعة تحمل رسائل اجتماعية وتُلبس في المناسبات اليومية.","de":"Ein bedrucktes Baumwolltuch trägt soziale Botschaften und wird im Alltag getragen.","en":"A printed cotton wrap carries social messages and is worn in everyday life."},"teaser":{"ar":"كيف تختار النساء الكانغا لما تقوله من أمثال وتحذيرات وتهانٍ؟","de":"Wie Frauen Kangas nach dem auswählen, was sie sagen – Lob, Warnung oder Beileid.","en":"How women choose kangas for what they say – praise, warning or condolence."},"readingMinutes":1,"sections":{"ar":[{"heading":"قطعة قماش تحمل رسالة","paragraphs":["الكانغا هي لفافة قطنية مطبوعة بحجم 1.5 في 1 متر تقريبًا، تُلبس في منطقة البحيرات الكبرى الأفريقية وتُباع عادة في أزواج. لكل قطعة حافة وحقل مركزي (مجي) وغالبًا مثل أو رسالة سواحيلية مطبوعة على الحافة.","يمكن للرسالة أن تهنئ أو تغازل أو تحذر أو تنعى، لذا تُختار الكانغا لما تقوله بقدر ما تُختار لنقشتها. تُستخدم الكانغا كتنانير وفساتين وأغطية رأس وحمالات أطفال، وتُقدَّم في الأعراس والولادات والجنازات."]},{"heading":"سياسة وأزياء على قماش رخيص","paragraphs":["تتابع التصاميم المطبوعة في المصانع السياسة وكرة القدم والأزياء، والقماش وسيلة رخيصة ومرئية للتعبير العلني. في حفل زفاف، تعطي الحماة كنتها الجديدة كانغا مطبوعة بمثل عن الصبر، وتُقرأ الرسالة بصوت عالٍ في الحفل.","رسائل الكانغا ليست دائمًا جدية ويعتمد معناها على السياق؛ وتختلف تقاليد الطباعة التنزانية والكينية، والكتنج هو قماش أثقل ومرتبط بها."]}],"de":[{"heading":"Ein Stoff mit Botschaft","paragraphs":["Eine Kanga ist ein bedrucktes Baumwolltuch von etwa 1,5 mal 1 Meter, das in der Region der Afrikanischen Großen Seen getragen und normalerweise paarweise verkauft wird. Jedes Tuch hat einen Rand, ein Mittelfeld (mji) und oft ein aufgedrucktes Swahili-Sprichwort oder eine Botschaft.","Die Botschaft kann gratulieren, necken, warnen oder trauern, daher wird die Kanga ebenso nach dem gewählt, was sie sagt, wie nach ihrem Muster. Kangas dienen als Röcke, Kleider, Kopfbedeckungen und Babytragen und werden bei Hochzeiten, Geburten und Beerdigungen überreicht."]},{"heading":"Politik und Mode auf billigem Stoff","paragraphs":["Industriell bedruckte Designs greifen Politik, Fußball und Mode auf, und der Stoff ist ein billiges, sichtbares Mittel für öffentliche Statements. Bei einer Hochzeit überreicht die Schwiegermutter ihrer neuen Schwiegertochter eine Kanga mit einem Sprichwort über Geduld, und die Botschaft wird bei der Zeremonie vorgelesen.","Kanga-Botschaften sind nicht immer ernst, und ihre Bedeutung hängt vom Kontext ab; die Drucktraditionen Tansanias und Kenias unterscheiden sich, und Kitenge ist ein schwererer, verwandter Stoff."]}],"en":[{"heading":"A Cloth with a Message","paragraphs":["A kanga is a printed cotton wrap about 1.5 by 1 metre, worn in the African Great Lakes region and normally sold in pairs. Each cloth has a border, a central field (mji) and often a Swahili proverb or message printed along the edge.","The message can congratulate, tease, warn or mourn, so the kanga is chosen for what it says as much as for its pattern. Kangas serve as skirts, dresses, head coverings and baby slings, and they are given at weddings, births and funerals."]},{"heading":"Politics and Fashion on Cheap Cloth","paragraphs":["Factory-printed designs track politics, football and fashion, and the cloth is a cheap, visible way to make a public statement. At a wedding, a mother-in-law gives her new daughter-in-law a kanga printed with a proverb about patience, and the message is read aloud at the ceremony.","Kanga messages are not always serious and their meaning depends on context; Tanzanian and Kenyan printing traditions differ, and kitenge is a heavier, related cloth."]}]},"context":{"countries":["TZ","KE"],"region":"African Great Lakes coast","continent":"africa","languages":["sw","en"],"period":"contemporary"},"tags":["everyday-life","African Great Lakes coast","A kanga","Each cloth"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kanga (garment)","de":"Kanga (garment)","en":"Kanga (garment)"},"url":"https://en.wikipedia.org/wiki/Kanga_(garment)","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Swahili culture","de":"Swahili culture","en":"Swahili culture"},"url":"https://en.wikipedia.org/wiki/Swahili_culture","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في حفل زفاف، تعطي الحماة كنتها الجديدة كانغا مطبوعة بمثل عن الصبر، وتُقرأ الرسالة بصوت عالٍ في الحفل.","de":"Bei einer Hochzeit überreicht die Schwiegermutter ihrer neuen Schwiegertochter eine Kanga mit einem Sprichwort über Geduld, und die Botschaft wird bei der Zeremonie vorgelesen.","en":"At a wedding, a mother-in-law gives her new daughter-in-law a kanga printed with a proverb about patience, and the message is read aloud at the ceremony."},"misunderstanding":{"ar":"الاعتقاد بأن الكانغا مجرد قماش زينة يتجاهل وظيفتها التواصلية، لكن معانيها تعتمد على الموقف.","de":"Die Annahme, eine Kanga sei nur ein dekorativer Stoff, übersieht ihre kommunikative Funktion, doch ihre Bedeutung hängt von der Situation ab.","en":"Assuming a kanga is merely decorative overlooks its communicative function, but its meaning depends on the situation."},"comparison":{"ar":"مثل بطاقات المعايدة المكتوبة، تحمل الكانغا رسائل جاهزة، لكنها تُلبس وتُعرض علنًا.","de":"Wie gedruckte Grußkarten tragen Kangas fertige Botschaften, doch sie werden getragen und öffentlich gezeigt.","en":"Like printed greeting cards, kangas carry ready-made messages, but they are worn and displayed publicly."}},{"id":"afr-015","version":2,"slug":"thirteen-months-and-a-seven-year-gap-the-ethiopian-calendar","contentType":"feature","category":"everyday-life","title":{"ar":"ثلاثة عشر شهرًا وفارق سبع سنوات","de":"Dreizehn Monate und sieben Jahre Abstand","en":"Thirteen months and a seven-year gap"},"deck":{"ar":"التقويم الإثيوبي يحدد الإيقاع اليومي في المرتفعات، من رأس السنة إلى ساعات اليوم.","de":"Der äthiopische Kalender prägt den Alltag im Hochland, vom Neujahr bis zur Uhrzeit.","en":"The Ethiopian calendar shapes daily life in the highlands, from New Year to the clock."},"teaser":{"ar":"في إثيوبيا، يبدأ العام في سبتمبر وينقسم إلى ثلاثة عشر شهرًا، والساعة تبدأ عند الفجر. كيف يعيش الناس هذا التقويم؟","de":"In Äthiopien beginnt das Jahr im September und hat dreizehn Monate. Die Uhr startet im Morgengrauen. Wie leben die Menschen mit diesem Kalender?","en":"In Ethiopia, the year starts in September and has thirteen months. The clock begins at dawn. How do people live with this calendar?"},"readingMinutes":1,"sections":{"ar":[{"heading":"سنة من ثلاثة عشر شهرًا","paragraphs":["تستخدم إثيوبيا تقويمها الخاص المشتق من التقليد القبطي والجعزي، والمكون من اثني عشر شهرًا من ثلاثين يومًا، ثم شهر ثالث عشر من خمسة أو ستة أيام. هذا الشهر القصير يحمل اسمًا خاصًا ويُعد فترة انتقالية بين عام وآخر.","يأتي رأس السنة الإثيوبية، المعروف باسم إنكوتاتاش، في 11 سبتمبر أو 12 سبتمبر في السنة الكبيسة، مع نهاية موسم الأمطار. في المرتفعات، يرتبط هذا اليوم بجني المحاصيل وتبادل التهاني بين الجيران."]},{"heading":"فارق سبع سنوات في الوثائق","paragraphs":["يسير العام الإثيوبي متأخرًا عن العام الميلادي بنحو سبع إلى ثماني سنوات، لذا يجب تحويل التواريخ على الوثائق الإثيوبية عند التعامل مع جهات خارجية. هذا الفارق يظهر بوضوح في العقود الرسمية وشهادات الميلاد.","تستخدم المدارس والكنائس والمكاتب الحكومية والصحف التواريخ الإثيوبية إلى جانب التواريخ الميلادية، مما يجعل التقويم علامة على الهوية الوطنية. في المدن الكبرى، يلاحظ الشباب هذا الازدواج في التعاملات اليومية أكثر من غيرهم."]},{"heading":"الساعة تبدأ عند الفجر","paragraphs":["الوقت أيضًا يُحسب بشكل مختلف في الكلام اليومي: تبدأ الساعة الإثيوبية عند الفجر، لذا فإن الساعة السابعة المذكورة قد تعني الواحدة صباحًا بالتوقيت الدولي. هذا الفارق يتطلب انتباهًا في المواعيد والاجتماعات.","في الفنادق والمكاتب، يُطبع الوقت أحيانًا وفق النظامين لتجنب الالتباس. يختلف استخدام الساعة الإثيوبية بين الأجيال والمناطق، إذ يميل كبار السن في الريف إلى الاعتماد عليها أكثر من الشباب في المدن."]}],"de":[{"heading":"Ein Jahr aus dreizehn Monaten","paragraphs":["Äthiopien verwendet einen eigenen Kalender, der aus der koptischen und ge'ez-Tradition stammt. Er besteht aus zwölf Monaten mit je 30 Tagen und einem dreizehnten Monat mit fünf oder sechs Tagen. Dieser kurze Monat gilt als Übergangszeit zwischen zwei Jahren.","Das äthiopische Neujahr, Enkutatash, fällt auf den 11. September oder in einem Schaltjahr auf den 12. September, wenn die Regenzeit endet. Im Hochland ist dieser Tag mit der Ernte und dem Austausch von Glückwünschen unter Nachbarn verbunden."]},{"heading":"Sieben Jahre Unterschied in Dokumenten","paragraphs":["Das äthiopische Jahr liegt etwa sieben bis acht Jahre hinter dem gregorianischen Jahr, daher müssen Daten auf äthiopischen Dokumenten umgerechnet werden. Dieser Unterschied zeigt sich deutlich in offiziellen Verträgen und Geburtsurkunden.","Schulen, Kirchen, Regierungsbüros und Zeitungen verwenden äthiopische Daten neben gregorianischen, und der Kalender ist ein Zeichen nationaler Identität. In den Städten bemerken jüngere Menschen diese Doppelung im Alltag stärker als andere."]},{"heading":"Die Uhr beginnt im Morgengrauen","paragraphs":["Auch die Zeit wird im Alltag anders gezählt: Die äthiopische Uhr beginnt im Morgengrauen, sodass eine genannte „7 Uhr“ 1 Uhr nachts internationaler Zeit bedeuten kann. Diese Differenz erfordert Aufmerksamkeit bei Terminen und Besprechungen.","In Hotels und Büros wird die Zeit manchmal in beiden Systemen angegeben, um Verwirrung zu vermeiden. Die Verwendung der äthiopischen Uhr variiert zwischen Generationen und Regionen; ältere Menschen auf dem Land verlassen sich stärker darauf als junge in den Städten."]}],"en":[{"heading":"A year of thirteen months","paragraphs":["Ethiopia uses its own calendar, derived from the Coptic and Ge'ez tradition, with twelve months of 30 days and a thirteenth month of five or six days. This short month is a transitional period between years.","The Ethiopian New Year, Enkutatash, falls on 11 September, or 12 September in a leap year, just as the rains end. In the highlands, the day is linked to harvest and exchanging greetings with neighbours."]},{"heading":"A seven-year difference in documents","paragraphs":["The Ethiopian year runs about seven to eight years behind the Gregorian year, so dates on Ethiopian documents must be converted. This gap is clear in official contracts and birth certificates.","Schools, churches, government offices and newspapers use Ethiopian dates alongside Gregorian ones, and the calendar is a marker of national identity. In cities, younger people notice this duality in everyday dealings more than others."]},{"heading":"The clock starts at dawn","paragraphs":["Time is also counted differently in everyday speech: the Ethiopian clock starts at dawn, so a stated '7 o'clock' can mean 1 a.m. in international time. This difference requires attention for appointments and meetings.","In hotels and offices, times are sometimes printed in both systems to avoid confusion. Use of the Ethiopian clock varies between generations and regions; older people in rural areas rely on it more than young people in cities."]}]},"context":{"countries":["ET"],"region":"Ethiopian highlands","continent":"africa","languages":["am","om"],"period":"contemporary"},"tags":["everyday-life","Ethiopian highlands"],"sources":[{"organization":"Wikipedia","title":{"ar":"Ethiopian calendar","de":"Ethiopian calendar","en":"Ethiopian calendar"},"url":"https://en.wikipedia.org/wiki/Ethiopian_calendar","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Enkutatash","de":"Enkutatash","en":"Enkutatash"},"url":"https://en.wikipedia.org/wiki/Enkutatash","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يطبع فندق في أديس أبابا وقت الاجتماع وفق التقويمين حتى لا يفوت الضيوف موعدًا يفصله سبع سنوات بين النظامين.","de":"Ein Hotel in Addis Abeba druckt eine Besprechungszeit in beiden Kalendern ab, damit Gäste keinen Termin verpassen, der sieben Jahre auseinanderliegt.","en":"A hotel in Addis Ababa prints a meeting time in both calendars so guests do not miss a date that lies seven years apart between systems."},"misunderstanding":{"ar":"يعتقد البعض أن التقويم الإثيوبي مجرد تقويم ديني، لكنه يُستخدم رسميًا في الحياة المدنية.","de":"Manche halten den äthiopischen Kalender für rein religiös, doch er wird offiziell im zivilen Leben verwendet.","en":"Some think the Ethiopian calendar is purely religious, but it is used officially in civil life."},"comparison":{"ar":"بينما يعتمد العالم الميلادي على سنة شمسية واحدة، يجمع التقويم الإثيوبي بين دورة شمسية وشهر قصير يكمل السنة.","de":"Während die gregorianische Welt ein Sonnenjahr nutzt, verbindet der äthiopische Kalender einen Sonnenzyklus mit einem kurzen Zusatzmonat.","en":"While the Gregorian world uses a single solar year, the Ethiopian calendar combines a solar cycle with a short additional month."}},{"id":"afr-016","version":2,"slug":"akan-day-names-the-weekday-that-becomes-a-person","contentType":"feature","category":"social-behaviour","title":{"ar":"أسماء الأيام لدى الآكان: يوم الولادة يصبح شخصًا","de":"Akan-Tagesnamen: Der Wochentag wird zur Person","en":"Akan day names: the weekday that becomes a person"},"deck":{"ar":"في غانا، تختار عائلات الآكان اسم الطفل بناءً على يوم ولادته، ليحمل الاسم معنى عن الشخصية والروح.","de":"In Ghana wählen Akan-Familien den Namen eines Kindes nach dem Wochentag seiner Geburt. Diese Tagesnamen tragen Bedeutungen über Charakter und Seele.","en":"In Ghana, Akan families name children after the day of the week they were born, and these day names carry meanings about character and soul."},"teaser":{"ar":"اسمك قد يكون يوم ميلادك: تعرف على تقليد أسماء الأيام لدى الآكان وكيف يرافق الفرد في حياته اليومية.","de":"Dein Name könnte dein Geburtstag sein: Entdecke die Akan-Tradition der Tagesnamen und wie sie das tägliche Leben begleiten.","en":"Your name might be your birthday: discover the Akan tradition of day names and how they accompany a person through daily life."},"readingMinutes":1,"sections":{"ar":[{"heading":"تقليد عريق","paragraphs":["في مناطق الآكان في غانا، تختار العائلات اسم الطفل بناءً على يوم الأسبوع الذي وُلد فيه. هذه الأسماء ليست مجرد تسميات، بل تحمل معاني تتعلق بالشخصية والروح. على سبيل المثال، كوامي هو اسم الذكر المولود يوم السبت، وأما للأنثى المولودة يوم السبت، وكوفي للذكر المولود يوم الجمعة، وأكوسوا للأنثى المولودة يوم الأحد.","تنتشر هذه الممارسة بين عائلات الآكان في غانا وساحل العاج، وقد انتقلت مع الشتات الأفريقي، فلا تزال العائلات الغانية في الخارج تمنح أسماء الأيام لأبنائها. وتختلف الممارسة قليلاً بين المجموعات الفرعية للآكان وبين العائلات المسيحية والمسلمة، كما أن ليس كل غاني من الآكان أو يستخدم أسماء الأيام."]},{"heading":"أسماء متعددة في سياقات مختلفة","paragraphs":["الأسماء الوسطى أكثر تنوعًا، ويمكن أن تشير إلى ترتيب الولادة أو حالة التوأم أو سلف معين. غالبًا ما تُضاف أسماء مسيحية أو إسلامية إلى جانب اسم اليوم. وهكذا، قد يُعرف الشخص بأسماء مختلفة في سياقات مختلفة: في المنزل، في المدرسة، وفي الوثائق الرسمية.","تُستخدم أسماء الأيام في المخاطبة اليومية، وفي سجلات المدارس، وفي الوثائق الرسمية. لذلك، قد يُعرف الشخص الواحد بعدة أسماء حسب السياق. هذا التنوع يعكس مرونة التقليد وقدرته على التكيف مع الحياة الحديثة."]},{"heading":"حياة الفرد بين الأسماء","paragraphs":["في أكرا، طالب يُدعى كوامي من قبل جدته، ومايكل في جواز سفره، وK. من قبل مدربه في كرة القدم. جميع هذه الأسماء صحيحة. يوضح هذا المثال كيف يتفاعل الاسم مع العلاقات الاجتماعية والمؤسسات الرسمية.","يعكس تقليد أسماء الأيام لدى الآكان ارتباط الهوية بالزمن والروح، ويظهر كيف يمكن للاسم أن يحمل تاريخًا شخصيًا واجتماعيًا. ورغم التغيرات الاجتماعية، لا يزال هذا التقليد حيًا في غانا وخارجها."]}],"de":[{"heading":"Eine alte Tradition","paragraphs":["In den Akan-Gebieten Ghanas wählen Familien den Namen eines Kindes nach dem Wochentag, an dem es geboren wurde. Diese Namen sind nicht nur Bezeichnungen, sondern tragen Bedeutungen über Charakter und Seele. Zum Beispiel ist Kwame der Name für einen am Samstag geborenen Jungen, Ama für ein am Samstag geborenes Mädchen, Kofi für einen am Freitag geborenen Jungen und Akosua für ein am Sonntag geborenes Mädchen.","Diese Praxis ist bei Akan-Familien in Ghana und der Elfenbeinküste verbreitet und hat sich mit der afrikanischen Diaspora verbreitet, sodass auch ghanaische Familien im Ausland Tagesnamen vergeben. Die Praxis variiert leicht zwischen den Akan-Untergruppen und zwischen christlichen und muslimischen Familien, und nicht jeder Ghanaer ist Akan oder verwendet Tagesnamen."]},{"heading":"Mehrere Namen in verschiedenen Kontexten","paragraphs":["Mittelnamen sind vielfältiger und können die Geburtsreihenfolge, den Zwillingsstatus oder einen Vorfahren kennzeichnen. Oft werden christliche oder muslimische Namen daneben hinzugefügt. So kann eine Person in verschiedenen Zusammenhängen unter verschiedenen Namen bekannt sein: zu Hause, in der Schule und in offiziellen Dokumenten.","Tagesnamen werden in der täglichen Anrede, in Schulregistern und in offiziellen Dokumenten verwendet. Daher kann eine Person je nach Kontext unter mehreren Namen bekannt sein. Diese Vielfalt spiegelt die Flexibilität der Tradition und ihre Anpassungsfähigkeit an das moderne Leben wider."]},{"heading":"Das Leben einer Person zwischen Namen","paragraphs":["In Accra wird ein Student von seiner Großmutter Kwame genannt, in seinem Pass heißt er Michael und sein Fußballtrainer nennt ihn K. Alle drei Namen sind korrekt. Dieses Beispiel zeigt, wie Namen mit sozialen Beziehungen und offiziellen Institutionen interagieren.","Die Akan-Tradition der Tagesnamen spiegelt die Verbindung von Identität, Zeit und Seele wider und zeigt, wie ein Name eine persönliche und soziale Geschichte tragen kann. Trotz gesellschaftlicher Veränderungen ist diese Tradition in Ghana und darüber hinaus lebendig."]}],"en":[{"heading":"An ancient tradition","paragraphs":["In Akan areas of Ghana, families choose a child's name based on the day of the week they were born. These names are not just labels; they carry meanings about character and soul. For example, Kwame is the name for a Saturday-born male, Ama for a Saturday-born female, Kofi for a Friday-born male, and Akosua for a Sunday-born female.","The practice is common among Akan families in Ghana and Côte d'Ivoire and has travelled with the African diaspora, so Ghanaian families abroad still give day names. The practice varies slightly among Akan subgroups and between Christian and Muslim families, and not every Ghanaian is Akan or uses day names."]},{"heading":"Multiple names in different contexts","paragraphs":["Middle names are more varied and can mark birth order, twin status or an ancestor. Christian or Muslim names are often added alongside. So a person may be known by different names in different settings: at home, at school and in official documents.","Day names are used in daily address, school registers and official documents. Therefore, one person may be known by several names depending on the context. This diversity reflects the tradition's flexibility and its adaptability to modern life."]},{"heading":"A person's life between names","paragraphs":["A student in Accra is called Kwame by his grandmother, Michael on his passport, and K. by his football coach. All three names are correct. This example shows how names interact with social relationships and official institutions.","The Akan day-name tradition reflects the connection between identity, time and soul, and shows how a name can carry a personal and social history. Despite social changes, this tradition remains alive in Ghana and beyond."]}]},"context":{"countries":["GH"],"region":"Akan areas of Ghana","community":"Akan","continent":"africa","languages":["ak","tw","en"],"period":"contemporary"},"tags":["social-behaviour","Akan areas of Ghana"],"sources":[{"organization":"Wikipedia","title":{"ar":"Akan name","de":"Akan name","en":"Akan name"},"url":"https://en.wikipedia.org/wiki/Akan_name","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Akan people","de":"Akan people","en":"Akan people"},"url":"https://en.wikipedia.org/wiki/Akan_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالب في أكرا يُدعى كوامي من قبل جدته، ومايكل في جواز سفره، وK. من قبل مدربه في كرة القدم، وجميع هذه الأسماء صحيحة.","de":"Ein Student in Accra wird von seiner Großmutter Kwame genannt, in seinem Pass heißt er Michael und sein Fußballtrainer nennt ihn K. Alle drei Namen sind korrekt.","en":"A student in Accra is called Kwame by his grandmother, Michael on his passport, and K. by his football coach, and all three names are correct."},"misunderstanding":{"ar":"قد يعتقد البعض أن اسم اليوم هو الاسم الرسمي الوحيد، لكن في الواقع يُستخدم إلى جانب أسماء أخرى في سياقات مختلفة.","de":"Manche glauben, der Tagesname sei der einzige offizielle Name, aber tatsächlich wird er neben anderen Namen in verschiedenen Kontexten verwendet.","en":"Some believe the day name is the only official name, but in fact it is used alongside other names in different contexts."},"comparison":{"ar":"على عكس العديد من الثقافات حيث يُختار الاسم لأسباب دينية أو عائلية فقط، في تقليد الآكان يرتبط الاسم بيوم الولادة ويعكس جوانب من الشخصية والروح.","de":"Im Gegensatz zu vielen Kulturen, in denen Namen nur aus religiösen oder familiären Gründen gewählt werden, verbindet die Akan-Tradition den Namen mit dem Geburtstag und spiegelt Aspekte von Charakter und Seele wider.","en":"Unlike many cultures where names are chosen for religious or family reasons only, the Akan tradition links the name to the day of birth and reflects aspects of character and soul."}},{"id":"afr-018","version":2,"slug":"xeer-somali-customary-law-and-the-elders-who-negotiate-it","contentType":"note","category":"social-behaviour","title":{"ar":"الزعير: قانون العرف ومساومة الشيوخ","de":"Xeer: Gewohnheitsrecht und verhandelnde Älteste","en":"Xeer: elders negotiating Somali customary law"},"deck":{"ar":"نظام قانوني صومالي يعمل بالتفاوض والتعويض لا بالعقاب، ويحكم العلاقات بين الجماعات.","de":"Ein somalisches Rechtssystem, das auf Ausgleich statt Strafe setzt und Beziehungen zwischen Gruppen regelt.","en":"A legal system built on negotiation and restitution rather than punishment, governing relations between groups."},"teaser":{"ar":"كيف يحلّ شيوخ من عشيرتين نزاعًا على طريق بلا محكمة ولا سجن، وما الذي يربحه الطرفان؟","de":"Wie Älteste zweier Clans einen Verkehrsunfall ohne Gericht und Gefängnis klären – und was beide Seiten gewinnen.","en":"How elders from two clans settle a road accident without a court or a prison — and what each side gains."},"readingMinutes":1,"sections":{"ar":[{"heading":"قانون يقوم على السابقة","paragraphs":["الزعير هو النظام القانوني العرفي الذي تستخدمه المجتمعات الصومالية في الصومال وجيبوتي وإقليم الصومال في إثيوبيا وشمال شرق كينيا.","يعمل من خلال الشيوخ وممثلي العشائر الذين يتفاوضون في قضايا التعويض والزواج والنزاعات على الموارد، استنادًا إلى سوابق متعارف عليها.","يسبق الزعير الإسلام في المنطقة، لكنه استوعب مبادئ إسلامية، ويتعايش مع المحاكم المدنية ومحاكم الشريعة. وقوته في التفاوض والردّ لا في العقاب، ما يمنع تصاعد النزاع بين الجماعات؛ وضعفه أنه يعتمد على العضوية العشائرية، فقد تُظلم النساء والأقليات ومن هم خارج الشبكات."]},{"heading":"حادث طريق يحلّه الشيوخ","paragraphs":["بعد حادث سير يجتمع شيوخ من عشيرتين، ويستمعون إلى الشهود، ويتفقون على دِية تُدفع من الماشية أو النقد.","هكذا يُغلق النزاع دون محكمة، لكن الحل يظل مشروطًا باعتراف الطرفين بالشيوخ وبالعشيرة التي يمثلونها."]},{"heading":"حدود النظام وانتقاداته","paragraphs":["الزعير غير مدوّن ويختلف بحسب المنطقة والعشيرة؛ وقد أُثني عليه لشرعيته المحلية وانتُقد لاستبعاده الأطراف الأضعف."]}],"de":[{"heading":"Recht aus Präzedenzfällen","paragraphs":["Xeer ist das Gewohnheitsrecht somalischer Gemeinschaften in Somalia, Dschibuti, der Somali-Region Äthiopiens und im Nordosten Kenias.","Es funktioniert über Älteste und Clanvertreter, die Entschädigung, Ehen und Ressourcenkonflikte nach Präzedenzfällen aushandeln.","Xeer ist älter als der Islam in der Region, hat aber islamische Grundsätze aufgenommen und besteht neben Zivil- und Schariagerichten. Seine Stärke ist Verhandlung und Wiedergutmachung statt Strafe, was Eskalation zwischen Gruppen bremst; seine Schwäche ist die Abhängigkeit von Clanzugehörigkeit, wodurch Frauen, Minderheiten und Menschen außerhalb der Netzwerke benachteiligt werden können."]},{"heading":"Ein Verkehrsunfall vor den Ältesten","paragraphs":["Nach einem Verkehrsunfall treffen sich Älteste zweier Clans, hören Zeugen an und einigen sich auf diya, eine Entschädigung in Vieh oder Bargeld.","So endet der Streit ohne Gericht – aber nur, solange beide Seiten die Ältesten und den Clan, für den sie sprechen, anerkennen."]},{"heading":"Grenzen und Kritik","paragraphs":["Xeer ist nicht kodifiziert und variiert nach Region und Clan; es wird für lokale Legitimität gelobt und dafür kritisiert, schwächere Parteien auszuschließen."]}],"en":[{"heading":"Law built on precedent","paragraphs":["Xeer is the customary legal system used by Somali communities in Somalia, Djibouti, the Somali Region of Ethiopia and north-eastern Kenya.","It works through elders and clan representatives who negotiate compensation, marriage and resource disputes according to precedent.","Xeer predates Islam in the region but has absorbed Islamic principles, and it coexists with civil and sharia courts. Its strength is negotiation and restitution rather than punishment, which can stop disputes escalating between groups; its weakness is dependence on clan membership, so women, minorities and people outside clan networks can be disadvantaged."]},{"heading":"A road accident before the elders","paragraphs":["After a road accident, elders from two clans meet, hear witnesses, and agree on diya paid in livestock or cash.","The dispute closes without a court, but only as long as both sides recognise the elders and the clan they speak for."]},{"heading":"Limits and criticism","paragraphs":["Xeer is not codified and varies by region and clan; it has been praised for local legitimacy and criticised for excluding weaker parties."]}]},"context":{"countries":["SO"],"region":"Horn of Africa","community":"Somali","continent":"africa","languages":["so","ar"],"period":"contemporary"},"tags":["social-behaviour","Horn of Africa","Xeer is","It works"],"sources":[{"organization":"Wikipedia","title":{"ar":"Xeer","de":"Xeer","en":"Xeer"},"url":"https://en.wikipedia.org/wiki/Xeer","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Somali clans","de":"Somali clans","en":"Somali clans"},"url":"https://en.wikipedia.org/wiki/Somali_clans","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"بعد حادث سير يجتمع شيوخ من عشيرتين ويستمعون إلى الشهود ويتفقون على دِية تُدفع من الماشية أو النقد.","de":"Nach einem Verkehrsunfall treffen sich Älteste zweier Clans, hören Zeugen an und einigen sich auf diya in Vieh oder Bargeld.","en":"After a road accident, elders from two clans meet, hear witnesses and agree on diya paid in livestock or cash."},"misunderstanding":{"ar":"يُظنّ الزعير محكمة دينية، لكنه نظام عرفي مستقل يتعايش مع الشريعة والقانون المدني.","de":"Xeer wird oft für ein religiöses Gericht gehalten, ist aber ein eigenständiges Gewohnheitsrecht neben Scharia und Zivilrecht.","en":"Xeer is often mistaken for a religious court, but it is a separate customary system alongside sharia and civil law."},"comparison":{"ar":"يشبه التحكيم المحلي في مجتمعات أخرى، لكن مرجعه هنا سوابق العشيرة لا نصّ مدوّن.","de":"Es ähnelt lokaler Schlichtung anderswo, doch die Grundlage sind Clanpräzedenzen, kein geschriebener Text.","en":"It resembles local arbitration elsewhere, except that clan precedent rather than a written code is the reference."}},{"id":"afr-019","version":2,"slug":"touba-and-the-mouride-order-faith-work-and-a-city-built-by-disciples","contentType":"feature","category":"traditions","title":{"ar":"طوبى: مدينة بناها المريدون بالعمل والعبادة","de":"Touba: eine Stadt, gebaut von Gläubigen","en":"Touba: a city built by disciples"},"deck":{"ar":"كيف تحوّل إيمان المريدين إلى مدينة وعمل واقتصاد يمتدّ من السنغال إلى المهاجر.","de":"Wie aus dem Glauben der Muriden eine Stadt, eine Arbeitsethik und ein weitgespanntes Handelsnetz entstanden.","en":"How Mouride faith turned into a city, a work ethic and a trading network stretching far beyond Senegal."},"teaser":{"ar":"في وسط السنغال مدينة يديرها أتباع طريقة صوفية، ويصلها كل عام ملايين الزائرين. فكيف صار العمل عبادةً وأسّس مجتمعًا؟","de":"Im Zentrum Senegals liegt eine Stadt, die eine Sufi-Bruderschaft weitgehend selbst verwaltet. Jedes Jahr kommen Millionen. Wie wurde Arbeit hier zum Gottesdienst?","en":"In central Senegal a city is run largely by a Sufi order, and millions arrive every year. How did work become worship and build a whole society?"},"readingMinutes":1,"sections":{"ar":[{"heading":"طريقة نشأت حول شيخ واحد","paragraphs":["تأسست الطريقة المريدية في السنغال على يد الشيخ أمادو بامبا (1853–1927)، وتتخذ من مدينة طوبى مقرًّا لها. وهي طريقة صوفية تجمع بين الذكر والانضباط، لكنها اشتهرت خصوصًا بعقيدتها في العمل كعبادة، إذ يرى المريد أن كدحه في الحقل أو المتجر أو الورشة جزء من إيمانه لا مجرّد وسيلة للعيش.","نمت طوبى حول ضريح بامبا والمسجد الكبير حتى صارت مدينة يتجاوز سكانها المليون، وتُدار شؤونها إلى حدّ كبير من داخل الطريقة لا من الدولة. وهذا يعني أن التخطيط والخدمات والأمن تنهض بها بنية دينية ومجتمعية، لا إدارة رسمية فقط."]},{"heading":"يوم المَغال: عندما تصبح المدينة موعدًا","paragraphs":["كل سنة يستقبل المَغال الكبير ملايين المريدين في طوبى، فيتحوّل الحدث إلى موعد اجتماعي واقتصادي كبير: أسواق، ولقاءات، وتبادل أخبار وأعمال. ويأتي كثير من الزائرين من شبكات المريدين في أوروبا وأمريكا الشمالية، وهي شبكات تُدرس بوصفها شكلًا من الاقتصاد الديني الذي يربط الهجرة بالتجارة.","مثال ذلك تاجر مريدي في داكار يغلق متجره أيام المَغال ويسافر إلى طوبى، ثم يعود ببركة وزيارة وعلاقات تجارية جديدة. فالسفر هنا ليس انقطاعًا عن العمل، بل جزء من دورة الثقة التي يقوم عليها النشاط الاقتصادي."]},{"heading":"تنوّع داخل الطريقة نفسها","paragraphs":["تتوزّع في السنغال طرق صوفية أخرى، منها التجانية وغيرها، كما تختلف حياة المريدين بين أتباع الريف الذين يعتمدون على الزراعة وتجار المدن الذين يعملون في التجارة والخدمات. ولهذا لا يصحّ الحديث عن نموذج واحد ثابت، فالممارسة تتغيّر بتغيّر الجيل والمهنة والمكان."]}],"de":[{"heading":"Ein Orden um einen einzigen Lehrer","paragraphs":["Die Muridiyya wurde in Senegal von Scheich Amadou Bamba (1853–1927) gegründet und hat ihr Zentrum in Touba. Sie ist ein Sufi-Orden mit Andacht und Disziplin, berühmt aber vor allem für die Lehre, dass Arbeit Gottesdienst sei: Der Muride versteht sein Tagewerk auf dem Feld, im Laden oder in der Werkstatt als Teil seines Glaubens, nicht nur als Mittel zum Lebensunterhalt.","Rund um Bambas Grab und die Große Moschee wuchs Touba zu einer Stadt mit über einer Million Einwohnern. Sie wird weitgehend vom Orden und nicht vom Staat verwaltet, sodass Planung, Versorgung und Ordnung von religiösen und gemeinschaftlichen Strukturen getragen werden."]},{"heading":"Der Magal: wenn die Stadt zum Treffpunkt wird","paragraphs":["Jährlich bringt der große Magal Millionen Muriden nach Touba und wird zu einem gewaltigen sozialen und wirtschaftlichen Ereignis mit Märkten, Begegnungen und dem Austausch über Geschäfte. Viele Reisende kommen aus muridischen Netzwerken in Europa und Nordamerika, die als religiöse Ökonomie untersucht werden und Migration mit Handel verbinden.","Ein muridischer Händler in Dakar schließt zum Beispiel während des Magal seinen Laden, reist nach Touba und kehrt mit Segen und neuen Geschäftskontakten zurück. Die Reise unterbricht das Geschäft nicht, sondern gehört zum Vertrauenskreislauf, auf dem der Handel beruht."]},{"heading":"Vielfalt innerhalb des Ordens","paragraphs":["In Senegal wirken auch andere Sufi-Orden wie die Tijaniyya, und das Leben der Muriden unterscheidet sich je nachdem, ob jemand im ländlichen Raum von der Landwirtschaft oder als Händler in der Stadt von Handel und Dienstleistungen lebt. Von einem festen Modell zu sprechen wäre deshalb falsch, denn die Praxis verändert sich mit Generation, Beruf und Ort."]}],"en":[{"heading":"An order gathered around one teacher","paragraphs":["The Mouride order was founded in Senegal by Sheikh Amadou Bamba (1853–1927) and is headquartered in Touba. It is a Sufi brotherhood of devotion and discipline, best known for its doctrine of work as worship: a disciple treats labour in the field, the shop or the workshop as part of faith, not merely as a way to earn a living.","Touba grew around Bamba's tomb and the Grand Mosque into a city of more than a million people. It is administered largely by the order rather than the state, so planning, services and order rest on religious and community structures."]},{"heading":"The Magal: when the city becomes a meeting point","paragraphs":["Every year the Grand Magal brings millions of Mourides to Touba and becomes a vast social and economic event, with markets, encounters and news of business. Many visitors come through Mouride networks in Europe and North America, studied as a religious economy that links migration and trade.","A Mouride trader in Dakar, for instance, closes his shop for the Magal, travels to Touba and comes back with blessings and new business contacts. The journey does not interrupt trade; it belongs to the cycle of trust on which that trade depends."]},{"heading":"Variety within the same order","paragraphs":["Senegal's Sufi landscape also includes the Tijaniyya and other orders, and Mouride life differs between rural disciples who farm and urban merchants who live from trade and services. Speaking of one fixed model would therefore be misleading, since practice shifts with generation, occupation and place."]}]},"context":{"countries":["SN"],"region":"Diourbel Region, central Senegal","community":"Mouride","continent":"africa","languages":["wo","fr","ar"],"period":"contemporary"},"tags":["traditions","Diourbel Region, central Senegal","The Mouride","It is"],"sources":[{"organization":"Wikipedia","title":{"ar":"Mouride Order","de":"Mouride Order","en":"Mouride Order"},"url":"https://en.wikipedia.org/wiki/Mouride_Order","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Touba","de":"Touba","en":"Touba"},"url":"https://en.wikipedia.org/wiki/Touba","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يغلق تاجر مريدي في داكار متجره أيام المَغال، ويسافر إلى طوبى، ثم يعود ببركة وعلاقات تجارية جديدة.","de":"Ein muridischer Händler in Dakar schließt während des Magal seinen Laden, reist nach Touba und kehrt mit Segen und neuen Geschäftskontakten zurück.","en":"A Mouride trader in Dakar closes his shop for the Magal, travels to Touba, and comes back with blessings and new business contacts."},"misunderstanding":{"ar":"ليس صحيحًا أن العمل عند المريدين بديل عن العبادة؛ فالتعاليم تجعلهما وجهين لحياة واحدة، لا نشاطين منفصلين.","de":"Arbeit ersetzt bei den Muriden nicht die Andacht; die Lehre verbindet beides zu einem Leben, statt zwei getrennte Bereiche daraus zu machen.","en":"Work does not replace devotion for Mourides; the teaching joins the two into one life rather than separating them."},"comparison":{"ar":"بينما تُدار مدن كثيرة في العالم بمؤسسات الدولة وحدها، تنهض طوبى ببنية دينية ومجتمعية تملك فيها الطريقة دورًا مركزيًّا.","de":"Während viele Städte weltweit allein von staatlichen Institutionen verwaltet werden, tragen in Touba religiöse und gemeinschaftliche Strukturen den Großteil der Organisation.","en":"Where many cities worldwide are run by state institutions alone, Touba relies on religious and community structures for much of its organisation."}},{"id":"afr-020","version":2,"slug":"the-annual-replastering-of-djenne-s-great-mosque","contentType":"feature","category":"traditions","title":{"ar":"إعادة تجصيص مسجد جينيه الكبير سنوياً","de":"Die jährliche Neuverputzung der Großen Moschee von Djenné","en":"The annual replastering of Djenné's great mosque"},"deck":{"ar":"في مالي، يتحد السكان كل عام قبل موسم الأمطار لتجديد جدران أكبر مبنى طيني في العالم، في تقليد يعيد الحياة إلى المسجد ويرسخ الروابط الاجتماعية.","de":"In Mali versammeln sich die Bewohner jedes Jahr vor der Regenzeit, um die Wände des größten Lehmbaus der Welt gemeinsam zu erneuern – ein Ritual, das die Moschee und den sozialen Zusammenhalt der Stadt belebt.","en":"In Mali, residents gather each year before the rainy season to renew the walls of the world's largest adobe building, a tradition that revitalizes both the mosque and the town's social fabric."},"teaser":{"ar":"قبل هطول الأمطار، يخرج أهل جينيه والزوار لتجصيص المسجد الكبير بالطين والقش، في عمل جماعي يعكس روح التضامن والتقاليد المتوارثة.","de":"Vor dem Regen versammeln sich die Menschen in Djenné, um die Große Moschee mit Schlamm und Reishülsen neu zu verputzen. Ein gemeinschaftliches Werk, das Tradition und Zusammenhalt feiert.","en":"Before the rains, the people of Djenné come together to replaster the Great Mosque with mud and rice husks—a communal effort that celebrates tradition and solidarity."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس سنوي قبل المطر","paragraphs":["في مدينة جينيه بمالي، ينتظر السكان كل عام موسم الجفاف ليبدأوا في تحضير الطين الممزوج بقشور الأرز والماء. هذا الخليط هو المادة الأساسية التي تُكسى بها جدران المسجد الكبير، الذي يُعد أكبر مبنى من الطوب اللبن في العالم. يعود المبنى الحالي إلى عام 1907، حيث حل محل مسجد أقدم كان قائماً في الموقع نفسه.","قبل حلول موسم الأمطار، تتجمع مجموعات من السكان والزوار في ورشة عمل جماعية تُعرف باسم «كريبيساس» (Crépissage). يشارك الجميع، من الرجال والنساء إلى الأطفال، في هذا النشاط الذي يتطلب جهداً بدنياً كبيراً."]},{"heading":"تنظيم وإشراف","paragraphs":["يشرف على العمل نقابات البنائين ومجموعات الأحياء، حيث يتم توزيع المهام بدقة. يحرص المنظمون على أن يساهم كل فرد حسب قدرته، مما يعزز روح التعاون والمشاركة.","لا يقتصر هذا الحدث على تجديد المبنى فحسب، بل يعيد أيضاً تجديد الروابط الاجتماعية بين سكان المدينة. فهو مناسبة للالتقاء والتعارف وتبادل الأخبار، مما يجعله حدثاً مجتمعياً بامتياز."]},{"heading":"بين التقاليد والحفاظ على التراث","paragraphs":["يقع المسجد في قلب حياة السوق والمهرجانات في جينيه، كما أن الحي القديم في المدينة مصنف كموقع تراث عالمي لليونسكو. هذا الوضع يجعل من صيانة المبنى قضية معقدة، حيث تتصادم ممارسات الصيانة المحلية مع قواعد الحفاظ على التراث التي تقيد إجراء تغييرات على المبنى.","تختلف ممارسات التجصيص من منطقة إلى أخرى ومن جيل إلى آخر، كما أن إدارة المسجد تشمل السلطات الدينية والدولة وهيئات التراث، لذا فإن الأوصاف المبسطة قد تكون مضللة."]}],"de":[{"heading":"Ein jährliches Ritual vor dem Regen","paragraphs":["In der Stadt Djenné in Mali warten die Bewohner jedes Jahr auf die Trockenzeit, um mit der Vorbereitung des Lehms zu beginnen, der mit Reishülsen und Wasser gemischt wird. Diese Mischung bildet die Grundlage für die Wände der Großen Moschee, dem größten Lehmbau der Welt. Das heutige Gebäude stammt aus dem Jahr 1907 und ersetzte eine ältere Moschee an derselben Stelle.","Vor Beginn der Regenzeit versammeln sich Bewohner und Besucher zu einer gemeinschaftlichen Arbeitsaktion, die als „Crépissage“ bekannt ist. Alle machen mit – Männer, Frauen und Kinder – und tragen so zu einer körperlich anstrengenden, aber gemeinschaftlichen Aufgabe bei."]},{"heading":"Organisation und Aufsicht","paragraphs":["Die Arbeiten werden von Maurergilden und Nachbarschaftsgruppen organisiert, die die Aufgaben genau einteilen. Jeder trägt nach seinen Möglichkeiten bei, was den Geist der Zusammenarbeit und Teilhabe stärkt.","Dieses Ereignis dient nicht nur der Erneuerung des Gebäudes, sondern auch der Pflege der sozialen Beziehungen in der Stadt. Es ist eine Gelegenheit zum Treffen, Kennenlernen und Austauschen von Neuigkeiten und somit ein gesellschaftliches Ereignis par excellence."]},{"heading":"Zwischen Tradition und Denkmalschutz","paragraphs":["Die Moschee liegt im Zentrum des Markt- und Festlebens von Djenné, und die Altstadt ist ein UNESCO-Weltkulturerbe. Dieser Status macht die Instandhaltung des Gebäudes zu einer komplexen Angelegenheit, da lokale Pflegetraditionen mit den Denkmalschutzregeln kollidieren, die Veränderungen am Gebäude einschränken.","Die Verputzungspraktiken variieren von Region zu Region und von Generation zu Generation. Zudem umfasst die Verwaltung der Moschee religiöse Autoritäten, den Staat und Denkmalbehörden, sodass einfache Beschreibungen irreführend sein können."]}],"en":[{"heading":"A yearly ritual before the rains","paragraphs":["In the town of Djenné in Mali, residents wait each year for the dry season to begin preparing the mud mixed with rice husks and water. This mixture is the essential material used to coat the walls of the Great Mosque, the largest adobe building in the world. The present structure dates from 1907, replacing an earlier mosque on the same site.","Before the rainy season arrives, groups of residents and visitors gather for a communal working party known as the crépissage. Everyone participates—men, women, and children—in this physically demanding yet collective task."]},{"heading":"Organization and oversight","paragraphs":["The work is organized by masons' guilds and neighborhood groups, which carefully assign tasks. Each person contributes according to their ability, strengthening the spirit of cooperation and participation.","This event is not only about renewing the building but also about renewing social ties in the town. It is an occasion for meeting, getting to know one another, and exchanging news, making it a social event par excellence."]},{"heading":"Between tradition and heritage","paragraphs":["The mosque sits at the center of Djenné's market and festival life, and the town's old quarter is a UNESCO World Heritage Site. This status makes maintenance a complex issue, as local maintenance traditions clash with heritage rules that restrict changes to the building.","Replastering practices vary from region to region and from generation to generation. Moreover, the mosque's management involves religious authorities, the state, and heritage bodies, so simple descriptions can mislead."]}]},"context":{"countries":["ML"],"region":"Inland Niger Delta, Mali","continent":"africa","languages":["bm","fr"],"period":"contemporary"},"tags":["traditions","Inland Niger Delta, Mali"],"sources":[{"organization":"Wikipedia","title":{"ar":"Great Mosque of Djenné","de":"Great Mosque of Djenné","en":"Great Mosque of Djenné"},"url":"https://en.wikipedia.org/wiki/Great_Mosque_of_Djenn%C3%A9","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Djenné","de":"Djenné","en":"Djenné"},"url":"https://en.wikipedia.org/wiki/Djenn%C3%A9","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يحمل الشبان سلال الطين فوق سقالات من سعف النخيل بينما تمد النساء والأطفال الماء، وتعمل المدينة بأكملها على إيقاع الطبول.","de":"Junge Männer tragen Körbe voller Lehm über Gerüste aus Palmzweigen, während Frauen und Kinder Wasser reichen, und die ganze Stadt arbeitet im Rhythmus der Trommeln.","en":"Young men carry baskets of mud up scaffolding of palm branches while women and children hand up water, and the whole town works to a rhythm of drumming."},"misunderstanding":{"ar":"قد يعتقد البعض أن إعادة التجصيص مجرد عمل صيانة روتيني، لكنه في الواقع طقس اجتماعي وديني عميق الجذور يعزز الهوية الجماعية.","de":"Man könnte denken, die Neuverputzung sei nur eine routinemäßige Instandhaltungsarbeit, doch tatsächlich ist sie ein tief verwurzeltes soziales und religiöses Ritual, das die kollektive Identität stärkt.","en":"Some might think the replastering is merely routine maintenance, but it is actually a deeply rooted social and religious ritual that reinforces collective identity."},"comparison":{"ar":"يشبه هذا التقليد طقوس البناء الجماعي في مجتمعات أخرى، حيث تتحول صيانة المعالم إلى مناسبة لتجديد الروابط الاجتماعية والتعبير عن الانتماء.","de":"Dieser Brauch ähnelt gemeinschaftlichen Bauprozessen in anderen Gesellschaften, bei denen die Pflege von Denkmälern zu einem Anlass wird, soziale Bindungen zu erneuern und Zugehörigkeit auszudrücken.","en":"This custom resembles communal building practices in other societies, where maintaining landmarks becomes an occasion to renew social bonds and express belonging."}},{"id":"afr-022","version":2,"slug":"kuomboka-the-lozi-king-s-journey-out-of-the-flood","contentType":"feature","category":"traditions","title":{"ar":"كومبوكا: رحلة الملك اللوزي خارج الماء","de":"Kuomboka: Der Lozi-König verlässt das Wasser","en":"Kuomboka: the Lozi king leaves the water"},"deck":{"ar":"حين يفيض الزامبيزي على سهل باروتسي، ينتقل الملك اللوزي بقاربه الملكي من ليالوي إلى ليمولونغا وسط الطبول والأغاني.","de":"Wenn der Sambesi die Barotse-Ebene überflutet, zieht der Lozi-König mit seinem königlichen Boot von Lealui nach Limulunga, begleitet von Trommeln und Gesang.","en":"When the Zambezi floods the Barotse plain, the Lozi king travels by royal barge from Lealui to Limulunga, accompanied by drumming, singing and paddlers."},"teaser":{"ar":"احتفال سنوي في غرب زامبيا يجمع بين الاستجابة العملية للفيضان وأداء الهوية الملكية اللوزية أمام الجماهير.","de":"Eine jährliche Zeremonie im Westen Sambias, die praktische Antwort auf die Flut und Aufführung königlicher Lozi-Identität zugleich ist.","en":"An annual ceremony in western Zambia that is at once a practical response to the flood and a performance of Lozi kingship and identity."},"readingMinutes":1,"sections":{"ar":[{"heading":"معنى الاسم وموسمه","paragraphs":["كلمة كومبوكا تعني باللغة اللوزية «الخروج من الماء»، وهي تسمية دقيقة لما يحدث كل عام في سهل باروتسي بغرب زامبيا. فمع نهاية موسم الأمطار يفيض نهر الزامبيزي الأعلى على السهل، فتغمر المياه المراعي والطرق والحقول.","ولا يرتبط موعد الاحتفال بتاريخ ثابت في التقويم، بل يتبع حركة الفيضان نفسه. لذلك يختلف التوقيت من سنة إلى أخرى، ويبقى الناس في ترقّب لعلامات الماء قبل أن يبدأ الاستعداد."]},{"heading":"الملك في قاربه","paragraphs":["ينتقل الليتونغا، ملك اللوزي، من ليالوي إلى ليمولونغا على متن قارب ملكي. ويصحبه في الرحلة قرع الطبول والغناء ومجدفون يرتدون أزياء احتفالية.","أما القارب الرئيسي، واسمه ناليكواندا، فيُطلى بالأسود والأبيض على هيئة حمار وحشي. وتتجمع الجماهير على الأرض المرتفعة لمشاهدة مروره، فتصطف العائلات على طول الطريق وتخيّم في مواقع آمنة من الماء."]},{"heading":"بين الحاجة والرمز","paragraphs":["هذا الاحتفال استجابة عملية للفيضان السنوي في الوقت نفسه الذي يمثل فيه أداءً للسلطة الملكية والهوية اللوزية. فالانتقال إلى أرض أعلى ليس مجرد تقليد، بل تنظيم للحياة في سهل يتغير وجهه كل عام.","وتعتبر زامبيا كومبوكا احتفالاً وطنياً، ويجذب اهتمام الزوار والباحثين المهتمين بتاريخ اللوزي وإدارة السهول الفيضية. وقد أثّرت السياسة اللوزية وتعاقب العرش على طريقة أداء الاحتفال عبر الزمن، كما تختلف مظاهر المشاركة بين المناطق والأجيال."]}],"de":[{"heading":"Der Name und seine Jahreszeit","paragraphs":["Kuomboka bedeutet in der Lozi-Sprache „aus dem Wasser herausgehen“, und genau das beschreibt, was sich jedes Jahr in der Barotse-Ebene im Westen Sambias abspielt. Am Ende der Regenzeit tritt der obere Sambesi über die Ufer und überflutet Weideland, Wege und Felder.","Der Termin der Zeremonie folgt nicht einem festen Kalenderdatum, sondern dem Wasser selbst. Deshalb verschiebt er sich von Jahr zu Jahr, und die Menschen beobachten die Zeichen des Flusses, bevor die Vorbereitungen beginnen."]},{"heading":"Der König im Boot","paragraphs":["Der Litunga, der König der Lozi, reist von Lealui nach Limulunga auf einem königlichen Boot. Trommeln, Gesang und Paddler in zeremonieller Kleidung begleiten ihn.","Das Hauptboot, die Nalikwanda, ist schwarz und weiß bemalt wie ein Zebra. Die Menschen versammeln sich auf höherem Gelände, um es vorbeiziehen zu sehen; Familien entlang der Route schlagen ihre Lager auf sicherem Boden auf."]},{"heading":"Zwischen Notwendigkeit und Zeichen","paragraphs":["Die Zeremonie ist zugleich eine praktische Antwort auf die jährliche Flut und eine Aufführung von Lozi-Königtum und Identität. Der Umzug auf höheres Land ist kein bloßes Schauspiel, sondern eine Ordnung des Lebens in einer Ebene, die sich jedes Jahr verändert.","Sambia erkennt Kuomboka als nationale Zeremonie an, und sie zieht Besucher und Forschende an, die sich für die Geschichte der Lozi und für die Bewirtschaftung von Flussauen interessieren. Die Lozi-Politik und die königliche Nachfolge haben die Ausführung über die Zeit geprägt, und die Beteiligung unterscheidet sich je nach Region und Generation."]}],"en":[{"heading":"The name and its season","paragraphs":["Kuomboka means “to get out of water” in Lozi, and that is exactly what happens each year on the Barotse Floodplain in western Zambia. At the end of the rainy season the upper Zambezi floods the plain, covering grazing land, paths and fields.","The ceremony does not follow a fixed calendar date but the flood itself. Its timing shifts from year to year, and people watch the signs of the river before preparations begin."]},{"heading":"The king in his barge","paragraphs":["The Litunga, king of the Lozi, travels from Lealui to Limulunga by royal barge. Drumming, singing and paddlers in ceremonial dress accompany him on the journey.","The main barge, the Nalikwanda, is painted black and white like a zebra. Crowds gather on the higher ground to watch it pass, and families along the route camp on safe ground to see the crossing."]},{"heading":"Practical need and living symbol","paragraphs":["The ceremony is both a practical response to the annual flood and a performance of Lozi kingship and identity. Moving to higher land is not merely display; it is how life is organised on a plain that changes shape every year.","Zambia recognises Kuomboka as a national ceremony, and it draws visitors and researchers interested in Lozi history and floodplain management. Lozi politics and royal succession have shaped how it is performed over time, and participation varies across regions and generations."]}]},"context":{"countries":["ZM"],"region":"Barotse Floodplain, Western Zambia","community":"Lozi","continent":"africa","languages":["en"],"period":"contemporary"},"tags":["traditions","Barotse Floodplain, Western Zambia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kuomboka","de":"Kuomboka","en":"Kuomboka"},"url":"https://en.wikipedia.org/wiki/Kuomboka","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Lozi people","de":"Lozi people","en":"Lozi people"},"url":"https://en.wikipedia.org/wiki/Lozi_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يبدأ قرع الطبول أياماً قبل العبور، وتخيّم العائلات على طول المسار في الأرض المرتفعة لمشاهدة مرور القارب.","de":"Die Trommler beginnen Tage vor der Überfahrt, und Familien entlang der Route campen auf höherem Gelände, um das Boot vorbeiziehen zu sehen.","en":"Drummers begin days before the crossing, and families along the route camp on high ground to watch the barge pass."},"misunderstanding":{"ar":"يظن بعض من يسمع بالاحتفال أنه مجرد استعراض سياحي، لكنه في جوهره تنظيم عملي للحياة مع فيضان متوقع كل عام.","de":"Manche halten die Zeremonie für eine reine Touristenattraktion, doch sie ist zuerst eine praktische Ordnung des Lebens mit einer erwartbaren Flut.","en":"Some assume the ceremony is only a tourist spectacle, but it is first a practical way of organising life around a flood that arrives every year."},"comparison":{"ar":"يشبه كومبوكا في وظيفته أي مجتمع ساحلي يعيد ترتيب بيته مع المدّ، لكنه هنا يرتبط بشخص الملك وبالقارب الملكي.","de":"Kuomboka ähnelt in seiner Funktion jeder Küstengemeinde, die sich mit der Flut neu einrichtet, doch hier ist es an den König und sein Boot gebunden.","en":"Kuomboka works much like any coastal community rearranging its home around the tide, except here it is tied to a king and a royal barge."}},{"id":"afr-023","version":2,"slug":"abusua-akan-identity-through-the-mother-s-line","contentType":"feature","category":"family-and-friendship","title":{"ar":"أبوسوا: هوية الأكان من خط الأم","de":"Abusua: Akan-Identität über die mütterliche Linie","en":"Abusua: Akan identity through the mother's line"},"deck":{"ar":"في مجتمعات الأكان بغانا، ينتمي الفرد مدى الحياة إلى أبوسوا أمه، حيث تتحدد الوراثة والمناصب والواجبات.","de":"In den Akan-Gesellschaften Ghanas gehört man lebenslang zur Abusua der Mutter, die Erbe, Ämter und Pflichten bestimmt.","en":"In Akan societies of Ghana, a person belongs for life to the mother's abusua, which shapes inheritance, office and obligations."},"teaser":{"ar":"أبوسوا هو مجموعة القرابة الأمومية عند الأكان، تحدد الهوية والوراثة والمناصب والواجبات الجنائزية.","de":"Abusua ist die matrilineare Verwandtschaftsgruppe der Akan, die Identität, Erbe, Ämter und Begräbnispflichten festlegt.","en":"Abusua is the Akan matrilineal group that determines identity, inheritance, political office and funeral duties."},"readingMinutes":1,"sections":{"ar":[{"heading":"أبوسوا: جماعة الأم مدى الحياة","paragraphs":["أبوسوا هو المصطلح الأكاني للجماعة القرابية المنحدرة من سلفة مشتركة من جهة الأم، وينتمي الشخص إلى أبوسوا أمه طوال حياته. هذا الانتماء لا يتغير بالزواج أو الإقامة، بل يظل راسخًا كجزء من هوية الفرد.","في تقاليد الأكان، تتبع وراثة الممتلكات والمناصب السياسية وبعض الأدوار الطقسية خط أبوسوا، حتى عندما يوفر الآباء لأطفالهم. هذا لا يعني إهمال دور الأب، بل يعني أن الملكية والمنصب لهما مسار محدد عبر الأم.","يرتبط كل أبوسوا بآلهة (أبوسوم) ومحظورات معينة، ويتشارك الأعضاء التزامات في الجنازات ومراسم تسمية الأطفال. هذه الالتزامات تعزز التضامن بين أفراد الجماعة وتؤكد انتماءهم المشترك.","يوجد سبعة أبوسوا قديمة في تقليد الأكان، مع العديد من الفروع الفرعية، والنظام ينظم zarówno القرابة والسياسة المحلية. فاختيار الزعماء الأكان يتم عبر خطوط أبوسوا، مما يجعل القرابة أساسًا للسلطة.","للأخ الأكبر للأم (ووفا) دور معترف به في تربية الطفل وحل النزاعات. فهو يمثل سلطة الأم في حياة الطفل، ويلعب دور الوسيط في الخلافات الأسرية.","تختلف الممارسة بين مجموعات الأكان مثل الأشانتي والفانتي وغيرها، كما أن الهجرة إلى المدن والمسيحية والقانون الرسمي قد غيرت كيفية التعامل مع الميراث. وهناك تباين إقليمي وجيلي في مدى التمسك بهذه التقاليد."]},{"heading":"الوراثة والمنصب عبر خط الأم","paragraphs":["في الماضي، كانت الممتلكات والمناصب تنتقل عبر أبوسوا، مما يعني أن الأخوال كانوا يلعبون دورًا محوريًا في حياة الأبناء. اليوم، مع تأثير القانون الرسمي، أصبحت بعض العائلات تجمع بين العرف والممارسة القانونية."]},{"heading":"الالتزامات والطقوس المشتركة","paragraphs":["يجتمع أفراد أبوسوا في المناسبات الاجتماعية والدينية، حيث يتشاركون الواجبات والاحتفالات. هذه المناسبات تعزز الروابط وتذكر الأجيال الجديدة بأصولهم المشتركة."]}],"de":[{"heading":"Abusua: Die mütterliche Gruppe ein Leben lang","paragraphs":["Abusua ist der Akan-Begriff für eine matrilineare Gruppe, die von einer gemeinsamen Vorfahrin abstammt. Eine Person gehört ihr Leben lang zur Abusua ihrer Mutter. Diese Zugehörigkeit ändert sich nicht durch Heirat oder Wohnsitz, sondern bleibt fester Teil der Identität.","In der Akan-Tradition folgen Erbschaft von Eigentum, politische Ämter und bestimmte rituelle Rollen der Abusua-Linie, auch wenn Väter für ihre Kinder sorgen. Das bedeutet nicht, dass die Rolle des Vaters fehlt, sondern dass Eigentum und Amt einen festgelegten Weg über die Mutter nehmen.","Jede Abusua ist mit bestimmten Abosom (Gottheiten) und Tabus verbunden, und die Mitglieder teilen Verpflichtungen bei Begräbnissen und Namensgebungszeremonien. Diese Pflichten stärken den Zusammenhalt und bestätigen die gemeinsame Zugehörigkeit.","Es gibt sieben alte Abusua in der Akan-Tradition, mit vielen Untergruppen, und das System organisiert sowohl Verwandtschaft als auch lokale Politik. Die Wahl der Akan-Häuptlinge erfolgt über Abusua-Linien, wodurch Verwandtschaft zur Grundlage der Autorität wird.","Der Mutterbruder (wɔfa) hat eine anerkannte Rolle in der Erziehung eines Kindes und bei der Beilegung von Streitigkeiten. Er vertritt die Autorität der Mutter im Leben des Kindes und vermittelt bei Familienkonflikten.","Die Praxis variiert zwischen Asante, Fante und anderen Akan-Gruppen, und Stadtmigration, Christentum und formelles Recht haben den Umgang mit Erbschaft verändert. Es gibt regionale und generationelle Unterschiede in der Bindung an diese Traditionen."]},{"heading":"Erbe und Amt über die mütterliche Linie","paragraphs":["Früher wurden Eigentum und Ämter über die Abusua weitergegeben, sodass Onkel mütterlicherseits eine zentrale Rolle im Leben der Kinder spielten. Heute kombinieren manche Familien aufgrund des formellen Rechts Gewohnheit und gesetzliche Praxis."]},{"heading":"Gemeinsame Pflichten und Rituale","paragraphs":["Die Mitglieder einer Abusua kommen bei sozialen und religiösen Anlässen zusammen und teilen Aufgaben und Feiern. Diese Anlässe stärken die Bindungen und erinnern die jüngeren Generationen an ihre gemeinsamen Wurzeln."]}],"en":[{"heading":"Abusua: the mother's group for life","paragraphs":["Abusua is the Akan term for a matrilineal group descended from a common ancestress, and a person belongs to the mother's abusua for life. This membership does not change through marriage or residence; it remains a fixed part of identity.","In Akan tradition, inheritance of property, political office and certain ritual roles follows the abusua line, even where fathers provide for their children. This does not mean the father's role is absent, but that property and office have a defined path through the mother.","Each abusua is associated with particular abosom (deities) and taboos, and members share obligations at funerals and naming ceremonies. These duties strengthen solidarity and affirm shared belonging.","There are seven ancient abusua in Akan tradition, with many more subgroups, and the system organises both kinship and local politics. Akan chiefs are chosen through abusua lines, making kinship a foundation of authority.","The mother's brother (wɔfa) has a recognised role in a child's upbringing and in settling disputes. He represents the mother's authority in the child's life and mediates in family conflicts.","Practice varies between Asante, Fante and other Akan groups, and urban migration, Christianity and formal law have changed how inheritance is handled. There is regional and generational variation in how strongly these traditions are upheld."]},{"heading":"Inheritance and office through the mother's line","paragraphs":["In the past, property and offices passed through the abusua, so maternal uncles played a central role in children's lives. Today, with the influence of formal law, some families combine custom with legal practice."]},{"heading":"Shared obligations and rituals","paragraphs":["Members of an abusua come together for social and religious occasions, sharing duties and celebrations. These occasions reinforce bonds and remind younger generations of their common roots."]}]},"context":{"countries":["GH"],"region":"Akan areas of Ghana","community":"Akan","continent":"africa","languages":["ak","tw","en"],"period":"contemporary"},"tags":["family-and-friendship","Akan areas of Ghana"],"sources":[{"organization":"Wikipedia","title":{"ar":"Abusua","de":"Abusua","en":"Abusua"},"url":"https://en.wikipedia.org/wiki/Abusua","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Matrilineality","de":"Matrilineality","en":"Matrilineality"},"url":"https://en.wikipedia.org/wiki/Matrilineality","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في جنازة أكانية، تقود أبوسوا المتوفى الحداد وتوزيع الممتلكات بدلاً من عائلة الزوج.","de":"Bei einem Akan-Begräbnis führen die Abusua des Verstorbenen die Trauer und die Verteilung des Eigentums an, nicht die Familie des Ehemanns.","en":"At an Akan funeral, the mourning and the distribution of property are led by the deceased's abusua rather than by the widower's family."},"misunderstanding":{"ar":"يعتقد البعض أن النظام الأمومي يعني غياب دور الأب، لكن الواقع أن الأب يوفر لأطفاله بينما تظل الهوية والوراثة عبر الأم.","de":"Manche glauben, das matrilineare System bedeute die Abwesenheit des Vaters, doch tatsächlich sorgt der Vater für seine Kinder, während Identität und Erbe über die Mutter laufen.","en":"Some believe that a matrilineal system means the father's role is absent, but in reality the father provides for his children while identity and inheritance run through the mother."},"comparison":{"ar":"بالمقارنة مع أنظمة القرابة الأبوية في أوروبا، حيث ينتمي الطفل إلى عائلة الأب، فإن أبوسوا تؤكد على خط الأم كهوية دائمة.","de":"Im Vergleich zu patrilinearen Verwandtschaftssystemen in Europa, wo das Kind zur Familie des Vaters gehört, betont Abusua die mütterliche Linie als dauerhafte Identität.","en":"Compared with patrilineal kinship systems in Europe, where a child belongs to the father's family, abusua emphasises the mother's line as a permanent identity."}},{"id":"afr-024","version":2,"slug":"lobolo-marriage-as-a-negotiation-between-families","contentType":"feature","category":"family-and-friendship","title":{"ar":"لوبولو: الزواج تفاوض بين عائلتين","de":"Lobolo: Ehe als Verhandlung zwischen Familien","en":"Lobolo: marriage as a negotiation between families"},"deck":{"ar":"كيف تحوّل مفاوضات الماشية أو المال الزواج إلى تحالف طويل الأمد بين عائلتين.","de":"Wie Verhandlungen über Vieh oder Geld eine Ehe in ein langfristiges Bündnis zwischen zwei Familien verwandeln.","en":"How negotiations over cattle or money turn a marriage into a lasting alliance between two families."},"teaser":{"ar":"ليست شراءً للعروس، بل اعتراف بفقدان عائلتها ورباط يلزم الطرفين. تعرّف على طقوس لوبولو في جنوب أفريقيا.","de":"Kein Brautkauf, sondern Anerkennung des Verlusts und dauerhafte Bindung. Ein Blick auf Lobolo in Südafrika und Mosambik.","en":"Not a purchase of a wife, but an acknowledgement of loss and a binding tie. Inside lobolo practices in southern Africa."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما وراء الماشية: معنى لوبولو","paragraphs":["لوبولو هو انتقال ماشية أو سلع من عائلة العريس إلى عائلة العروس، ويمارَس بين الزولو والكوسا والسوازي والندبيلي وغيرهم من مجتمعات الجنوب الأفريقي. وهو ليس شراءً للزوجة؛ فالمفاوضات تعترف بخسارة عائلة العروس وتنشئ التزامات وروابط دائمة بين العائلتين.","في كثير من المناطق، تكون الأبقار تقليدية، لكن العائلات الحضرية تتوافق بشكل متزايد على المال أو الأقساط أو عدد رمزي من الحيوانات. وغالبًا ما يجتمع كبار السن والوسطاء لإجراء المفاوضات التي قد تستغرق شهورًا، ويمكن للزوجين أن يعيشا معًا قبل إتمام اللوبولو.","تختلف الممارسة بشكل واضح بين المجموعات: فعادة الزولو تختلف عن عادة الكوسا والسوازي والتسونغا، كما تختلف بين الأجيال. وفي المدن، قد يكتفي البعض برمزية العدد بينما يتمسك آخرون بالتفاصيل التقليدية."]},{"heading":"كيف تسير المفاوضات","paragraphs":["تبدأ المفاوضات عادة بزيارة رسمية من عائلة العريس إلى منزل العروس، حيث يتبادل الطرفان التحيات ويقدّم الوفد طلبه. يتحدث عم العروس باسم عائلتها، ويقود الوسطاء النقاش حول العدد والشكل.","مثال: تلتقي عائلتان في منزل العروس، وتتبادلان التحيات، ثم يبدأ الطلب الرسمي للوبولو، حيث يتحدث عم العروس باسم عائلتها. هذه اللحظة ليست مجرد صفقة، بل إعلان عن علاقة جديدة بين العائلتين."]},{"heading":"نقاش عام وحياة يومية","paragraphs":["تتكرر في النقاش العام في جنوب أفريقيا قضية تكلفة اللوبولو للشباب وعلاقته بالمساواة بين الجنسين. فبعض الأسر ترى فيه حماية للعروس، بينما يرى آخرون أنه قد يؤخر الزواج أو يثقل كاهل العريس.","في الحياة اليومية، غالبًا ما يُدمج اللوبولو مع الزواج المدني أو الكنسي بطرق مختلفة. فبعض الأزواج يكملون الإجراءات التقليدية أولاً، وآخرون يبدؤون بالمدني ثم يستكملون اللوبولو لاحقًا."]}],"de":[{"heading":"Mehr als Vieh: die Bedeutung von Lobolo","paragraphs":["Lobolo (auch Lobola) bezeichnet die Übertragung von Vieh oder Gütern von der Familie des Bräutigams an die Familie der Braut, wie sie bei den Zulu, Xhosa, Swazi, Ndebele und anderen Gesellschaften im südlichen Afrika praktiziert wird. Es ist kein Kauf einer Ehefrau: Die Verhandlungen erkennen den Verlust der Brautfamilie an und schaffen dauerhafte Verpflichtungen und Bindungen zwischen beiden Familien.","Die Beträge und Formen variieren stark; in vielen Gebieten ist Vieh traditionell, während städtische Familien zunehmend Geld, Ratenzahlungen oder eine symbolische Anzahl von Tieren vereinbaren. Älteste und Vermittler führen die Verhandlungen, die Monate dauern können, und ein Paar kann zusammenleben, bevor Lobolo abgeschlossen ist.","Die Praxis unterscheidet sich deutlich zwischen Gruppen – Zulu, Xhosa, Swazi und Tsonga haben eigene Bräuche – und auch zwischen Generationen. In Städten begnügen sich manche mit symbolischen Zahlen, während andere auf traditionellen Details beharren."]},{"heading":"Wie die Verhandlungen ablaufen","paragraphs":["Die Verhandlungen beginnen meist mit einem formellen Besuch der Familie des Bräutigams im Haus der Braut, bei dem Begrüßungen ausgetauscht und die Anfrage vorgebracht wird. Der Onkel der Braut spricht für ihre Familie, und Vermittler leiten das Gespräch über Anzahl und Form.","Beispiel: Zwei Familien treffen sich im Haus der Braut, tauschen Begrüßungen aus und beginnen die formelle Bitte um Lobolo, wobei der Onkel der Braut für ihre Familie spricht. Dieser Moment ist kein bloßes Geschäft, sondern die Ankündigung einer neuen Beziehung zwischen den Familien."]},{"heading":"Öffentliche Debatte und Alltag","paragraphs":["In der südafrikanischen Öffentlichkeit wird immer wieder über die Kosten von Lobolo für junge Männer und den Zusammenhang mit Geschlechtergerechtigkeit diskutiert. Manche Familien sehen darin einen Schutz der Braut, andere befürchten, dass es Ehen verzögert oder den Bräutigam überlastet.","Im Alltag wird Lobolo oft mit standesamtlicher oder kirchlicher Trauung kombiniert. Manche Paare absolvieren zuerst die traditionellen Schritte, andere heiraten zuerst standesamtlich und holen Lobolo später nach."]}],"en":[{"heading":"Beyond cattle: the meaning of lobolo","paragraphs":["Lobolo (lobola) is the transfer of livestock or goods from a groom's family to a bride's family, practised among Zulu, Xhosa, Swazi, Ndebele and other southern African societies. It is not a purchase of a wife: the negotiations recognise the bride's family's loss and create lasting obligations and ties between two families.","Amounts and forms vary widely; cattle are traditional in many areas, while urban families increasingly agree on cash, instalments or a symbolic number of animals. Elders and go-betweens conduct the negotiations, which can take months, and a couple may live together before lobolo is completed.","The practice differs markedly between groups — Zulu, Xhosa, Swazi and Tsonga customs are not the same — and between generations. In cities, some families settle on a symbolic number while others insist on traditional details."]},{"heading":"How the negotiations unfold","paragraphs":["Negotiations usually begin with a formal visit from the groom's family to the bride's home, where greetings are exchanged and the request is presented. The bride's uncle speaks for her family, and go-betweens guide the discussion of number and form.","Example: Two families meet at the bride's home, exchange greetings, and begin the formal request for lobolo, with the bride's uncle speaking for her family. This moment is not merely a transaction but the announcement of a new relationship between the families."]},{"heading":"Public debate and daily life","paragraphs":["The cost of lobolo for young men, and its relationship to gender equality, are recurring subjects in South African public debate. Some families see it as protecting the bride, while others worry it delays marriages or burdens the groom.","In daily life, lobolo is often combined with civil or church marriage. Some couples complete the traditional steps first, while others marry civilly and complete lobolo later."]}]},"context":{"countries":["ZA","MZ"],"region":"Southern Africa","community":"Nguni and Tsonga families","continent":"africa","languages":["zu","st","sn","pt"],"period":"contemporary"},"tags":["family-and-friendship","Southern Africa","Lobolo (lobola)","It is"],"sources":[{"organization":"Wikipedia","title":{"ar":"Lobolo","de":"Lobolo","en":"Lobolo"},"url":"https://en.wikipedia.org/wiki/Lobolo","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Bride price","de":"Bride price","en":"Bride price"},"url":"https://en.wikipedia.org/wiki/Bride_price","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تلتقي عائلتان في منزل العروس، وتتبادلان التحيات، ثم يبدأ الطلب الرسمي للوبولو، حيث يتحدث عم العروس باسم عائلتها.","de":"Zwei Familien treffen sich im Haus der Braut, tauschen Begrüßungen aus und beginnen die formelle Bitte um Lobolo, wobei der Onkel der Braut für ihre Familie spricht.","en":"Two families meet at the bride's home, exchange greetings, and begin the formal request for lobolo, with the bride's uncle speaking for her family."},"misunderstanding":{"ar":"الاعتقاد بأن اللوبولو شراء للعروس خطأ شائع؛ فهو في جوهره اعتراف ورباط بين عائلتين، وليس معاملة تجارية.","de":"Der Irrglaube, Lobolo sei ein Brautkauf, ist weit verbreitet; tatsächlich ist es eine Anerkennung und ein Bündnis zwischen zwei Familien, kein Handelsgeschäft.","en":"The common misconception that lobolo is a purchase of a wife is misleading; it is fundamentally an acknowledgement and a bond between two families, not a commercial transaction."},"comparison":{"ar":"بينما تُفهم بعض أشكال المهر في مجتمعات أخرى كدفعة من العروس، يركز اللوبولو على التعويض الرمزي والتحالف بين العائلتين.","de":"Während in manchen Gesellschaften eine Mitgift als Zahlung der Brautelftern gilt, betont Lobolo den symbolischen Ausgleich und das Bündnis zwischen den Familien.","en":"While dowry in some societies is understood as a payment from the bride's family, lobolo emphasises symbolic compensation and alliance between the families."}},{"id":"afr-025","version":2,"slug":"kwanjula-the-baganda-introduction-that-makes-a-marriage","contentType":"scene","category":"family-and-friendship","title":{"ar":"كوانجولا: حين يُقدَّم العريس إلى عائلة العروس","de":"Kwanjula: Wenn die Familie des Bräutigams um die Braut wirbt","en":"Kwanjula: When a Groom's Family Comes Asking"},"deck":{"ar":"مراسم التعريف الباغندية ليست حفلة عابرة، بل عقد زواج عرفي يُعلن أمام الجميع.","de":"Die Baganda-Introduction ist kein bloßes Fest, sondern ein öffentlich geschlossener Ehevertrag nach Gewohnheitsrecht.","en":"The Baganda introduction is not a decorative party but a publicly concluded customary marriage contract."},"teaser":{"ar":"في وسط أوغندا، لا يبدأ الزواج بموافقة العروسين فقط، بل بوفد يحمل سلال فاكهة ينتظر حكم العائلة.","de":"In Zentraluganda beginnt eine Ehe nicht nur mit zwei Ja-Worten, sondern mit einer Delegation, die Früchtekörbe trägt und auf das Urteil der Familie wartet.","en":"In central Uganda a marriage begins not with two yeses alone, but with a delegation carrying fruit baskets and waiting on a family's verdict."},"readingMinutes":1,"sections":{"ar":[{"heading":"من يطلب ومن يوافق","paragraphs":["الكوانجولا هو مراسم التعريف لدى الباغندا في وسط أوغندا، يقدّم فيها العريس وعائلته رسمياً إلى عائلة العروس. وهو في ثقافة كيغاندا عقد الزواج العرفي نفسه، يشمل تقديم الهدايا والخطب والإعلان العلني عن العلاقة أمام الحاضرين.","تستضيف عائلة العروس المناسبة، ولها حق القبول أو المساءلة، ولهذا تكون الاحتفالات كبيرة بحضور الطعام والموسيقى ومقدّم الحفل. ومن هنا يفهم المشاركون أن الأمر ليس مجاملة، بل تفاوض اجتماعي معلن."]},{"heading":"اللباس والحساب","paragraphs":["ترتدي النساء عادةً الغوميسي، وهو فستان طويل يبلغ الأرض، بينما يرتدي الرجال الكانزو. أما سكان المدن فيقيمون الكوانجولا إلى جانب حفل الكنيسة أو الزواج المدني، وقد صار الحدث نفقة كبيرة ومظهراً اجتماعياً.","مثال يومي: يصل وفد العريس حاملاً سلال فاكهة ومظاريف، وتستقبله عمّات العروس، ثم ينتظر الجميع بينما تتناقش العائلة في الطلب. والكوانجولا خاص ببوغندا؛ فلمجتمعات أوغندية أخرى تقاليد تعريف مختلفة، وتختلف الطوائف المسيحية في تعاملها معه."]}],"de":[{"heading":"Wer bittet, wer entscheidet","paragraphs":["Kwanjula ist die Introduction-Zeremonie der Baganda in Zentraluganda, bei der der Bräutigam und seine Familie der Familie der Braut formell vorgestellt werden. In der Kiganda-Kultur gilt sie zugleich als der traditionelle Ehevertrag: mit Geschenken, Reden und der öffentlichen Benennung der Beziehung.","Gastgeber ist die Familie der Braut. Sie kann den Bräutigam annehmen oder befragen, weshalb die Veranstaltung meist groß ist, mit Essen, Musik und Moderation. Wer teilnimmt, versteht deshalb: Es geht nicht um Höflichkeit, sondern um eine öffentliche soziale Aushandlung."]},{"heading":"Gewand und Rechnung","paragraphs":["Frauen tragen bei der Kwanjula üblicherweise die knöchellange Gomesi, Männer den Kanzu. Städtische Ugander feiern die Kwanjula oft neben der kirchlichen oder standesamtlichen Hochzeit, und das Ereignis ist zu einer erheblichen Ausgabe und einem gesellschaftlichen Schaufenster geworden.","Ein Alltagsbild: Die Delegation des Bräutigams kommt mit Obstkörben und Umschlägen, die Tanten der Braut begrüßen sie, und alle warten, während die Familie über die Anfrage berät. Die Kwanjula ist spezifisch für Buganda; andere ugandische Gesellschaften haben eigene Introduktionsbräuche, und christliche Konfessionen gehen unterschiedlich damit um."]}],"en":[{"heading":"Who asks and who decides","paragraphs":["Kwanjula is the Baganda introduction ceremony in which a groom and his family are formally presented to the bride's family. In Kiganda culture it is the customary marriage contract itself, involving gift-giving, speeches and the public naming of the relationship.","The bride's family hosts and can accept or question the groom, which is why the event is usually large, with food, music and emcees. Participants understand it as a public social negotiation rather than a courtesy."]},{"heading":"Dress and expense","paragraphs":["Women usually wear the gomesi, a floor-length dress, while men wear the kanzu. Urban Ugandans often hold kwanjula alongside church or civil weddings, and it has become a major expense and social display.","A concrete scene: a groom's delegation arrives with baskets of fruit and envelopes, is greeted by the bride's aunties, and waits while the family discusses the request. Kwanjula is specific to Buganda; other Ugandan societies have different introduction customs, and Christian denominations vary in how they treat it."]}]},"context":{"countries":["UG"],"region":"Buganda, central Uganda","community":"Baganda","continent":"africa","languages":["lg","en","sw"],"period":"contemporary"},"tags":["family-and-friendship","Buganda, central Uganda","Kwanjula is","It is"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kwanjula","de":"Kwanjula","en":"Kwanjula"},"url":"https://en.wikipedia.org/wiki/Kwanjula","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Gomesi","de":"Gomesi","en":"Gomesi"},"url":"https://en.wikipedia.org/wiki/Gomesi","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يصل وفد العريس حاملاً سلال فاكهة ومظاريف، وتستقبله عمّات العروس، ثم ينتظر بينما تتناقش العائلة في الطلب.","de":"Die Delegation des Bräutigams kommt mit Obstkörben und Umschlägen, die Tanten der Braut begrüßen sie, und alle warten, während die Familie über die Anfrage berät.","en":"A groom's delegation arrives with baskets of fruit and envelopes, is greeted by the bride's aunties, and waits while the family discusses the request."},"misunderstanding":{"ar":"ليس كل زواج أوغندي يبدأ بكوانجولا، فهي مراسم خاصة ببوغندا وليست نموذجاً لكل البلاد.","de":"Nicht jede ugandische Hochzeit beginnt mit einer Kwanjula; sie gehört zu Buganda und ist kein Muster für das ganze Land.","en":"Not every Ugandan marriage begins with a kwanjula; it belongs to Buganda and is not a template for the whole country."},"comparison":{"ar":"كما تختلف مراسم الخطوبة في مجتمعات أخرى بين عقد مكتوب ولقاء عائلي غير ملزم، يظل الكوانجولا عقداً اجتماعياً علنياً لا مجرد حفلة تعريف.","de":"Wie Verlobungsbräuche anderer Gesellschaften zwischen verbindlichem Vertrag und unverbindlichem Familientreffen schwanken, bleibt die Kwanjula ein öffentlich geschlossener sozialer Vertrag und nicht nur ein Fest.","en":"As engagement customs elsewhere range from binding contract to informal family meeting, kwanjula remains a publicly concluded social contract rather than merely a celebration."}},{"id":"afr-026","version":2,"slug":"cattle-as-kinship-dinka-life-in-south-sudan","contentType":"feature","category":"family-and-friendship","title":{"ar":"البقر قرابة: حياة الدينكا في جنوب السودان","de":"Vieh als Verwandtschaft: Das Leben der Dinka im Südsudan","en":"Cattle as kinship: Dinka life in South Sudan"},"deck":{"ar":"عند الدينكا، ليست البقرة مجرد حيوان، بل سجل للعلاقات الأسرية والهوية والكرامة.","de":"Bei den Dinka ist das Rind kein Nutztier allein, sondern ein lebendiges Register von Verwandtschaft, Identität und Ansehen.","en":"For the Dinka, cattle are not just livestock but a living record of kinship, identity and standing."},"teaser":{"ar":"كيف تصبح البقرة شاهداً على الزواج والحداد والمصالحة؟ رحلة إلى حياة الرعاة حيث تختلط الأسماء بالأغاني والقرون المزخرفة.","de":"Wie wird ein Rind zum Zeugen von Hochzeit, Trauer und Versöhnung? Eine Reise in das Leben von Hirten, in dem Namen, Lieder und geschmückte Hörner zusammenspielen.","en":"How does an ox become a witness to marriage, mourning and reconciliation? A journey into pastoral life where names, songs and decorated horns intertwine."},"readingMinutes":2,"sections":{"ar":[{"heading":"قطيع العائلة وسجلها","paragraphs":["يعيش الدينكا، وهم شعب نيلي في جنوب السودان، على ضفاف النيل وسهوله الفيضية، وتدور حياتهم الاقتصادية والاجتماعية حول البقر. فالماشية هي وسيلة الزواج والمهر، وتُستخدم في الجنائز والتعويضات وتسمية الأطفال، ويُعرّف مكانة الأسرة بعدد رؤوس ماشيتها. فالبقرة ليست ملكاً فحسب، بل سجل حي للعلاقات بين الأسر.","في مواسم الجفاف، تنتقل مخيمات الرعاة بين النهر والمراعي، حيث يعيش الشباب مع الأبقار. يأخذ الشاب ثوراً ويسميه ويؤلف فيه الأغاني ويزين قرونه، فتصبح الأغنية وسيلة للتودد وتسجيل تاريخ العائلة. في أحد المخيمات، ينشد شاب أغنية عن ثوره المفضل، فيسمعه أهل الفتاة ويعرفون من خلالها أصله وسمعته."]},{"heading":"اللبن والذرة: غذاء يومي","paragraphs":["يعتمد الدينكا في طعامهم على اللبن والذرة الرفيعة، مع الأسماك والأطعمة البرية. وتوفر الماشية الجلود والروث الذي يُستخدم في الأرضيات والوقود. وبهذا تدخل البقرة في تفاصيل البيت اليومي، من فرش الأرضية إلى إشعال النار.","لكن العقود الماضية من الحروب والنزوح والضغوط المناخية أخلّت بالقطعان، وكثير من الدينكا الآن يعيشون في المدن أو الخارج مع احتفاظهم بروابطهم بالبقر. فالحياة الرعوية لم تعد كما كانت، لكن البقرة تظل مرجعاً للهوية."]},{"heading":"تنوع لا يمحوه اسم واحد","paragraphs":["مجتمع الدينكا ليس متجانساً، فهو يضم فروعاً وعشائر كثيرة، ولكل منها تقاليدها في الرعي والزواج. كما أن جيرانهم النوير وغيرهم من الشعوب النيلية لهم تقاليد بقرية متصلة لكنها مختلفة. فما يوصف هنا ليس قاعدة ثابتة لكل الدينكا، بل نمط عام يتنوع بحسب المنطقة والجيل.","ومع ذلك، يظل البقر الخيط الذي يربط بين هذه الفروع، ويظل الشاب الذي يغني لثوره صوتاً يعبر عن ذاته وعن جماعته في آن واحد."]}],"de":[{"heading":"Die Herde als Familienregister","paragraphs":["Die Dinka, ein nilotisches Volk im Südsudan, leben am Nil und in seinen Überschwemmungsebenen; ihr wirtschaftliches und soziales Leben dreht sich um Rinder. Vieh dient als Brautpreis, bei Begräbnissen und Entschädigungen sowie bei Namensgebungen, und der Status einer Familie wird oft über ihre Herde beschrieben. Das Rind ist also nicht nur Besitz, sondern ein lebendiges Verzeichnis der Beziehungen zwischen Familien.","In der Trockenzeit ziehen Viehlager zwischen Fluss und Weideland umher, wo junge Männer mit den Rindern leben. Ein junger Mann nimmt einen Ochsen, gibt ihm einen Namen, dichtet Lieder über ihn und schmückt seine Hörner; das Lied wird zum Mittel der Werbung und zur Aufzeichnung der Familiengeschichte. In einem Lager singt ein junger Mann ein Lied über seinen Lieblingsochsen, und die Familie des Mädchens hört zu und erfährt so von seiner Herkunft und seinem Ruf."]},{"heading":"Milch und Sorghum: die tägliche Nahrung","paragraphs":["Die Ernährung der Dinka stützt sich auf Milch und Sorghum, ergänzt durch Fisch und wild gesammelte Nahrung. Rinder liefern zudem Häute und Dung, der für Fußböden und Feuer verwendet wird. So ist das Rind in alle Einzelheiten des Alltags eingebunden, vom Boden des Hauses bis zum Feuer.","Doch jahrzehntelange Kriege, Vertreibung und klimatischer Stress haben die Herden gestört. Viele Dinka leben heute in Städten oder im Ausland und halten dennoch ihre Bindungen an das Vieh aufrecht. Das Hirtenleben ist nicht mehr dasselbe, aber das Rind bleibt ein Bezugspunkt der Identität."]},{"heading":"Vielfalt unter einem Namen","paragraphs":["Die Dinka-Gesellschaft ist nicht homogen; sie umfasst viele Abschnitte und Clans mit eigenen Traditionen in Viehhaltung und Heirat. Auch ihre Nachbarn, die Nuer und andere nilotische Völker, haben verwandte, aber eigenständige Viehtraditionen. Was hier beschrieben wird, ist also kein festes Regelwerk für alle Dinka, sondern ein allgemeines Muster, das sich nach Region und Generation unterscheidet.","Dennoch bleibt das Rind der Faden, der diese Abschnitte verbindet, und der junge Mann, der für seinen Ochsen singt, spricht zugleich für sich und für seine Gemeinschaft."]}],"en":[{"heading":"The herd as a family record","paragraphs":["The Dinka, a Nilotic people of South Sudan, live along the Nile and its floodplains, and their economic and social life centres on cattle. Cattle serve as bridewealth, at funerals and in compensation, and in naming; a family's standing is often described through its herd. The cow is thus not merely property but a living register of relationships between families.","In the dry season, cattle camps move between the river and grazing land, where young men live with the herds. A young man takes an ox, gives it a name, composes songs about it and decorates its horns; the song becomes a way of courting and of recording family history. In one camp, a young man sings a song about his favourite ox, and the girl's family listens and learns of his origins and reputation."]},{"heading":"Milk and sorghum: the daily diet","paragraphs":["Dinka meals rely on milk and sorghum, supplemented by fish and wild foods. Cattle also provide hides and dung for floors and fires. In this way the cow enters the details of daily life, from the floor of the house to the lighting of the fire.","Yet decades of war, displacement and climate stress have disrupted herds. Many Dinka now live in towns or abroad while maintaining cattle ties. Pastoral life is no longer the same, but the cow remains a reference point for identity."]},{"heading":"Diversity under one name","paragraphs":["Dinka society is not homogeneous; it includes many sections and clans with their own traditions of herding and marriage. Their neighbours, the Nuer and other Nilotic peoples, have related but distinct cattle traditions. What is described here is therefore not a fixed rule for all Dinka but a general pattern that varies by region and generation.","Nevertheless, cattle remain the thread that connects these sections, and the young man who sings to his ox speaks at once for himself and for his community."]}]},"context":{"countries":["SS"],"region":"Nilotic South Sudan","community":"Dinka","continent":"africa","languages":["en","ar"],"period":"contemporary"},"tags":["family-and-friendship","Nilotic South Sudan","The Dinka","Cattle are"],"sources":[{"organization":"Wikipedia","title":{"ar":"Dinka people","de":"Dinka people","en":"Dinka people"},"url":"https://en.wikipedia.org/wiki/Dinka_people","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"South Sudan","de":"South Sudan","en":"South Sudan"},"url":"https://en.wikipedia.org/wiki/South_Sudan","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في أحد مخيمات الرعي، ينشد شاب أغنية عن ثوره المفضل، فتصبح الأغنية وسيلة للتودد وتسجيل تاريخ العائلة.","de":"In einem Viehlager singt ein junger Mann ein Lied über seinen Lieblingsochsen; das Lied wird zum Mittel der Werbung und zur Aufzeichnung der Familiengeschichte.","en":"In a cattle camp, a young man sings a song about his favourite ox; the song becomes a way of courting and of recording family history."},"misunderstanding":{"ar":"ليس كل الدينكا رعاة بالمعنى التقليدي؛ فبعضهم يعيش في المدن ويعمل في مهن أخرى، لكن صلة البقر تبقى رمزية واجتماعية.","de":"Nicht alle Dinka sind traditionelle Hirten; manche leben in Städten und üben andere Berufe aus, doch die Beziehung zum Vieh bleibt symbolisch und sozial bedeutsam.","en":"Not all Dinka are traditional herders; some live in towns and work in other professions, yet the relationship with cattle remains symbolically and socially important."},"comparison":{"ar":"في مجتمعات زراعية أخرى، تُقاس المكانة بالأرض، بينما عند الدينكا تُقاس بالقطيع وعلاقاته.","de":"In manchen Ackerbaugesellschaften misst sich Status an Landbesitz, bei den Dinka an der Herde und ihren Beziehungen.","en":"In some farming societies status is measured by land, whereas among the Dinka it is measured by the herd and its relationships."}},{"id":"afr-027","version":2,"slug":"jollof-rice-and-the-politics-of-the-shared-pot","contentType":"feature","category":"food-and-hospitality","title":{"ar":"جولوف رايس: سياسة القدر المشترك","de":"Jollof-Reis und die Politik des gemeinsamen Topfes","en":"Jollof Rice and the Politics of the Shared Pot"},"deck":{"ar":"طبق أرز واحد يجمع غرب أفريقيا ويقسمها في الوقت نفسه، فكيف يصبح القدر مقياساً للكرم؟","de":"Ein Reisgericht, das Westafrika verbindet und spaltet – warum der Topf zum Maßstab für Gastfreundschaft wird.","en":"One rice dish unites and divides West Africa—how the pot becomes a measure of hospitality."},"teaser":{"ar":"من حفلات الزفاف في لاغوس إلى الموائد السنغالية، يتحول الأرز إلى ساحة تنافس ومحبة. اكتشف كيف يعبر الجولوف عن الهوية والضيافة.","de":"Von Hochzeiten in Lagos bis zu senegalesischen Tafeln: Reis wird zur Bühne für Wettbewerb und Zuneigung. Entdecken Sie, wie Jollof Identität und Gastfreundschaft ausdrückt.","en":"From Lagos weddings to Senegalese tables, rice becomes a stage for rivalry and affection. Discover how jollof expresses identity and hospitality."},"readingMinutes":1,"sections":{"ar":[{"heading":"قدر واحد وحكاية عابرة للحدود","paragraphs":["يُعد جولوف رايس طبقاً يُطبخ في قدر واحد، حيث يُطهى الأرز مع الطماطم والفلفل والبصل والتوابل. وتتنازع كل من السنغال وغامبيا وغانا ونيجيريا ودول غرب أفريقية أخرى شرف انتسابه إليها. ويُرجَّح أن الاسم يعود إلى شعب الولوف في منطقة السينيغامبيا، كما أن الطبق السنغالي ثيبوديين هو قريب أقدم للجولوف. ويحضر الجولوف في الأعراس والجنازات والتجمعات السياسية، وتُقاس جودة القدر كمعيار علني للضيافة.","في حفل زفاف في لاغوس، تتناقش عمتان حول ما إذا كان يجب أن يكون الجولوف مدخناً، ويُحكم على متعهد الطعام بناءً على القشرة في قاع القدر. فهذه الطبقة، المعروفة بـ«أرز الحفلة»، هي الجزء الأكثر تقديراً. ويتم الطهي بشكل اجتماعي: القدر كبير، والأرز يُطهى على نار هادئة، مما يسمح بتكوين تلك القشرة. ويختلف الأمر حسب الدولة والمنزل، فلا ينبغي اعتبار الطبق ملكية وطنية واحدة؛ فالنسخ السنغالية والغانية والنيجيرية مختلفة حقاً."]},{"heading":"حروب الجولوف: فكاهة واعتزاز","paragraphs":["تشكل «حروب الجولوف» بين غانا ونيجيريا نكتة عامة مستمرة ومصدر فخر حقيقي، تُقام على وسائل التواصل الاجتماعي وفي المهرجانات. فالسخرية المتبادلة حول أي بلد يطبخ الطبق بشكل أفضل هي وسيلة للتعبير عن الانتماء الوطني دون عداء حقيقي. وتختلف حدة هذه المزاح حسب الجيل والمنطقة، إذ يأخذها البعض على محمل الجدية أكثر من الآخرين."]},{"heading":"لماذا القدر الكبير يعني الكثير","paragraphs":["في المناسبات الكبيرة، يكون الجولوف حاضراً دائماً، وغالباً ما يُطبخ بكميات ضخمة لإطعام مئات الضيوف. ويعكس حجم القدر مكانة المضيف وقدرته على الكرم. ويُعتبر نجاح الطبق دليلاً على مهارة الطبخ والتنظيم. وهكذا يصبح الجولوف أكثر من مجرد طعام؛ إنه وسيلة للتواصل الاجتماعي وتأكيد الهوية الجماعية."]}],"de":[{"heading":"Ein Topf und eine grenzüberschreitende Geschichte","paragraphs":["Jollof-Reis ist ein Eintopfgericht, bei dem Reis mit Tomaten, Paprika, Zwiebeln und Gewürzen in einem einzigen Topf gegart wird. Senegal, Gambia, Ghana, Nigeria und andere westafrikanische Länder beanspruchen das Gericht für sich. Der Name wird meist auf das Volk der Wolof in Senegambien zurückgeführt, und das senegalesische Gericht Thieboudienne gilt als älterer Verwandter. Jollof ist Standard bei Hochzeiten, Beerdigungen und politischen Kundgebungen, und die Qualität des Topfes ist ein öffentliches Maß für Gastfreundschaft.","In einem Haus in Lagos streiten zwei Tanten darüber, ob der Jollof rauchig sein soll, und der Caterer wird nach der Kruste am Boden des Topfes beurteilt. Diese Schicht, bekannt als „Party-Reis“, ist der geschätzteste Teil. Das Kochen ist sozial: Der Topf ist groß, der Reis gart bei schwacher Hitze, und so kann sich die Kruste bilden. Die Rezepte unterscheiden sich je nach Land und Haushalt, und das Gericht sollte nicht als ein nationaler Besitz betrachtet werden; die senegalesischen, ghanaischen und nigerianischen Versionen sind wirklich verschieden."]},{"heading":"Die Jollof-Kriege: Humor und Stolz","paragraphs":["Die „Jollof-Kriege“ zwischen Ghana und Nigeria sind ein wiederkehrender Witz und ein echter Grund zum Stolz, der in sozialen Medien und auf Festivals ausgetragen wird. Der gegenseitige Spott darüber, welches Land das Gericht besser kocht, ist eine Möglichkeit, nationalen Stolz ohne echte Feindseligkeit auszudrücken. Die Intensität dieses Scherzes variiert je nach Generation und Region, da einige ihn ernster nehmen als andere."]},{"heading":"Warum der große Topf so viel bedeutet","paragraphs":["Bei großen Anlässen ist Jollof immer präsent und wird oft in riesigen Mengen gekocht, um Hunderte von Gästen zu bewirten. Die Größe des Topfes spiegelt den Status und die Großzügigkeit des Gastgebers wider. Das Gelingen des Gerichts gilt als Beweis für Kochkunst und Organisation. So wird Jollof mehr als nur Essen; es ist ein Mittel der sozialen Kommunikation und der Bestätigung kollektiver Identität."]}],"en":[{"heading":"One Pot, a Cross-Border Story","paragraphs":["Jollof rice is a one-pot dish of rice cooked with tomatoes, peppers, onions, and spices. Senegal, The Gambia, Ghana, Nigeria, and other West African countries all claim it. The name is usually traced to the Wolof people of Senegambia, and the Senegalese dish thieboudienne is an older relative. Jollof is standard at weddings, funerals, and political rallies, and the quality of the pot is a public measure of hospitality.","At a Lagos wedding, two aunties argue about whether the jollof should be smoky, and the caterer is judged on the crust at the bottom of the pot. That layer, known as 'party rice,' is the most prized part. Cooking is social: the pot is large, the rice steams over a low fire, allowing the crust to form. Recipes differ by country and household, and the dish should not be treated as one national possession; Senegalese, Ghanaian, and Nigerian versions are genuinely different."]},{"heading":"The Jollof Wars: Humor and Pride","paragraphs":["The Ghana–Nigeria 'jollof wars' are a running public joke and a genuine point of pride, staged on social media and at festivals. The mutual teasing about which country cooks it better is a way to express national pride without real hostility. The intensity of this joke varies by generation and region, as some take it more seriously than others."]},{"heading":"Why the Big Pot Matters","paragraphs":["At large occasions, jollof is always present, often cooked in huge quantities to feed hundreds of guests. The size of the pot reflects the host's status and generosity. The success of the dish is seen as proof of cooking skill and organization. Thus jollof becomes more than food; it is a means of social communication and affirmation of collective identity."]}]},"context":{"countries":["NG","GH","SN","GM"],"region":"West Africa","continent":"africa","languages":["en","wo","fr"],"period":"contemporary"},"tags":["food-and-hospitality","West Africa","Jollof rice","The name"],"sources":[{"organization":"Wikipedia","title":{"ar":"Jollof rice","de":"Jollof rice","en":"Jollof rice"},"url":"https://en.wikipedia.org/wiki/Jollof_rice","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"West African cuisine","de":"West African cuisine","en":"West African cuisine"},"url":"https://en.wikipedia.org/wiki/West_African_cuisine","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في حفل زفاف في لاغوس، تتناقش عمتان حول ما إذا كان الجولوف يجب أن يكون مدخناً، ويُحكم على متعهد الطعام بناءً على القشرة في قاع القدر.","de":"Bei einer Hochzeit in Lagos streiten zwei Tanten darüber, ob der Jollof rauchig sein soll, und der Caterer wird nach der Kruste am Boden des Topfes beurteilt.","en":"At a Lagos wedding, two aunties argue about whether the jollof should be smoky, and the caterer is judged on the crust at the bottom of the pot."},"misunderstanding":{"ar":"الاعتقاد بأن الجولوف طبق وطني واحد لدولة واحدة هو تبسيط مفرط؛ فالوصفات تختلف بشكل كبير بين البلدان والمنازل، ولكل نسخة نكهتها الخاصة.","de":"Die Annahme, Jollof sei ein einziges Nationalgericht eines Landes, ist eine Vereinfachung; die Rezepte unterscheiden sich stark zwischen Ländern und Haushalten, und jede Version hat ihren eigenen Geschmack.","en":"Assuming jollof is a single national dish of one country is an oversimplification; recipes vary greatly between countries and households, and each version has its own character."},"comparison":{"ar":"بينما يُنظر إلى البيتزا في إيطاليا كرمز وحدوي، فإن الجولوف يحتفي بالتنوع الإقليمي داخل غرب أفريقيا.","de":"Während Pizza in Italien als Einheitssymbol gilt, feiert Jollof die regionale Vielfalt innerhalb Westafrikas.","en":"While pizza in Italy is seen as a unifying symbol, jollof celebrates regional diversity within West Africa."}},{"id":"afr-028","version":2,"slug":"the-ethiopian-coffee-ceremony-three-rounds-and-a-social-order","contentType":"scene","category":"food-and-hospitality","title":{"ar":"قهوة إثيوبيا: ثلاث جولات ونظام اجتماعي","de":"Äthiopiens Kaffeezeremonie: Drei Runden und eine soziale Ordnung","en":"Ethiopia's Coffee Ceremony: Three Rounds and a Social Order"},"deck":{"ar":"حفل البونّا ليس استراحة كافيين سريعة، بل وقت بطيء يعيد ترتيب العلاقات في البيت.","de":"Die Buna ist keine schnelle Kaffeepause, sondern eine langsame Zeit, die Beziehungen im Haus neu ordnet.","en":"The buna is not a quick caffeine break but a slow stretch of time that reorders relationships in the house."},"teaser":{"ar":"في المرتفعات، تُحمّص الحبوب على الفحم، ويُسكب البن ثلاث مرات، ويجلس الجيران ساعات ليتبادلوا الأخبار.","de":"Im Hochland werden Bohnen über Holzkohle geröstet, der Kaffee dreimal eingeschenkt, und Nachbarn sitzen stundenlang zusammen.","en":"In the highlands, beans are roasted over charcoal, coffee is poured three times, and neighbours sit for hours exchanging news."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الفحم إلى الجيبينا","paragraphs":["حفل القهوة، أو بونا، طقس اجتماعي يومي في إثيوبيا وإريتريا، تستضيفه عادةً امرأة تحمّص الحبوب الخضراء على الفحم. وتطحنها وتخمرها في قدر الجيبينا الطيني، ثم تقدم ثلاث جولات: أبول وتونا وبيريكا.","يُقدَّم للضيوف بحسب العمر والمكانة، ويصاحب القهوة البخور والفشار أو الخبز. ومن هنا يفهم المشاركون أن الأمر ليس شرباً سريعاً، بل استقبال وإصغاء."]},{"heading":"رفض مهذب","paragraphs":["رفض القهوة بأدب يعني عادةً أن الشاي سيُقدَّم بدلاً منها، والحفل وسيلة لاستقبال الجيران وتبادل الأخبار. ويستغرق الطقس ساعة أو أكثر، وينتمي إلى الضيافة والحداد والاحتفال.","مثال يومي: يصل جار بلا موعد في أديس أبابا، فتشعل المضيفة الفحم وتحمّص الحبوب، فيصير الزيارة أصيلاً من الحديث على ثلاث فناجين. وتختلف الممارسة بين الأسر الأرثوذكسية والمسلمة والحضرية، وكثيراً ما تقدم المقاهي في المدينة القهوة بسرعة دون أداء الحفل كاملاً."]}],"de":[{"heading":"Von der Kohle zur Jebena","paragraphs":["Die Kaffeezeremonie, Buna, ist ein tägliches soziales Ritual in Äthiopien und Eritrea, meist von einer Frau ausgerichtet, die grüne Bohnen über Holzkohle röstet. Sie mahlt und brüht den Kaffee in der Tonkanne Jebena und serviert drei Runden: Abol, Tona und Bereka.","Die Gäste werden nach Alter und Status bedient, Weihrauch sowie Popcorn oder Brot begleiten den Kaffee. Daran zeigt sich: Es geht nicht um schnelles Trinken, sondern um Empfang und Zuhören."]},{"heading":"Höfliche Ablehnung","paragraphs":["Kaffee höflich abzulehnen bedeutet meist, dass stattdessen Tee angeboten wird; die Zeremonie ist ein Weg, Nachbarn zu empfangen und Neuigkeiten zu tauschen. Das Ritual dauert eine Stunde oder länger und gehört zu Gastfreundschaft, Trauer und Feiern.","Ein Alltagsbild: Eine Nachbarin kommt in Addis Abeba unangekündigt; die Gastgeberin entzündet Holzkohle, röstet Bohnen, und der Besuch wird zu einem Nachmittag Gespräch über drei Tassen. Die Praxis variiert zwischen orthodoxen, muslimischen und städtischen Haushalten, und Stadtcafés servieren Kaffee oft schnell statt der vollen Zeremonie."]}],"en":[{"heading":"From charcoal to the jebena","paragraphs":["The coffee ceremony, buna, is a daily social ritual in Ethiopia and Eritrea, usually hosted by a woman who roasts green beans over charcoal. She grinds and brews the coffee in the jebena clay pot and serves three rounds: abol, tona and bereka.","Guests are served in order of age and status, and incense plus popcorn or bread accompany the coffee. This shows that the point is not quick drinking but receiving and listening."]},{"heading":"Declining politely","paragraphs":["Declining coffee politely usually means tea will be offered instead, and the ceremony is a way to receive neighbours and exchange news. The ritual takes an hour or more and belongs to hospitality, mourning and celebration.","A concrete scene: a neighbour arrives unannounced in Addis Ababa; the host lights charcoal, roasts beans, and the visit becomes an afternoon of conversation over three cups. Practice varies between Orthodox Christian, Muslim and urban households, and city cafés often serve coffee quickly rather than performing the full ceremony."]}]},"context":{"countries":["ET","ER"],"region":"Ethiopian and Eritrean highlands","continent":"africa","languages":["am","ti","om"],"period":"contemporary"},"tags":["food-and-hospitality","Ethiopian and Eritrean highlands","The coffee","The host"],"sources":[{"organization":"Wikipedia","title":{"ar":"Coffee ceremony of Ethiopia and Eritrea","de":"Coffee ceremony of Ethiopia and Eritrea","en":"Coffee ceremony of Ethiopia and Eritrea"},"url":"https://en.wikipedia.org/wiki/Coffee_ceremony_of_Ethiopia_and_Eritrea","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Ethiopian cuisine","de":"Ethiopian cuisine","en":"Ethiopian cuisine"},"url":"https://en.wikipedia.org/wiki/Ethiopian_cuisine","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يصل جار بلا موعد في أديس أبابا، فتشعل المضيفة الفحم وتحمّص الحبوب، فيصير الزيارة أصيلاً من الحديث على ثلاث فناجين.","de":"Eine Nachbarin kommt in Addis Abeba unangekündigt; die Gastgeberin entzündet Holzkohle, röstet Bohnen, und der Besuch wird zu einem Nachmittag Gespräch über drei Tassen.","en":"A neighbour arrives unannounced in Addis Ababa; the host lights charcoal, roasts beans, and the visit becomes an afternoon of conversation over three cups."},"misunderstanding":{"ar":"حفل البونا ليس مجرد طريقة لتحضير القهوة، بل مؤسسة ضيافة تُنظّم من يُستقبل وكيف يُسمع.","de":"Die Buna ist nicht nur eine Zubereitungsart, sondern eine Institution der Gastfreundschaft, die regelt, wer empfangen und gehört wird.","en":"The buna is not merely a brewing method but an institution of hospitality that governs who is received and heard."},"comparison":{"ar":"حيث تُشرب القهوة في سياقات أخرى واقفاً وفي دقائق، تُدار هنا كوقت اجتماعي كامل.","de":"Wo Kaffee anderswo im Stehen und in Minuten getrunken wird, wird er hier als vollständige soziale Zeit gestaltet.","en":"Where coffee elsewhere is drunk standing up in minutes, here it is staged as a full stretch of social time."}},{"id":"afr-029","version":2,"slug":"fespaco-ouagadougou-s-biennial-argument-about-african-cinema","contentType":"feature","category":"work-and-education","title":{"ar":"فسباكو: جدال واغادوغو حول السينما الأفريقية","de":"FESPACO: Ouagadougous Debatte über afrikanisches Kino","en":"FESPACO: Ouagadougou's biennial argument about African cinema"},"deck":{"ar":"مهرجان السينما والتلفزيون الأفريقي في واغادوغو يجمع صناع الأفلام والجمهور كل عامين للنقاش حول الهوية والتمويل.","de":"Das Panafrikanische Film- und Fernsehfestival in Ouagadougou bringt alle zwei Jahre Filmschaffende und Publikum zusammen, um über Identität und Finanzierung zu diskutieren.","en":"The Panafrican Film and Television Festival in Ouagadougou brings filmmakers and audiences together every two years to debate identity, funding and distribution."},"teaser":{"ar":"كل عامين، تتحول واغادوغو إلى ملتقى للسينمائيين الأفارقة، حيث يُطرح سؤال الهوية والتمويل والتوزيع على شاشات المدينة.","de":"Alle zwei Jahre wird Ouagadougou zum Treffpunkt afrikanischer Filmschaffender, wo Fragen nach Identität, Finanzierung und Verleih auf den Leinwänden der Stadt verhandelt werden.","en":"Every two years, Ouagadougou becomes a meeting point for African filmmakers, where questions of identity, funding and distribution play out on the city's screens."},"readingMinutes":1,"sections":{"ar":[{"heading":"ملتقى القارة على الشاشة","paragraphs":["في واغادوغو، عاصمة بوركينا فاسو، يُنظم مهرجان فسباكو للسينما والتلفزيون الأفريقي في الأعوام الفردية. يجمع هذا الحدث مخرجين ونقادًا وجمهورًا من مختلف أنحاء القارة، ليشكل نقطة التقاء سنوية للنقاش حول السينما الأفريقية.","بدأ المهرجان عام 1969، ومنذ ذلك الحين أصبح منصة مهمة للسينمائيين الأفارقة. يُقبل في المسابقة فقط الأفلام التي ينتجها أفارقة، وتُمنح الجائزة الكبرى «الجواد الذهبي ليينينغا» لأفضل فيلم."]},{"heading":"ليلة الافتتاح والمدينة","paragraphs":["تُقام ليلة الافتتاح في ملعب 4 أغسطس، بينما تتوزع العروض على صالات السينما في أنحاء المدينة. هذا الانتشار يجعل المهرجان حدثًا ثقافيًا كبيرًا لبوركينا فاسو، حيث يشارك السكان في فعالياته.","يختلف الحضور والاهتمام حسب المنطقة والجيل؛ فبعض الشباب يتابعون الأفلام عبر الإنترنت، بينما يحرص آخرون على حضور العروض في الصالات. هذا التنوع يعكس التحولات في طرق مشاهدة السينما."]},{"heading":"نقاشات التمويل واللغة","paragraphs":["لقد شكّل فسباكو نقاشات حول التمويل والتوزيع واللغة في السينما الأفريقية. فالمخرجون يواجهون تحديات في الحصول على الدعم المالي وتوزيع أفلامهم خارج القارة.","رغم أهميته، تأثر المهرجان بالأوضاع الأمنية في بوركينا فاسو وبالتمويل، وتغيرت دوريته في بعض الأحيان. لكنه يظل منبرًا للمخرجين الشباب الذين يسعون لإيصال أصواتهم.","في كل دورة، يعيد فسباكو طرح السؤال: كيف يمكن للسينما الأفريقية أن تعبر عن واقع القارة وتصل إلى جمهور أوسع؟"]}],"de":[{"heading":"Ein Kontinent auf der Leinwand","paragraphs":["In Ouagadougou, der Hauptstadt Burkina Fasos, findet in ungeraden Jahren das Panafrikanische Film- und Fernsehfestival FESPACO statt. Es bringt Regisseure, Kritiker und Publikum aus ganz Afrika zusammen und ist ein jährlicher Treffpunkt für den Austausch über afrikanisches Kino.","Das Festival begann 1969 und ist seitdem eine wichtige Plattform für afrikanische Filmschaffende. Zum Wettbewerb werden nur Filme zugelassen, die von Afrikanern produziert wurden, und der Hauptpreis ist der Étalon d'or de Yennenga."]},{"heading":"Eröffnungsabend und Stadt","paragraphs":["Die Eröffnungsnacht findet im Stade du 4-Août statt, während die Vorführungen auf die Kinos der Stadt verteilt sind. Diese Verteilung macht das Festival zu einem großen kulturellen Ereignis für Burkina Faso, an dem die Bevölkerung teilnimmt.","Die Teilnahme und das Interesse variieren je nach Region und Generation; einige Junge verfolgen Filme online, während andere die Vorführungen in den Kinos besuchen. Diese Vielfalt spiegelt den Wandel der Sehgewohnheiten wider."]},{"heading":"Debatten über Finanzierung und Sprache","paragraphs":["FESPACO hat Debatten über Finanzierung, Verleih und Sprache im afrikanischen Film geprägt. Regisseure stehen vor Herausforderungen bei der Beschaffung von Fördermitteln und der Verbreitung ihrer Filme außerhalb des Kontinents.","Trotz seiner Bedeutung ist das Festival von der Sicherheitslage in Burkina Faso und der Finanzierung beeinflusst, und sein Rhythmus hat sich zeitweise geändert. Dennoch bleibt es ein Forum für junge Regisseure, die ihre Stimmen Gehör verschaffen wollen.","In jeder Ausgabe stellt FESPACO die Frage neu: Wie kann das afrikanische Kino die Realität des Kontinents ausdrücken und ein breiteres Publikum erreichen?"]}],"en":[{"heading":"A continent on screen","paragraphs":["In Ouagadougou, Burkina Faso's capital, the Panafrican Film and Television Festival of Ouagadougou (FESPACO) is held in odd-numbered years. It brings together directors, critics and audiences from across the continent, serving as a regular meeting point for discussions about African cinema.","The festival began in 1969 and has since become an important platform for African filmmakers. Only films by African filmmakers, chiefly produced in Africa, are accepted for competition, and the top prize is the Étalon d'or de Yennenga."]},{"heading":"Opening night and the city","paragraphs":["The opening night is held at the Stade du 4-Août, while screenings spread across the city's cinemas. This distribution makes the festival a major cultural event for Burkina Faso, with residents participating in its activities.","Attendance and interest vary by region and generation; some young people follow films online, while others make a point of attending screenings in cinemas. This diversity reflects changes in how people watch cinema."]},{"heading":"Debates on funding and language","paragraphs":["FESPACO has shaped debates about funding, distribution and language in African film. Directors face challenges in securing financial support and distributing their films beyond the continent.","Despite its importance, the festival has been affected by Burkina Faso's security situation and funding, and its biennial rhythm has changed at times. Yet it remains a forum for young directors seeking to make their voices heard.","With each edition, FESPACO poses the question anew: how can African cinema express the continent's reality and reach a wider audience?"]}]},"context":{"countries":["BF"],"region":"Ouagadougou, Burkina Faso","continent":"africa","languages":["fr","en"],"period":"contemporary"},"tags":["work-and-education","Ouagadougou, Burkina Faso"],"sources":[{"organization":"Wikipedia","title":{"ar":"Panafrican Film and Television Festival of Ouagadougou","de":"Panafrican Film and Television Festival of Ouagadougou","en":"Panafrican Film and Television Festival of Ouagadougou"},"url":"https://en.wikipedia.org/wiki/Panafrican_Film_and_Television_Festival_of_Ouagadougou","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Ouagadougou","de":"Ouagadougou","en":"Ouagadougou"},"url":"https://en.wikipedia.org/wiki/Ouagadougou","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مخرج شاب من بوركينا فاسو يدخر لمدة عام لحضور فسباكو، يصطف لمشاهدة فيلم، ويقدم نصه السينمائي في بهو فندق.","de":"Ein junger Regisseur aus Burkina Faso spart ein Jahr lang, um am FESPACO teilzunehmen, steht für eine Vorführung Schlange und stellt sein Drehbuch in einer Hotelhalle vor.","en":"A young Burkinabè director saves for a year to attend FESPACO, queues for a screening and pitches a script in a hotel lobby."},"misunderstanding":{"ar":"يعتقد البعض أن فسباكو مهرجان للنخبة فقط، لكنه في الواقع يجذب جمهورًا واسعًا من مختلف الأعمار والخلفيات.","de":"Manche glauben, FESPACO sei nur ein Festival für Eliten, doch tatsächlich zieht es ein breites Publikum unterschiedlichen Alters und Hintergrunds an.","en":"Some believe FESPACO is an elite-only festival, but it actually attracts a broad audience of different ages and backgrounds."},"comparison":{"ar":"مثل مهرجان كان بالنسبة للسينما الأوروبية، يعد فسباكو الحدث الأبرز للسينما الأفريقية، لكنه يركز على إنتاج القارة ومواضيعها.","de":"Wie Cannes für das europäische Kino ist FESPACO das wichtigste Ereignis für das afrikanische Kino, konzentriert sich aber auf die Produktion des Kontinents und seine Themen.","en":"Like Cannes for European cinema, FESPACO is the premier event for African cinema, but it focuses on the continent's production and themes."}},{"id":"afr-030","version":2,"slug":"susu-saving-together-when-banks-are-far-away","contentType":"feature","category":"work-and-education","title":{"ar":"سوسو: الادخار الجماعي حين يبعد البنك","de":"Susu: gemeinsam sparen, wenn die Bank weit weg ist","en":"Susu: saving together when banks are far away"},"deck":{"ar":"في غانا وسيراليون وليبيريا، يجمع الجيران أموالهم في صندوق دوّار يوزّع على واحد منهم كل أسبوع أو شهر، فيسدّ حاجات لا يطالها البنك.","de":"In Ghana, Sierra Leone und Liberia legen Nachbarn regelmäßig Geld in einen wandernden Topf. Jede Runde bekommt eine Person alles – nach einem vorher vereinbarten Plan.","en":"In Ghana, Sierra Leone and Liberia, neighbours pay into a rotating pot at fixed intervals. Each round one member takes it all, following an order agreed in advance."},"teaser":{"ar":"مجموعة صغيرة، مبلغ ثابت، ودور متفق عليه مسبقًا: هكذا يموّل الناس الرسوم والمتاجر والجنازات بعيدًا عن البنوك.","de":"Kleine Gruppe, fester Betrag, vorab bestimmte Reihenfolge: So finanzieren Menschen Schulgebühren, Marktware und Begräbnisse, wo Banken teuer oder fern sind.","en":"A small group, a fixed amount, a rota set at the start: this is how people fund school fees, market stock and funerals where banks are costly or distant."},"readingMinutes":2,"sections":{"ar":[{"heading":"صندوق يدور بين الأيدي","paragraphs":["في مدن غانا وأسواق سيراليون وليبيريا، تُعرف هذه الطريقة بأسماء عدة: سوسو، أو سو-سو، أو أوسوسو، أو أسوي. وهي جمعية ادخار وإقراض دوّارة، يدفع فيها الأعضاء المبلغ نفسه على فترات ثابتة، ويأخذ عضو واحد في كل دورة كل ما جُمع.","يُتفق على ترتيب الأدوار مسبقًا، لا بالقرعة ولا بالمفاضلة في اللحظة الأخيرة. هذا الاتفاق المسبق هو ما يجعل الصندوق يسير بلا خلافات تُذكر، لأن كل عضو يعرف متى سيصل دوره ويعوّل عليه.","يُموّل هذا المال أشياء ملموسة في الحياة اليومية: رسوم مدرسة، وبضاعة للسوق، وجنازة عائلية، ورأس مال صغير لمشروع. ولا ينتظر الناس أن تصبح مدخراتهم كبيرة، بل يستخدمون ما يجمعونه في موعده."]},{"heading":"الثقة بدل الضمانات","paragraphs":["لا يقوم النظام على رهن أو عقد موثّق، بل على الثقة والضغط الاجتماعي. من يتأخر عن دفع حصته يعرف أن سمعته في الحي أو السوق هي ما يوضع على المحك، وأن ذلك قد يكلّفه أكثر من المبلغ نفسه.","لهذا يعمل سوسو حيث يكون التعامل المصرفي مكلفًا أو بعيدًا. فبدل أن يقطع التاجر يوم عمل ليصل إلى فرع بنك، يجمع المال قريبًا منه، ضمن دائرة يعرف أفرادها بعضهم جيدًا.","في غانا وسيراليون، قد يحتفظ جامعو سوسو بالأموال مقابل رسم ويسجّلون الحسابات، فيقومون بدور مصرفي غير رسمي. وهذا يتيح لبعض الناس الانضمام دون أن يتولوا حراسة الصندوق بأنفسهم.","تختلف الترتيبات من بلد إلى آخر ومن جامع إلى آخر، كما تختلف بين جيل يكبر على النقود الورقية وجيل يستخدم المحفظة الإلكترونية. وليست هذه الصناديق خاضعة للتنظيم كالبنوك، لذا تعتمد حلول الخلافات على الجزاء المجتمعي أكثر من المحاكم."]},{"heading":"عادات تتغيّر مع الهاتف","paragraphs":["في السنوات الأخيرة، تكيّف سوسو مع النقود المحمولة. صار بعض الأعضاء يحوّلون حصصهم عبر الهاتف بدل تسليمها نقدًا، وبقي جوهر الأمر كما هو: مبلغ ثابت، ودور معروف، ومجموعة تثق بعضها ببعض.","هذا التكيّف يبيّن أن النظام ليس بقايا ماضٍ، بل ترتيب عملي يتشكّل حسب ما هو متاح. وحيث يصل البنك بصعوبة، يبقى الصندوق الدوّار أقرب إلى حياة الناس وأسرع في تلبية حاجاتهم."]}],"de":[{"heading":"Ein Topf, der die Runde macht","paragraphs":["In den Städten Ghanas, auf den Märkten Sierra Leones und in Liberia hat diese Praxis viele Namen: Susu, Sou-Sou, Osusu oder Asue. Es ist ein rotierender Spar- und Kreditverein, in dem die Mitglieder in festen Abständen denselben Betrag einzahlen und pro Runde eine Person den gesamten Topf erhält.","Die Reihenfolge wird im Voraus vereinbart, nicht ausgelost und nicht spontan entschieden. Genau diese frühe Absprache hält die Gruppe zusammen, denn jede Person weiß, wann sie an der Reihe ist, und kann darauf planen.","Das Geld fließt in sehr konkrete Dinge des Alltags: Schulgebühren, Waren für den Marktstand, ein Familienbegräbnis oder das Startkapital für ein kleines Geschäft. Niemand wartet darauf, dass die Ersparnisse groß werden; man nutzt, was zum vereinbarten Zeitpunkt zusammenkommt."]},{"heading":"Vertrauen statt Sicherheiten","paragraphs":["Das System beruht nicht auf Pfändern oder notariellen Verträgen, sondern auf Vertrauen und sozialem Druck. Wer seine Rate nicht zahlt, weiß, dass der Ruf in der Nachbarschaft oder auf dem Markt auf dem Spiel steht – und das kann teurer werden als der Betrag selbst.","Darum funktioniert Susu dort, wo Bankgeschäfte teuer oder weit entfernt sind. Statt einen Arbeitstag zu verlieren, um eine Filiale zu erreichen, spart man in der Nähe, in einem Kreis von Menschen, die einander gut kennen.","In Ghana und Sierra Leone verwahren Susu-Sammler das Geld gegen eine Gebühr und führen Aufzeichnungen; sie handeln damit als informelle Banker. So können auch Menschen teilnehmen, die nicht selbst den Topf beaufsichtigen wollen.","Die Arrangements unterscheiden sich von Land zu Land und von Sammler zu Sammler, und sie unterscheiden sich zwischen einer Generation, die mit Scheinen groß wurde, und einer, die mit dem Handy zahlt. Wie Banken sind diese Gruppen nicht reguliert; Streitfälle hängen daher eher von gemeinschaftlichen Sanktionen ab als von Gerichten."]},{"heading":"Alte Gewohnheit, neues Telefon","paragraphs":["In den letzten Jahren hat sich Susu an mobiles Geld angepasst. Manche Mitglieder überweisen ihre Raten per Telefon statt sie bar zu übergeben, doch der Kern bleibt gleich: ein fester Betrag, eine bekannte Reihenfolge und eine Gruppe, die einander vertraut.","Diese Anpassung zeigt, dass Susu kein Rest der Vergangenheit ist, sondern eine praktische Ordnung, die sich nach dem richtet, was gerade verfügbar ist. Wo die Bank schwer erreichbar bleibt, ist der wandernde Topf näher am Leben der Menschen und schneller zur Stelle."]}],"en":[{"heading":"A pot that travels round","paragraphs":["In Ghanaian cities, Sierra Leonean markets and Liberian towns, the practice goes by several names: susu, sou-sou, osusu or asue. It is a rotating savings and credit association in which members contribute the same amount at fixed intervals, and each period one member receives the whole pot.","The order is agreed in advance, not drawn by lot or settled on the day. That early agreement is what keeps the group steady: every member knows when their turn comes and can plan around it.","The money goes into concrete things of everyday life: school fees, stock for a market stall, a family funeral or the first capital for a small business. People do not wait for savings to grow large; they use what has gathered when the date arrives."]},{"heading":"Trust instead of collateral","paragraphs":["The system does not rest on collateral or signed contracts but on trust and social pressure. Anyone who falls behind knows that their reputation in the neighbourhood or the market is at stake, and that this can cost more than the amount itself.","That is why susu works where formal banking is expensive or distant. Rather than losing a working day to reach a branch, a trader saves close by, among people who know one another well.","In Ghana and Sierra Leone, susu collectors may hold the money for a fee and keep records, acting as informal bankers. This lets some people join without having to guard the pot themselves.","Arrangements vary by country and by collector, and they vary between a generation raised on cash and one that pays by phone. The groups are not regulated like banks, so disputes depend on community sanctions rather than courts."]},{"heading":"An old habit, a new phone","paragraphs":["In recent years susu has adapted to mobile money. Some members send their contributions by phone instead of handing over notes, but the core stays the same: a fixed amount, a known rota and a group that trusts one another.","That adaptation shows susu is not a leftover from the past but a practical arrangement shaped by whatever is at hand. Where the bank remains hard to reach, the rotating pot stays closer to people's lives and quicker to respond."]}]},"context":{"countries":["GH","SL","LR"],"region":"West Africa","continent":"africa","languages":["en","tw"],"period":"contemporary"},"tags":["work-and-education","West Africa"],"sources":[{"organization":"Wikipedia","title":{"ar":"Susu (informal loan club)","de":"Susu (informal loan club)","en":"Susu (informal loan club)"},"url":"https://en.wikipedia.org/wiki/Susu_(informal_loan_club)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Rotating savings and credit association","de":"Rotating savings and credit association","en":"Rotating savings and credit association"},"url":"https://en.wikipedia.org/wiki/Rotating_savings_and_credit_association","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عشر بائعات في سوق كوماسي تدفع كل واحدة مئة سيدي أسبوعيًا، وتأخذ واحدة منهن كل أسبوع الألف سيدي كاملة وفق ترتيب اتفقن عليه في البداية.","de":"Zehn Marktfrauen in Kumasi zahlen jede Woche 100 Cedis ein, und jede Woche nimmt eine von ihnen den vollen Betrag von 1.000 Cedis entgegen – nach einer zu Beginn vereinbarten Reihenfolge.","en":"Ten market women in Kumasi each pay 100 cedis a week, and one of them takes the full 1,000-cedi pot each week, following a rota agreed at the start."},"misunderstanding":{"ar":"يظن بعض الناس أن سوسو مجرد جمع تبرعات بين الأصدقاء، لكنه في الحقيقة التزام دوري بمبلغ ثابت وترتيب محدد سلفًا، وله قواعد والتزامات.","de":"Manche halten Susu für eine lockere Geldsammlung unter Freunden. Tatsächlich ist es eine regelmäßige Verpflichtung zu einem festen Betrag mit klarer Reihenfolge, Regeln und Erwartungen.","en":"Some assume susu is just loose money pooling among friends. In fact it is a regular commitment to a fixed amount with a clear order, rules and expectations that members are held to."},"comparison":{"ar":"يشبه سوسو حساب توفير جماعيًا، لكن بدل أن يدفع البنك فائدة، يحصل كل عضو على المبلغ كاملًا في دوره، والضمانة هي الثقة لا العقد.","de":"Susu ähnelt einem gemeinsamen Sparkonto, doch statt Zinsen zahlt die Bank niemandem etwas aus: Jedes Mitglied erhält den vollen Betrag, wenn es an der Reihe ist, und die Sicherheit ist Vertrauen, kein Vertrag.","en":"Susu resembles a shared savings account, but instead of paying interest, no bank stands in the middle: each member receives the full amount when their turn comes, and the guarantee is trust, not a contract."}},{"id":"afr-031","version":2,"slug":"stokvels-south-africa-s-savings-clubs-as-social-insurance","contentType":"feature","category":"work-and-education","title":{"ar":"ستوكفيلز: نوادي الادخار كتأمين اجتماعي","de":"Stokvels: Südafrikas Sparclubs als soziale Absicherung","en":"Stokvels: South Africa's Savings Clubs as Social Insurance"},"deck":{"ar":"في جنوب أفريقيا، تجمع مجموعات من الأصدقاء والجيران أموالها بانتظام، وتتناوب على استلامها، وتوفر شبكة أمان مالي واجتماعي.","de":"In Südafrika legen Gruppen von Freunden und Nachbarn regelmäßig Geld zusammen, erhalten es abwechselnd und schaffen ein finanzielles und soziales Sicherheitsnetz.","en":"In South Africa, groups of friends and neighbours pool money regularly, take turns receiving it, and create a financial and social safety net."},"teaser":{"ar":"نوادي ادخار تدعى ستوكفيلز تجمع الأموال وتوزعها بالتناوب، وتقدم دعماً للجنازات والمواد الغذائية، وتعمل بقواعد صارمة.","de":"Stokvels sind Sparclubs, die Geld sammeln und abwechselnd auszahlen, Beerdigungsfonds und Lebensmittelprogramme anbieten und nach strengen Regeln funktionieren.","en":"Stokvels are savings clubs that collect and rotate money, offer burial funds and grocery schemes, and operate on strict rules and social accountability."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما هو الستوكفيل؟","paragraphs":["الستوكفيل هو نادٍ للادخار في جنوب أفريقيا، يُدعى إليه الأعضاء بدعوة فقط، ويتكون عادة من اثني عشر عضواً أو أكثر. يدفع كل عضو مبلغاً ثابتاً أسبوعياً أو كل أسبوعين أو شهرياً. يجتمع الأعضاء بانتظام، وغالباً ما يكون الاجتماع في منزل أحدهم، حيث تُدفع الاشتراكات وتُدار الأعمال.","يأتي الاسم من 'معارض الماشية'، وهي مزادات الماشية الدوارة التي أقامها المستوطنون الإنجليز في كيب الشرقية في أوائل القرن التاسع عشر. تطورت الفكرة لتصبح أداة مالية جماعية للمجتمعات السوداء في جنوب أفريقيا."]},{"heading":"كيف يعمل التناوب والتضامن؟","paragraphs":["يتناوب الأعضاء على استلام المبلغ المجمع، فيحصل كل عضو على دوره. وغالباً ما تدير الستوكفيلز صناديق للجنازات، ومخططات لشراء البقالة، وحسابات استثمارية. هذا التنوع يجعلها أكثر من مجرد جمعية ادخار؛ إنها شكل من أشكال التأمين الاجتماعي.","تخضع الستوكفيلز لقواعد مكتوبة أو شفهية ومساءلة اجتماعية. تُحل الخلافات في الاجتماعات وليس في المحاكم. هذا يعزز الثقة والانضباط، ويقلل من تكاليف اللجوء إلى القضاء."]},{"heading":"أهمية اقتصادية واجتماعية","paragraphs":["تُعد الستوكفيلز جزءاً رئيسياً من الحياة المالية للسود في جنوب أفريقيا. تشير التقديرات إلى أن الأموال التي تحتفظ بها تصل إلى عشرات المليارات من الراند. هذا يعكس دورها في تعبئة المدخرات الصغيرة وتحويلها إلى رأس مال مفيد.","تختلف الستوكفيلز على نطاق واسع في الحجم والغرض ودرجة الرسمية. بعضها كان وسيلة لخطط هرمية أو احتيال، لذا فإن القطاع ليس آمناً بشكل موحد. كما تتباين الممارسات حسب المنطقة والجيل؛ فبعض المجموعات الشابة تفضل الإدارة الرقمية، بينما تتمسك الأجيال الأكبر بالاجتماعات وجههاً لوجه."]}],"de":[{"heading":"Was ist ein Stokvel?","paragraphs":["Ein Stokvel ist ein südafrikanischer Sparclub, der nur auf Einladung zugänglich ist und typischerweise aus zwölf oder mehr Mitgliedern besteht. Jedes Mitglied zahlt wöchentlich, zweiwöchentlich oder monatlich einen festen Betrag ein. Die Mitglieder treffen sich regelmäßig, oft bei jemandem zu Hause, um Beiträge zu zahlen und Angelegenheiten zu regeln.","Der Name stammt von 'stock fairs', den rotierenden Viehauktionen, die englische Siedler im frühen 19. Jahrhundert in der Eastern Cape abhielten. Die Idee entwickelte sich zu einem kollektiven Finanzinstrument für schwarze Gemeinschaften in Südafrika."]},{"heading":"Wie Rotation und Solidarität funktionieren","paragraphs":["Die Mitglieder erhalten abwechselnd das gesammelte Geld. Viele Stokvels betreiben auch Beerdigungsfonds, Lebensmittelprogramme und Investmentkonten. Diese Vielfalt macht sie mehr als nur einen Sparverein; sie sind eine Form der sozialen Absicherung.","Stokvels unterliegen schriftlichen oder mündlichen Regeln und sozialer Rechenschaftspflicht. Streitigkeiten werden in Versammlungen und nicht vor Gericht beigelegt. Das stärkt Vertrauen und Disziplin und senkt die Kosten für Rechtsstreitigkeiten."]},{"heading":"Wirtschaftliche und soziale Bedeutung","paragraphs":["Stokvels sind ein wichtiger Teil des Finanzlebens der schwarzen Südafrikaner. Schätzungen zufolge belaufen sich die von ihnen gehaltenen Gelder auf mehrere zehn Milliarden Rand. Das zeigt ihre Rolle bei der Mobilisierung kleiner Ersparnisse und deren Umwandlung in nutzbares Kapital.","Stokvels unterscheiden sich stark in Größe, Zweck und Formalitätsgrad. Einige waren Vehikel für Pyramidenpläne oder Betrug, daher ist der Sektor nicht durchweg sicher. Auch die Praktiken variieren je nach Region und Generation; einige jüngere Gruppen bevorzugen digitale Verwaltung, während ältere Generationen auf persönliche Treffen setzen."]}],"en":[{"heading":"What Is a Stokvel?","paragraphs":["A stokvel is an invitation-only South African savings club, typically of twelve or more members who contribute fixed sums weekly, fortnightly or monthly. Members meet regularly, often at someone's home, to pay contributions and conduct business.","The name comes from 'stock fairs', the rotating cattle auctions held by English settlers in the Eastern Cape in the early 19th century. The idea evolved into a collective financial tool for Black South African communities."]},{"heading":"How Rotation and Solidarity Work","paragraphs":["Members take turns receiving the pooled money. Many stokvels also run burial funds, grocery schemes and investment accounts. This diversity makes them more than just a savings club; they are a form of social insurance.","Stokvels are governed by written or spoken rules and social accountability. Disputes are handled at meetings rather than in court. This builds trust and discipline and reduces the costs of litigation."]},{"heading":"Economic and Social Significance","paragraphs":["Stokvels are a major part of Black South African financial life. Estimates of the money they hold run into the tens of billions of rand. This reflects their role in mobilising small savings and turning them into useful capital.","Stokvels differ widely in size, purpose and formality. Some have been vehicles for pyramid schemes or fraud, so the sector is not uniformly safe. Practices also vary by region and generation; some younger groups prefer digital management, while older generations stick to face-to-face meetings."]}]},"context":{"countries":["ZA"],"region":"South Africa","continent":"africa","languages":["zu","af","en"],"period":"contemporary"},"tags":["work-and-education","South Africa"],"sources":[{"organization":"Wikipedia","title":{"ar":"Stokvel","de":"Stokvel","en":"Stokvel"},"url":"https://en.wikipedia.org/wiki/Stokvel","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Rotating savings and credit association","de":"Rotating savings and credit association","en":"Rotating savings and credit association"},"url":"https://en.wikipedia.org/wiki/Rotating_savings_and_credit_association","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مجموعة من الممرضات في سويتو تدير ستوكفيل تدفع في ديسمبر لشراء ملابس المدرسة والبقالة، مع صندوق منفصل للجنازات.","de":"Eine Gruppe von Krankenschwestern in Soweto betreibt einen Stokvel, der im Dezember für Schulkleidung und Lebensmittel auszahlt, mit einem separaten Beerdigungsfonds.","en":"A group of nurses in Soweto runs a stokvel that pays out in December for school clothes and groceries, with a separate burial fund."},"misunderstanding":{"ar":"يعتقد البعض أن الستوكفيل مجرد جمعية ادخار بسيطة، لكنها تشمل أيضاً صناديق جنازات ومخططات بقالة واستثمارات، وتلعب دوراً تأمينياً.","de":"Manche halten Stokvels für einfache Sparvereine, doch sie umfassen auch Beerdigungsfonds, Lebensmittelprogramme und Investitionen und spielen eine Versicherungsrolle.","en":"Some think a stokvel is just a simple savings club, but it also includes burial funds, grocery schemes and investments, playing an insurance role."},"comparison":{"ar":"على غرار جمعيات الادخار الدوارة (ROSCAs) في مناطق أخرى، لكن الستوكفيلز تتميز بطابعها الاجتماعي القوي وتنوع أغراضها.","de":"Ähnlich wie rotierende Sparvereine (ROSCAs) in anderen Regionen, aber Stokvels zeichnen sich durch ihren starken sozialen Charakter und ihre vielfältigen Zwecke aus.","en":"Similar to rotating savings and credit associations (ROSCAs) elsewhere, but stokvels are distinguished by their strong social character and diverse purposes."}},{"id":"afr-032","version":2,"slug":"m-pesa-how-a-phone-became-the-bank-branch","contentType":"feature","category":"work-and-education","title":{"ar":"M-Pesa: كيف أصبح الهاتف فرعاً مصرفياً","de":"M-Pesa: Wie das Handy zur Bankfiliale wurde","en":"M-Pesa: How a Phone Became the Bank Branch"},"deck":{"ar":"في كينيا وتنزانيا، غيّر نظام الدفع عبر الهاتف طريقة تعامل الناس مع المال في حياتهم اليومية.","de":"In Kenia und Tansania hat mobiles Bezahlen den Alltag vieler Menschen verändert.","en":"In Kenya and Tanzania, mobile money has changed how people handle money in everyday life."},"teaser":{"ar":"من دفع أجرة الحافلة إلى تحويل مصروف المدرسة، أصبح الهاتف المحمول أداة مالية لا غنى عنها لكثيرين.","de":"Vom Matatu-Fahrgeld bis zu Schulgeld und Gemüseeinkäufen: Das Handy ist für viele zur unverzichtbaren Finanzzentrale geworden.","en":"From matatu fares to school fees and vegetables, the mobile phone has become an essential financial tool for many."},"readingMinutes":1,"sections":{"ar":[{"heading":"بداية غير متوقعة","paragraphs":["انطلق M-Pesa في كينيا عام 2007 كخدمة أموال عبر الهاتف تديرها شركة سافاريكوم وفودافون، وكان الهدف الأولي تحصيل أقساط التمويل الأصغر. لكن الناس سرعان ما استخدموه لتحويل الأموال ودفع الفواتير، فتحول إلى جزء من الحياة اليومية.","يعتمد النظام على شبكة من الوكلاء، غالباً أصحاب دكاكين صغيرة، حيث يودع الناس النقود أو يسحبونها. ثم يرسلون المال عبر الهاتف إلى أي رقم آخر. وقد انتشر النموذج لاحقاً إلى تنزانيا وموزمبيق وجمهورية الكونغو الديمقراطية وليسوتو وغانا ومصر وإثيوبيا، مع اختلافات في التنظيم والرسوم."]},{"heading":"المال في جيب الجميع","paragraphs":["غيّر M-Pesa طريقة دفع أجرة حافلات الماتاتو، ورسوم المدارس، والخضروات، والتحويلات المالية، خاصة حيث تقل فروع البنوك. ففي نيروبي، يرسل سائق الماتاتو الباقي عبر M-Pesa لأن لا هو ولا الراكب يملكان فكة صغيرة. وأصبحت إيصالات M-Pesa مقبولة كإثبات للدفع في كثير من المعاملات.","شبكة الوكلاء نفسها أصبحت طبقة جديدة من التجارة المحلية، حيث يقدم البقالون والصرافون الصغار خدمات مالية إلى جانب بضائعهم. لكن التجربة تختلف باختلاف البلد والتنظيم؛ فنجاح M-Pesa في كينيا يعود إلى ظروف سوقية وتنظيمية خاصة، بينما لتنزانيا وغيرها تاريخ مختلف وهياكل رسوم مختلفة."]},{"heading":"تحديات وفرص","paragraphs":["أجبر نجاح الأموال عبر الهاتف البنوك والجهات التنظيمية على التكيف، وأثار أسئلة حول الرسوم والبيانات واستبعاد من لا يملكون هواتف. ورغم ذلك، يبقى M-Pesa مثالاً على كيف يمكن لحل تقني بسيط أن يعيد تشكيل العلاقة بين الناس والمال في حياتهم اليومية."]}],"de":[{"heading":"Ein unerwarteter Anfang","paragraphs":["M-Pesa startete 2007 in Kenia als mobiler Gelddienst von Safaricom und Vodafone, ursprünglich um Mikrokreditraten einzuziehen. Doch die Menschen nutzten es bald für Überweisungen und Rechnungen, und es wurde Teil des Alltags.","Das System basiert auf einem Netz von Agenten, oft kleine Ladenbesitzer, bei denen man Bargeld ein- und auszahlen kann. Anschließend sendet man Geld per Handy an eine andere Nummer. Später breitete sich das Modell nach Tansania, Mosambik, in die DR Kongo, nach Lesotho, Ghana, Ägypten und Äthiopien aus – mit unterschiedlichen Regeln und Gebühren."]},{"heading":"Geld in jedermanns Tasche","paragraphs":["M-Pesa veränderte die Bezahlung von Matatu-Fahrten, Schulgebühren, Gemüse und Geldtransfers, besonders dort, wo Bankfilialen selten sind. In Nairobi schickt ein Matatu-Schaffner das Wechselgeld per M-Pesa, weil weder er noch der Fahrgast kleine Scheine hat. M-Pesa-Quittungen gelten in vielen Geschäften als Zahlungsnachweis.","Das Agentennetz wurde zu einer neuen Ebene des lokalen Handels, da Kioskbesitzer und kleine Geldwechsler neben ihren Waren auch Finanzdienstleistungen anbieten. Doch die Erfahrung variiert je nach Land und Regulierung; der Erfolg in Kenia ist an spezifische Markt- und Regulierungsbedingungen gebunden, während Tansania und andere Länder eine andere Geschichte und andere Gebührenstrukturen haben."]},{"heading":"Herausforderungen und Chancen","paragraphs":["Der Erfolg von mobilem Geld zwang Banken und Aufsichtsbehörden zur Anpassung und warf Fragen zu Gebühren, Daten und dem Ausschluss von Menschen ohne Handy auf. Dennoch bleibt M-Pesa ein Beispiel dafür, wie eine einfache technische Lösung die Beziehung zwischen Menschen und Geld im Alltag neu gestalten kann."]}],"en":[{"heading":"An Unexpected Start","paragraphs":["M-Pesa launched in Kenya in 2007 as a mobile money service run by Safaricom and Vodafone, originally to collect microfinance repayments. But people soon used it for transfers and bills, and it became part of daily life.","The system relies on a network of agents, often small shopkeepers, where people deposit or withdraw cash. They then send money by phone to another number. The model later spread to Tanzania, Mozambique, DR Congo, Lesotho, Ghana, Egypt and Ethiopia, with different regulations and fees."]},{"heading":"Money in Everyone's Pocket","paragraphs":["M-Pesa changed how people pay for matatu rides, school fees, vegetables and remittances, especially where bank branches are scarce. In Nairobi, a matatu conductor sends change through M-Pesa because neither he nor the passenger has small notes. M-Pesa receipts are accepted as proof of payment in many transactions.","The agent network itself became a new layer of local commerce, as shopkeepers and small money changers offer financial services alongside their goods. But the experience varies by country and regulation; M-Pesa's success in Kenya is tied to specific market and regulatory conditions, while Tanzania and others have different histories and fee structures."]},{"heading":"Challenges and Opportunities","paragraphs":["The success of mobile money forced banks and regulators to adapt and raised questions about fees, data and the exclusion of people without phones. Still, M-Pesa remains an example of how a simple technical solution can reshape the relationship between people and money in everyday life."]}]},"context":{"countries":["KE","TZ"],"region":"East Africa","continent":"africa","languages":["sw","en"],"period":"contemporary"},"tags":["work-and-education","East Africa","M-Pesa launched","Users deposit"],"sources":[{"organization":"Wikipedia","title":{"ar":"M-PESA","de":"M-PESA","en":"M-PESA"},"url":"https://en.wikipedia.org/wiki/M-PESA","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Kenya","de":"Kenya","en":"Kenya"},"url":"https://en.wikipedia.org/wiki/Kenya","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في نيروبي، يرسل سائق الماتاتو الباقي عبر M-Pesa لأن لا هو ولا الراكب يملكان فكة صغيرة.","de":"In Nairobi schickt ein Matatu-Schaffner das Wechselgeld per M-Pesa, weil weder er noch der Fahrgast kleine Scheine hat.","en":"In Nairobi, a matatu conductor sends change through M-Pesa because neither he nor the passenger has small notes."},"misunderstanding":{"ar":"ليس كل مستخدمي M-Pesa في شرق أفريقيا لديهم نفس التجربة؛ فالتنظيم والرسوم تختلف بين كينيا وتنزانيا وغانا.","de":"Nicht alle M-Pesa-Nutzer in Ostafrika machen dieselben Erfahrungen; Regulierung und Gebühren unterscheiden sich zwischen Kenia, Tansania und Ghana.","en":"Not all M-Pesa users in East Africa have the same experience; regulation and fees differ between Kenya, Tanzania and Ghana."},"comparison":{"ar":"بينما تعتمد بعض الدول على البطاقات البنكية، وجد كثيرون في شرق أفريقيا في الهاتف المحمول بديلاً عملياً للخدمات المصرفية.","de":"Während in einigen Ländern Bankkarten dominieren, haben viele in Ostafrika im Handy einen praktischen Ersatz für Bankdienstleistungen gefunden.","en":"While some countries rely on bank cards, many in East Africa have found in the mobile phone a practical alternative to banking services."}},{"id":"afr-034","version":2,"slug":"matatu-nairobi-s-privately-run-public-transport","contentType":"feature","category":"cities-and-community","title":{"ar":"الماتاتو: حياة نيروبي على أربع عجلات","de":"Matatu: Nairobis privater Nahverkehr","en":"Matatu: Nairobi's privately run public transport"},"deck":{"ar":"حافلات صغيرة يملكها أفراد وتنقل أغلب سكان نيروبي، فتصنع ثقافة ولغة وعملاً للشباب.","de":"Privat betriebene Minibusse tragen den Großteil des Berufsverkehrs in Nairobi und schaffen Kultur, Sprache und Arbeit.","en":"Privately owned minibuses carry most commuter trips in Nairobi, shaping culture, slang and work for young people."},"teaser":{"ar":"في نيروبي ليست الحافلة الصغيرة مجرد وسيلة نقل، بل مسرح يومي للناس والأصوات والبحث عن لقمة العيش.","de":"In Nairobi ist der Matatu mehr als ein Bus: ein täglicher Schauplatz von Stimmen, Stil und dem Ringen um den Lebensunterhalt.","en":"In Nairobi the minibus is more than transport: a daily stage of voices, style and the struggle to make a living."},"readingMinutes":1,"sections":{"ar":[{"heading":"من يركب ومن يعمل","paragraphs":["في نيروبي يعتمد كثير من الناس على الماتاتو، وهي حافلات صغيرة يملكها أفراد وتنقل أغلب رحلات التنقل في المدينة، إذ تشير بعض التقديرات إلى أكثر من سبعين في المئة.","هذه الحافلات ليست وسيلة نقل فقط، بل مكان يعمل فيه شباب كسائقين ومحصلين ومسوّقين ينادون على الركاب في المحطات.","يقف المحصل أحياناً عند الباب وهو يصرخ باسم الوجهة، بينما يشغّل السائق أغنية مختارة لتجذب ركاب الحافلة المنافسة خلفه."]},{"heading":"الزينة والصوت","paragraphs":["كثيراً ما تُزيَّن الماتاتو بصور موسيقيين وسياسيين وشعارات وأضواء وأنظمة صوت، وهذا التزيين جزء من جاذبية الحافلة نفسها.","هذه الثقافة أنتجت عامية وأزياء وموسيقى خاصة بها، وصارت علامة يتعرّف عليها سكان المدينة.","لكن المظهر المزخرف لا يخفي كل شيء، فالظروف داخل الحافلة غالباً أفقر مما يوحي الخارج اللامع."]},{"heading":"التنظيم والمخاطر","paragraphs":["تُدار الخطوط والمحطات والأجرة عبر مجموعات ادخار وائتمان وجمعيات محطات تتفاوض مع حكومة المقاطعة.","تبقى الحوادث والازدحام والرسوم غير الرسمية مشكلات مستمرة، وقد أدخلت قواعد ميتشوكي عام 2004 أحزمة الأمان وحدوداً للسرعة.","تختلف التنظيمات والأسلوب بين نيروبي ومومباسا والبلدات الأصغر، كما يختلف تعامل الأجيال مع هذه الحافلات بين من يعتمد عليها يومياً ومن يفضّل غيرها.","هكذا يبقى الماتاتو مساحة يومية للناس: عمل وركوب وصوت وزينة، ومسألة تنظيم لا تنتهي."]}],"de":[{"heading":"Wer fährt, wer arbeitet","paragraphs":["In Nairobi sind Matatus privat betriebene Minibusse, die den Großteil der Pendlerfahrten bewältigen – nach manchen Schätzungen über siebzig Prozent.","Sie sind nicht nur Verkehrsmittel, sondern auch Arbeitsplatz: Junge Menschen arbeiten als Fahrer, Schaffner und Anrufer an den Haltestellen.","Ein Schaffner hängt manchmal aus der Tür und ruft das Ziel aus, während der Fahrer einen Titel spielt, der Fahrgäste vom konkurrierenden Bus dahinter abziehen soll."]},{"heading":"Dekor und Klang","paragraphs":["Oft sind die Fahrzeuge mit Porträts von Musikern und Politikern, Slogans, Lichtern und Soundsystemen geschmückt; die Dekoration gehört zum Reiz eines Wagens.","Diese Kultur hat eigenen Slang, eigene Mode und eigene Musik hervorgebracht und ist zu einem Erkennungszeichen der Stadt geworden.","Doch das geschmückte Äußere verdeckt nicht alles: Die Bedingungen im Inneren sind oft ärmlicher, als der glänzende Lack vermuten lässt."]},{"heading":"Organisation und Risiken","paragraphs":["Routen, Haltestellen und Fahrpreise werden von Spar- und Kreditgruppen sowie Haltestellenvereinigungen verwaltet, die mit der Bezirksregierung verhandeln.","Unfälle, Staus und informelle Gebühren bleiben hartnäckige Probleme; die Michuki-Regeln von 2004 führten Sicherheitsgurte und Tempolimits ein.","Regulierung und Stil unterscheiden sich zwischen Nairobi, Mombasa und kleineren Städten, und auch der Umgang der Generationen mit dem Matatu ist verschieden.","So bleibt der Matatu ein täglicher Raum der Menschen: Arbeit, Fahrt, Klang und Dekor – und eine nie endende Frage der Regulierung."]}],"en":[{"heading":"Who rides and who works","paragraphs":["In Nairobi, Matatus are privately owned minibuses that carry most commuter trips in the city — over 70 percent by some estimates.","They are not only vehicles but workplaces: young people earn a living as drivers, conductors and touts calling for passengers at the stages.","A conductor sometimes hangs out of the door shouting the destination while the driver plays a track chosen to pull passengers from the rival bus behind."]},{"heading":"Decoration and sound","paragraphs":["Matatus are often decorated with portraits of musicians and politicians, slogans, lights and sound systems, and the decoration is part of a vehicle's appeal.","This culture has produced its own slang, fashion and music, and it has become a recognisable mark of the city.","But the decorated exterior does not hide everything: conditions inside are often poorer than the gleaming paint suggests."]},{"heading":"Organisation and risks","paragraphs":["Routes, stages and fares are managed by savings and credit groups and stage associations that negotiate with the county government.","Crashes, congestion and informal fees are persistent problems, and the 2004 Michuki rules introduced seat belts and speed limits.","Regulation and style vary between Nairobi, Mombasa and smaller towns, and different generations relate to the matatu in different ways.","So the matatu remains a daily space for people: work, travel, sound and decoration, and an endless question of regulation."]}]},"context":{"countries":["KE"],"region":"Nairobi, Kenya","continent":"africa","languages":["sw","en"],"period":"contemporary"},"tags":["cities-and-community","Nairobi, Kenya"],"sources":[{"organization":"Wikipedia","title":{"ar":"Matatu","de":"Matatu","en":"Matatu"},"url":"https://en.wikipedia.org/wiki/Matatu","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Nairobi","de":"Nairobi","en":"Nairobi"},"url":"https://en.wikipedia.org/wiki/Nairobi","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يقف المحصل عند الباب صارخاً باسم الوجهة، بينما يشغّل السائق أغنية مختارة لتجذب ركاب الحافلة المنافسة خلفه.","de":"Ein Schaffner hängt aus der Tür und ruft das Ziel aus, während der Fahrer einen Titel spielt, der Fahrgäste vom konkurrierenden Bus dahinter abziehen soll.","en":"A conductor hangs out of the door shouting the destination while the driver plays a track chosen to pull passengers from the rival bus behind."},"misunderstanding":{"ar":"كثيرون خارج كينيا يظنون أن الماتاتو مجرد حافلات قديمة مزدحمة، لكنها في الواقع نظام نقل خاص تديره مجموعات محلية وتعمل فيه أجيال من الشباب.","de":"Viele außerhalb Kenias halten Matatus für bloß alte, überfüllte Busse; tatsächlich sind sie ein privat organisiertes Verkehrssystem, das lokale Gruppen betreiben und in dem Generationen junger Menschen arbeiten.","en":"Many outside Kenya assume matatus are simply old, overcrowded buses; in fact they are a privately organised transport system run by local groups and staffed by generations of young workers."},"comparison":{"ar":"يشبه الماتاتو في دوره حافلات النقل الخاص في مدن أخرى، لكن زينته الصوتية والبصرية وثقافته العامية تمنحه طابعاً محلياً مميزاً.","de":"In seiner Rolle ähnelt der Matatu privaten Sammeltransporten anderer Städte, doch seine klangliche und visuelle Dekoration und sein eigener Slang geben ihm einen unverwechselbar lokalen Charakter.","en":"In its role the matatu resembles private minibus transport in other cities, but its visual and sonic decoration and its own slang give it a distinctly local character."}},{"id":"afr-035","version":2,"slug":"umuganda-rwanda-s-monthly-communal-work","contentType":"feature","category":"cities-and-community","title":{"ar":"أوموغاندا: العمل المجتمعي الشهري في رواندا","de":"Umuganda: Ruandas monatliche Gemeinschaftsarbeit","en":"Umuganda: Rwanda's Monthly Communal Work"},"deck":{"ar":"في كل سبت أخير من الشهر، يشارك الروانديون في خدمة مجتمعية إلزامية تنظف الأحياء وتبني المنازل وتفتح باب الحوار.","de":"Jeden letzten Samstag im Monat leisten die Menschen in Ruanda einen verpflichtenden Gemeindedienst, der Straßen reinigt, Häuser baut und Raum für Dialog schafft.","en":"On the last Saturday of every month, Rwandans take part in a mandatory community service that cleans roads, builds houses and opens a space for dialogue."},"teaser":{"ar":"كيف تحول يوم عمل تطوعي إلى التزام قانوني يجمع الجيران لتحسين حياتهم اليومية؟","de":"Wie wird ein gemeinschaftlicher Arbeitstag zu einer gesetzlichen Pflicht, die Nachbarn zusammenbringt und das tägliche Leben verbessert?","en":"How does a day of communal work become a legal obligation that brings neighbours together and improves daily life?"},"readingMinutes":1,"sections":{"ar":[{"heading":"يوم السبت الأخير: البداية والنطاق","paragraphs":["في تمام الساعة الثامنة صباحًا من كل سبت أخير في الشهر، تتوقف الحياة العادية في رواندا لتبدأ أوموغاندا، خدمة مجتمعية إلزامية على مستوى البلاد. يخرج السكان من منازلهم للمشاركة في أنشطة تستمر حتى الحادية عشرة، وتشمل تنظيف الطرق وبناء منازل للمحتاجين وزراعة الأشجار وإصلاح البنية التحتية. هذه الممارسة ليست مجرد حملة نظافة، بل هي لحظة تجتمع فيها المجتمعات المحلية لتحسين بيئتها المباشرة. وتختلف طبيعة المشاركة حسب المنطقة، حيث تتنوع المهام بين الريف والحضر، كما يلاحظ اختلاف في مستوى الحماس بين الأجيال الأصغر والأكبر."]},{"heading":"ما بعد العمل: الاجتماع المجتمعي","paragraphs":["بعد انتهاء ساعات العمل، يتحول المتطوعون إلى اجتماع مجتمعي يعقد في الهواء الطلق أو في قاعات عامة. يُستخدم هذا الاجتماع للإعلانات المحلية، وحل النزاعات بين الجيران، ونقل رسائل الحكومة. إنه منبر مزدوج: من جهة، يرفع السكان شكاواهم ويطرحون احتياجاتهم، ومن جهة أخرى، تصلهم توجيهات رسمية. هذا المزيج بين العمل اليدوي والحوار المدني هو ما يميز أوموغاندا عن أشكال التطوع الأخرى."]},{"heading":"بين الإلزام والمشاركة: آراء متباينة","paragraphs":["ينص القانون الرواندي على إلزامية المشاركة، وقد يُفرض غرامة على من يتخلف. يرى المؤيدون أن هذا الإلزام يضمن تحسينات ملموسة في البنية التحتية ويعزز روح المشاركة المحلية. في المقابل، يشير المنتقدون إلى أن الخدمة الإلزامية وشكل الاجتماع قد يعملان كأدوات للرقابة الاجتماعية. الجدل حول أوموغاندا يعكس توترًا أوسع بين المصلحة الجماعية والحرية الفردية، وهو نقاش حاضر في العديد من المجتمعات."]}],"de":[{"heading":"Der letzte Samstag: Beginn und Umfang","paragraphs":["Pünktlich um 08:00 Uhr an jedem letzten Samstag im Monat kommt das normale Leben in Ruanda zum Stillstand, um Platz für Umuganda zu machen, einen landesweiten verpflichtenden Gemeindedienst. Die Bewohner verlassen ihre Häuser und beteiligen sich an Aktivitäten, die bis 11:00 Uhr dauern und das Reinigen von Straßen, den Bau von Häusern für Bedürftige, das Pflanzen von Bäumen und die Reparatur von Infrastruktur umfassen. Diese Praxis ist nicht nur eine Reinigungsaktion, sondern ein Moment, in dem lokale Gemeinschaften zusammenkommen, um ihre unmittelbare Umgebung zu verbessern. Die Art der Beteiligung variiert je nach Region, wobei sich die Aufgaben zwischen ländlichen und städtischen Gebieten unterscheiden, und es gibt auch Unterschiede in der Begeisterung zwischen jüngeren und älteren Generationen."]},{"heading":"Nach der Arbeit: die Gemeinschaftsversammlung","paragraphs":["Nach den Arbeitsstunden verwandeln sich die Freiwilligen in eine Gemeinschaftsversammlung, die im Freien oder in öffentlichen Hallen stattfindet. Diese Versammlung dient lokalen Ankündigungen, der Beilegung von Streitigkeiten zwischen Nachbarn und der Übermittlung von Regierungsbotschaften. Sie ist eine doppelte Plattform: Einerseits bringen die Bewohner ihre Beschwerden vor und äußern ihre Bedürfnisse, andererseits erhalten sie offizielle Anweisungen. Diese Kombination aus Handarbeit und zivilgesellschaftlichem Dialog unterscheidet Umuganda von anderen Formen des Freiwilligendienstes."]},{"heading":"Zwischen Pflicht und Teilnahme: geteilte Meinungen","paragraphs":["Das ruandische Gesetz schreibt die Teilnahme verpflichtend vor, und bei Nichtteilnahme kann eine Geldstrafe verhängt werden. Befürworter argumentieren, dass diese Verpflichtung konkrete Verbesserungen der Infrastruktur gewährleistet und den Geist der lokalen Beteiligung stärkt. Kritiker weisen jedoch darauf hin, dass der verpflichtende Dienst und das Format der Versammlung auch als Instrumente der sozialen Kontrolle dienen können. Die Debatte um Umuganda spiegelt eine breitere Spannung zwischen Gemeinwohl und individueller Freiheit wider, eine Diskussion, die in vielen Gesellschaften präsent ist."]}],"en":[{"heading":"The Last Saturday: Start and Scope","paragraphs":["At 08:00 sharp on the last Saturday of every month, normal life in Rwanda pauses for Umuganda, a nationwide mandatory community service. Residents leave their homes to take part in activities that last until 11:00 and include cleaning roads, building houses for vulnerable people, planting trees and repairing infrastructure. This practice is not just a clean-up campaign; it is a moment when local communities come together to improve their immediate surroundings. The nature of participation varies by region, with tasks differing between rural and urban areas, and there is also a noticeable difference in enthusiasm between younger and older generations."]},{"heading":"After the Work: The Community Meeting","paragraphs":["After the working hours, the volunteers turn into a community meeting held outdoors or in public halls. This meeting is used for local announcements, resolving disputes between neighbours and conveying government messages. It is a dual platform: on one hand, residents raise complaints and express their needs; on the other, they receive official directives. This combination of manual work and civic dialogue is what distinguishes Umuganda from other forms of volunteering."]},{"heading":"Between Obligation and Participation: Divided Opinions","paragraphs":["Rwandan law mandates participation, and failure to take part can result in a fine. Supporters argue that this obligation ensures tangible infrastructure improvements and strengthens the spirit of local participation. Critics, however, point out that mandatory service and the meeting format can also serve as tools of social control. The debate around Umuganda reflects a broader tension between collective welfare and individual freedom, a discussion present in many societies."]}]},"context":{"countries":["RW"],"region":"Rwanda","continent":"africa","languages":["rw","fr","en"],"period":"contemporary"},"tags":["cities-and-community","Rwanda"],"sources":[{"organization":"Wikipedia","title":{"ar":"Umuganda","de":"Umuganda","en":"Umuganda"},"url":"https://en.wikipedia.org/wiki/Umuganda","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Rwanda","de":"Rwanda","en":"Rwanda"},"url":"https://en.wikipedia.org/wiki/Rwanda","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في صباح سبت في كيغالي، يقوم الجيران بتنظيف قناة تصريف معًا، ثم يجلسون تحت شجرة للاستماع إلى المسؤولين المحليين وطرح الشكاوى.","de":"An einem Samstagmorgen in Kigali reinigen Nachbarn gemeinsam einen Entwässerungskanal und setzen sich dann unter einen Baum, um lokalen Beamten zuzuhören und Beschwerden vorzubringen.","en":"On a Saturday morning in Kigali, neighbours clear a drainage channel together, then sit under a tree to hear local officials and raise complaints."},"misunderstanding":{"ar":"يعتقد البعض أن أوموغاندا مجرد يوم تنظيف، لكنها في الواقع تشمل بناء منازل وزراعة أشجار وإصلاح بنية تحتية، وتُختتم باجتماع مجتمعي له وظائف إدارية.","de":"Manche glauben, Umuganda sei nur ein Reinigungstag, aber tatsächlich umfasst es den Bau von Häusern, das Pflanzen von Bäumen und die Reparatur von Infrastruktur und endet mit einer Gemeinschaftsversammlung, die administrative Funktionen hat.","en":"Some believe Umuganda is just a clean-up day, but it actually includes building houses, planting trees and repairing infrastructure, and ends with a community meeting that has administrative functions."},"comparison":{"ar":"تختلف أوموغاندا عن أشكال العمل التطوعي في المنطقة بسبب طابعها الإلزامي، مما يميزها عن مبادرات تطوعية أخرى.","de":"Umuganda unterscheidet sich von Formen der Freiwilligenarbeit in der Region durch seinen verpflichtenden Charakter, was es von anderen freiwilligen Initiativen abhebt.","en":"Umuganda differs from forms of volunteer work in the region because of its compulsory character, which sets it apart from other voluntary initiatives."}},{"id":"afr-036","version":2,"slug":"kgotla-botswana-s-public-assembly-and-the-rule-of-consensus","contentType":"feature","category":"cities-and-community","title":{"ar":"الكغوتلا: مجلس العامة وحكم التوافق","de":"Kgotla: Versammlung und Konsens in Botswana","en":"Kgotla: Botswana's Assembly and the Rule of Consensus"},"deck":{"ar":"في بوتسوانا يجتمع الناس تحت شجرة أو في ساحة القرية ليقرروا معًا، في تقليد يجعل الاستماع قبل الكلام قاعدة.","de":"In Botswana entscheidet die Dorfgemeinschaft im offenen Gespräch, und Zuhören gilt dabei als Pflicht vor dem eigenen Wort.","en":"In Botswana the community gathers to decide together, and listening before speaking is treated as a duty rather than a courtesy."},"teaser":{"ar":"مجلس يجمع القرية كلها، يحلّ الخلافات ويوزّع الأرض، ويشترط ألا يقاطع أحد متحدثًا.","de":"Eine Versammlung, die Streit schlichtet und Land verteilt, mit einer klaren Regel: Niemand unterbricht einen Sprecher.","en":"A public meeting that settles disputes and allocates land, with one firm rule: nobody interrupts while another is speaking."},"readingMinutes":1,"sections":{"ar":[{"heading":"مجلس يجمع القرية","paragraphs":["الكغوتلا في بوتسوانا ليس مجرد لقاء عابر، بل مجلس عام ومجلس محلي ومحكمة تقليدية في الوقت نفسه. يرأسه زعيم أو شيخ يعمل مع مستشارين، ويجتمع الناس فيه لمناقشة ما يخصّهم من أرض وخلافات وسياسات.","توجد مؤسسات مشابهة في المناطق الريفية في ليسوتو وجنوب أفريقيا، ما يدل على أن فكرة المجلس المفتوح أقدم من الحدود الحديثة. وفي المدن، كثيرًا ما يعود السكان إلى قراهم الأصلية لحضور الكغوتلا، فيبقى الرابط بالقرية قائمًا حتى مع الحياة الحضرية."]},{"heading":"قواعد الكلام والاستماع","paragraphs":["ما يميز هذا المجلس هو ترتيب الكلام: لا يجوز لأحد أن يقاطع آخر وهو يتحدث، ولكل حاضر حقه في أن يقول ما عنده. والمجلس هو المكان المعترف به لطرح المظالم، فلا يُطلب من صاحب الشكوى أن يبحث عن طريق آخر.","بعد أن يتكلم الجميع تُتخذ القرارات بالتوافق، لا بغلبة الأصوات وحدها. هذا الأسلوب يمنح القرار شرعية أوسع، لأنه لا يُفرض على من لم يُسمع رأيه.","وتختلف الممارسة من مجموعة إثنية إلى أخرى داخل بوتسوانا، كما تتباين بين الأجيال: فالشباب قد يشاركون أكثر في المدن، بينما يبقى الحضور الرسمي في القرية لكبار السن غالبًا."]},{"heading":"الديمقراطية والانتقادات","paragraphs":["يربط كثيرون سمعة بوتسوانا كديمقراطية مستقرة بتقاليد الكغوتلا في التشاور العلني، حيث يتعلم الناس النقاش والمساءلة منذ الصغر. غير أن المؤسسة تتأثر أيضًا بالسياسة الحزبية، ولم تبقَ بمعزل عن التنافس بين الأحزاب.","وقد وُجّهت انتقادات للممارسة لأنها غالبًا ما تُبقي الشباب والنساء بعيدين عن مواقع الكلام الرسمي، حتى عندما يحضرون. ومع ذلك يبقى المجلس مكانًا يُلجأ إليه لتسوية المنازعات وتوزيع الأرض والاستشارة في السياسات.","وهذا التوازن بين التقاليد والانتقاد هو ما يجعل الكغوتلا موضوعًا حيًّا في النقاش العام، لا مجرد ذكرى من الماضي."]}],"de":[{"heading":"Eine Versammlung für das ganze Dorf","paragraphs":["Die Kgotla in Botswana ist kein flüchtiges Treffen, sondern zugleich öffentliche Versammlung, Gemeinderat und traditionelles Gericht. Geleitet wird sie von einem Häuptling oder Vorsteher, der mit Beratern zusammenarbeitet, und die Menschen kommen zusammen, um über Land, Streitigkeiten und Politik zu beraten.","Ähnliche Einrichtungen gibt es im ländlichen Lesotho und in Südafrika, was zeigt, dass die Idee der offenen Versammlung älter ist als moderne Staatsgrenzen. In den Städten kehren viele Bewohner für die Kgotla in ihre Heimatdörfer zurück, sodass die Bindung zum Dorf auch im urbanen Leben bestehen bleibt."]},{"heading":"Regeln des Sprechens und Zuhörens","paragraphs":["Das Besondere ist die Ordnung des Wortes: Niemand darf einen anderen unterbrechen, und jede anwesende Person hat das Recht zu sprechen. Die Versammlung ist der anerkannte Ort, um Beschwerden vorzubringen, sodass niemand einen anderen Weg suchen muss.","Erst wenn alle gesprochen haben, werden Entscheidungen im Konsens getroffen, nicht allein durch Mehrheiten. Das verleiht Beschlüssen breitere Legitimität, weil sie niemandem aufgezwungen werden, der nicht gehört wurde.","Die Praxis unterscheidet sich zwischen den ethnischen Gruppen Botswanas und auch zwischen den Generationen: Jüngere beteiligen sich in Städten stärker, während in den Dörfern die formellen Sprechrollen oft bei Älteren liegen."]},{"heading":"Demokratie und Kritik","paragraphs":["Botswanas Ruf als stabile Demokratie wird häufig mit den Kgotla-Traditionen öffentlicher Beratung verbunden, da Menschen dort früh Debatte und Rechenschaft lernen. Zugleich ist die Institution von Parteipolitik geprägt und steht nicht außerhalb des Wettbewerbs der Parteien.","Kritik richtet sich darauf, dass junge Menschen und Frauen oft von formellen Sprechpositionen ausgeschlossen bleiben, selbst wenn sie anwesend sind. Dennoch bleibt die Kgotla ein Ort für Landvergabe, Streitschlichtung und Beratung über Politik.","Genau diese Spannung zwischen Tradition und Kritik macht die Kgotla zu einem lebendigen Thema der öffentlichen Debatte und nicht zu einer bloßen Erinnerung."]}],"en":[{"heading":"A meeting for the whole village","paragraphs":["A kgotla in Botswana is not a fleeting gathering but a public meeting, community council and traditional court at once. It is headed by a chief or headman who works with advisers, and people come together to discuss land, disputes and policy.","Similar institutions exist in rural Lesotho and South Africa, which shows that the idea of open assembly is older than modern borders. In towns, urban residents often return to their home villages for the kgotla, so the link to the village survives even in city life."]},{"heading":"Rules of speaking and listening","paragraphs":["What sets the assembly apart is the ordering of speech: no one may interrupt while another is having their say, and every person present has the right to speak. The kgotla is the accepted place to raise grievances, so nobody has to look for another route.","Only after everyone has spoken are decisions reached by consensus, not by majority alone. This gives decisions broader legitimacy, because they are not imposed on anyone who was not heard.","Practice varies across Botswana's ethnic groups and between generations: younger people take part more in towns, while formal speaking roles in villages often stay with elders."]},{"heading":"Democracy and its critics","paragraphs":["Botswana's reputation for stable democracy is often linked to kgotla traditions of public deliberation, where people learn debate and accountability early. At the same time the institution is shaped by party politics and does not stand outside party competition.","Critics point out that young people and women are often kept out of formal speaking positions, even when they attend. Yet the kgotla remains a place used for land allocation, dispute settlement and consultation on policy.","That tension between tradition and criticism is what keeps the kgotla a living subject of public debate rather than a memory of the past."]}]},"context":{"countries":["BW"],"region":"Botswana","continent":"africa","languages":["tn","en"],"period":"contemporary"},"tags":["cities-and-community","Botswana"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kgotla","de":"Kgotla","en":"Kgotla"},"url":"https://en.wikipedia.org/wiki/Kgotla","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Botswana","de":"Botswana","en":"Botswana"},"url":"https://en.wikipedia.org/wiki/Botswana","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"ينشب خلاف على أرض في قرية بوتسوانية فيُحال إلى الكغوتلا، حيث تتحدث كل أسرة بدورها قبل أن يعلن الزعيم قرارًا يقبله المجتمع.","de":"Ein Landstreit in einem botswanischen Dorf geht an die Kgotla, wo beide Familien der Reihe nach sprechen, bevor der Häuptling eine von der Gemeinschaft akzeptierte Entscheidung verkündet.","en":"A land dispute in a Botswana village goes to the kgotla, where both families speak in turn before the chief announces a decision the community accepts."},"misunderstanding":{"ar":"يظن بعض الخارجيين أن الكغوتلا محكمة قديمة لا صلة لها بالحاضر، والحقيقة أنه مجلس حيّ يُستخدم اليوم في الأرض والخلافات والسياسات.","de":"Manche Außenstehende halten die Kgotla für ein altes Gericht ohne Bezug zur Gegenwart, doch sie ist eine lebendige Versammlung für Land, Konflikte und Politik.","en":"Some outsiders assume the kgotla is an old court with no relevance today, but it is a living assembly used for land, disputes and policy."},"comparison":{"ar":"يشبه الكغوتلا الاجتماعات المحلية المفتوحة في كثير من المجتمعات، لكن ما يميزه هو إلزامية عدم المقاطعة والتوافق بدل التصويت.","de":"Die Kgotla ähnelt offenen Nachbarschaftsversammlungen anderswo, doch das Verbot der Unterbrechung und der Konsens statt Abstimmung sind besonders.","en":"The kgotla resembles open neighbourhood meetings elsewhere, but the ban on interrupting and consensus instead of voting are distinctive."}},{"id":"afr-037","version":2,"slug":"highlife-the-dance-band-music-of-west-africa-s-ports","contentType":"feature","category":"music-and-dance","title":{"ar":"هايلايف: موسيقى الرقص في موانئ غرب أفريقيا","de":"Highlife: Tanzmusik aus den Häfen Westafrikas","en":"Highlife: Dance-Band Music from West Africa's Ports"},"deck":{"ar":"كيف تحوّلت موسيقى النخبة الاستعمارية إلى إيقاع شعبي يعزف في الأعراس والمآتم.","de":"Wie die Musik der kolonialen Elite zum Soundtrack von Hochzeiten und Beerdigungen wurde.","en":"How the music of the colonial elite became the soundtrack of weddings and funerals."},"teaser":{"ar":"من صالات الرقص في أكرا إلى الأوركسترات النيجيرية، تحكي الهايلايف قصة مدن الموانئ واختلاطها بالعالم.","de":"Von den Tanzsälen Accras zu nigerianischen Orchestern – Highlife erzählt die Geschichte der Hafenstädte und ihrer globalen Verflechtung.","en":"From the dance halls of Accra to Nigerian orchestras, highlife tells the story of port cities and their global connections."},"readingMinutes":1,"sections":{"ar":[{"heading":"من صالات الرقص إلى الشارع","paragraphs":["نشأت الهايلايف في مدن الساحل الغاني في القرن التاسع عشر، حيث امتزجت الإيقاعات المحلية بآلات غربية وألحان الجاز. ويرتبط اسمها غالباً بالحياة الرفيعة التي كان يعيشها النخبة الاستعمارية وبقاعات الرقص التي كانت تُعزف فيها. لكن الموسيقى سرعان ما تجاوزت تلك القاعات لتصل إلى الأحياء الشعبية.","يتميز هذا الطراز بأبواق الجاز والغيتارات وتقنية العزف بإصبعين المستعارة من موسيقى نبيذ النخيل. فالعازفون يقرعون الأوتار بإبهامهم وسبابتهم معاً، مما يمنح الإيقاع نكهته المميزة. وعندما انتقلت الهايلايف إلى نيجيريا، أصبحت أكبر وأكثر أوركسترالية، وساهمت لاحقاً في تطوير الأفروبيت."]},{"heading":"موسيقى المناسبات الاجتماعية","paragraphs":["بعد الاستقلال، بقيت الهايلايف موسيقى اجتماعية للأعراس والجنازات والتجمعات السياسية. ففي جنازة غانية، تعزف فرقة هايلايف الأغنية المفضلة للفقيد بينما يرقص المشيعون ويُعلن عن المتبرعين. وهكذا تصبح الموسيقى وسيلة لتوديع الميت وتكريم الداعمين في آن واحد.","والهايلايف عائلة من الأساليب وليست صوتاً واحداً؛ فهي تختلف بين غانا ونيجيريا، وموسيقى نبيذ النخيل تقليد مرتبط بها لكنه ليس منها. كما أن الأجيال الشابة أعادت إحياءها بأصوات جديدة، مما يدل على مرونتها وقدرتها على التجدد."]},{"heading":"إرث يمتد خارج القارة","paragraphs":["لم تقتصر الهايلايف على غرب أفريقيا، بل سافرت مع الموسيقيين إلى أوروبا وأمريكا، حيث أثرت في موسيقى الجاز الأفريقي وأنماط أخرى. واليوم، تعزفها فرق في لندن ونيويورك، لكن جذورها تبقى في مدن الموانئ التي ولدت فيها. وهكذا تظل الهايلايف شاهدة على تاريخ التجارة والاستعمار والهجرة."]}],"de":[{"heading":"Von den Tanzsälen auf die Straße","paragraphs":["Highlife entstand im 19. Jahrhundert in den Küstenstädten des heutigen Ghana, wo lokale Rhythmen mit westlichen Instrumenten und Jazzmelodien verschmolzen. Der Name wird oft mit dem teuren „high life“ der kolonialen Elite und den Tanzsälen, in denen die Musik gespielt wurde, in Verbindung gebracht. Doch schon bald verließ die Musik diese Säle und erreichte die breite Bevölkerung.","Der Stil zeichnet sich durch jazzige Bläser, Gitarren und die Zwei-Finger-Zupftechnik aus der Palmweinmusik aus. Die Gitarristen zupfen die Saiten mit Daumen und Zeigefinger gleichzeitig, was dem Rhythmus seine besondere Note verleiht. Als Highlife nach Nigeria kam, wurde es größer und orchestraler und trug später zur Entwicklung des Afrobeat bei."]},{"heading":"Musik für soziale Anlässe","paragraphs":["Nach der Unabhängigkeit blieb Highlife soziale Musik für Hochzeiten, Beerdigungen und politische Kundgebungen. Bei einer ghanaischen Beerdigung spielt eine Highlife-Band das Lieblingslied des Verstorbenen, während die Trauergäste tanzen und Spender bekannt gegeben werden. So wird die Musik zum Mittel, den Toten zu verabschieden und gleichzeitig die Unterstützer zu ehren.","Highlife ist eine Familie von Stilen, kein einzelner Klang; ghanaischer und nigerianischer Highlife unterscheiden sich, und Palmweinmusik ist eine verwandte, aber eigenständige Tradition. Jüngere Künstler haben den Stil wiederbelebt, was seine Anpassungsfähigkeit und Erneuerungskraft zeigt."]},{"heading":"Ein Erbe über den Kontinent hinaus","paragraphs":["Highlife blieb nicht auf Westafrika beschränkt, sondern reiste mit Musikern nach Europa und Amerika, wo es afrikanischen Jazz und andere Stile beeinflusste. Heute spielen Bands in London und New York Highlife, doch seine Wurzeln liegen in den Hafenstädten, in denen es entstand. So bleibt Highlife ein Zeugnis der Geschichte von Handel, Kolonialismus und Migration."]}],"en":[{"heading":"From Dance Halls to the Streets","paragraphs":["Highlife developed in the coastal cities of present-day Ghana in the 19th century, blending local rhythms with Western instruments and jazz melodies. Its name is often linked to the expensive 'high life' of colonial elites and to the dance halls where the music was played. But the music soon moved beyond those halls to reach ordinary neighbourhoods.","The style is marked by jazzy horns, guitars and the two-finger plucking technique borrowed from palm-wine music. Guitarists pluck the strings with thumb and index finger together, giving the rhythm its distinctive flavour. As it travelled to Nigeria, highlife became bigger and more orchestral, and it fed into the later development of Afrobeat."]},{"heading":"Music for Social Occasions","paragraphs":["After independence, highlife remained social music for weddings, funerals and political rallies. At a Ghanaian funeral, a highlife band plays the deceased's favourite song while mourners dance and donors are announced. In this way, the music becomes a means of bidding farewell to the dead while honouring supporters.","Highlife is a family of styles rather than one sound; Ghanaian and Nigerian highlife differ, and palm-wine music is a related but distinct tradition. Younger artists have revived it with new sounds, showing its adaptability and capacity for renewal."]},{"heading":"An Legacy Beyond the Continent","paragraphs":["Highlife did not stay confined to West Africa; it travelled with musicians to Europe and America, where it influenced African jazz and other styles. Today, bands in London and New York play highlife, but its roots remain in the port cities where it was born. Thus highlife remains a witness to the history of trade, colonialism and migration."]}]},"context":{"countries":["GH","NG"],"region":"Ghanaian and Nigerian coast","continent":"africa","languages":["ak","en","yo"],"period":"contemporary"},"tags":["music-and-dance","Ghanaian and Nigerian coast","Highlife developed","Its name"],"sources":[{"organization":"Wikipedia","title":{"ar":"Highlife","de":"Highlife","en":"Highlife"},"url":"https://en.wikipedia.org/wiki/Highlife","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Palm-wine music","de":"Palm-wine music","en":"Palm-wine music"},"url":"https://en.wikipedia.org/wiki/Palm-wine_music","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في جنازة غانية، تعزف فرقة هايلايف الأغنية المفضلة للفقيد بينما يرقص المشيعون ويُعلن عن المتبرعين.","de":"Bei einer ghanaischen Beerdigung spielt eine Highlife-Band das Lieblingslied des Verstorbenen, während die Trauergäste tanzen und Spender bekannt gegeben werden.","en":"At a Ghanaian funeral, a highlife band plays the deceased's favourite song while mourners dance and donors are announced."},"misunderstanding":{"ar":"ليس كل ما يُعزف في غانا ونيجيريا هايلايف؛ فهي أسلوب محدد له خصائصه، وليس مجرد موسيقى رقص غرب أفريقية.","de":"Nicht alles, was in Ghana und Nigeria gespielt wird, ist Highlife; es ist ein spezifischer Stil mit eigenen Merkmalen, nicht einfach westafrikanische Tanzmusik.","en":"Not everything played in Ghana and Nigeria is highlife; it is a specific style with its own features, not just any West African dance music."},"comparison":{"ar":"بينما ارتبطت الهايلايف بالنخبة في بداياتها، تحولت لاحقاً إلى موسيقى شعبية، على عكس بعض أنواع الجاز التي بقيت مرتبطة بجمهور محدود.","de":"Während Highlife anfangs mit der Elite verbunden war, wurde es später zur Volksmusik – im Gegensatz zu manchen Jazzformen, die einem begrenzten Publikum vorbehalten blieben.","en":"While highlife was initially associated with the elite, it later became popular music—unlike some jazz forms that remained tied to a limited audience."}},{"id":"afr-038","version":2,"slug":"mbalax-sabar-drums-at-the-centre-of-senegambian-dance-music","contentType":"feature","category":"music-and-dance","title":{"ar":"إيقاع السابار: قلب رقص المبالاكس","de":"Mbalax: Sabar-Trommeln im Zentrum des Tanzes","en":"Mbalax: Sabar Drums at the Heart of Dance"},"deck":{"ar":"كيف تحولت طبول السابار من ساحات الأعراس إلى مسارح العالم.","de":"Wie die Sabar-Trommeln von den Familienfeiern auf die Weltbühnen gelangten.","en":"How sabar drumming moved from family courtyards to global stages."},"teaser":{"ar":"في السنغال وغامبيا، يبدأ كل حفل زفاف بطبول السابار قبل أن تعلو الأغاني الكهربائية. تعرف على المبالاكس، الموسيقى التي تجمع بين التقاليد والحداثة.","de":"In Senegal und Gambia beginnt jede Hochzeit mit Sabar-Trommeln, bevor die elektrische Band übernimmt. Entdecken Sie Mbalax, die Musik, die Tradition und Moderne verbindet.","en":"In Senegal and The Gambia, weddings begin with sabar drums before the electric band takes over. Discover mbalax, the music that bridges tradition and modernity."},"readingMinutes":1,"sections":{"ar":[{"heading":"من ساحة العرس إلى المسرح","paragraphs":["في السنغال وغامبيا وموريتانيا، وُلدت موسيقى المبالاكس من إيقاع طبول السابار التي يعزفها الغريوت والطبّالون في المناسبات العائلية. يجتمع الناس في الأعراس وحفلات تسمية المولود، حيث تبدأ فرق السابار بالعزف، فيتبع الراقصون تغيرات الإيقاع، ثم تبدأ الفرقة الكهربائية عملها فتنتقل السهرة إلى فناء المنزل. هذا الانتقال من الطبول التقليدية إلى الصوت المكبر ليس مجرد تغيير تقني، بل هو امتداد لحياة اجتماعية تضع الرقص في صميم الاحتفال.","ساهم يوسو ندور في تطوير هذا الأسلوب ونقله إلى العالمية في السبعينيات والثمانينيات، مستفيدًا من موسيقى النجوب السيريرية وموسيقى تدريب ندوت. وقد جعلت هذه الخلفية المبالاكس لغة موسيقية قادرة على مخاطبة الأجيال المختلفة، دون أن تقطع صلتها بالطبول الأصلية التي لا تزال حاضرة في الأعراس."]},{"heading":"أغانٍ تتحدث عن الناس","paragraphs":["لا تقتصر أغاني المبالاكس على الترفيه؛ فهي تعلق على القضايا الاجتماعية، وتمدح الرعاة، وتروي الحكايات. الكلمات بالولوف والفرنسية، مما يعكس واقعًا لغويًا متعددًا في المنطقة. الرقص جزء لا يتجزأ من الأداء، إذ يترجم الراقصون الإيقاع إلى حركة، ويصبح الجمهور مشاركًا لا متفرجًا."]},{"heading":"تنوع محلي وامتداد عالمي","paragraphs":["ليست موسيقى المبالاكس متطابقة في السنغال وغامبيا، كما أن شكلها الحديث تشكل بفعل استوديوهات التسجيل وجمهور المهجر. فبعض الفرق تحافظ على التوزيع التقليدي للطبول، بينما تميل فرق أخرى إلى إدخال آلات كهربائية وأساليب إنتاج عالمية. هذا التنوع يعني أن ما يسمعه المرء في داكار قد يختلف عمّا يُعزف في بانجول أو في حفلات المهجر.","في حفل زفاف بالعاصمة السنغالية، يغيّر عازفو السابار الإيقاع فيتبعهم الراقصون، ثم تبدأ فرقة المبالاكس فينتقل الحفل إلى الفناء. هذا المشهد المتكرر يظهر كيف تتعايش الطبول التقليدية والفرقة المكبرة في حدث واحد."]}],"de":[{"heading":"Vom Hof der Feiern zur Bühne","paragraphs":["In Senegal, Gambia und Mauretanien entstand Mbalax aus dem Rhythmus der Sabar-Trommeln, die von Griots und Trommlern bei Familienfeiern gespielt werden. Bei Hochzeiten und Namenszeremonien versammeln sich die Menschen, die Sabar-Ensembles beginnen zu spielen, die Tänzer folgen den Rhythmuswechseln, und dann übernimmt die verstärkte Band, sodass die Feier in den Innenhof wandert. Dieser Übergang von den traditionellen Trommeln zum elektrischen Sound ist nicht nur ein technischer Wandel, sondern Ausdruck eines sozialen Lebens, in dem der Tanz im Mittelpunkt der Feier steht.","Youssou N'Dour trug in den 1970er und 1980er Jahren zur Entwicklung und globalen Verbreitung des Stils bei, wobei er auf die Serer-Musik Njuup und die Initiationsmusik Ndut zurückgriff. Diese Grundlage machte Mbalax zu einer musikalischen Sprache, die verschiedene Generationen anspricht, ohne die Verbindung zu den ursprünglichen Trommeln zu kappen, die bei Hochzeiten weiterhin präsent sind."]},{"heading":"Lieder, die von Menschen erzählen","paragraphs":["Mbalax-Songs dienen nicht nur der Unterhaltung; sie kommentieren soziale Themen, preisen Gönner und erzählen Geschichten. Die Texte sind auf Wolof und Französisch, was die mehrsprachige Realität der Region widerspiegelt. Der Tanz ist integraler Bestandteil der Aufführung, denn die Tänzer übersetzen den Rhythmus in Bewegung, und das Publikum wird zum Teilnehmenden statt zum Zuschauer."]},{"heading":"Lokale Vielfalt und globale Reichweite","paragraphs":["Mbalax ist nicht in ganz Senegal und Gambia identisch, und seine moderne Form wurde durch Aufnahmestudios und Diaspora-Publikum geprägt. Manche Ensembles bewahren die traditionelle Trommelbesetzung, während andere elektrische Instrumente und internationale Produktionsweisen einbeziehen. Diese Vielfalt bedeutet, dass das, was man in Dakar hört, sich von dem unterscheiden kann, was in Banjul oder bei Diaspora-Konzerten gespielt wird.","Bei einer Hochzeit in der senegalesischen Hauptstadt wechseln die Sabar-Spieler den Rhythmus, die Tänzer folgen, dann beginnt eine Mbalax-Band, und die Feier verlagert sich in den Hof. Diese wiederkehrende Szene zeigt, wie traditionelle Trommeln und verstärkte Band bei ein und demselben Ereignis koexistieren."]}],"en":[{"heading":"From Courtyard to Stage","paragraphs":["In Senegal, The Gambia and Mauritania, mbalax grew out of the sabar drum rhythm played by griots and drummers at family ceremonies. At weddings and naming ceremonies, people gather as sabar ensembles start to play, dancers follow the rhythm changes, and then the amplified band begins, moving the celebration into the courtyard. This shift from traditional drums to electric sound is not just a technical change but an expression of social life where dance is central to the event.","Youssou N'Dour helped develop and globalise the style in the 1970s and 1980s, drawing on Serer njuup and ndut initiation music. This foundation made mbalax a musical language that speaks to different generations without severing its connection to the original drums, which remain present at weddings."]},{"heading":"Songs That Speak of People","paragraphs":["Mbalax songs are not only for entertainment; they comment on social issues, praise patrons and tell stories. The lyrics are in Wolof and French, reflecting the multilingual reality of the region. Dance is integral to the performance, as dancers translate rhythm into movement and the audience becomes participants rather than spectators."]},{"heading":"Local Variation, Global Reach","paragraphs":["Mbalax is not identical across Senegal and The Gambia, and its modern form has been shaped by recording studios and diaspora audiences. Some ensembles maintain traditional drum arrangements, while others incorporate electric instruments and international production styles. This diversity means that what one hears in Dakar may differ from what is played in Banjul or at diaspora concerts.","At a Dakar wedding, the sabar players change rhythm, the dancers follow, then a mbalax band starts and the party moves into the courtyard. This recurring scene shows how traditional drums and amplified band coexist in a single event."]}]},"context":{"countries":["SN","GM"],"region":"Senegambia","continent":"africa","languages":["wo","fr"],"period":"contemporary"},"tags":["music-and-dance","Senegambia","Mbalax is","It is"],"sources":[{"organization":"Wikipedia","title":{"ar":"Mbalax","de":"Mbalax","en":"Mbalax"},"url":"https://en.wikipedia.org/wiki/Mbalax","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Youssou N'Dour","de":"Youssou N'Dour","en":"Youssou N'Dour"},"url":"https://en.wikipedia.org/wiki/Youssou_N%27Dour","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في حفل زفاف بالعاصمة داكار، يغيّر عازفو السابار الإيقاع فيتبعهم الراقصون، ثم تبدأ فرقة مبالاكس فينتقل الحفل إلى الفناء.","de":"Bei einer Hochzeit in Dakar wechseln die Sabar-Spieler den Rhythmus, die Tänzer folgen, dann beginnt eine Mbalax-Band, und die Feier verlagert sich in den Hof.","en":"At a Dakar wedding the sabar players change rhythm and the dancers follow, then a mbalax band starts and the party moves into the courtyard."},"misunderstanding":{"ar":"يظن البعض أن المبالاكس مجرد موسيقى رقص حديثة، لكن جذورها في طبول السابار ووظيفتها الاجتماعية في الأعراس تجعلها امتدادًا للتقاليد وليست قطيعة معها.","de":"Manche halten Mbalax für rein moderne Tanzmusik, doch seine Wurzeln in den Sabar-Trommeln und seine soziale Funktion bei Hochzeiten machen es zu einer Fortsetzung der Tradition, nicht zu einem Bruch.","en":"Some assume mbalax is purely modern dance music, but its roots in sabar drumming and its social function at weddings make it a continuation of tradition, not a break from it."},"comparison":{"ar":"في حين أن موسيقى البوب العالمية غالبًا ما تفصل بين المؤدي والجمهور، فإن المبالاكس يدمج الرقص والمشاركة الجماعية في صميم الأداء.","de":"Während globale Popmusik oft zwischen Künstler und Publikum trennt, integriert Mbalax Tanz und gemeinschaftliche Teilnahme in den Kern der Aufführung.","en":"While global pop music often separates performer and audience, mbalax integrates dance and communal participation into the heart of the performance."}},{"id":"afr-039","version":2,"slug":"congolese-rumba-two-capitals-one-guitar-line","contentType":"feature","category":"music-and-dance","title":{"ar":"الرومبا الكونغولية: نغمتان على ضفتي النهر","de":"Kongolesische Rumba: eine Gitarrenlinie, zwei Hauptstädte","en":"Congolese rumba: one guitar line, two capitals"},"deck":{"ar":"كيف صارت موسيقى راقصة من كينشاسا وبرازافيل لغة اجتماعية تعبر الحدود.","de":"Wie eine Tanzmusik aus Kinshasa und Brazzaville zur sozialen Sprache über den Fluss hinweg wurde.","en":"How a dance music from Kinshasa and Brazzaville became a shared social language across the river."},"teaser":{"ar":"من حفلات الأعراس في كينشاسا إلى مسارح باريس، تحمل الرومبا الكونغولية حكايات الحب والسياسة والفقد على أوتار متشابكة.","de":"Von Hochzeiten in Kinshasa bis zu Bühnen in Paris trägt die kongolesische Rumba Geschichten von Liebe, Politik und Verlust auf ineinandergreifenden Saiten.","en":"From Kinshasa weddings to Paris stages, Congolese rumba carries stories of love, politics and loss on interlocking strings."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور تعبر النهر","paragraphs":["نشأت الرومبا الكونغولية في كينشاسا وبرازافيل منذ الثلاثينيات والأربعينيات، إذ امتزج السون الكوبي بالإيقاعات المحلية وبكلمات اللينغالا. قامت على غيتارات متشابكة وغيتار باس دافع وتناغم صوتي، فغدت موسيقى الرقص المهيمنة في وسط أفريقيا.","كان النهران يفصلان مدينتين لكنهما لم يفصلا الأذن الواحدة؛ فالحناجر والأوتار كانت تنتقل مع الناس بين الضفتين، وتتشكل في كل مرة على مقاس الحياة اليومية."]},{"heading":"أغانٍ تحكي ما لا يُقال","paragraphs":["أغاني الرومبا سجلات اجتماعية: تمدح الرعاة، وتعلّق على الحب والسياسة، وتؤرخ الأعراس والجنازات. في عرس بكينشاسا تعزف الفرقة لحناً كلاسيكياً قديماً، فيردد ثلاثة أجيال الكورس باللينغالا عن ظهر قلب.","هكذا تعمل الرومبا كأرشيف حي؛ فالكلمات تنتقل شفاهة، وتظل قادرة على قول ما يصعب قوله في الكلام العادي."]},{"heading":"من الصالة إلى المهجر","paragraphs":["في الستينيات انتشر السوكوس، وهو فرع أسرع بمزيد من الارتجال على الغيتار، إلى باريس وإلى شتات أفريقي أوسع. ومع ذلك ظلت الرومبا الأصلية أقرب إلى المناسبات العائلية والاحتفالات المحلية.","قد تختلف حرارة الأداء بين حفلات كينشاسا وبرازافيل وبين مشاهد المهجر منذ التسعينيات، كما يتباين إقبال الأجيال الشابة على القديم والجديد، لكن النغمة نفسها تظل مدخلاً للتعرف على المدينة."]},{"heading":"ماذا تعني الرومبا للناس","paragraphs":["ليست الرومبا مجرد ترفيه؛ فهي تحدد كيف يجتمع الناس في الأفراح والأحزان، وكيف يتعلم الشباب الغناء والرقص، وكيف تُروى ذاكرة المدن.","في ديسمبر 2021 أدرجت اليونسكو الرومبا الكونغولية في قائمتها للتراث الثقافي غير المادي، لكن قيمتها اليومية تبقى في الأعراس والليالي العائلية أكثر من أي مكان آخر."]}],"de":[{"heading":"Wurzeln, die den Fluss überqueren","paragraphs":["Die kongolesische Rumba entstand seit den 1930er- und 1940er-Jahren in Kinshasa und Brazzaville, wo kubanischer Son, lokale Rhythmen und Lingala-Texte zusammenkamen. Sie ruht auf ineinandergreifenden Gitarren, einem treibenden Bass und Gesangsharmonien und wurde zur dominierenden Tanzmusik Zentralafrikas.","Der Fluss trennte zwei Städte, aber nicht das gemeinsame Ohr: Stimmen und Saiten wanderten mit den Menschen zwischen den Ufern und formten sich jedes Mal neu am Alltag."]},{"heading":"Lieder, die sagen, was sonst ungesagt bleibt","paragraphs":["Rumba-Lieder sind soziale Chroniken: Sie loben Gönner, kommentieren Liebe und Politik und markieren Hochzeiten wie Begräbnisse. Bei einer Hochzeit in Kinshasa spielt die Band einen alten Rumba-Standard, und drei Generationen singen den Lingala-Refrain aus dem Gedächtnis mit.","So wirkt die Rumba als lebendiges Archiv; die Texte wandern von Mund zu Mund und können Dinge aussprechen, die im Alltagsgespräch schwer fallen."]},{"heading":"Vom Saal in die Diaspora","paragraphs":["In den 1960er-Jahren verbreitete sich Soukous, ein schnellerer Ableger mit mehr Gitarrenimprovisation, nach Paris und in die weitere afrikanische Diaspora. Die ursprüngliche Rumba blieb dennoch näher an Familienfeiern und lokalen Festen.","Die Intensität kann sich zwischen Feiern in Kinshasa und Brazzaville und Diaspora-Szenen seit den 1990er-Jahren unterscheiden, ebenso wie die Neigung junger Generationen zwischen Alt und Neu schwankt; der gemeinsame Klang bleibt ein Zugang zur Stadt."]},{"heading":"Was die Rumba den Menschen bedeutet","paragraphs":["Rumba ist nicht bloß Unterhaltung; sie bestimmt, wie Menschen bei Freude und Trauer zusammenkommen, wie Jugendliche Singen und Tanzen lernen und wie die Erinnerung der Städte weitererzählt wird.","Im Dezember 2021 nahm die UNESCO die kongolesische Rumba in ihre Liste des immateriellen Kulturerbes auf, doch ihr täglicher Wert liegt eher in Hochzeiten und Familienabenden als an jedem anderen Ort."]}],"en":[{"heading":"Roots that cross the river","paragraphs":["Congolese rumba developed in Kinshasa and Brazzaville from the 1930s and 1940s, drawing on Cuban son, local rhythms and Lingala lyrics. Built on interlocking guitars, a driving bass and vocal harmonies, it became the dominant dance music of Central Africa.","The river separated two cities but not a shared ear: voices and strings moved with people between the banks, reshaping themselves each time around daily life."]},{"heading":"Songs that say what is otherwise unsaid","paragraphs":["Rumba songs are social chronicles: they praise patrons, comment on love and politics, and mark weddings and funerals. At a Kinshasa wedding the band plays an old rumba standard and three generations sing the Lingala chorus from memory.","In this way rumba works as a living archive; lyrics travel by mouth and can voice what is hard to say in ordinary conversation."]},{"heading":"From the hall to the diaspora","paragraphs":["In the 1960s soukous, a faster offshoot with more guitar improvisation, spread to Paris and the wider African diaspora. The original rumba nonetheless stayed closer to family occasions and local celebrations.","Intensity can differ between parties in Kinshasa and Brazzaville and diaspora scenes since the 1990s, and younger generations waver between old and new, but the shared sound remains a way into the city."]},{"heading":"What rumba means to people","paragraphs":["Rumba is not merely entertainment; it shapes how people gather in joy and grief, how young people learn to sing and dance, and how the memory of the cities is passed on.","In December 2021 UNESCO added Congolese rumba to its list of intangible cultural heritage, yet its everyday value lies in weddings and family evenings more than anywhere else."]}]},"context":{"countries":["CD","CG"],"region":"Kinshasa and Brazzaville","continent":"africa","languages":["ln","fr"],"period":"contemporary"},"tags":["music-and-dance","Kinshasa and Brazzaville","Congolese rumba","It is"],"sources":[{"organization":"Wikipedia","title":{"ar":"Congolese rumba","de":"Congolese rumba","en":"Congolese rumba"},"url":"https://en.wikipedia.org/wiki/Congolese_rumba","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Soukous","de":"Soukous","en":"Soukous"},"url":"https://en.wikipedia.org/wiki/Soukous","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في عرس بكينشاسا تعزف الفرقة لحناً كلاسيكياً من الرومبا، فيردد ثلاثة أجيال الكورس باللينغالا عن ظهر قلب.","de":"Bei einer Hochzeit in Kinshasa spielt die Band einen alten Rumba-Standard, und drei Generationen singen den Lingala-Refrain aus dem Gedächtnis mit.","en":"At a Kinshasa wedding the band plays an old rumba standard and three generations sing the Lingala chorus from memory."},"misunderstanding":{"ar":"الرومبا الكونغولية والسوكوس متقاربان لكنهما مختلفان، وقد تباعدت مشاهد الكونغو والمهجر منذ التسعينيات، فلا يصح الحديث عن أسلوب واحد ثابت.","de":"Kongolesische Rumba und Soukous sind verwandt, aber verschieden, und die Szenen im Kongo und in der Diaspora haben sich seit den 1990er-Jahren auseinanderentwickelt; von einem festen Stil zu sprechen, wäre irreführend.","en":"Congolese rumba and soukous are related but distinct, and Congolese and diaspora scenes have diverged since the 1990s, so speaking of one fixed style would mislead."},"comparison":{"ar":"كما تحتفظ موسيقى السالSA في الكاريبي بذاكرة الهجرة، تحفظ الرومبا تاريخ المدن الكونغولية في كلماتها وألحانها.","de":"Ähnlich wie der Salsa in der Karibik das Gedächtnis der Migration bewahrt, hält die Rumba die Geschichte der kongolesischen Städte in Texten und Melodien fest.","en":"Much as salsa in the Caribbean keeps the memory of migration, rumba holds the history of the Congolese cities in its lyrics and melodies."}},{"id":"afr-040","version":2,"slug":"taarab-swahili-poetry-sung-with-an-orchestra","contentType":"feature","category":"music-and-dance","title":{"ar":"طرب: شعر سواحيلي بأوركسترا","de":"Taarab: Swahili-Poesie mit Orchester","en":"Taarab: Swahili Poetry with an Orchestra"},"deck":{"ar":"كيف تحولت أغاني الأعراس في زنجبار إلى مرآة للمجتمع والنقد الاجتماعي.","de":"Wie Hochzeitslieder aus Sansibar zum Spiegel der Gesellschaft und zur sozialen Kritik wurden.","en":"How wedding songs in Zanzibar became a mirror of society and a tool for social critique."},"teaser":{"ar":"من سيتي بنت سعد إلى لوحات المفاتيح الحديثة، يظل الطرب فنًا يغني الحياة اليومية ويراقب الناس بأشعارهم.","de":"Von Siti binti Saad bis zu modernen Keyboards: Taarab besingt den Alltag und beobachtet die Menschen durch ihre Poesie.","en":"From Siti binti Saad to modern keyboards, taarab sings everyday life and watches people through their poetry."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور متشابكة وإرث سيتي بنت سعد","paragraphs":["نشأ الطرب في زنجبار والساحل السواحيلي كفن يجمع بين تقاليد البحيرات العظمى الأفريقية ومؤثرات شمال أفريقية وشرق أوسطية وهندية. يعتمد على آلات الأوركسترا وأشعار سواحيلية مغناة. في عام 1928، برزت سيتي بنت سعد كأول امرأة في شرق أفريقيا تسجل تجاريًا، مما منح الطرب انتشارًا واسعًا.","منذ البداية، ارتبط الطرب بالمناسبات الاجتماعية، وخاصة الأعراس والمهرجانات. الأغاني لا تقتصر على الترفيه، بل تحمل مدحًا أو نقدًا لأفراد معينين وتعليقًا على الحياة الاجتماعية. هذا الدور المزدوج جعل الطرب أداة تواصل اجتماعي حيوية."]},{"heading":"الطرب في الأعراس: الاستماع إلى الكلمات","paragraphs":["في حفل زفاف في زنجبار، يؤدي مغني طرب أغنية أُلفت خصيصًا للعروسين، ويستمع الضيوف بانتباه إلى الكلمات لالتقاط المدح أو المزاح. هذا التفاعل المباشر يعكس كيف يعمل الطرب كوسيط اجتماعي، حيث يعبر الناس عن مشاعرهم ومواقفهم من خلال الشعر المغنى.","تختلف أساليب الطرب وتتنوع لهجاتها الإقليمية. الطرب المعاصر في زنجبار يختلف عن التسجيلات القديمة وعن طرب كينيا. كما أدخلت التكنولوجيا الحديثة لوحات المفاتيح وآلات الإيقاع، مما أثرى الصوت لكنه حافظ على جوهر الكلمة."]},{"heading":"تأثير ممتد إلى الأجيال الجديدة","paragraphs":["أثر الطرب في أنواع موسيقية أحدث مثل بونغو فلافا والبوب السواحيلي، حيث استلهم الفنانون الجدد من أسلوبه الشعري واللحني. ورغم التحديث، يبقى الطرب رمزًا للهوية السواحيلية وقناة للتعبير الاجتماعي.","يختلف حضور الطرب حسب المنطقة والجيل: فبعض الشباب يفضلون النسخ المحدثة، بينما يتمسك كبار السن بالأنماط التقليدية. هذا التنوع يثري المشهد الموسيقي ويعكس حيوية الثقافة السواحيلية."]}],"de":[{"heading":"Verwurzelte Tradition und das Erbe der Siti binti Saad","paragraphs":["Taarab entstand in Sansibar und an der Swahili-Küste als Musikgenre, das afrikanische Traditionen der Großen Seen mit nordafrikanischen, nahöstlichen und indischen Einflüssen verbindet. Es nutzt Orchesterinstrumente und gesungene Swahili-Poesie. 1928 trat Siti binti Saad hervor, eine der ersten ostafrikanischen Frauen, die kommerziell aufnahmen und Taarab weit verbreiteten.","Von Anfang an war Taarab eng mit gesellschaftlichen Anlässen verbunden, besonders mit Hochzeiten und Festen. Die Lieder dienen nicht nur der Unterhaltung, sondern enthalten Lob oder Kritik an Einzelpersonen und Kommentare zum sozialen Leben. Diese Doppelrolle macht Taarab zu einem lebendigen Medium der sozialen Kommunikation."]},{"heading":"Taarab bei Hochzeiten: Auf die Worte hören","paragraphs":["Bei einer Hochzeit in Sansibar singt ein Taarab-Sänger ein eigens für das Paar komponiertes Lied, und die Gäste hören aufmerksam auf den Text, um Lob oder Neckerei herauszuhören. Diese direkte Interaktion zeigt, wie Taarab als sozialer Vermittler wirkt, indem Menschen ihre Gefühle und Haltungen durch gesungene Poesie ausdrücken.","Die Stile und regionalen Varianten von Taarab sind vielfältig. Zeitgenössischer Taarab in Sansibar unterscheidet sich von älteren Aufnahmen und von kenianischem Taarab. Moderne Technologie hat Keyboards und Drumcomputer eingeführt, was den Klang bereichert, aber den Kern des Wortes bewahrt."]},{"heading":"Ausstrahlung auf jüngere Generationen","paragraphs":["Taarab beeinflusste neuere Musikrichtungen wie Bongo Flava und Swahili-Pop, deren Künstler von seinem poetischen und melodischen Stil inspiriert sind. Trotz Modernisierung bleibt Taarab ein Symbol der Swahili-Identität und ein Kanal für sozialen Ausdruck.","Die Präsenz von Taarab variiert je nach Region und Generation: Manche Jugendliche bevorzugen modernisierte Versionen, während ältere Menschen an traditionellen Formen festhalten. Diese Vielfalt bereichert die Musikszene und spiegelt die Lebendigkeit der Swahili-Kultur wider."]}],"en":[{"heading":"Interwoven Roots and the Legacy of Siti binti Saad","paragraphs":["Taarab emerged in Zanzibar and the Swahili coast as a genre blending African Great Lakes traditions with North African, Middle Eastern, and Indian influences. It uses orchestral instruments and sung Swahili poetry. In 1928, Siti binti Saad rose to prominence as one of the first East African women to record commercially, giving taarab wide reach.","From the start, taarab was tied to social occasions, especially weddings and festivals. Songs are not just entertainment; they carry praise or criticism of individuals and comment on social life. This dual role makes taarab a vibrant medium of social communication."]},{"heading":"Taarab at Weddings: Listening to the Words","paragraphs":["At a Zanzibar wedding, a taarab singer performs a song composed for the couple, and guests listen closely to the lyrics for praise or teasing. This direct interaction shows how taarab works as a social mediator, where people express feelings and attitudes through sung poetry.","Taarab styles and regional variants are diverse. Contemporary Zanzibar taarab differs from older recordings and from Kenyan taarab. Modern technology has introduced keyboards and drum machines, enriching the sound while preserving the centrality of the word."]},{"heading":"Influence on Younger Generations","paragraphs":["Taarab has influenced newer genres like bongo flava and Swahili pop, with artists drawing on its poetic and melodic style. Despite modernization, taarab remains a symbol of Swahili identity and a channel for social expression.","Taarab's presence varies by region and generation: some youth prefer modernized versions, while older people hold on to traditional forms. This diversity enriches the music scene and reflects the vitality of Swahili culture."]}]},"context":{"countries":["TZ"],"region":"Zanzibar and the Swahili coast","continent":"africa","languages":["sw","ar"],"period":"contemporary"},"tags":["music-and-dance","Zanzibar and the Swahili coast","Taarab is","It blends"],"sources":[{"organization":"Wikipedia","title":{"ar":"Taarab","de":"Taarab","en":"Taarab"},"url":"https://en.wikipedia.org/wiki/Taarab","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Zanzibar","de":"Zanzibar","en":"Zanzibar"},"url":"https://en.wikipedia.org/wiki/Zanzibar","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في حفل زفاف في زنجبار، يؤدي مغني طرب أغنية أُلفت خصيصًا للعروسين، ويستمع الضيوف بانتباه إلى الكلمات لالتقاط المدح أو المزاح.","de":"Bei einer Hochzeit in Sansibar singt ein Taarab-Sänger ein eigens für das Paar komponiertes Lied, und die Gäste hören aufmerksam auf den Text, um Lob oder Neckerei herauszuhören.","en":"At a Zanzibar wedding a taarab singer performs a song composed for the couple, and the guests listen closely to the lyrics for praise or teasing."},"misunderstanding":{"ar":"يعتقد البعض أن الطرب مجرد موسيقى ترفيهية، لكنه في الواقع وسيلة نقد اجتماعي ومدح، وقد يحمل رسائل مبطنة.","de":"Manche halten Taarab für reine Unterhaltungsmusik, doch es ist tatsächlich ein Mittel der sozialen Kritik und des Lobes und kann versteckte Botschaften tragen.","en":"Some assume taarab is purely entertainment, but it is actually a means of social critique and praise, and can carry hidden messages."},"comparison":{"ar":"على عكس الأغاني الشعبية في مناطق أخرى التي قد تقتصر على الاحتفال، يجعل الطرب من الكلمة الشعرية محور التفاعل الاجتماعي.","de":"Anders als Volkslieder in anderen Regionen, die oft nur der Feier dienen, stellt Taarab das poetische Wort in den Mittelpunkt der sozialen Interaktion.","en":"Unlike folk songs in other regions that may only serve celebration, taarab makes the poetic word the center of social interaction."}},{"id":"afr-041","version":2,"slug":"amapiano-log-drums-and-the-township-dance-floor","contentType":"feature","category":"music-and-dance","title":{"ar":"أماپيانو: طبلات السجل وأرض الرقص","de":"Amapiano: Log Drums und Tanzkreis","en":"Amapiano: log drums and the dance floor"},"deck":{"ar":"من ساحات جوهانسبرغ وپريتوريا إلى العالم: كيف صار الأماپيانو لغة شبابية تجمع الناس حول السمّاعة.","de":"Aus den Townships von Johannesburg und Pretoria auf die Weltbühnen: Wie Amapiano junge Leute um einen Lautsprecher versammelt.","en":"From the townships of Johannesburg and Pretoria to the world: how amapiano gathers young people around a single speaker."},"teaser":{"ar":"نوع موسيقي جنوب أفريقي وُلد في البلدات، يجمع الكوايتو والديب هاوس والگووم، ويُرقص في دوائر حتى آخر النهار.","de":"Ein südafrikanisches Genre aus den Townships, das Kwaito, Deep House und Gqom verbindet und in Kreisen getanzt wird, oft den ganzen Tag.","en":"A South African genre born in the townships, blending kwaito, deep house and gqom, danced in circles and often all day long."},"readingMinutes":1,"sections":{"ar":[{"heading":"من البلدات إلى السمّاعة","paragraphs":["ظهر الأماپيانو في بلدات جوهانسبرغ وپريتوريا، وانتشر بقوة في أوائل العشرينيات. يجمعه الناس بسرعة لأنه يخلط الكوايتو والديب هاوس والگووم والجاز والسول وأجواء اللاونج في قالب واحد.","ما يميّزه صوتياً خطوط باس الطبلات الخشبية المعروفة بـ«لوگ درامز»، مع سينثات هوائية خفيفة تترك مساحة للرقص. الاسم نفسه يأتي من كلمة إيسيزولو التي تعني البيانو، وهو ما يشرح حضوره القوي في الأذن الشعبية.","ينتشر الأماپيانو عبر واتساپ ويوتيوب وتحديات الرقص، فتصبح الأغنية مشروعاً جماعياً يشارك فيه المستمعون قبل أن تصل إلى الإذاعة."]},{"heading":"دوائر الرقص والمنافسة","paragraphs":["ثقافة الرقص في الأماپيانو اجتماعية وتنافسية في الوقت نفسه. الحفلات غالباً أحداث تمتد طوال اليوم، والرقص يدور في حلقات يأخذ فيها كل شخص دوره في المنتصف.","هذه الدائرة ليست مجرد ترتيب مكاني، بل عُرف اجتماعي: من يقف في الوسط يُشاهد، ومن حوله يشجّع ويتعلّم. لهذا يصف كثيرون الأماپيانو بأنه مدرسة مفتوحة للحركة.","تختلف هذه العادة من حيّ إلى حيّ ومن جيل إلى جيل؛ فبعض الشباب يفضّلون النسخ الأسرع، بينما يحافظ الكبار على إيقاعات أهدأ وأكثر تكراراً."]},{"heading":"موسيقى تعبر الحدود","paragraphs":["بحلول العشرينيات صار الأماپيانو من أكبر صادرات أفريقيا الموسيقية، مع تعاونات عبر القارة وفي أوروبا. لكن نجاحه الدولي أحياناً يطمس أصوله الجنوب أفريقية.","المشهد سريع الحركة وفيه أنماط فرعية كثيرة، لذا من الصعب حصره في تعريف واحد. ومع ذلك يبقى الناس في البلدات هم من يختبرون الأصوات أولاً ويقررون ما ينجح.","في نهاية اليوم، يبقى الأماپيانو طريقة للالتقاء: سمّاعة واحدة، ساحة صغيرة، ودائرة تكبر مع كل أغنية."]}],"de":[{"heading":"Vom Hof zum Lautsprecher","paragraphs":["Amapiano entstand in den Townships von Johannesburg und Pretoria und wurde Anfang der 2020er Jahre populär. Menschen nehmen es schnell auf, weil es Kwaito, Deep House, Gqom, Jazz, Soul und Lounge-Einflüsse in einem Klang verbindet.","Typisch sind die Basslinien der Log Drums und luftige Synths, die viel Raum zum Tanzen lassen. Der Name stammt vom isiZulu-Wort für Klaviere, was die starke Präsenz des Klangs im Alltag erklärt.","Verbreitet wird die Musik über WhatsApp, YouTube und Tanz-Challenges. So wird ein Song zum Gemeinschaftsprojekt, bevor er überhaupt im Radio ankommt."]},{"heading":"Kreise und Wettbewerb","paragraphs":["Die Tanzkultur ist sozial und zugleich wettbewerbsorientiert. Amapiano-Partys sind oft ganztägige Ereignisse, und getanzt wird in Kreisen, in denen jede Person einmal in die Mitte tritt.","Der Kreis ist nicht nur eine räumliche Ordnung, sondern eine soziale Regel: Wer in der Mitte steht, wird gesehen; die anderen feuern an und lernen mit. Viele beschreiben Amapiano deshalb als offene Schule der Bewegung.","Diese Praxis unterscheidet sich von Viertel zu Viertel und zwischen Generationen; manche Jüngeren mögen schnellere Varianten, während Ältere ruhigere, repetitivere Rhythmen bevorzugen."]},{"heading":"Musik über Grenzen hinweg","paragraphs":["In den 2020er Jahren wurde Amapiano zu einem der größten musikalischen Exporte Afrikas, mit Kooperationen auf dem Kontinent und in Europa. Der internationale Erfolg verwischt jedoch manchmal die südafrikanischen Ursprünge.","Die Szene ist schnelllebig und hat viele Substile, lässt sich also schwer auf eine Definition festlegen. Trotzdem sind es die Menschen in den Townships, die neue Sounds zuerst hören und entscheiden, was funktioniert.","Am Ende bleibt Amapiano eine Art, zusammenzukommen: ein Lautsprecher, ein kleiner Hof und ein Kreis, der mit jedem Lied wächst."]}],"en":[{"heading":"From the yard to the speaker","paragraphs":["Amapiano emerged from Johannesburg and Pretoria townships and became popular in the early 2020s. People pick it up quickly because it blends kwaito, deep house, gqom, jazz, soul and lounge influences into one sound.","Its signature is the log-drum bass line, paired with airy synths that leave room for movement. The name comes from the isiZulu word for pianos, which helps explain how strongly the sound sits in everyday listening.","The music spreads through WhatsApp, YouTube and dance challenges. A track becomes a shared project among listeners long before it reaches radio."]},{"heading":"Circles and friendly competition","paragraphs":["Amapiano dance culture is social and competitive at once. Parties are often all-day events, and dancing happens in circles where each person takes a turn in the middle.","The circle is not just a layout but a social rule: whoever stands in the centre is watched, while those around cheer and learn. That is why many describe amapiano as an open school of movement.","The practice varies from neighbourhood to neighbourhood and across generations; some younger dancers prefer faster variants, while older ones keep to slower, more repetitive grooves."]},{"heading":"Music that crosses borders","paragraphs":["By the 2020s amapiano had become one of Africa's biggest musical exports, with collaborations across the continent and in Europe. International success sometimes blurs its South African origins.","The scene moves fast and holds many sub-styles, so it resists a single definition. Still, it is people in the townships who hear new sounds first and decide what works.","In the end, amapiano remains a way of coming together: one speaker, a small yard and a circle that grows with every song."]}]},"context":{"countries":["ZA"],"region":"Johannesburg and Pretoria townships","continent":"africa","languages":["zu","en","af"],"period":"contemporary"},"tags":["music-and-dance","Johannesburg and Pretoria townships"],"sources":[{"organization":"Wikipedia","title":{"ar":"Amapiano","de":"Amapiano","en":"Amapiano"},"url":"https://en.wikipedia.org/wiki/Amapiano","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Gqom","de":"Gqom","en":"Gqom"},"url":"https://en.wikipedia.org/wiki/Gqom","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مجموعة أصدقاء في سويتو يفرغون مساحة في الفناء، يشغّلون الأماپيانو من سمّاعة، ويتبادلون الرقص في وسط الدائرة.","de":"Eine Gruppe Freundinnen und Freunde in Soweto räumt einen Hof frei, spielt Amapiano über einen Lautsprecher und tanzt abwechselnd in der Mitte des Kreises.","en":"A group of friends in Soweto clear a space in a yard, play amapiano from a speaker, and take turns dancing in the middle of the circle."},"misunderstanding":{"ar":"يُفترض أحياناً أن الأماپيانو مجرد نمط إلكتروني عالمي بلا جذور محلية، لكنه في الأصل تجربة بلدات جنوب أفريقية لها قواعد رقص واجتماع خاصة.","de":"Manchmal wird angenommen, Amapiano sei nur ein globaler elektronischer Stil ohne lokale Wurzeln, doch es ist ursprünglich eine Township-Erfahrung mit eigenen Tanz- und Sozialregeln.","en":"Amapiano is sometimes assumed to be a rootless global electronic style, but it began as a township experience with its own dance and social rules."},"comparison":{"ar":"يشبه الأماپيانو في دوره الاجتماعي أنواعاً رقصة أخرى تجمع الأحياء حول صوت واحد، لكنه يتميّز بخطوط باس الطبلات الخشبية والدوائر التنافسية الطويلة.","de":"In seiner sozialen Rolle ähnelt Amapiano anderen Tänzen, die Nachbarschaften um einen Klang versammeln, doch die Log-Drum-Basslinien und die langen, wettbewerbsorientierten Kreise machen es besonders.","en":"In its social role amapiano resembles other dances that gather neighbourhoods around one sound, yet its log-drum bass lines and long, competitive circles set it apart."}},{"id":"afr-042","version":2,"slug":"kizomba-slow-dance-from-angola-s-parties","contentType":"scene","category":"music-and-dance","title":{"ar":"كيزومبا: رقصة بطيئة من حفلات أنغولا","de":"Kizomba: der langsame Tanz von Angolas Festen","en":"Kizomba: slow dance from Angola's parties"},"deck":{"ar":"رقصة شريكة قريبة وُلدت في احتفالات العائلة والأحياء في لواندا قبل أن تصبح مشهداً عالمياً.","de":"Ein Paartanz aus den Familien- und Nachbarschaftsfeiern von Luanda, der zu einer weltweiten Szene wurde.","en":"A close partner dance born in family and neighbourhood celebrations in Luanda before becoming a worldwide scene."},"teaser":{"ar":"ما الذي يربط رقصة بطيئة في لواندا بمسارح الرقص في لشبونة وباريس؟ حكاية كلمة تعني «حفلة».","de":"Was verbindet einen langsamen Tanz in Luanda mit Tanzsälen in Lissabon und Paris? Die Geschichte eines Wortes, das „Party“ bedeutet.","en":"What links a slow dance in Luanda to dance halls in Lisbon and Paris? The story of a word that means “party”."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الحفلة إلى النادي","paragraphs":["ظهرت الكيزومبا رقصةً وموسيقى اجتماعية في أنغولا في أواخر السبعينيات وأوائل الثمانينيات. الكلمة تعني «حفلة» في لغة كيمبوندو، وقد تطوّرت الرقصة في احتفالات العائلة والحي قبل أن تنتقل إلى النوادي.","تمزج موسيقاها السيمبا الأنغولية بالزوك وتأثيرات كاريبية أخرى، والرقص قريب وبطيء ويقوم على الشريكين."]},{"heading":"الهجرة والانتشار","paragraphs":["انتشرت الكيزومبا إلى البرتغال وفرنسا والرأس الأخضر والبرازيل عبر هجرة الأنغوليين وسكان الرأس الأخضر، فصارت مشهداً عالمياً للرقص الاجتماعي.","في حفلة عائلية في لواندا، يرقص الأزواج الأكبر سناً الكيزومبا على موسيقى حية بينما يصوّر الأقارب الأصغر خطواتهم ويقلّدونها. ويختلف الأسلوب بين المناطق، وقد غيّر مشهد الرقص الدولي الطابع الأصلي بدرجة ملحوظة."]}],"de":[{"heading":"Vom Fest in den Club","paragraphs":["Kizomba entstand Ende der 1970er- und Anfang der 1980er-Jahre in Angola als Gesellschaftstanz und Musikgenre. Das Wort bedeutet in Kimbundu „Party“, und der Tanz entwickelte sich zunächst bei Familien- und Nachbarschaftsfeiern, bevor er in Clubs gelangte.","Die Musik verbindet angolanischen Semba mit Zouk und anderen karibischen Einflüssen; getanzt wird eng, langsam und paarweise."]},{"heading":"Migration und Verbreitung","paragraphs":["Über angolanische und kapverdische Migration gelangte Kizomba nach Portugal, Frankreich, Kap Verde und Brasilien und wurde zu einer globalen Social-Dance-Szene.","Bei einer Familienfeier in Luanda tanzen ältere Paare Kizomba zu Live-Musik, während jüngere Verwandte die Schritte filmen und nachahmen. Der Stil unterscheidet sich je nach Region, und die internationale Tanzszene hat ihn deutlich verändert."]}],"en":[{"heading":"From party to club","paragraphs":["Kizomba emerged in Angola in the late 1970s and early 1980s as a social dance and music genre. The word means “party” in Kimbundu, and the dance developed at family and neighbourhood celebrations before moving into clubs.","Its music blends Angolan semba with zouk and other Caribbean influences; the dance is close, slow and partner-based."]},{"heading":"Migration and spread","paragraphs":["Through Angolan and Cape Verdean migration, kizomba reached Portugal, France, Cape Verde and Brazil and became a global social-dance scene.","At a Luanda family party, older couples dance kizomba to live music while younger relatives film the steps and copy them. The style differs from region to region, and the international dance scene has changed it considerably."]}]},"context":{"countries":["AO"],"region":"Luanda, Angola","continent":"africa","languages":["pt"],"period":"contemporary"},"tags":["music-and-dance","Luanda, Angola","Kizomba is","The word"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kizomba","de":"Kizomba","en":"Kizomba"},"url":"https://en.wikipedia.org/wiki/Kizomba","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Semba","de":"Semba","en":"Semba"},"url":"https://en.wikipedia.org/wiki/Semba","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في حفلة عائلية في لواندا، يرقص الأزواج الأكبر سناً الكيزومبا على موسيقى حية بينما يصوّر الأقارب الأصغر خطواتهم ويقلّدونها.","de":"Bei einer Familienfeier in Luanda tanzen ältere Paare Kizomba zu Live-Musik, während jüngere Verwandte die Schritte filmen und nachahmen.","en":"At a Luanda family party, older couples dance kizomba to live music while younger relatives film the steps and copy them."},"misunderstanding":{"ar":"كثيراً ما تُخلط الكيزومبا بالسيمبا والزوك؛ فالشكل الأنغولي له تنويعات إقليمية، وقد غيّر مشهد الرقص العالمي الأسلوب كثيراً.","de":"Kizomba, Semba und Zouk werden oft verwechselt; die angolanische Form kennt regionale Varianten, und die internationale Tanzszene hat den Stil erheblich verändert.","en":"Kizomba, semba and zouk are often confused; the Angolan form has regional variants, and the international dance scene has changed the style considerably."},"comparison":{"ar":"كما تُقرأ رقصات شريكة أخرى خارج سياقها العائلي، تعرّضت الكيزومبا لتسويق جنساني في الخارج بينما يشدّد ممارسوها الأنغوليون على أصولها العائلية والمجتمعية.","de":"Wie andere Paartänze außerhalb ihres familiären Rahmens gelesen werden, wurde Kizomba im Ausland sexualisiert vermarktet, während angolanische Praktizierende ihre familiären und gemeinschaftlichen Wurzeln betonen.","en":"Like other partner dances read outside their family setting, kizomba has been sexualised in marketing abroad, while Angolan practitioners emphasise its family and community origins."}},{"id":"afr-043","version":2,"slug":"laamb-wrestling-as-village-reputation-and-national-sport","contentType":"feature","category":"games-and-leisure","title":{"ar":"المصارعة السنغالية: شرف القرية ورياضة وطنية","de":"Laamb: Ringen als Dorfehre und Nationalsport","en":"Laamb: wrestling as village reputation and national sport"},"deck":{"ar":"لعبة مصارعة شعبية تحوّلت إلى مسرح جماهيري حيث يختلط الغناء والرهان والانتماء القروي.","de":"Ein Ringkampf, der zur Massenbühne wurde, auf der Gesang, Wetten und Dorfzugehörigkeit zusammenkommen.","en":"A folk wrestling tradition turned mass arena where song, betting and village belonging meet."},"teaser":{"ar":"في السنغال وغامبيا، لا تُقاس المصارعة بالنقاط بل بكرامة القرية، وبضربة واحدة قد تنتهي المباراة.","de":"In Senegal und Gambia misst man Ringen nicht in Punkten, sondern in Dorfwürde – ein einziger Wurf kann alles entscheiden.","en":"In Senegal and The Gambia, wrestling is measured not in points but in village dignity — one throw can settle everything."},"readingMinutes":1,"sections":{"ar":[{"heading":"من القرية إلى الحلبة الكبرى","paragraphs":["تُعرف المصارعة السنغالية باسم «لامب»، وهي تقليد شعبي أدّته شعوب السيرير، وصارت اليوم رياضة وطنية في السنغال وغامبيا.","تتميّز بأنها من قلائل تقاليد المصارعة في غرب أفريقيا التي تسمح بالضربات باليد، ما يمنح النزال إيقاعاً حادّاً ومتوتراً.","تنتهي كثير من النزالات في ثوانٍ، لكن الإعداد لها يستغرق أشهراً من التدريب في الإسطبلات.","يتباين الاهتمام بالرياضة بين المناطق والأجيال؛ فالشباب في المدن يتابعون الأبطال عبر الشاشات، بينما تبقى القرى أوثق صلةً بطقوس الحلبة.","لكل إسطبل اسم وهوية، ولكل قرية أو حيّ سمعة يدافع عنها مصارعوه أمام الجمهور."]},{"heading":"الطبول والمدّاحون والجمهور","paragraphs":["المباراة حدث كبير: طبول تُقرع، ومدّاحون ينشدون أسماء المصارعين، وجمهور يهتف ويراهن على النتيجة.","المدّاح ليس مجرد منشّط، بل حامل لذاكرة المكان، يذكّر الحاضرين بتاريخ الإسطبل وأمجاده.","وتتحوّل الحلبة إلى ساحة للكلام الجماعي، حيث تُقال الشعارات وتُختبر السمعة أمام الجميع.","ومع دخول الرعاية والتلفزيون، تغيّرت اقتصاديات اللعبة، وصار الأبطال نجومًا تتقاضى مبالغ كبيرة."]},{"heading":"بين الشرف والتجارة","paragraphs":["ما زال الانتماء القروي والحضري حاضراً في كل نزال، حتى حين يُبثّ على الشاشات.","لكن النجاح التجاري غيّر الشكل التقليدي للقرية، فأصبحت المباريات تُنظَّم في قاعات كبيرة وتُدار بعقود ورعاية.","يبقى السؤال قائماً: هل تحافظ اللعبة على معناها المحلي حين تصبح صناعة ترفيه؟"]}],"de":[{"heading":"Vom Dorf zur großen Arena","paragraphs":["Der senegalesische Ringkampf heißt Laamb. Er ist eine Volkstradition der Serer und heute Nationalsport in Senegal und Gambia.","Er gehört zu den wenigen westafrikanischen Ringtraditionen, die Handschläge erlauben, was jedem Kampf einen scharfen, angespannten Rhythmus gibt.","Viele Kämpfe enden in Sekunden, doch die Vorbereitung dauert Monate des Trainings in Ställen.","Die Begeisterung variiert regional und generationell: Junge in den Städten verfolgen die Champions auf Bildschirmen, während Dörfer den Riten der Arena näher bleiben.","Jeder Stall hat einen Namen und eine Identität, jedes Dorf und Viertel einen Ruf, den seine Ringer vor Publikum verteidigen."]},{"heading":"Trommeln, Griots und Publikum","paragraphs":["Ein Kampf ist ein Großereignis: Trommeln erklingen, Griots preisen die Ringer, das Publikum jubelt und wettet auf den Ausgang.","Der Griot ist nicht nur Anheizer, sondern Träger der Erinnerung des Ortes; er ruft die Geschichte des Stalls und seine Triumphe wach.","Die Arena wird so zum Raum kollektiver Rede, in der Parolen fallen und der Ruf vor allen geprüft wird.","Mit Sponsoring und Fernsehen hat sich die Ökonomie des Sports verändert; Spitzenringer verdienen beträchtliche Summen."]},{"heading":"Zwischen Ehre und Geschäft","paragraphs":["Die Zugehörigkeit zu Dorf und Stadtviertel bleibt in jedem Kampf spürbar, auch wenn er im Fernsehen läuft.","Der kommerzielle Erfolg hat jedoch das traditionelle Dorfformat verändert: Kämpfe finden in großen Hallen statt und werden mit Verträgen und Sponsoren organisiert.","So bleibt die Frage: Bewahrt der Sport seine lokale Bedeutung, wenn er zur Unterhaltungsindustrie wird?"]}],"en":[{"heading":"From village ground to the big arena","paragraphs":["Senegalese wrestling, known as laamb, is a folk tradition performed by the Serer people and now a national sport in Senegal and The Gambia.","It is one of the few West African wrestling traditions that allows hand strikes, giving each bout a sharp, tense rhythm.","Many matches end in seconds, yet preparation takes months of training in stables.","Interest varies by region and generation: young people in cities follow champions on screens, while villages stay closer to the rituals of the arena.","Each stable has a name and an identity, and every village or neighbourhood has a reputation its wrestlers defend before a crowd."]},{"heading":"Drums, griots and the crowd","paragraphs":["A match is a large event: drums sound, griots praise the wrestlers, and the crowd shouts and bets on the outcome.","The griot is not merely a hype man but a bearer of local memory, recalling the stable's history and triumphs.","The arena becomes a space of collective speech, where slogans are raised and reputation is tested before everyone.","With sponsorship and television, the sport's economics have grown, and top wrestlers earn significant purses."]},{"heading":"Between honour and business","paragraphs":["Village and neighbourhood belonging remains present in every bout, even when it is broadcast on screen.","Yet commercial success has changed the traditional village format: matches are staged in large halls and managed through contracts and sponsors.","So the question remains: does the sport keep its local meaning when it becomes an entertainment industry?"]}]},"context":{"countries":["SN"],"region":"Senegambia","community":"Serer and Wolof wrestlers","continent":"africa","languages":["wo","fr"],"period":"contemporary"},"tags":["games-and-leisure","Senegambia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Senegalese wrestling","de":"Senegalese wrestling","en":"Senegalese wrestling"},"url":"https://en.wikipedia.org/wiki/Senegalese_wrestling","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Wolof people","de":"Wolof people","en":"Wolof people"},"url":"https://en.wikipedia.org/wiki/Wolof_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في قاعة بالعاصمة داكار، ينشد المدّاحون مديح مصارع، فيهتف الجمهور بشعاراته، ثم تنتهي المباراة برمية واحدة تحسم تفوّق القرية.","de":"In einer Arena in Dakar besingen Griots einen Ringer, das Publikum ruft Parolen, und ein einziger Wurf beendet den Kampf und entscheidet den Dorfruhm.","en":"In a Dakar arena, griots sing a wrestler's praises, the crowd shouts slogans, and a single throw ends the match and settles village bragging rights."},"misunderstanding":{"ar":"يظنّ كثيرون أن المصارعة مجرد عنف بدني، لكنها في الواقع نظام علاقات اجتماعية تُختبر فيه السمعة والانتماء.","de":"Viele halten Ringen für bloße Körpergewalt, doch es ist ein Geflecht sozialer Beziehungen, in dem Ruf und Zugehörigkeit geprüft werden.","en":"Many assume wrestling is mere physical violence, but it is a web of social relations in which reputation and belonging are tested."},"comparison":{"ar":"تشبه المصارعة السنغالية المصارعة التقليدية في غرب أفريقيا، لكنها تسمح بالضربات باليد وتتمتع باقتصاد إعلامي أكبر.","de":"Laamb ähnelt anderen westafrikanischen Ringtraditionen, erlaubt aber Handschläge und verfügt über eine größere Medienwirtschaft.","en":"Laamb resembles other West African wrestling styles, but it allows hand strikes and carries a larger media economy."}},{"id":"afr-044","version":2,"slug":"oware-the-board-game-that-counts-and-captures","contentType":"feature","category":"games-and-leisure","title":{"ar":"أواريه: لعبة العد والحصاد","de":"Oware: Zählen und Ernten","en":"Oware: The Counting and Capturing Game"},"deck":{"ar":"لعبة استراتيجية من عائلة مانكالا تجمع بين الحساب والصبر والملاحظة، يلعبها الصغار والكبار في غانا ونيجيريا.","de":"Ein Strategiespiel aus der Mancala-Familie, das Rechnen, Geduld und Beobachtung verbindet und in Ghana und Nigeria von Jung und Alt gespielt wird.","en":"A mancala-family strategy game that blends arithmetic, patience, and observation, played by young and old in Ghana and Nigeria."},"teaser":{"ar":"في أسواق كوماسي، تتجمع الأنظار حول لوح أواريه بينما يحسب اللاعبون خطواتهم مسبقًا.","de":"Auf dem Markt von Kumasi versammeln sich Schaulustige um ein Oware-Brett, während die Spieler mehrere Züge im Voraus berechnen.","en":"In Kumasi's market, a crowd gathers around an oware board while skilled players calculate several moves ahead."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور أشanti وتقاليد متوارثة","paragraphs":["يُعتقد على نطاق واسع أن لعبة أواريه، من عائلة مانكالا، ذات أصل أشanti. يلعبها شخصان، يوزعان البذور في حفر اللوح ويحاولان حصاد بذور الخصم عبر الهبوط في مواضع معينة. تتنوع القواعد بين المنازل والمناطق، فما يصلح في قرية قد يختلف في أخرى.","تنتقل اللعبة عبر الأجيال، حيث يتعلم الأطفال من الكبار ليس فقط الحركات بل أيضًا الصبر والتفكير المسبق. في بعض العائلات، يعد الأب أو الجد المعلم الأول، وفي أخرى يتعلم الطفل من أقرانه في الشارع. هذا التنوع في طرق التعلم يعكس مرونة اللعبة نفسها.","تختلف شعبية اللعبة بين الأجيال؛ فبينما يقبل الشباب على الألعاب الرقمية، لا يزال الكثيرون يجدون في أواريه متعة التحدي المباشر والتواصل الاجتماعي. في المناسبات العائلية، تعود اللعبة لتأخذ مكانها كجسر بين الأجيال."]},{"heading":"من الحفر في الأرض إلى الألواح المنقوشة","paragraphs":["تتراوح ألواح أواريه بين قطع خشبية منحوتة بعناية وحفر تُحفر في الأرض. هذا التنوع يعكس تكيف اللعبة مع بيئات مختلفة، من الأسواق المزدحمة إلى أفنية المنازل. في المدارس، تُستخدم لتعليم العد والاستراتيجية، حيث يجد المعلمون فيها أداة محببة للتلاميذ."]},{"heading":"لعبة تتجاوز الحدود","paragraphs":["تظهر أواريه في الحياة الثقافية الغانية والكاريبية، حيث تُلعب في المنازل والأسواق والمدارس. يجتمع اللاعبون المهرة حول اللوح، يحسبون عدة نقلات مسبقًا بينما يراقبهم الجمهور. في مثل هذه اللحظات، تتحول اللعبة إلى مسرح صغير للتفكير والتشجيع.","تختلف قواعد أواريه بين المناطق والأسر، كما أن ألعاب مانكالا تُلعب في أنحاء أفريقيا وآسيا، لذا فإن الأصل الأشanti هو تقليد شفهي أكثر منه حقيقة مستقرة. هذا الغموض يضيف إلى جاذبية اللعبة، إذ يصبح كل لاعب جزءًا من حكاية مستمرة."]}],"de":[{"heading":"Ashanti-Ursprung und mündliche Tradition","paragraphs":["Oware, ein Spiel aus der Mancala-Familie, wird weithin als ashantischen Ursprungs angesehen. Zwei Spieler verteilen Samen auf die Mulden des Brettes und versuchen, die Samen des Gegners zu ernten, indem sie auf bestimmten Positionen landen. Die Regeln variieren von Region zu Region und von Haushalt zu Haushalt.","Das Spiel wird über Generationen weitergegeben, wobei Kinder von Erwachsenen nicht nur die Züge lernen, sondern auch Geduld und Vorausdenken. In manchen Familien ist der Vater oder Großvater der erste Lehrer, in anderen lernt das Kind von Gleichaltrigen auf der Straße. Diese Vielfalt der Lernwege spiegelt die Flexibilität des Spiels wider.","Die Beliebtheit variiert zwischen den Generationen: Während Jugendliche zu digitalen Spielen neigen, schätzen viele weiterhin die direkte Herausforderung und das soziale Miteinander von Oware. Bei Familienfeiern dient das Spiel oft als Brücke zwischen den Generationen."]},{"heading":"Von Erdlöchern zu geschnitzten Brettern","paragraphs":["Oware-Bretter reichen von sorgfältig geschnitzten Holzstücken bis zu Löchern im Boden. Diese Vielfalt zeigt die Anpassungsfähigkeit des Spiels an verschiedene Umgebungen, vom belebten Markt bis zum Innenhof. In Schulen wird es zum Lehren von Zählen und Strategie genutzt, da Lehrer es als beliebtes Werkzeug bei Schülern schätzen."]},{"heading":"Ein Spiel jenseits der Grenzen","paragraphs":["Oware erscheint im kulturellen Leben Ghanas und der Karibik, wo es in Häusern, Märkten und Schulen gespielt wird. Geschickte Spieler versammeln sich um das Brett, berechnen mehrere Züge im Voraus, während eine Menge zuschaut. In solchen Momenten wird das Spiel zu einer kleinen Bühne des Denkens und der Ermutigung.","Die Regeln von Oware unterscheiden sich zwischen Regionen und Familien, und Mancala-Spiele werden in ganz Afrika und Asien gespielt. Der ashantische Ursprung ist daher eine Tradition rather than eine gesicherte Tatsache. Diese Unschärfe erhöht den Reiz des Spiels, da jeder Spieler Teil einer fortlaufenden Geschichte wird."]}],"en":[{"heading":"Ashanti Roots and Living Tradition","paragraphs":["Oware, a mancala-family game, is widely believed to be of Ashanti origin. Two players sow seeds around the board's pits and try to capture the opponent's seeds by landing in particular positions. Rules vary from region to region and even between households, so a move that works in one village may differ in another.","The game passes down through generations, with children learning from elders not just moves but patience and forward thinking. In some families, a father or grandfather is the first teacher; in others, a child learns from peers in the street. This variety in learning reflects the game's flexibility.","Popularity shifts across generations: while youth gravitate to digital games, many still find oware's direct challenge and social contact appealing. At family gatherings, the game often serves as a bridge between generations."]},{"heading":"From Dug Holes to Carved Boards","paragraphs":["Oware boards range from carefully carved wooden pieces to holes dug in the ground. This diversity shows the game's adaptability to different settings, from crowded markets to home courtyards. In schools, it is used to teach counting and strategy, as teachers find it a popular tool with pupils."]},{"heading":"A Game Beyond Borders","paragraphs":["Oware appears in Ghanaian and Caribbean cultural life, played in homes, markets, and schools. Skilled players gather around the board, calculating several moves ahead while a crowd watches. In such moments, the game becomes a small stage for thinking and encouragement.","Oware rules vary between regions and households, and mancala games are played across Africa and Asia, so the Ashanti origin is a tradition rather than a settled fact. This ambiguity adds to the game's appeal, as each player becomes part of an ongoing story."]}]},"context":{"countries":["GH","NG"],"region":"West Africa","community":"Akan","continent":"africa","languages":["ak","tw","yo","en"],"period":"contemporary"},"tags":["games-and-leisure","West Africa"],"sources":[{"organization":"Wikipedia","title":{"ar":"Oware","de":"Oware","en":"Oware"},"url":"https://en.wikipedia.org/wiki/Oware","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Mancala","de":"Mancala","en":"Mancala"},"url":"https://en.wikipedia.org/wiki/Mancala","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"رجلان في سوق كوماسي يلعبان أواريه على لوح منحوت بينما يراقبهما ثالث ويشير إلى حصاد فائت.","de":"Zwei Männer auf dem Markt von Kumasi spielen Oware auf einem geschnitzten Brett, während ein Dritter zusieht und auf eine verpasste Ernte hinweist.","en":"Two men in a Kumasi market play oware on a carved board while a third watches and points out a missed capture."},"misunderstanding":{"ar":"يعتقد البعض أن أواريه مجرد لعبة حظ، لكنها في الواقع تعتمد على الحساب والتخطيط المسبق.","de":"Manche halten Oware für ein reines Glücksspiel, doch es beruht auf Berechnung und Vorausplanung.","en":"Some assume oware is a game of chance, but it actually relies on calculation and forward planning."},"comparison":{"ar":"مثل الشطرنج في تعقيده، لكن أواريه أكثر بساطة في أدواته وأقرب إلى الحياة اليومية.","de":"In seiner Komplexität dem Schach ähnlich, aber mit einfacheren Mitteln und näher am Alltag.","en":"Similar in complexity to chess, but simpler in its tools and closer to everyday life."}},{"id":"afr-045","version":2,"slug":"nollywood-video-storytelling-as-a-national-argument","contentType":"feature","category":"storytelling","title":{"ar":"نوليوود: سرد الفيديو كجدل وطني","de":"Nollywood: Videogeschichten als nationale Debatte","en":"Nollywood: Video storytelling as a national argument"},"deck":{"ar":"كيف تحولت أفلام الفيديو النيجيرية إلى منصة للنقاش العام حول الأخلاق والثروة والسلطة.","de":"Wie nigerianische Videofilme zu einem öffentlichen Forum für Moral, Reichtum und Macht wurden.","en":"How Nigerian video films became a public forum for debating morality, wealth and power."},"teaser":{"ar":"من كاميرات الفيديو الرخيصة إلى المنصات الرقمية، أصبحت نوليوود صوتًا يوميًا يعيد صياغة القضايا الاجتماعية في نيجيريا.","de":"Von billigen Camcordern bis zu Streamingdiensten: Nollywood ist eine tägliche Stimme, die soziale Fragen in Nigeria verhandelt.","en":"From cheap camcorders to streaming platforms, Nollywood is a daily voice shaping social debates across Nigeria."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الفيديو إلى الشاشة الكبيرة","paragraphs":["انطلقت نوليوود من طفرة الفيديو في التسعينيات، عندما جعلت كاميرات التصوير الرخيصة وتوزيع الأفلام مباشرة إلى الفيديو السينما في متناول الجميع. سرعان ما أصبحت هذه الأفلام جزءًا من الحياة اليومية، تُباع في الأسواق وتُشاهد في المنازل. ومع الوقت، تحولت إلى منصة للنقاش العام حول الثروة والفساد والعلاقات الأسرية.","في مدينة إينوغو، تجتمع عائلة مساءً لمشاهدة فيلم نوليوود جديد، ثم تتناقش حول ما إذا كانت النهاية أخلاقية أم مجرد حل سهل. هذا النقاش العائلي يعكس كيف تطرح الأفلام أسئلة حول القيم والمسؤولية. وتختلف هذه التجربة بين الأجيال، فالشباب قد يتابعون الأعمال عبر المنصات الرقمية بينما يظل الآباء أوفياء لسوق الفيديو التقليدي."]},{"heading":"نقاشات الأخلاق والسلطة","paragraphs":["تتناول الأفلام والمسلسلات النيجيرية قصصًا أخلاقية وعائلية ودينية وسياسية، وتلعب دورًا محوريًا في الجدل العام حول الثروة والفساد والمساواة بين الجنسين. فهي لا تعكس الواقع فحسب، بل تساهم في تشكيله عبر طرح نماذج للسلوك وتقييمها.","منذ العقد الثاني من القرن الحادي والعشرين، غيّرت خدمات البث ودور السينما طرق التوزيع، لكن سوق الفيديو القديم لا يزال قائمًا. هذا التنوع في التوزيع يعني أن الجمهور يتفاعل مع الأفلام بطرق مختلفة، مما يوسع دائرة النقاش العام."]},{"heading":"تعدد المراكز والأنواع","paragraphs":["نوليوود ليست صناعة واحدة، بل تسمية فضفاضة تشمل صناعات وأنواعًا متعددة. ففي كانو، توجد كانيوود الناطقة بالهوسا، ولها أسواقها وجمهورها الخاص. هذا التعدد يعكس التنوع الثقافي واللغوي في نيجيريا، ويذكرنا بأن المصطلح نفسه ظل محل جدل منذ صياغته في أوائل الألفية.","تختلف نوليوود عن صناعات السينما الأخرى في اعتمادها على التوزيع غير الرسمي في الأسواق، مما يجعلها قريبة من الناس. لكن هذا لا يعني أنها موحدة؛ فالتجارب تتفاوت حسب المنطقة واللغة والجيل."]}],"de":[{"heading":"Vom Video auf die Leinwand","paragraphs":["Nollywood entstand in den 1990er Jahren aus einem Videoboom: günstige Camcorder, Direktvertrieb auf Video und Marktvertrieb machten Filme in ganz Afrika erschwinglich. Schnell wurden diese Filme Teil des Alltags, wurden auf Märkten verkauft und zu Hause angesehen. Mit der Zeit entwickelten sie sich zu einer Plattform für öffentliche Debatten über Wohlstand, Korruption und Familienbeziehungen.","In Enugu versammelt sich eine Familie am Abend, um einen neuen Nollywood-Film anzusehen, und diskutiert anschließend, ob das Ende moralisch oder nur bequem war. Diese familiäre Diskussion zeigt, wie Filme Fragen nach Werten und Verantwortung aufwerfen. Die Erfahrung variiert zwischen den Generationen: Jüngere verfolgen Inhalte oft über Streamingdienste, während Ältere dem traditionellen Videomarkt treu bleiben."]},{"heading":"Debatten über Moral und Macht","paragraphs":["Nigerianische Filme und Serien erzählen moralische, familiäre, religiöse und politische Geschichten und spielen eine zentrale Rolle in öffentlichen Auseinandersetzungen über Reichtum, Korruption und Geschlechtergerechtigkeit. Sie spiegeln die Realität nicht nur wider, sondern prägen sie mit, indem sie Verhaltensmodelle vorstellen und bewerten.","Seit den 2010er Jahren haben Streamingdienste und Kinos die Vertriebswege verändert, doch der ältere Videomarkt besteht weiter. Diese Vielfalt der Vertriebswege bedeutet, dass das Publikum auf unterschiedliche Weise mit Filmen interagiert, was den öffentlichen Diskurs erweitert."]},{"heading":"Vielfalt der Zentren und Genres","paragraphs":["Nollywood ist keine einzelne Industrie, sondern eine lockere Bezeichnung für viele Branchen und Genres. In Kano gibt es das hausa-sprachige Kannywood mit eigenen Märkten und Publikum. Diese Vielfalt spiegelt die kulturelle und sprachliche Diversität Nigerias wider und erinnert daran, dass der Begriff selbst seit seiner Prägung in den frühen 2000er Jahren umstritten ist.","Nollywood unterscheidet sich von anderen Filmindustrien durch den informalisierten Marktvertrieb, der sie den Menschen nahebringt. Das bedeutet jedoch nicht, dass sie einheitlich ist; die Erfahrungen unterscheiden sich je nach Region, Sprache und Generation."]}],"en":[{"heading":"From video boom to big screen","paragraphs":["Nollywood grew from the 1990s video boom, when cheap camcorders, straight-to-video releases and market distribution made films affordable across Africa. These films quickly became part of everyday life, sold in markets and watched at home. Over time, they evolved into a platform for public arguments about wealth, corruption and family relationships.","In Enugu, a family gathers in the evening to watch a new Nollywood release, then argues about whether the ending was moral or merely convenient. This family debate shows how films raise questions about values and responsibility. The experience varies across generations: younger viewers often follow content on streaming services, while older family members remain loyal to the traditional video market."]},{"heading":"Debates on morality and power","paragraphs":["Nigerian films and series tell moral, family, religious and political stories, and they are central to public arguments about wealth, corruption and gender. They do not merely reflect reality; they help shape it by presenting and evaluating models of behaviour.","Since the 2010s, streaming services and cinemas have changed distribution, but the older video market persists. This diversity of distribution means audiences engage with films in different ways, widening the circle of public debate."]},{"heading":"Many centres and genres","paragraphs":["Nollywood is not a single industry but a loose label for many industries and genres. In Kano, Hausa-language Kannywood has its own markets and audiences. This plurality reflects Nigeria's cultural and linguistic diversity and reminds us that the term itself has been contested since it was coined in the early 2000s.","Nollywood differs from other film industries in its reliance on informal market distribution, which brings it close to people. But this does not mean it is uniform; experiences vary by region, language and generation."]}]},"context":{"countries":["NG"],"region":"Nigeria — Lagos, Enugu and Kano","continent":"africa","languages":["en","ig","yo","ha"],"period":"contemporary"},"tags":["storytelling","Nigeria — Lagos, Enugu and Kano","Nollywood is","It grew"],"sources":[{"organization":"Wikipedia","title":{"ar":"Nollywood","de":"Nollywood","en":"Nollywood"},"url":"https://en.wikipedia.org/wiki/Nollywood","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Cinema of Nigeria","de":"Cinema of Nigeria","en":"Cinema of Nigeria"},"url":"https://en.wikipedia.org/wiki/Cinema_of_Nigeria","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في إينوغو، تجتمع عائلة لمشاهدة فيلم نوليوود جديد، ثم تتناقش حول ما إذا كانت النهاية أخلاقية أم مجرد حل سهل.","de":"In Enugu versammelt sich eine Familie am Abend, um einen neuen Nollywood-Film anzusehen, und diskutiert anschließend, ob das Ende moralisch oder nur bequem war.","en":"In Enugu, a family gathers in the evening to watch a new Nollywood release, then argues about whether the ending was moral or merely convenient."},"misunderstanding":{"ar":"الاعتقاد بأن نوليوود صناعة واحدة متجانسة يخفي تنوعها اللغوي والجهوي، فهي تضم كانيوود وغيرها من المراكز.","de":"Die Annahme, Nollywood sei eine homogene Industrie, verdeckt ihre sprachliche und regionale Vielfalt, zu der auch Kannywood gehört.","en":"Assuming Nollywood is a single homogeneous industry obscures its linguistic and regional diversity, including Kannywood."},"comparison":{"ar":"بخلاف هوليوود التي تهيمن عليها دور السينما والإنتاج الضخم، نشأت نوليوود من توزيع الفيديو الرخيص في الأسواق المحلية.","de":"Anders als Hollywood, das von Kinos und Großproduktionen dominiert wird, entstand Nollywood aus dem billigen Videovertrieb auf lokalen Märkten.","en":"Unlike Hollywood, dominated by cinemas and large-scale production, Nollywood emerged from cheap video distribution in local markets."}},{"id":"afr-046","version":2,"slug":"griots-history-praise-and-diplomacy-in-mande-society","contentType":"feature","category":"storytelling","title":{"ar":"الجريو: ذاكرة التاريخ وصوت الدبلوماسية","de":"Griots: Gedächtnis, Lob und Diplomatie","en":"Griots: memory, praise and diplomacy"},"deck":{"ar":"كيف يحفظ الجريو في مجتمع المانديه الأنساب والملاحم ويستخدمون الكلمة للوساطة والمدح والنقد.","de":"Wie Griots in der Mandé-Gesellschaft Genealogien und Epen bewahren und mit Worten vermitteln, loben und kritisieren.","en":"How griots in Mandé society keep genealogies and epics alive, and use words to mediate, praise and criticise."},"teaser":{"ar":"ليس مجرد مغنٍّ أو راوٍ، بل حافظ للذاكرة الجماعية ووسيط اجتماعي. تعرّف على دور الجريو في غرب أفريقيا.","de":"Kein bloßer Sänger, sondern Hüter der Erinnerung und Vermittler. Entdecken Sie die Rolle der Griots in Westafrika.","en":"Not just a singer or storyteller, but a keeper of collective memory and a social mediator. Discover the griot's role in West Africa."},"readingMinutes":1,"sections":{"ar":[{"heading":"وراثة الكلمة والذاكرة","paragraphs":["في مجتمعات المانديه بغرب أفريقيا، الجريو (وجمعها بالماندينكا jeliw) هم مؤرخون ورواة قصص ومدّاحون وموسيقيون. دورهم وراثي ينتقل من جيل إلى جيل داخل أسر معروفة. يحفظون الأنساب والأحداث الكبرى، ويروون ملحمة سوندياتا التي تحكي تأسيس إمبراطورية مالي، وهي من صميم ذخيرتهم التي تُؤدى عبر الأجيال.","يرافق الجريو نفسه غالبًا بآلة الكورا، ويؤدي في الأعراس وحفلات تسمية المولود والمناسبات السياسية. في عرس بباماكو، يمدح الجريو نسب العروس بالاسم ويستعيد مآثر أحد أجدادها، فتقدم الأسرة الهدايا تقديرًا لدوره. هذه الهدايا ليست أجرًا فحسب، بل اعتراف بمكانته كحافظ للذاكرة."]},{"heading":"الكلمة التي تزن وتُسكت","paragraphs":["يتمتع الجريو بحرية كلامية تتيح له المدح والنقد معًا. كلماته تحمل ثقلًا اجتماعيًا، ويمكن أن تُحرج أو تُصلح. لذلك يُستدعى أحيانًا للوساطة في الخلافات، مستندًا إلى معرفته بالأنساب والعلاقات بين الأسر.","لكن مكانته معقدة: فهو محترم كحافظ للذاكرة، لكنه في بعض السياقات يُنظر إليه كفئة منفصلة. هذا التمييز ليس ثابتًا في كل مكان، بل يختلف باختلاف المجتمعات والمناطق."]},{"heading":"الجريو في زمن الإذاعة والهجرة","paragraphs":["تغيرت ممارسة الجريو مع الإذاعة والتسجيلات الصوتية وانتشار المهاجرين. فبعضهم صار يقدم برامج أو يسجل أشرطة، وآخرون يؤدون في المهجر. هذا التكيف لم يلغِ الدور الوراثي، لكنه أضاف إليه قنوات جديدة.","كما تختلف تقاليد الجريو بين مجتمعات المانديه والولوف وغيرها، والكلمة الواحدة تغطي أدوارًا ليست قابلة للتبادل. فما يفعله جريو ماندينكا في حفل تسمية قد لا يطابق تمامًا ما يفعله مداح ولوف في مناسبة أخرى."]}],"de":[{"heading":"Vererbte Worte, vererbtes Gedächtnis","paragraphs":["In den Mandé-Gesellschaften Westafrikas sind Griots (auf Manding jeliw) Historiker, Geschichtenerzähler, Lobredner und Musiker. Ihre Rolle ist erblich und wird innerhalb bekannter Familien von Generation zu Generation weitergegeben. Sie bewahren Genealogien und große Ereignisse und tragen das Sundiata-Epos vor, das von der Gründung des Mali-Reiches erzählt und über Generationen weitergegeben wird.","Oft begleiten sie sich auf der Kora und treten bei Hochzeiten, Namenszeremonien und politischen Anlässen auf. Bei einer Hochzeit in Bamako lobt ein Jeli die Abstammung der Braut namentlich und erinnert an die Taten eines Vorfahren; die Familie schenkt daraufhin Gaben. Diese Gaben sind nicht nur Bezahlung, sondern Anerkennung seiner Rolle als Hüter der Erinnerung."]},{"heading":"Worte, die Gewicht haben","paragraphs":["Griots genießen Redefreiheit: Sie können loben und kritisieren. Ihre Worte haben soziales Gewicht und können verletzen oder versöhnen. Deshalb werden sie manchmal zur Vermittlung in Konflikten hinzugezogen, gestützt auf ihre Kenntnis der Genealogien und Familienbeziehungen.","Ihr Status ist jedoch komplex: Sie werden als Hüter der Erinnerung respektiert, in manchen Kontexten aber als eigene Kaste betrachtet. Diese Unterscheidung ist nicht überall gleich und variiert je nach Gesellschaft und Region."]},{"heading":"Griots zwischen Radio und Diaspora","paragraphs":["Mit Radio, Tonaufnahmen und Migration hat sich die Praxis verändert. Manche Griots moderieren Sendungen oder nehmen Kassetten auf, andere treten in der Diaspora auf. Diese Anpassung hat die erbliche Rolle nicht abgeschafft, aber neue Kanäle hinzugefügt.","Die Traditionen unterscheiden sich zwischen Mandé-, Wolof- und anderen Gesellschaften, und das Wort umfasst unterschiedliche, nicht austauschbare Rollen. Was ein Manding-Jeli bei einer Namenszeremonie tut, muss nicht genau dem entsprechen, was ein Wolof-Lobredner bei einem anderen Anlass tut."]}],"en":[{"heading":"Inherited words, inherited memory","paragraphs":["In Mandé societies of West Africa, griots (jeliw in Manding) are historians, storytellers, praise singers and musicians. The role is hereditary, passed down within known families. They keep genealogies and major events, and perform the Epic of Sundiata, which tells of the founding of the Mali Empire—a core part of their repertoire across generations.","Griots often accompany themselves on the kora and perform at weddings, naming ceremonies and political events. At a Bamako wedding, a jeli praises the bride's lineage by name and recounts an ancestor's deeds, and the family gives gifts in recognition. These gifts are not merely payment but an acknowledgement of his role as keeper of memory."]},{"heading":"Words that carry weight","paragraphs":["Griots speak with licence: they can praise and criticise. Their words carry social weight and can shame or reconcile. That is why they are sometimes called to mediate disputes, drawing on their knowledge of genealogies and family ties.","Yet their status is complex: respected as keepers of memory, they are in some contexts treated as a separate caste. This distinction is not uniform everywhere and varies across societies and regions."]},{"heading":"Griots amid radio and diaspora","paragraphs":["With radio, recordings and migration, the practice has changed. Some griots host programmes or record cassettes, others perform in the diaspora. This adaptation has not abolished the hereditary role but added new channels.","Traditions differ across Mandé, Wolof and other societies, and the word covers a range of roles that are not interchangeable. What a Manding jeli does at a naming ceremony may not exactly match what a Wolof praise singer does on another occasion."]}]},"context":{"countries":["ML","GN","SN","GM"],"region":"Mandé West Africa","community":"Griots (jeliw)","continent":"africa","languages":["bm","fr","wo"],"period":"contemporary"},"tags":["storytelling","Mandé West Africa","Griots (jeliw","They keep"],"sources":[{"organization":"Wikipedia","title":{"ar":"Griot","de":"Griot","en":"Griot"},"url":"https://en.wikipedia.org/wiki/Griot","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Epic of Sundiata","de":"Epic of Sundiata","en":"Epic of Sundiata"},"url":"https://en.wikipedia.org/wiki/Epic_of_Sundiata","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في عرس بباماكو، يمدح الجريو نسب العروس بالاسم ويستعيد مآثر أحد أجدادها، فتقدم الأسرة الهدايا تقديرًا له.","de":"Bei einer Hochzeit in Bamako lobt ein Jeli die Abstammung der Braut namentlich und erinnert an die Taten eines Vorfahren; die Familie schenkt daraufhin Gaben.","en":"At a Bamako wedding, a jeli praises the bride's lineage by name and recounts an ancestor's deeds, and the family gives gifts in recognition."},"misunderstanding":{"ar":"يُفهم الجريو أحيانًا كمجرد مغنٍّ ترفيهي، لكنه في سياقات كثيرة حافظ للأنساب ووسيط اجتماعي، ودوره يتجاوز الترفيه.","de":"Griots werden manchmal nur als Unterhalter gesehen, doch in vielen Kontexten sind sie Hüter der Genealogien und soziale Vermittler – ihre Rolle geht über Unterhaltung hinaus.","en":"Griots are sometimes seen only as entertainers, but in many contexts they are keepers of genealogies and social mediators—their role goes beyond entertainment."},"comparison":{"ar":"في المجتمعات التي تعتمد على الأرشيف المكتوب، تُحفظ الأنساب في وثائق، بينما يحفظها الجريو في الذاكرة والكلمة المنطوقة.","de":"In Gesellschaften mit schriftlichen Archiven werden Genealogien in Dokumenten bewahrt, während Griots sie im Gedächtnis und im gesprochenen Wort halten.","en":"In societies with written archives, genealogies are kept in documents, whereas griots hold them in memory and spoken word."}},{"id":"afr-047","version":2,"slug":"izibongo-zulu-praise-poetry-that-can-also-criticise","contentType":"feature","category":"storytelling","title":{"ar":"إيزيبونغو: شعر المدح الناقد","de":"Izibongo: Lobpreis mit kritischem Ton","en":"Izibongo: Praise Poetry That Can Criticise"},"deck":{"ar":"شعر شفهي زولو وخوسا يمتدح ويحذّر في المجالس نفسها.","de":"Mündliche Dichtung der Zulu und Xhosa, die lobt und zugleich warnt.","en":"Zulu and Xhosa oral poetry that honours and warns in the same breath."},"teaser":{"ar":"في الأعراس والجنازات والتجمعات السياسية، يمدح الشعراء الأسلاف ثم يوجهون تحذيراً هادئاً.","de":"Bei Hochzeiten, Begräbnissen und politischen Versammlungen preisen Dichter die Ahnen – und schieben leise eine Warnung ein.","en":"At weddings, funerals and political gatherings, poets praise a leader's ancestors – then slip in a quiet warning."},"readingMinutes":1,"sections":{"ar":[{"heading":"صوت يُسمع في المناسبات","paragraphs":["إيزيبونغو نوع من الشعر الشفهي لدى شعوب البانتو في الجنوب الأفريقي، ولا سيما الزولو والخوسا. يُؤدى في الأعراس والجنازات والتجمعات السياسية، ويسجّل تاريخ العائلات والسمعة العامة للأشخاص.","يُطلق عليه غالباً «شعر المدح»، لكن الباحثين يلاحظون أنه قد يحمل أيضاً النقد والتحذير والسخرية. هذا الجانب هو ما يجعله أكثر من مجرد إطراء.","يختلف الأداء من منطقة إلى أخرى ومن جيل إلى جيل؛ فالشباب في المدن قد يعيدون صياغته بأسلوب أقرب إلى الخطاب السياسي المعاصر."]},{"heading":"شاعر يتجاوز حدود الكلام","paragraphs":["شعراء المدح (إيمبونغي) يستطيعون مخاطبة الزعماء والسياسيين بطرق لا يملكها الناس العاديون. هذا الامتياز يمنحهم مساحة للتعبير عن مظالم المجتمع علناً.","استُخدم هذا الشكل في النضال ضد الفصل العنصري، ولا يزال حاضراً في السياسة المعاصرة. فالشاعر قد يبدأ بمدح الأسلاف ثم يضيف تحذيراً بشأن احتياجات لم تُلبَّ.","في تجمع في كوازولو-ناتال، يمدح شاعر المدح أسلاف الزعيم، ثم يدرج تحذيراً حول الاحتياجات التي لم تُلبَّ في المجتمع."]},{"heading":"من المنصة إلى الكتاب المدرسي","paragraphs":["المجموعات المكتوبة والمناهج المدرسية حوّلت إيزيبونغو إلى نوع أدبي إلى جانب كونه أداءً حياً. هذا الانتقال غيّر طريقة تلقّيه، لكنه لم يلغِ حضوره في المناسبات.","ينبغي الحذر من الترجمة «شعر المدح»، فقد انتُقدت لأنها تسطّح الحدة النقدية لهذا النوع. التسمية الأجنبية تخفي ما يعرفه المستمع المحلي.","يبقى السؤال: هل نسمع المدح فقط، أم نسمع التحذير الذي يختبئ خلفه؟"]}],"de":[{"heading":"Eine Stimme, die gehört wird","paragraphs":["Izibongo ist eine Form mündlicher Dichtung bei Bantu-Völkern des südlichen Afrika, besonders bei den Zulu und Xhosa. Sie werden bei Hochzeiten, Begräbnissen und politischen Versammlungen aufgeführt und halten Familiengeschichten und öffentliche Reputation fest.","Oft heißt es „Lobdichtung“, doch Forschende betonen, dass sie auch Kritik, Warnung und Satire enthalten kann. Genau dieser Anteil macht sie mehr als eine bloße Huldigung.","Die Aufführung variiert je nach Region und Generation; junge Menschen in Städten gestalten sie bisweilen in einem Ton, der heutigen politischen Reden näher steht."]},{"heading":"Ein Dichter, der mehr sagen darf","paragraphs":["Lobdichter (imbongi) können Häuptlinge und Politiker auf eine Weise ansprechen, die gewöhnlichen Menschen verwehrt ist. Dieses Privileg schafft Raum, gesellschaftliche Missstände öffentlich zu benennen.","Die Form wurde im Kampf gegen die Apartheid genutzt und ist auch in der Gegenwartspolitik präsent. Ein Dichter kann mit dem Lob der Ahnen beginnen und dann eine Warnung über unerfüllte Bedürfnisse anfügen.","Bei einer Kundgebung in KwaZulu-Natal lobt ein imbongi die Ahnen des Anführers und fügt dann eine Warnung über unerfüllte Bedürfnisse der Gemeinde ein."]},{"heading":"Von der Bühne ins Schulbuch","paragraphs":["Schriftliche Sammlungen und Lehrpläne haben Izibongo zu einer literarischen Gattung gemacht, ohne die Aufführung zu verdrängen. Der Wechsel verändert die Rezeption, nicht aber die Präsenz bei Anlässen.","Vorsicht ist bei der Übersetzung „Lobdichtung“ geboten: Sie steht in der Kritik, weil sie die kritische Schärfe der Gattung einebnet. Die fremde Bezeichnung verdeckt, was Einheimische hören.","Bleibt die Frage: Hören wir nur das Lob – oder auch die Warnung dahinter?"]}],"en":[{"heading":"A Voice Heard at Gatherings","paragraphs":["Izibongo is a genre of oral poetry among Bantu peoples of southern Africa, especially the Zulu and Xhosa. It is performed at weddings, funerals and political gatherings, and it records family histories and public reputations.","It is often called praise poetry, but researchers note that it can contain criticism, warning and satire as well as praise. That edge makes it more than flattery.","Performance varies by language, region and generation; young people in cities sometimes reshape it in a register closer to contemporary political speech."]},{"heading":"A Poet Who Can Say More","paragraphs":["Praise poets (imbongi) can address chiefs and politicians in ways ordinary people cannot. That licence creates room to name community grievances in public.","The form has been used in anti-apartheid struggle and in contemporary politics. A poet may open with praise of a leader's ancestors, then add a warning about unmet needs.","At a rally in KwaZulu-Natal, an imbongi praises the leader's ancestors, then slips in a warning about the community's unmet needs."]},{"heading":"From the Stage to the Syllabus","paragraphs":["Written collections and school syllabuses have turned izibongo into a literary genre as well as a performance. The shift changes how it is received, not whether it appears at gatherings.","The translation 'praise poetry' has been criticised for flattening the genre's critical edge. The foreign label can hide what local listeners already hear.","The question remains: do we hear only the praise, or also the warning behind it?"]}]},"context":{"countries":["ZA","ZW"],"region":"Southern Africa","community":"Zulu and Xhosa","continent":"africa","languages":["zu","xh","en"],"period":"contemporary"},"tags":["storytelling","Southern Africa"],"sources":[{"organization":"Wikipedia","title":{"ar":"Izibongo","de":"Izibongo","en":"Izibongo"},"url":"https://en.wikipedia.org/wiki/Izibongo","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Zulu literature","de":"Zulu literature","en":"Zulu literature"},"url":"https://en.wikipedia.org/wiki/Zulu_literature","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في تجمع في كوازولو-ناتال، يمدح شاعر المدح أسلاف الزعيم، ثم يدرج تحذيراً حول الاحتياجات التي لم تُلبَّ في المجتمع.","de":"Bei einer Kundgebung in KwaZulu-Natal lobt ein imbongi die Ahnen des Anführers und fügt dann eine Warnung über unerfüllte Bedürfnisse der Gemeinde ein.","en":"At a rally in KwaZulu-Natal, an imbongi praises the leader's ancestors, then slips in a warning about the community's unmet needs."},"misunderstanding":{"ar":"يُفهم إيزيبونغو غالباً كمدح خالص، لكنه في الواقع قد يحمل نقداً وتحذيراً وسخرية.","de":"Izibongo gilt oft als reine Lobdichtung, kann aber tatsächlich Kritik, Warnung und Satire enthalten.","en":"Izibongo is often taken as pure praise, yet it can carry criticism, warning and satire."},"comparison":{"ar":"مثل خطبة عامة تجمع بين الإشادة والمساءلة، يعمل إيزيبونغو كمنبر يمدح ويحاسب في الوقت نفسه.","de":"Wie eine öffentliche Rede, die Lob und Rechenschaft verbindet, wirkt Izibongo als Bühne, die zugleich preist und zur Verantwortung zieht.","en":"Like a public speech that combines tribute with accountability, izibongo works as a stage that honours and holds to account at once."}},{"id":"afr-048","version":2,"slug":"kente-cloth-status-and-the-politics-of-wearing","contentType":"feature","category":"clothing-and-design","title":{"ar":"الكنتي: قماش يحمل أسماء وأدواراً","de":"Kente: Stoff, Status und die Politik des Tragens","en":"Kente: cloth, status and the politics of wearing"},"deck":{"ar":"من بونويري إلى حفلات التخرج في أكرا، يظل الكنتي علامة على الهوية والانتماء، لكن من يحق له ارتداء أي نقش؟","de":"Vom Weben in Bonwire bis zu Abschlussfeiern in Accra: Kente zeigt Zugehörigkeit – doch wer darf welches Muster tragen?","en":"From looms in Bonwire to graduation halls in Accra, kente marks who people are — but who may wear which pattern is still argued over."},"teaser":{"ar":"نسيج غاني من شرائط حريرية وقطنية، يحمل كل نقش فيه اسماً ومعنى، ويطرح أسئلة عن الأصالة والانتماء.","de":"Ein ghanaisches Gewebe aus Seiden- und Baumwollstreifen, dessen Muster Namen und Bedeutungen tragen und Fragen nach Herkunft und Echtheit aufwerfen.","en":"A Ghanaian cloth of silk and cotton strips, whose patterns carry names and meanings, raising questions of authenticity and belonging."},"readingMinutes":1,"sections":{"ar":[{"heading":"نشأة النسيج في بونويري","paragraphs":["يروي التقليد الشفهي عند الأشنتي أن الكنتي بدأ في بلدة بونويري بمنطقة أشنتي، حيث يُنسج يدوياً من شرائط من الحرير والقطن تُخاط معاً في قطعة واحدة.","وكان يُلبس قديماً على هيئة رداء يشبه التوجة عند الأشنتي والأكان والإيوي، ولكل نقش اسم خاص يحمل دلالة اجتماعية أو تاريخية.","وتعترف غانا رسمياً بالكنتي كمؤشر جغرافي وطني، أي أن أصله مرتبط بأرض بعينها وبأيدٍ تعرف حرفة النسج."]},{"heading":"متى يُلبس ومن يرتديه","paragraphs":["اليوم يظهر الكنتي في حفلات التخرج والأعراس والجنازات والخدمات الكنسية، ويحرص الغانيون في المهجر على ارتدائه كعلامة على الانتماء.","وفي حفل تخرج بأكرا، قد يرتدي الخريج وشاحاً من الكنتي فوق عباءته، ويُعلن اسم النقش أمام العائلة أثناء التقاط الصور.","ويختلف شكل النقش ودلالته بين تقاليد النسج عند الأشنتي والإيوي، كما تتفاوت الأذواق بين الأجيال وبين المدن والقرى في طريقة اللبس والاختيار."]},{"heading":"سؤال الأصالة والتقليد","paragraphs":["مع انتشار الكنتي تجارياً، ظهر جدل حول الأصالة: فكثير من الأقمشة المطبوعة آلياً تُسوَّق باسم «كنتي» دون أن تكون منسوجة يدوياً.","ويطرح السؤال أيضاً من يحق له ارتداء نقش بعينه، إذ تحمل بعض الأنماط معاني مرتبطة بالمناسبة أو بالمكانة.","يبقى الكنتي أكثر من قطعة ملابس: إنه لغة بصرية يقول بها الناس من هم وأين نشأوا، حتى وهم يتبادلون الحديث في مناسبة واحدة."]}],"de":[{"heading":"Ursprung am Webstuhl von Bonwire","paragraphs":["Nach mündlicher Überlieferung der Asante entstand Kente in Bonwire in der Ashanti-Region. Der Stoff wird von Hand aus Streifen aus Seide und Baumwolle gewebt und zusammengenäht.","Früher wurde er in togaähnlicher Form von Asante, Akan und Ewe getragen. Die Muster tragen Namen und Bedeutungen, die an Anlässe, Familien oder Ereignisse erinnern.","Ghana erkennt Kente offiziell als geografische Herkunftsangabe an – der Stoff gehört also zu einem bestimmten Ort und zu Händen, die das Weben beherrschen."]},{"heading":"Wann Kente getragen wird","paragraphs":["Heute erscheint Kente bei Abschlussfeiern, Hochzeiten, Begräbnissen und Gottesdiensten. Ghanaerinnen und Ghanaer im Ausland tragen es als Zeichen ihrer Identität.","In Accra kann eine Absolventin eine Kente-Stola über der Robe tragen, während der Name des Musters verlesen wird und die Familie fotografiert.","Muster und Bedeutung unterscheiden sich zwischen Asante- und Ewe-Webertraditionen; auch zwischen Generationen und zwischen Stadt und Region variiert, wie und wann Kente getragen wird."]},{"heading":"Die Debatte um Echtheit","paragraphs":["Mit der Vermarktung wuchs die Diskussion über Authentizität: Viel maschinell bedruckter Stoff wird als „Kente-Print“ verkauft, ohne handgewebt zu sein.","Zugleich wird gefragt, wer ein bestimmtes Muster tragen darf, da manche Motive mit Anlass oder Status verbunden sind.","So bleibt Kente mehr als Kleidung: eine visuelle Sprache, mit der Menschen sagen, wer sie sind und woher sie kommen – auch im Gespräch auf ein und derselben Feier."]}],"en":[{"heading":"Where the weaving began","paragraphs":["Asante oral tradition places kente's origin at Bonwire in the Ashanti Region. It is hand-woven from silk and cotton strips that are sewn together into a single cloth.","Historically it was worn in toga-like fashion by Asante, Akan and Ewe people, and its patterns carry names and meanings linked to occasions, families or events.","Ghana officially recognises kente as a geographical indication, tying the cloth to a particular place and to the hands that know how to weave it."]},{"heading":"When people wear it","paragraphs":["Today kente appears at graduations, weddings, funerals and church services, and Ghanaians abroad wear it as a marker of identity.","In Accra a graduate may wear a kente stole over a gown while the pattern's name is announced and family members take photographs.","Designs and meanings differ between Asante and Ewe weaving traditions, and how and when kente is worn shifts between generations and between city and hometown."]},{"heading":"The argument over authenticity","paragraphs":["Commercial success brought debate about authenticity: much machine-printed fabric is sold as 'kente-print' without ever being hand-woven.","There is also the question of who may wear a particular pattern, since some designs are tied to an occasion or to status.","Kente remains more than clothing: a visual language through which people say who they are and where they come from, even while chatting at the same celebration."]}]},"context":{"countries":["GH"],"region":"Ashanti Region, Ghana","community":"Asante and Ewe weavers","continent":"africa","languages":["ak","ee","en"],"period":"contemporary"},"tags":["clothing-and-design","Ashanti Region, Ghana"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kente cloth","de":"Kente cloth","en":"Kente cloth"},"url":"https://en.wikipedia.org/wiki/Kente_cloth","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Bonwire","de":"Bonwire","en":"Bonwire"},"url":"https://en.wikipedia.org/wiki/Bonwire","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"خريج غاني في أكرا يرتدي وشاح كنتي فوق عباءته، ويُعلن اسم النقش بينما تلتقط العائلة الصور.","de":"Eine Absolventin in Accra trägt eine Kente-Stola über der Robe; der Name des Musters wird verlesen, während die Familie Fotos macht.","en":"A Ghanaian graduate in Accra wears a kente stole over a gown, and the pattern's name is announced while family members take photographs."},"misunderstanding":{"ar":"يُظن أحياناً أن كل قماش يحمل رسوماً هندسية ملونة هو كنتي أصلي، لكن جزءاً كبيراً مما يُباع مطبوع آلياً وليس منسوجاً يدوياً.","de":"Manchmal wird jedes bunte geometrische Gewebe für echtes Kente gehalten, doch ein großer Teil des Angebots ist maschinell bedruckt und nicht handgewebt.","en":"People sometimes assume any brightly patterned geometric cloth is genuine kente, yet much of what is sold is machine-printed rather than hand-woven."},"comparison":{"ar":"يشبه الكنتي في وظيفته الاجتماعية ما تحمله بعض الأزياء الإقليمية من دلالات على المكانة والمناسبة، لكن ما يميزه أن لكل نقش اسماً متعارفاً عليه.","de":"Wie manche regionale Tracht signalisiert Kente Status und Anlass, doch besonders ist, dass jedes Muster einen allgemein bekannten Namen trägt.","en":"Like other regional dress, kente signals status and occasion, but what sets it apart is that individual patterns carry recognised names."}},{"id":"afr-049","version":2,"slug":"la-sape-dressing-well-as-a-moral-position","contentType":"feature","category":"clothing-and-design","title":{"ar":"اللاباس: الأناقة كموقف أخلاقي","de":"La Sape: Eleganz als moralische Haltung","en":"La Sape: Dressing Well as a Moral Position"},"deck":{"ar":"في كينشاسا وبرازافيل، يختار السابور أن يلبسوا الأناقة كوسيلة للحفاظ على الكرامة والاحترام في مواجهة صعوبات الحياة.","de":"In Kinshasa und Brazzaville machen Sapeurs deutlich, dass gutes Auftreten und Würde zusammengehören – auch unter schwierigen Bedingungen.","en":"In Kinshasa and Brazzaville, sapeurs show that elegance and dignity go hand in hand, even when life is hard."},"teaser":{"ar":"حركة اللاباس تجعل من الملابس الفاخرة والسلوك المهذب تعبيرًا عن احترام الذات والتحدي اليومي.","de":"La Sape ist mehr als teure Kleidung: Sie ist ein Bekenntnis zu Selbstachtung und Respekt im Alltag.","en":"La Sape is more than expensive clothes: it is a commitment to self-respect and good manners in everyday life."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما هي اللاباس؟","paragraphs":["اللاباس ظاهرة اجتماعية وثقافية تتمركز في مدينتي كينشاسا وبرازافيل، وتعني اسمها «جمعية أهل البهجة والأناقة». يطلق على ممارسيها اسم «سابور»، وهم يحرصون على ارتداء ملابس فاخرة من تصميمات عالمية، مع سلوك مهذب وأداء علني في الأماكن العامة.","لا توجد منظمة واحدة تجمعهم، بل هي ممارسة تختلف بين المدينتين وفي أوساط الشتات. فبعض الشباب يتبنونها بحماس، بينما يراها آخرون من الأجيال الأكبر مبالغة في الإنفاق."]},{"heading":"الجذور والتحول","paragraphs":["تعود جذور الحركة إلى عمال المنازل في الحقبة الاستعمارية الذين تبنوا الملابس الأوروبية، ثم تحولت لاحقًا إلى تعبير عن الكرامة في ظل الأزمات الاقتصادية. فقد أصبح ارتداء البدلة الأنيقة وسيلة لإثبات القيمة الإنسانية عندما تعجز الظروف المادية عن ذلك.","غالبًا ما ينفق السابور مبالغ كبيرة على الملابس مقارنة بدخلهم، وقد قُرئ هذا السلوك أحيانًا كاستهلاك تفاخري، وأحيانًا أخرى كتعبير عن احترام الذات. وفي كلا الحالتين، يبقى الاختيار واعيًا ومقصودًا."]},{"heading":"التأثير والحضور","paragraphs":["أثّرت اللاباس في فيديوهات الموسيقى الكونغولية وتصوير الأزياء، ويظهر السابور في مدن أوروبية ذات جاليات كونغولية. كما أنهم يحرصون على أناقتهم في المناسبات الدينية والاجتماعية، مثل الذهاب إلى الكنيسة يوم الأحد في بذلات مفصلة وأحذية لامعة.","تظل اللاباس ظاهرة حية تعكس تنوع التقاليد الحضرية في الكونغو، مع اختلافات واضحة بين الأجيال والمناطق، مما يجعلها موضع نقاش دائم حول معنى الأناقة والكرامة."]}],"de":[{"heading":"Was ist La Sape?","paragraphs":["La Sape ist eine Modessubkultur mit Zentren in Kinshasa und Brazzaville. Der Name leitet sich von der Société des Ambianceurs et des Personnes Élégantes ab. Ihre Anhänger, die Sapeurs, tragen teure Designerkleidung und pflegen Eleganz, Manieren und öffentliche Performance.","Dabei handelt es sich nicht um eine einheitliche Organisation. Die Praktiken unterscheiden sich zwischen Kinshasa, Brazzaville und der Diaspora. Junge Leute greifen den Stil oft begeistert auf, während ältere Generationen ihn manchmal als übertrieben empfinden."]},{"heading":"Wurzeln und Wandel","paragraphs":["Die Bewegung hat ihre Wurzeln bei Hausangestellten der Kolonialzeit, die europäische Kleidung übernahmen. Später wurde sie zu einem Ausdruck von Würde in wirtschaftlichen Krisenzeiten. Eine elegant geschnittene Garderobe wurde zum Zeichen dafür, dass menschlicher Wert nicht von materiellen Umständen abhängt.","Sapeurs geben oft viel Geld für Kleidung aus – gemessen an ihrem Einkommen. Das wird sowohl als auffälliger Konsum als auch als Ausdruck von Selbstachtung gelesen. In beiden Fällen bleibt die Entscheidung bewusst und gut überlegt."]},{"heading":"Wirkung und Präsenz","paragraphs":["La Sape hat kongolesische Musikvideos und Modefotografie beeinflusst. Sapeurs treten auch in europäischen Städten mit kongolesischen Gemeinschaften auf. Zu besonderen Anlässen wie dem Kirchgang am Sonntag erscheinen sie in maßgeschneiderten Anzügen und polierten Schuhen.","So bleibt La Sape eine lebendige städtische Tradition, die regionale und generationelle Unterschiede zeigt und die Frage nach dem Verhältnis von Stil und Würde immer wieder neu stellt."]}],"en":[{"heading":"What Is La Sape?","paragraphs":["La Sape is a fashion subculture centred on Kinshasa and Brazzaville. Its name derives from the Société des Ambianceurs et des Personnes Élégantes. Adherents, called sapeurs, wear expensive designer clothes and cultivate elegance, manners and public performance.","It is not a single organisation. Practices differ between Kinshasa, Brazzaville and diaspora scenes. Younger people often embrace the style enthusiastically, while some older generations see it as excessive spending."]},{"heading":"Roots and Transformation","paragraphs":["The movement has roots in colonial-era servants who adopted European dress. It later became a statement of dignity amid economic crisis. A well-tailored outfit became a way to assert human worth when material conditions could not.","Sapeurs often spend large sums on clothes relative to their income. The practice has been read as both conspicuous consumption and self-respect. In either reading, the choice is deliberate and considered."]},{"heading":"Influence and Presence","paragraphs":["La Sape has influenced Congolese music videos and fashion photography. Sapeurs also appear in European cities with Congolese communities. On occasions like Sunday church, they turn out in tailored suits and polished shoes.","La Sape remains a living urban tradition, with clear regional and generational variation, keeping alive the question of what elegance and dignity mean today."]}]},"context":{"countries":["CD","CG"],"region":"Kinshasa and Brazzaville","community":"Sapeurs","continent":"africa","languages":["fr","ln"],"period":"contemporary"},"tags":["clothing-and-design","Kinshasa and Brazzaville"],"sources":[{"organization":"Wikipedia","title":{"ar":"La Sape","de":"La Sape","en":"La Sape"},"url":"https://en.wikipedia.org/wiki/La_Sape","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Brazzaville","de":"Brazzaville","en":"Brazzaville"},"url":"https://en.wikipedia.org/wiki/Brazzaville","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في يوم أحد في باكونغو، يسير سابور إلى الكنيسة ببدلة مفصلة وحذاء لامع، ويسلم على أصدقاء معجبين بتناسق الألوان.","de":"An einem Sonntag in Bacongo geht ein Sapeur in einem maßgeschneiderten Anzug und geputzten Schuhen zur Kirche und grüßt Freunde, die die Farbkombination bewundern.","en":"On a Sunday in Bacongo, a sapeur walks to church in a tailored suit and polished shoes, greeting friends who admire the colour combination."},"misunderstanding":{"ar":"يُفهم أحيانًا أن اللاباس مجرد تباهٍ بالملابس، لكنها في جوهرها موقف أخلاقي يربط الأناقة بالاحترام والكرامة.","de":"Manchmal wird La Sape als reine Prahlerei mit Kleidung missverstanden. Tatsächlich ist sie eine moralische Haltung, die Eleganz mit Respekt und Würde verbindet.","en":"La Sape is sometimes mistaken for mere showing off. In fact, it is a moral position that links elegance with respect and dignity."},"comparison":{"ar":"تشبه اللاباس ظواهر أخرى في العالم حيث تصبح الملابس وسيلة تعبير عن الهوية، لكنها تتميز بتركيزها على السلوك المهذب والأداء العلني.","de":"La Sape ähnelt anderen weltweiten Phänomenen, bei denen Kleidung Identität ausdrückt, betont aber besonders gutes Benehmen und öffentliche Performance.","en":"La Sape resembles other global phenomena where clothing expresses identity, but it places particular emphasis on good manners and public performance."}},{"id":"afr-050","version":2,"slug":"the-capulana-mozambique-s-everyday-cloth","contentType":"feature","category":"clothing-and-design","title":{"ar":"الكابولانا: قماش موزمبيق اليومي","de":"Der Capulana: Mosambiks Alltagsstoff","en":"The capulana: Mozambique's everyday cloth"},"deck":{"ar":"قطعة قماش واحدة تتحول إلى تنورة أو حمالة أطفال أو غطاء رأس، وتحمل معاني الاحترام والحزن والفرح في حياة الموزمبيقيين.","de":"Ein Stück Stoff, das als Rock, Trage oder Kopftuch dient und Respekt, Trauer und Freude im mosambikanischen Leben ausdrückt.","en":"A single length of cloth becomes a skirt, a baby carrier, or a headwrap, carrying meanings of respect, mourning, and joy in Mozambican life."},"teaser":{"ar":"الكابولانا ليست مجرد قماش، بل رفيقة يومية تلبس وتلف وتحمل، وتخبر عن مناسبات الناس وأفراحهم وأحزانهم.","de":"Der Capulana ist mehr als Stoff: Er wird getragen, gewickelt und gebunden und erzählt von den Anlässen und Gefühlen der Menschen.","en":"The capulana is more than fabric: it is worn, wrapped, and carried, telling of people's occasions, celebrations, and sorrows."},"readingMinutes":1,"sections":{"ar":[{"heading":"قطعة قماش تكفي لكل شيء","paragraphs":["الكابولانا قطعة قماش تشبه السارونغ، يبلغ طولها حوالي مترين وعرضها متر واحد، وتُلبس بشكل أساسي في موزمبيق وجنوب شرق أفريقيا. يمكن أن تكون تنورة أو فستانًا أو غطاء رأس أو حمالة أطفال أو باقة محمولة، وتُعتبر قطعة ملابس كاملة بحد ذاتها.","في المنازل الموزمبيقية، تعلق الكابولانا في الخزانة أو على الحبل، جاهزة للاستخدام في أي لحظة. الأمهات يستخدمنها لحمل أطفالهن على الظهر أثناء الطهي أو العمل في الحقل، والرجال يلفونها حول الخصر في البيت أو أثناء الراحة."]},{"heading":"أنماط تحكي المناسبات","paragraphs":["تُطبع الكابولانات بأنماط زاهية، ولكل تصميم دلالة خاصة. بعض الأنماط مخصصة للأعراس، وبعضها للحزن، وأخرى للاستخدام اليومي. تُباع في الأسواق وتُقدَّم كهدايا، وتُستخدم في الاحتفالات وكعلامة على الاحترام.","في سوق مابوتو، تختار امرأة كابولانا بنقشة مناسبة لجنازة، ثم تشتري أخرى أكثر إشراقًا لزفاف ابنتها. هذا الاختيار ليس عشوائيًا، بل يعكس معرفة دقيقة بالعادات والتقاليد."]},{"heading":"من السوق إلى المنصة","paragraphs":["دخلت الكابولانا عالم الأزياء والفن المعاصر في موزمبيق، وتُستخدم أيضًا في السياقات السياسية والدينية. فهي حاضرة في الحملات الانتخابية، وفي الكنائس، وفي عروض الأزياء التي تحتفي بالهوية المحلية.","تختلف أعراف الأنماط حسب المنطقة والعائلة، وأقمشة مشابهة تحمل أسماء أخرى تُلبس في أنحاء جنوب أفريقيا. كما أن الأجيال الشابة تبتكر طرقًا جديدة لارتدائها، بينما تتمسك الأجيال الأكبر بالأنماط التقليدية."]}],"de":[{"heading":"Ein Stoff für alles","paragraphs":["Ein Capulana ist ein sarongähnliches Stück Stoff, etwa 2 mal 1 Meter groß, das vor allem in Mosambik und im südöstlichen Afrika getragen wird. Er kann als Rock, Kleid, Kopftuch, Babytrage oder getragenes Bündel dienen und gilt als vollständiges Kleidungsstück.","In mosambikanischen Haushalten hängt der Capulana im Schrank oder auf der Leine, jederzeit einsatzbereit. Mütter nutzen ihn, um ihre Kinder beim Kochen oder auf dem Feld auf dem Rücken zu tragen; Männer wickeln ihn zu Hause oder bei der Rast um die Hüften."]},{"heading":"Muster erzählen von Anlässen","paragraphs":["Capulanas werden mit leuchtenden Mustern bedruckt, und jedes Design hat eine besondere Bedeutung. Einige Muster sind für Hochzeiten, andere für Trauer, wieder andere für den Alltag. Sie werden auf Märkten verkauft und als Geschenk überreicht, bei Zeremonien verwendet und als Zeichen des Respekts getragen.","Auf dem Markt in Maputo wählt eine Frau einen Capulana mit einem für eine Beerdigung passenden Muster und kauft dann einen helleren für die Hochzeit ihrer Tochter. Diese Wahl ist nicht willkürlich, sondern spiegelt genaue Kenntnis der Bräuche wider."]},{"heading":"Vom Markt auf den Laufsteg","paragraphs":["Der Capulana hat Einzug in die zeitgenössische mosambikanische Mode und Kunst gehalten und wird auch in politischen und religiösen Kontexten verwendet. Er ist bei Wahlkampagnen, in Kirchen und bei Modenschauen präsent, die die lokale Identität feiern.","Die Musterkonventionen unterscheiden sich je nach Region und Familie, und ähnliche Stoffe unter anderen Namen werden in ganz Südafrika getragen. Jüngere Generationen erfinden neue Arten, ihn zu tragen, während ältere an traditionellen Mustern festhalten."]}],"en":[{"heading":"One cloth for everything","paragraphs":["A capulana is a sarong-like length of cloth about 2 by 1 metres, worn primarily in Mozambique and south-eastern Africa. It can be a skirt, a dress, a headwrap, a baby carrier or a carried bundle, and it is treated as a complete piece of clothing.","In Mozambican homes, the capulana hangs in the wardrobe or on the line, ready for use at any moment. Mothers use it to carry their babies on their backs while cooking or working in the field, and men wrap it around their waists at home or while resting."]},{"heading":"Patterns that speak of occasions","paragraphs":["Capulanas are printed in bright patterns, and particular designs mark weddings, mourning and everyday wear. They are sold in markets and given as gifts, and the cloth is used in ceremonies and as a marker of respect.","At a Maputo market a woman chooses a capulana with a pattern suitable for a funeral, then buys a brighter one for her daughter's wedding. This choice is not random; it reflects precise knowledge of customs and traditions."]},{"heading":"From market to runway","paragraphs":["The capulana has entered contemporary Mozambican fashion and art, and it is also used in political and religious contexts. It appears in election campaigns, in churches, and in fashion shows that celebrate local identity.","Pattern conventions differ by region and family, and similar cloths under other names are worn across southern Africa. Younger generations invent new ways of wearing it, while older generations hold on to traditional patterns."]}]},"context":{"countries":["MZ"],"region":"Mozambique","continent":"africa","languages":["pt"],"period":"contemporary"},"tags":["clothing-and-design","Mozambique"],"sources":[{"organization":"Wikipedia","title":{"ar":"Capulana","de":"Capulana","en":"Capulana"},"url":"https://en.wikipedia.org/wiki/Capulana","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Mozambique","de":"Mozambique","en":"Mozambique"},"url":"https://en.wikipedia.org/wiki/Mozambique","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في سوق مابوتو، تختار امرأة كابولانا بنقشة مناسبة لجنازة، ثم تشتري أخرى أكثر إشراقًا لزفاف ابنتها.","de":"Auf dem Markt in Maputo wählt eine Frau einen Capulana mit einem für eine Beerdigung passenden Muster und kauft dann einen helleren für die Hochzeit ihrer Tochter.","en":"At a Maputo market a woman chooses a capulana with a pattern suitable for a funeral, then buys a brighter one for her daughter's wedding."},"misunderstanding":{"ar":"يعتقد البعض أن الكابولانا مجرد قماش تقليدي بسيط، لكنها في الواقع قطعة ملابس كاملة تحمل دلالات اجتماعية وثقافية عميقة.","de":"Manche halten den Capulana für einen einfachen traditionellen Stoff, doch tatsächlich ist er ein vollständiges Kleidungsstück mit tiefer sozialer und kultureller Bedeutung.","en":"Some think the capulana is just a simple traditional cloth, but it is actually a complete garment with deep social and cultural significance."},"comparison":{"ar":"مثل الشال أو الإزار في cultures أخرى، الكابولانا تجمع بين الوظيفة العملية والرمزية في آن واحد.","de":"Wie der Schal oder das Umschlagtuch in anderen Kulturen vereint der Capulana praktische und symbolische Funktionen.","en":"Like the shawl or wrap in other cultures, the capulana combines practical and symbolic functions."}},{"id":"afr-051","version":2,"slug":"transhumance-moving-with-the-rains-in-the-sahel","contentType":"feature","category":"nature-and-seasons","title":{"ar":"الرعي المتنقل: حياة تسير مع المطر","de":"Transhumanz: mit dem Regen wandern","en":"Transhumance: moving with the rains"},"deck":{"ar":"كيف يتحرك رعاة الفولاني مع قطعانهم عبر الساحل بحثًا عن الكلأ والماء، ولماذا يزداد هذا التقليد صعوبة.","de":"Wie fulbische Hirten im Sahel mit ihren Herden zwischen festen Weidegebieten ziehen und warum diese Praxis unter Druck gerät.","en":"How Fulani herders in the Sahel move their herds between fixed pastures, and why this way of life is under pressure."},"teaser":{"ar":"في الساحل، لا تعني الحركة دائمًا الهجرة؛ إنها استراتيجية بقاء. تعرّف على الرعي المتنقل كما يعيشه الفولانيون يوميًا.","de":"In der Sahelzone bedeutet Bewegung nicht immer Migration – sie ist eine Überlebensstrategie. Ein Blick auf die Transhumanz im Alltag der Fulbe.","en":"In the Sahel, movement is not always migration—it is a survival strategy. A look at transhumance as Fulani pastoralists live it daily."},"readingMinutes":2,"sections":{"ar":[{"heading":"حركة منظمة لا هجرة عشوائية","paragraphs":["الرعي المتنقل هو التنقل الموسمي للماشية بين مراعٍ ثابتة، ويمارسه رعاة الفولاني وغيرهم من الرعاة في منطقة الساحل. تتحرك القطعان شمالًا خلال موسم الأمطار حيث ينمو العشب، ثم تعود جنوبًا في موسم الجفاف حيث تبقى المياه والكلأ. هذا النمط من استخدام الأرض مصمم للتعامل مع أمطار غير متوقعة، إذ لا يمكن الاعتماد على بقعة واحدة طوال العام.","المسارات ليست عشوائية؛ فهي متعارف عليها بالعرف ومتفاوض عليها مع المجتمعات الزراعية. في موسم الجفاف، تقود أسرة فولانية أبقارها جنوبًا عبر حقول محصودة، وتدفع رسومًا متفقًا عليها لعبور الأراضي الزراعية والوصول إلى نقطة ماء. هذا الترتيب يسمح بالمرور مقابل تعويض، لكنه يحتاج إلى ثقة متبادلة وإلى مساحة للتفاوض."]},{"heading":"اقتصاد الرعي وأثره اليومي","paragraphs":["تساهم اقتصادات الرعي في توفير اللحوم والحليب وقوة الجر الحيوانية، وهي جزء من الحياة اليومية للكثيرين في المدن والريف على حد سواء. لكن الطرق المتعارف عليها أصبحت مقطوعة بشكل متزايد بسبب الحقول والطرق والضغوط المناخية. هذا لا يهدد نمط حياة الرعاة فقط، بل يزيد أيضًا من التوترات حول تلف المحاصيل والوصول إلى الماء.","ليست كل أسر الفولاني رعاة، وكثير منها يعيش في المدن أو يمارس الزراعة. كما تختلف الترتيبات بين دولة وأخرى، وتتغير عبر الأجيال مع تزايد الضغوط على المراعي. من المهم أن نرى في الرعي المتنقل نظامًا متكيفًا مع بيئته، لا مجرد بقايا ماضٍ."]},{"heading":"توترات متزايدة بين الرعاة والمزارعين","paragraphs":["أصبحت النزاعات بين الرعاة والمزارعين بسبب تلف المحاصيل والوصول إلى الماء أكثر تواترًا وذات طابع سياسي. عندما تُغلق المسارات، يجد الرعاة أنفسهم مضطرين إلى المرور عبر أراضٍ مزروعة أو البحث عن نقاط ماء بديلة، ما يخلق احتكاكًا يوميًا. هذه التوترات ليست جديدة، لكن الضغوط المناخية والطرق الحديثة تجعلها أكثر حدة.","في هذا السياق، يظل التفاوض المحلي هو الأداة الأساسية لتنظيم المرور. لكن فعالية هذه الأداة تعتمد على استمرار العرف وعلى وجود سلطات محلية قادرة على الوساطة. عندما تضعف هذه الآليات، يتحول الرعي المتنقل من استراتيجية تكيف إلى مصدر صراع."]}],"de":[{"heading":"Geordnete Bewegung statt zielloses Umherziehen","paragraphs":["Transhumanz ist die saisonale Wanderung von Vieh zwischen festen Weidegebieten, die von fulbischen und anderen Hirten im Sahel praktiziert wird. In der Regenzeit ziehen die Herden nach Norden, wo Gras wächst; in der Trockenzeit kehren sie nach Süden zurück, wo Wasser und Futter bleiben. Diese Form der Landnutzung ist an unvorhersehbare Niederschläge angepasst – man kann sich nicht das ganze Jahr auf einen einzigen Ort verlassen.","Die Routen sind nicht willkürlich, sondern durch Gewohnheit festgelegt und mit Ackerbaugemeinschaften ausgehandelt. In der Trockenzeit treibt eine fulbische Familie ihr Vieh nach Süden über abgeerntete Felder und zahlt eine vereinbarte Gebühr, um Ackerland zu durchqueren und eine Wasserstelle zu erreichen. Diese Regelung ermöglicht Durchgang gegen Entschädigung, erfordert aber gegenseitiges Vertrauen und Verhandlungsspielraum."]},{"heading":"Die Ökonomie der Weidewirtschaft","paragraphs":["Die Weidewirtschaft trägt zur Versorgung mit Fleisch, Milch und tierischer Zugkraft bei und ist Teil des Alltags vieler Menschen, ob in der Stadt oder auf dem Land. Doch die überlieferten Routen werden zunehmend durch Felder, Straßen und klimatischen Stress blockiert. Das bedroht nicht nur die Lebensweise der Hirten, sondern verschärft auch Spannungen um Ernteschäden und Wasserzugang.","Nicht alle Fulbe sind Hirten; viele leben in Städten oder betreiben Ackerbau. Auch die Arrangements unterscheiden sich von Land zu Land und verändern sich über Generationen hinweg, während der Druck auf die Weiden wächst. Transhumanz sollte daher als anpassungsfähiges System verstanden werden, nicht als Überbleibsel einer vergangenen Zeit."]},{"heading":"Zunehmende Spannungen zwischen Hirten und Bauern","paragraphs":["Konflikte zwischen Hirten und Bauern wegen Ernteschäden und Wasserzugang sind häufiger und politisch aufgeladen geworden. Wenn Routen blockiert werden, sehen sich Hirten gezwungen, durch bestellte Felder zu ziehen oder alternative Wasserstellen zu suchen – das erzeugt tägliche Reibung. Diese Spannungen sind nicht neu, aber klimatischer Stress und moderne Straßen verschärfen sie.","In diesem Kontext bleibt die lokale Verhandlung das wichtigste Mittel zur Regelung des Durchzugs. Ihre Wirksamkeit hängt jedoch davon ab, dass Gewohnheitsrechte fortbestehen und lokale Autoritäten vermitteln können. Wo diese Mechanismen schwächer werden, wird Transhumanz von einer Anpassungsstrategie zur Konfliktquelle."]}],"en":[{"heading":"Ordered movement, not wandering","paragraphs":["Transhumance is the seasonal movement of livestock between fixed pastures, practised by Fulani and other pastoralists across the Sahel. Herds move north during the rainy season, where grass grows, and return south in the dry season, where water and fodder remain. This form of land use is adapted to unpredictable rainfall—you cannot rely on a single spot all year round.","The routes are not random; they are established by custom and negotiated with farming communities. In the dry season, a Fulani family drives cattle south past harvested fields, paying a negotiated fee to cross farmland and reach a water point. This arrangement allows passage in exchange for compensation, but it requires mutual trust and room for negotiation."]},{"heading":"The economy of herding","paragraphs":["Pastoralist economies supply meat, milk and animal traction, and they are part of daily life for many people, in cities and rural areas alike. But customary routes are increasingly blocked by fields, roads and climate stress. This threatens not only herders' livelihoods but also heightens tensions over crop damage and water access.","Not all Fulani are pastoralists; many live in towns or farm. Arrangements also differ from country to country and change across generations as pressure on pastures grows. Transhumance is best understood as an adaptable system, not a relic of the past."]},{"heading":"Growing friction between herders and farmers","paragraphs":["Conflicts between herders and farmers over crop damage and water access have become more frequent and politically charged. When routes are blocked, herders find themselves forced to pass through cultivated land or seek alternative water points—creating daily friction. These tensions are not new, but climate stress and modern roads make them sharper.","In this context, local negotiation remains the primary tool for regulating passage. Its effectiveness depends on customary rights persisting and local authorities being able to mediate. Where these mechanisms weaken, transhumance shifts from an adaptation strategy to a source of conflict."]}]},"context":{"countries":["NE","ML","BF","NG"],"region":"Sahel","community":"Fulani pastoralists","continent":"africa","languages":["ff","fr","ha"],"period":"contemporary"},"tags":["nature-and-seasons","Sahel","Transhumance is","Herds move"],"sources":[{"organization":"Wikipedia","title":{"ar":"Transhumance","de":"Transhumance","en":"Transhumance"},"url":"https://en.wikipedia.org/wiki/Transhumance","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Fula people","de":"Fula people","en":"Fula people"},"url":"https://en.wikipedia.org/wiki/Fula_people","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في موسم الجفاف، تقود أسرة فولانية أبقارها جنوبًا عبر حقول محصودة، وتدفع رسومًا متفقًا عليها لعبور الأراضي الزراعية والوصول إلى نقطة ماء.","de":"In der Trockenzeit treibt eine fulbische Familie ihr Vieh nach Süden über abgeerntete Felder und zahlt eine vereinbarte Gebühr, um Ackerland zu durchqueren und eine Wasserstelle zu erreichen.","en":"In the dry season a Fulani family drives cattle south past harvested fields, paying a negotiated fee to cross farmland and reach a water point."},"misunderstanding":{"ar":"كثيرًا ما يُخلط بين الرعي المتنقل والرعي البدوي؛ فالمسارات والترتيبات تختلف بين البلدان، وليس كل الفولاني رعاة.","de":"Transhumanz wird oft mit nomadischer Viehhaltung verwechselt; die Routen und Arrangements unterscheiden sich von Land zu Land, und nicht alle Fulbe sind Hirten.","en":"Transhumance is often confused with nomadic pastoralism; routes and arrangements differ between countries, and not all Fulani are pastoralists."},"comparison":{"ar":"على عكس الزراعة المستقرة التي تعتمد على قطعة أرض واحدة، يعتمد الرعي المتنقل على التنقل بين مراعٍ ثابتة لمواجهة تقلبات المطر.","de":"Anders als sesshafte Landwirtschaft, die auf einem einzigen Stück Land basiert, beruht Transhumanz auf dem Wechsel zwischen festen Weidegebieten, um unregelmäßige Regenfälle auszugleichen.","en":"Unlike settled farming, which relies on a single plot of land, transhumance depends on moving between fixed pastures to cope with irregular rainfall."}},{"id":"afr-053","version":2,"slug":"vodun-lived-religion-in-benin-and-togo","contentType":"feature","category":"beliefs-and-folklore","title":{"ar":"فودون: دين حي في بنين وتوغو","de":"Vodún: gelebte Religion in Benin und Togo","en":"Vodún: Lived Religion in Benin and Togo"},"deck":{"ar":"فودون ليس مجرد معتقد قديم، بل هو نسيج يومي يربط الأسر والمجتمعات في بنين وتوغو.","de":"Vodún ist keine ferne Tradition, sondern ein täglicher Faden, der Familien und Gemeinschaften in Benin und Togo verbindet.","en":"Vodún is not a distant tradition but a daily thread weaving families and communities together in Benin and Togo."},"teaser":{"ar":"كيف يعيش الناس الفودون في غرب أفريقيا، بعيدًا عن الصور النمطية، من خلال الطقوس والقرابين والرقص.","de":"Wie Menschen in Westafrika Vodún leben – jenseits von Klischees, mit Ritualen, Opfergaben und Tanz.","en":"How people in West Africa live Vodún beyond stereotypes, through rituals, offerings, and dance."},"readingMinutes":2,"sections":{"ar":[{"heading":"جذور ممتدة في غرب أفريقيا","paragraphs":["فودون هو دين تقليدي يمارسه شعوب الأجا والإيوي والفون في بنين وتوغو وغانا ونيجيريا. لا توجد سلطة مركزية واحدة، بل تنظمه مجموعات محلية وشبكات من الكهنة والعرافين. يرتبط كل فودون بروح أو إلهة تمثل قوى الطبيعة أو الأسلاف أو أماكن معينة. يقدم الممارسون القرابين، ويستشيرون العرافين، ويقيمون احتفالات بالطبول والرقص.","في حياة الناس، يظهر فودون في المناسبات العائلية والمجتمعية. فالمزارات ليست أماكن منعزلة، بل مراكز يلتقي فيها الجيران لتقديم القرابين وتبادل الطعام. يحرص الأهل على تعليم الأطفال احترام الأرواح والتقاليد منذ الصغر. وتختلف الممارسات من منطقة إلى أخرى، كما تتباين بين الأجيال، إذ يضيف الشباب لمساتهم الخاصة مع الحفاظ على الجوهر."]},{"heading":"طقوس تعزز الروابط الاجتماعية","paragraphs":["تجمع الاحتفالات بين الطبول والرقص والقرابين، وتشارك فيها الأسرة الممتدة والجيران. يقدم الناس الطعام والشراب للأرواح ثم يتشاركونه، مما يعزز التضامن. في بنين، تعزز الحكومة فودون كتراث وطني، ويستضيف مدينة ويداه مهرجانًا سنويًا للفودون يجذب الزوار من داخل البلاد وخارجها.","هذه المناسبات ليست مجرد أداء ديني، بل فرصة لتجديد العلاقات الاجتماعية وحل الخلافات. يلعب الكهنة دور الوساطة بين الناس والأرواح، ويقدمون النصح في أمور الحياة اليومية. كما أن مشاركة النساء والأطفال في التحضير والطهي والغناء تعكس تكامل الأدوار. وتظل هذه الممارسات حية رغم التحديات الحديثة."]},{"heading":"فودون في العالم الجديد","paragraphs":["سافر فودون مع الأفارقة المستعبدين إلى الأمريكتين، حيث ساهم في تشكيل الفودو الهايتي والسانتيريا الكوبية والكاندومبليه البرازيلي. هذه الأديان تشترك في جذور تاريخية مع فودون، لكنها تطورت في سياقات مختلفة وأصبحت لها طقوسها الخاصة. لا ينبغي الخلط بينها وبين فودون كما يمارس في غرب أفريقيا، لأن العلاقة تاريخية وليست تطابقًا.","غالبًا ما تقدم وسائل الإعلام الأجنبية فودون بشكل مثير ومشوه، لكنه دين حي ومتنوع. يمارسه الناس في حياتهم اليومية، ويحتفلون به في المهرجانات، ويعبرون من خلاله عن هويتهم. في بنين وتوغو، يظل فودون جزءًا لا يتجزأ من النسيج الاجتماعي والثقافي."]}],"de":[{"heading":"Verwurzelt in Westafrika","paragraphs":["Vodún ist eine traditionelle Religion, die von den Aja-, Ewe- und Fon-Völkern in Benin, Togo, Ghana und Nigeria praktiziert wird. Es gibt keine zentrale Autorität; stattdessen organisieren lokale Gruppen und Netzwerke von Priestern und Wahrsagern das religiöse Leben. Jeder Vodún ist ein Geist oder eine Gottheit, die mit Naturkräften, Ahnen oder bestimmten Orten verbunden ist. Die Anhänger bringen Opfergaben dar, konsultieren Wahrsager und feiern Zeremonien mit Trommeln und Tanz.","Im Alltag zeigt sich Vodún bei Familienfeiern und gemeinschaftlichen Anlässen. Schreine sind keine abgelegenen Orte, sondern Treffpunkte, an denen Nachbarn Opfergaben darbringen und Essen teilen. Eltern bringen ihren Kindern früh Respekt vor den Geistern und Traditionen bei. Die Praktiken variieren von Region zu Region und zwischen den Generationen, wobei junge Leute eigene Akzente setzen und den Kern bewahren."]},{"heading":"Rituale stärken den Zusammenhalt","paragraphs":["Zeremonien verbinden Trommeln, Tanz und Opfergaben, an denen die Großfamilie und Nachbarn teilnehmen. Die Menschen opfern Speisen und Getränke den Geistern und teilen sie anschließend, was Solidarität fördert. In Benin fördert die Regierung Vodún als nationales Erbe, und Ouidah veranstaltet jährlich ein Vodún-Festival, das Besucher aus dem In- und Ausland anzieht.","Diese Anlässe sind nicht nur religiöse Aufführungen, sondern Gelegenheiten, soziale Beziehungen zu erneuern und Konflikte zu lösen. Priester vermitteln zwischen Menschen und Geistern und geben Ratschläge für den Alltag. Die Beteiligung von Frauen und Kindern beim Vorbereiten, Kochen und Singen zeigt die Integration der Rollen. Trotz moderner Herausforderungen bleiben diese Praktiken lebendig."]},{"heading":"Vodún in der Neuen Welt","paragraphs":["Mit versklavten Afrikanern gelangte Vodún nach Amerika und prägte den haitianischen Vodou, die kubanische Santería und den brasilianischen Candomblé. Diese Religionen teilen historische Wurzeln mit Vodún, entwickelten sich aber in anderen Kontexten und haben eigene Rituale. Man sollte sie nicht mit dem westafrikanischen Vodún gleichsetzen, denn die Beziehung ist historisch, nicht identisch.","Ausländische Medien stellen Vodún oft sensationell und verzerrt dar, doch es ist eine vielfältige gelebte Religion. Menschen praktizieren sie im Alltag, feiern sie bei Festivals und drücken dadurch ihre Identität aus. In Benin und Togo bleibt Vodún ein untrennbarer Teil des sozialen und kulturellen Gefüges."]}],"en":[{"heading":"Rooted in West Africa","paragraphs":["Vodún is a traditional religion practised by the Aja, Ewe, and Fon peoples in Benin, Togo, Ghana, and Nigeria. There is no central authority; instead, local groups and networks of priests and diviners organise religious life. Each vodún is a spirit or deity associated with natural forces, ancestors, or particular places. Practitioners make offerings, consult diviners, and hold ceremonies with drumming and dance.","In daily life, Vodún appears at family and community events. Shrines are not isolated places but meeting points where neighbours bring offerings and share food. Parents teach children respect for the spirits and traditions from an early age. Practices vary from region to region and between generations, with young people adding their own touches while preserving the core."]},{"heading":"Rituals Strengthen Social Bonds","paragraphs":["Ceremonies combine drumming, dance, and offerings, involving the extended family and neighbours. People offer food and drink to the spirits and then share them, fostering solidarity. In Benin, the government promotes Vodún as national heritage, and Ouidah hosts an annual Vodún festival that attracts visitors from home and abroad.","These occasions are not just religious performances but opportunities to renew social ties and resolve conflicts. Priests mediate between people and spirits, offering advice on everyday matters. The participation of women and children in preparing, cooking, and singing reflects integrated roles. Despite modern challenges, these practices remain vibrant."]},{"heading":"Vodún in the New World","paragraphs":["Vodún travelled to the Americas with enslaved Africans, shaping Haitian Vodou, Cuban Santería, and Brazilian Candomblé. These religions share historical roots with Vodún but developed in different contexts and have their own rituals. They should not be equated with West African Vodún, as the relationship is historical rather than identical.","Foreign media often portray Vodún sensationally and distortedly, yet it is a diverse lived religion. People practise it in daily life, celebrate it at festivals, and express their identity through it. In Benin and Togo, Vodún remains an inseparable part of the social and cultural fabric."]}]},"context":{"countries":["BJ","TG"],"region":"Benin and Togo","community":"Fon and Ewe","continent":"africa","languages":["ee","fr"],"period":"contemporary"},"tags":["beliefs-and-folklore","Benin and Togo"],"sources":[{"organization":"Wikipedia","title":{"ar":"West African Vodún","de":"West African Vodún","en":"West African Vodún"},"url":"https://en.wikipedia.org/wiki/West_African_Vod%C3%BAn","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Fon people","de":"Fon people","en":"Fon people"},"url":"https://en.wikipedia.org/wiki/Fon_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في ويداه، تكرم أسرة فودونها في مزار بتقديم القرابين والطبول والطعام المشترك، وينضم الجيران إلى الاحتفال.","de":"In Ouidah ehrt eine Familie ihren Vodún an einem Schrein mit Opfergaben, Trommeln und gemeinsamem Essen, und Nachbarn schließen sich der Zeremonie an.","en":"In Ouidah a family honours its vodún at a shrine with offerings, drumming, and shared food, and neighbours join the ceremony."},"misunderstanding":{"ar":"يُصور فودون غالبًا في الإعلام الأجنبي بشكل مبالغ فيه؛ لكنه دين متنوع وعملي، وعلاقته بالأديان المهاجرة تاريخية وليست متطابقة.","de":"Vodún wird in ausländischen Medien oft sensationell dargestellt; es ist eine vielfältige gelebte Religion, und seine Beziehung zu Diaspora-Religionen ist historisch, nicht identisch.","en":"Vodún is often sensationalised in foreign media; it is a diverse lived religion, and its relationship to diaspora religions is historical rather than identical."},"comparison":{"ar":"بينما يشترك فودون في جذور تاريخية مع الفودو الهايتي والسانتيريا الكوبية والكاندومبليه البرازيلي، فإن كلًا منها تطور بشكل مستقل وله طقوسه الخاصة.","de":"Obwohl Vodún historische Wurzeln mit haitianischem Vodou, kubanischer Santería und brasilianischem Candomblé teilt, hat sich jede eigenständig entwickelt und besitzt eigene Rituale.","en":"While Vodún shares historical roots with Haitian Vodou, Cuban Santería, and Brazilian Candomblé, each has developed independently with its own rituals."}},{"id":"afr-054","version":2,"slug":"bwiti-initiation-and-ancestor-knowledge-in-gabon","contentType":"note","category":"beliefs-and-folklore","title":{"ar":"بويتي: التلقين ومعرفة الأسلاف في الغابون","de":"Bwiti: Initiation und Ahnenwissen in Gabun","en":"Bwiti: initiation and ancestor knowledge in Gabon"},"deck":{"ar":"طريق روحي طويل يمرّ بالتدريب والموسيقى ومسؤولية المجتمع.","de":"Ein langer spiritueller Weg über Lehre, Musik und gemeinschaftliche Verantwortung.","en":"A long spiritual path built on instruction, music and responsibility to the community."},"teaser":{"ar":"كيف يصبح الشاب مسؤولاً في مجتمعه؟ رحلة تلقين في الغابون تمزج الأسلاف بالموسيقى وبالنبات المقدّس والاعتراف.","de":"Wie junge Menschen in Gabun Verantwortung für ihre Gemeinschaft übernehmen: eine Initiation mit Ahnen, Trommeln, Iboga und offenem Bekenntnis.","en":"How young people in Gabon take on responsibility for their community: an initiation blending ancestors, drumming, a sacred plant and confession."},"readingMinutes":1,"sections":{"ar":[{"heading":"التلقين مدخلاً إلى المسؤولية","paragraphs":["بويتي مذهب روحي عند شعبي بونو وميتسوغو في الغابون، ويمارسه أيضاً مجتمع الفانغ. يقوم على التلقين وتوقير الأسلاف واستخدام الإيبوغا، وهو نبات ذو تأثير نفسي، في احتفالات مضبوطة.","يجمع بويتي الحديث بين الإحيائية وعبادة الأسلاف، وفي بعض الحالات المسيحية، في نظام توفيقي. ويتضمّن التلقين تعليماً وموسيقى واحتفالاً طويلاً، ويعلن دخول الشخص مرحلة الرشد وتحلّيه بمسؤولية تجاه الجماعة.","في جنوب الغابون، يستعدّ مُلقَّن لاحتفال يستمر ليلاً كاملاً بالطبول والاعتراف والتعليم على أيدي الشيوخ. وتتباين شعب بويتي وممارساته المحلية، فلكل جماعة تفاصيلها الخاصة في الطقوس والتعليم."]},{"heading":"نباتٌ محلّ جدل","paragraphs":["انتشر بويتي إلى أجزاء أخرى من وسط إفريقيا وإلى أوروبا، ويُدرَس استخدام الإيبوغا العلاجي ويُنظَّم قانونياً في عدد من البلدان."]}],"de":[{"heading":"Initiation als Eintritt in Verantwortung","paragraphs":["Bwiti ist eine spirituelle Disziplin der Punu und Mitsogo in Gabun, die auch in Fang-Gemeinschaften praktiziert wird. Im Zentrum stehen Initiation, Ahnenverehrung und die Nutzung von Iboga, einer Pflanze mit psychoaktiver Wirkung, in kontrollierten Zeremonien.","Das moderne Bwiti verbindet Animismus und Ahnenverehrung, in manchen Fällen auch Christentum, zu einem synkretistischen System. Die Initiation umfasst Unterweisung, Musik und eine lange Zeremonie; sie markiert den Eintritt ins Erwachsenenalter und in gemeinschaftliche Verantwortung.","Im Süden Gabuns bereitet sich ein Initiand auf eine nächtelange Zeremonie mit Trommeln, Bekenntnis und Belehrung durch Älteste vor. Bwiti hat viele Zweige und lokale Varianten, denn jede Gemeinschaft gestaltet ihre Riten und Lehren eigenständig."]},{"heading":"Eine Pflanze im Zwielicht","paragraphs":["Bwiti hat sich in andere Teile Zentralafrikas und nach Europa verbreitet, und die therapeutische Nutzung von Iboga wird heute erforscht und reguliert."]}],"en":[{"heading":"Initiation as entry into responsibility","paragraphs":["Bwiti is a spiritual discipline of the Punu and Mitsogo peoples of Gabon, also practised by Fang communities. It centres on initiation, ancestor veneration and the use of iboga, a plant with psychoactive properties, in controlled ceremonies.","Modern Bwiti combines animism and ancestor worship, and in some cases Christianity, into a syncretic system. Initiation involves instruction, music and a long ceremony, and it marks entry into adulthood and community responsibility.","In southern Gabon an initiate prepares for a night-long ceremony with drumming, confession and teaching from elders. Bwiti has many branches and local variations, and each community shapes its own rites and teaching."]},{"heading":"A plant under scrutiny","paragraphs":["Bwiti has spread to other parts of Central Africa and to Europe, and iboga's therapeutic use is now studied and regulated in several countries."]}]},"context":{"countries":["GA"],"region":"Southern Gabon","community":"Punu and Mitsogo","continent":"africa","languages":["fr"],"period":"contemporary"},"tags":["beliefs-and-folklore","Southern Gabon","Bwiti is","It centres"],"sources":[{"organization":"Wikipedia","title":{"ar":"Bwiti","de":"Bwiti","en":"Bwiti"},"url":"https://en.wikipedia.org/wiki/Bwiti","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Gabon","de":"Gabon","en":"Gabon"},"url":"https://en.wikipedia.org/wiki/Gabon","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في جنوب الغابون، يستعدّ مُلقَّن لاحتفال يستمر ليلاً كاملاً بالطبول والاعتراف والتعليم على أيدي الشيوخ.","de":"Im Süden Gabuns bereitet sich ein Initiand auf eine nächtelange Zeremonie mit Trommeln, Bekenntnis und Belehrung durch Älteste vor.","en":"In southern Gabon an initiate prepares for a night-long ceremony with drumming, confession and teaching from elders."},"misunderstanding":{"ar":"لبويتي فروع وتنويعات محلية كثيرة، وكثيراً ما تركّز أوصاف الغرباء على الإيبوغا وتغفل التعليم الأخلاقي والجماعي.","de":"Bwiti hat viele Zweige und lokale Varianten, und Beschreibungen von Außenstehenden betonen oft Iboga und übersehen die ethische und gemeinschaftliche Lehre.","en":"Bwiti has many branches and local variations, and outsiders' descriptions often emphasise iboga while missing the ethical and community teaching."},"comparison":{"ar":"كما تُنظَّم اليوم ممارسات روحية كانت محلية في بلد واحد، صار الإيبوغا موضوعاً للدراسة والتنظيم خارج الغابون.","de":"So wie heute spirituelle Praktiken reguliert werden, die einst nur an einem Ort beheimatet waren, ist Iboga außerhalb Gabuns zum Gegenstand von Forschung und Gesetzgebung geworden.","en":"Just as spiritual practices once rooted in one place are now regulated, iboga has become a subject of research and law beyond Gabon."}},{"id":"afr-055","version":2,"slug":"famadihana-turning-the-ancestors-in-madagascar","contentType":"scene","category":"beliefs-and-folklore","title":{"ar":"فاماديهانا: تكريم الأسلاف في مرتفعات مدغشقر","de":"Famadihana: Ahnen im Hochland von Madagaskar ehren","en":"Famadihana: honouring ancestors in Madagascar's highlands"},"deck":{"ar":"عائلات في المرتفعات تُخرج موتاها من القبور لتلفّهم بأقمشة جديدة وتجدّد صلاتها بهم في احتفال يجمع الحزن والفرح.","de":"Familien im Hochland holen die Toten aus den Gräbern, hüllen sie in neue Tücher und erneuern so ihre Bindung – zwischen Trauer und Fest.","en":"Highland families bring their dead from the tomb, rewrap them in new cloth and renew their ties in a gathering that is both joyful and solemn."},"teaser":{"ar":"تقليد جنائزي مدغشقري يحوّل زيارة القبور إلى مناسبة عائلية كبرى، لكنه مكلف ويواجه انتقادات وتراجعًا في أوقات الأوبئة.","de":"Eine madagassische Bestattungstradition macht den Gräberbesuch zum großen Familientreffen, ist aber teuer und gerät unter Kritik und in Krisenzeiten ins Stocken.","en":"A Malagasy funerary tradition turns a tomb visit into a large family reunion, but it is costly and has faced criticism and decline in times of disease."},"readingMinutes":1,"sections":{"ar":[{"heading":"ماذا يحدث في فاماديهانا","paragraphs":["في تقليد فاماديهانا الجنائزي في مدغشقر، تُخرج العائلات أجساد أسلافها من القبر، وتلفّها بأقمشة جديدة، وتعيد كتابة أسمائهم.","تتضمن المراسم موسيقى ورقصًا وطعامًا مشتركًا، وهي مناسبة مبهجة بقدر ما هي وقورة، وتُقام أساسًا لدى مجموعات المرتفعات مثل الميرينا والبِتسيلِيو.","يختلف هذا التقليد بين المناطق والأجيال: فالمجتمعات الساحلية والمسلمة لها ممارسات دفن مختلفة، وقد تغيّر التقليد نفسه مع الوقت."]},{"heading":"التكلفة والانتقادات","paragraphs":["يكرّم فاماديهانا الأسلاف ويجدّد الروابط العائلية، لكنه مكلف، وقد تؤجّل العائلات إقامته سنوات وهي تدّخر المال.","انتقدت بعض الكنائس المسيحية ومسؤولو الصحة العامة هذه المراسم، وتراجعت خلال تفشّي الطاعون وجائحة كوفيد-19."]}],"de":[{"heading":"Was bei Famadihana geschieht","paragraphs":["Bei Famadihana, einer madagassischen Bestattungstradition, holen Familien die Körper ihrer Ahnen aus dem Grab, wickeln sie in neue Tücher und schreiben ihre Namen neu.","Die Zeremonie umfasst Musik, Tanz und gemeinsames Essen; sie ist ein fröhlicher und zugleich feierlicher Anlass und wird vor allem von Hochlandgruppen wie den Merina und Betsileo gepflegt.","Regionale und generationelle Unterschiede sind deutlich: Küsten- und muslimische Gemeinschaften haben andere Begräbnispraktiken, und die Tradition selbst hat sich verändert."]},{"heading":"Kosten und Kritik","paragraphs":["Famadihana ehrt die Ahnen und erneuert Familienbande, ist aber teuer; Familien verschieben es oft jahrelang, während sie Geld sparen.","Einige christliche Kirchen und Gesundheitsbehörden kritisierten das Ritual; während Pestausbrüchen und der COVID-19-Pandemie ging es zurück."]}],"en":[{"heading":"What happens at Famadihana","paragraphs":["In Famadihana, a Malagasy funerary tradition, families bring ancestors' bodies from the tomb, rewrap them in new cloth and rewrite their names.","The ceremony includes music, dancing and shared food; it is a joyful occasion as well as a solemn one, practised mainly by highland groups such as the Merina and Betsileo.","Regional and generational variation is real: coastal and Muslim communities have different burial practices, and the tradition itself has changed over time."]},{"heading":"Cost and criticism","paragraphs":["Famadihana honours ancestors and renews family ties, but it is expensive, and families may postpone it for years while saving the money.","Some Christian churches and public-health officials have criticised the ritual, and it declined during plague outbreaks and the COVID-19 pandemic."]}]},"context":{"countries":["MG"],"region":"Highlands of Madagascar","community":"Merina and Betsileo","continent":"africa","languages":["mg","fr"],"period":"contemporary"},"tags":["beliefs-and-folklore","Highlands of Madagascar"],"sources":[{"organization":"Wikipedia","title":{"ar":"Famadihana","de":"Famadihana","en":"Famadihana"},"url":"https://en.wikipedia.org/wiki/Famadihana","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Malagasy peoples","de":"Malagasy peoples","en":"Malagasy peoples"},"url":"https://en.wikipedia.org/wiki/Malagasy_peoples","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة في أنتاناناريفو تستأجر فرقة موسيقية، وتجمع الأقارب من الخارج، وتطوف بالأسلاف الملفّفين حول القبر قبل إعادتهم.","de":"Eine Familie in Antananarivo engagiert eine Band, versammelt Verwandte aus dem Ausland und trägt die neu gewickelten Ahnen um das Grab, bevor sie zurückkehren.","en":"A family in Antananarivo hires a band, gathers relatives from abroad, and carries the rewrapped ancestors around the tomb before returning them."},"misunderstanding":{"ar":"يظنّ بعض الغرباء أنها احتفال بالموت أو سخرية منه، لكنها في جوهرها تعبير عن الاحترام والامتنان للأسلاف وتجديد للروابط.","de":"Außenstehende halten es manchmal für Spott über den Tod, doch es ist vor allem Respekt und Dankbarkeit gegenüber den Ahnen und eine Erneuerung der Bande.","en":"Outsiders sometimes mistake it for mockery of death, but it is chiefly respect and gratitude toward ancestors and a renewal of family bonds."},"comparison":{"ar":"تشبه في وظيفتها زيارات المقابر السنوية في ثقافات أخرى، حيث يجتمع الأقارب لتذكّر الموتى، لكنها هنا تتجاوز الزيارة إلى إعادة لفّ الجسد وتسميته.","de":"Es ähnelt jährlichen Gräberbesuchen anderer Kulturen, bei denen Verwandte zusammenkommen, geht aber weiter: Der Körper wird neu gewickelt und benannt.","en":"It resembles annual grave visits in other cultures where relatives gather to remember the dead, yet here the body is rewrapped and renamed."}}];

